def request_cancel(_signum: int, _frame: object) -> None:
    global _cancel_requested
    _cancel_requested = True


signal.signal(signal.SIGINT, request_cancel)
signal.signal(signal.SIGTERM, request_cancel)


class HarnessError(Exception):
    terminal = "InternalFault"


class UsageRefused(HarnessError):
    terminal = "UsageRefused"


class InputRefused(HarnessError):
    terminal = "InputRefused"


class NoData(HarnessError):
    terminal = "NoData"


class EvidenceFailed(HarnessError):
    terminal = "EvidenceFailed"


class CancelledDrained(HarnessError):
    terminal = "CancelledDrained"


class InfrastructureFailed(HarnessError):
    terminal = "InfrastructureFailed"


class OutputPublicationFailed(InfrastructureFailed):
    def __init__(
        self,
        message: str,
        *,
        bytes_committed: int | None,
    ) -> None:
        super().__init__(message)
        self.bytes_committed = bytes_committed


class PublishedV2Refusal(HarnessError):
    def __init__(
        self,
        *,
        terminal: str,
        document: Mapping[str, Any],
    ) -> None:
        super().__init__(terminal)
        self.terminal = terminal
        self.document = dict(document)


def check_cancel() -> None:
    if _cancel_requested:
        raise CancelledDrained("cancellation requested; no mutation is in flight")


@contextmanager
def v2_offline_replay_scope() -> Iterator[None]:
    """Fail closed on every subprocess while any offline replay is active."""
    global _v2_offline_replay_depth
    with _v2_offline_replay_scope_lock:
        if _v2_offline_replay_depth == 0 and _v2_active_subprocesses:
            raise EvidenceFailed(
                "offline v2 replay cannot overlap an active subprocess"
            )
        _v2_offline_replay_depth += 1
    try:
        yield
    finally:
        with _v2_offline_replay_scope_lock:
            if _v2_offline_replay_depth <= 0:
                raise EvidenceFailed("offline replay scope depth underflow")
            _v2_offline_replay_depth -= 1


def canonical_bytes(value: Any) -> bytes:
    return (
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        + "\n"
    ).encode("utf-8")


def strict_json_loads(
    payload: bytes | str,
    *,
    label: str,
    require_canonical: bool = False,
) -> Any:
    try:
        text = payload.decode("utf-8") if isinstance(payload, bytes) else payload
    except UnicodeDecodeError as error:
        raise InputRefused(f"{label} is not valid UTF-8") from error
    if text.startswith("\ufeff"):
        raise InputRefused(f"{label} contains a forbidden UTF-8 BOM")

    def closed_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise InputRefused(f"{label} contains duplicate JSON key {key!r}")
            result[key] = value
        return result

    def reject_constant(value: str) -> Any:
        raise InputRefused(f"{label} contains non-finite number {value}")

    try:
        document = json.loads(
            text,
            object_pairs_hook=closed_object,
            parse_constant=reject_constant,
        )
    except InputRefused:
        raise
    except json.JSONDecodeError as error:
        raise InputRefused(f"{label} is malformed JSON") from error
    if require_canonical and canonical_bytes(document) != text.encode("utf-8"):
        raise InputRefused(f"{label} is not canonical JSON with one terminal newline")
    return document


def semantic_root(value: Any) -> str:
    return "sha256-v1:" + hashlib.sha256(canonical_bytes(value)).hexdigest()


def text_root(value: str) -> str:
    return "sha256-v1:" + hashlib.sha256(value.encode("utf-8")).hexdigest()


def json_stdout(value: Any) -> None:
    payload = canonical_bytes(value)
    try:
        written = sys.stdout.buffer.write(payload)
        if type(written) is not int or written != len(payload):
            raise OutputPublicationFailed(
                "canonical JSONL publication was incomplete",
                bytes_committed=(
                    written
                    if (
                        type(written) is int
                        and 0 <= written <= len(payload)
                    )
                    else None
                ),
            )
        sys.stdout.flush()
    except OutputPublicationFailed:
        raise
    except BaseException as error:
        raise OutputPublicationFailed(
            "canonical JSONL publication failed with unknown commit state",
            bytes_committed=None,
        ) from error


def terminal_row(
    terminal: str,
    *,
    mode: str,
    detail: str,
    extra: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    row: dict[str, Any] = {
        "schema": EVENT_SCHEMA,
        "mode": mode,
        "stage": "terminal",
        "sequence": 0,
        "terminal": terminal,
        "exit_code": TERMINAL_EXIT[terminal],
        "detail": detail,
        "no_claim": (
            "template-hygiene evidence classifies tracker-plan debt only and "
            "mints no implementation, scientific, or release authority"
        ),
    }
    if extra:
        row.update(extra)
    return row


def safe_relative(value: str, *, label: str) -> PurePosixPath:
    if not value:
        raise UsageRefused(f"{label} must be a non-empty repository-relative path")
    if value != unicodedata.normalize("NFC", value):
        raise UsageRefused(f"{label} must use NFC Unicode normalization")
    if len(value.encode("utf-8")) > CAPS["relative_path_bytes"]:
        raise UsageRefused(f"{label} exceeds the relative-path byte cap")
    if any(ord(character) < 32 or ord(character) == 127 for character in value):
        raise UsageRefused(f"{label} contains a control character")
    if "\\" in value or value.startswith("~") or re.match(r"^[A-Za-z]:", value):
        raise UsageRefused(f"{label} uses a forbidden path spelling")
    raw_parts = value.split("/")
    if (
        len(raw_parts) > CAPS["path_depth"]
        or any(part in {"", ".", ".."} for part in raw_parts)
        or any(
            len(part.encode("utf-8")) > CAPS["path_component_bytes"]
            for part in raw_parts
        )
    ):
        raise UsageRefused(f"{label} has an unsafe or over-cap component")
    candidate = PurePosixPath(value)
    if candidate.is_absolute() or ".." in candidate.parts:
        raise UsageRefused(f"{label} must be repository-relative without '..'")
    return candidate


def resolve_safe(value: str, *, label: str, must_exist: bool = False) -> Path:
    relative = safe_relative(value, label=label)
    candidate = REPO_ROOT.joinpath(*relative.parts)
    resolved = candidate.resolve(strict=False)
    try:
        resolved.relative_to(REPO_ROOT)
    except ValueError as error:
        raise UsageRefused(f"{label} escapes the repository") from error

    cursor = REPO_ROOT
    for part in relative.parts:
        cursor = cursor / part
        if cursor.exists() and cursor.is_symlink():
            raise InputRefused(f"{label} traverses symlink {cursor.relative_to(REPO_ROOT)}")
    if must_exist and not candidate.exists():
        raise InputRefused(f"{label} does not exist: {relative}")
    return candidate


def bounded_read(
    path: Path,
    *,
    cap: int = CAPS["input_artifact_bytes"],
    nofollow: bool = False,
    require_unique_link: bool = False,
) -> bytes:
    if type(cap) is not int or cap < 0:
        raise EvidenceFailed("bounded-read cap must be a nonnegative integer")
    if type(nofollow) is not bool or type(require_unique_link) is not bool:
        raise EvidenceFailed(
            "bounded-read descriptor policies must be exact booleans"
        )
    try:
        display_path = str(path.relative_to(REPO_ROOT))
    except ValueError:
        display_path = str(path)
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NONBLOCK", 0)
    if nofollow:
        if not hasattr(os, "O_NOFOLLOW"):
            raise EvidenceFailed(
                "bounded-read nofollow policy is unavailable on this host"
            )
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except OSError as error:
        raise InputRefused(
            f"expected readable regular file: {display_path}"
        ) from error
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise InputRefused(f"expected regular file: {display_path}")
        if require_unique_link and before.st_nlink != 1:
            raise InputRefused(
                f"expected unique regular file: {display_path}"
            )
        with os.fdopen(descriptor, "rb", closefd=False) as handle:
            payload = handle.read(cap + 1)
        after = os.fstat(descriptor)
    except HarnessError:
        raise
    except OSError as error:
        raise InputRefused(
            f"bounded input read failed: {display_path}"
        ) from error
    finally:
        os.close(descriptor)
    if len(payload) > cap:
        raise InputRefused(
            f"input artifact exceeds {cap} byte cap: {display_path}"
        )
    stable_fields = (
        "st_dev",
        "st_ino",
        "st_mode",
        "st_nlink",
        "st_size",
        "st_mtime_ns",
        "st_ctime_ns",
    )
    if any(
        getattr(before, field) != getattr(after, field)
        for field in stable_fields
    ):
        raise InputRefused(
            f"input artifact changed during bounded read: {display_path}"
        )
    return payload


def v2_read_repo_relative_file_strict(
    value: str,
    *,
    label: str,
    cap: int = CAPS["input_artifact_bytes"],
) -> bytes:
    relative = safe_relative(value, label=label)
    if type(cap) is not int or cap < 0:
        raise EvidenceFailed(f"{label} strict-read cap is invalid")
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_CLOEXEC", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    file_flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    file_flags |= getattr(os, "O_NONBLOCK", 0)
    file_flags |= getattr(os, "O_NOFOLLOW", 0)
    directory_descriptors: list[int] = []
    directory_links: list[tuple[int, str, int, int, int]] = []
    file_descriptor: int | None = None
    try:
        root_descriptor = os.open(REPO_ROOT, directory_flags)
        directory_descriptors.append(root_descriptor)
        current_descriptor = root_descriptor
        for part in relative.parts[:-1]:
            child_descriptor = os.open(
                part,
                directory_flags,
                dir_fd=current_descriptor,
            )
            child_stat = os.fstat(child_descriptor)
            if not stat.S_ISDIR(child_stat.st_mode):
                raise InputRefused(
                    f"{label} contains a non-directory component"
                )
            directory_descriptors.append(child_descriptor)
            directory_links.append(
                (
                    current_descriptor,
                    part,
                    child_stat.st_dev,
                    child_stat.st_ino,
                    stat.S_IFMT(child_stat.st_mode),
                )
            )
            current_descriptor = child_descriptor
        leaf = relative.parts[-1]
        file_descriptor = os.open(
            leaf,
            file_flags,
            dir_fd=current_descriptor,
        )
        before = os.fstat(file_descriptor)
        before_entry = os.stat(
            leaf,
            dir_fd=current_descriptor,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink != 1
            or before.st_dev != before_entry.st_dev
            or before.st_ino != before_entry.st_ino
            or stat.S_IFMT(before.st_mode)
            != stat.S_IFMT(before_entry.st_mode)
        ):
            raise InputRefused(
                f"{label} is not one uniquely linked regular file"
            )
        if before.st_size > cap:
            raise InputRefused(f"{label} exceeds its bounded byte cap")
        chunks: list[bytes] = []
        offset = 0
        while offset < before.st_size:
            chunk = os.pread(
                file_descriptor,
                min(1024 * 1024, before.st_size - offset),
                offset,
            )
            if not chunk:
                raise InputRefused(f"{label} changed while being read")
            chunks.append(chunk)
            offset += len(chunk)
        if os.pread(file_descriptor, 1, offset):
            raise InputRefused(f"{label} grew while being read")
        after = os.fstat(file_descriptor)
        after_entry = os.stat(
            leaf,
            dir_fd=current_descriptor,
            follow_symlinks=False,
        )
        stable_fields = (
            "st_dev",
            "st_ino",
            "st_mode",
            "st_nlink",
            "st_size",
            "st_mtime_ns",
            "st_ctime_ns",
        )
        if (
            after.st_nlink != 1
            or any(
                getattr(before, field) != getattr(after, field)
                for field in stable_fields
            )
            or after.st_dev != after_entry.st_dev
            or after.st_ino != after_entry.st_ino
            or stat.S_IFMT(after.st_mode)
            != stat.S_IFMT(after_entry.st_mode)
        ):
            raise InputRefused(f"{label} changed while being read")
        for parent, name, device, inode, file_type in directory_links:
            retained_entry = os.stat(
                name,
                dir_fd=parent,
                follow_symlinks=False,
            )
            if (
                retained_entry.st_dev != device
                or retained_entry.st_ino != inode
                or stat.S_IFMT(retained_entry.st_mode) != file_type
            ):
                raise InputRefused(
                    f"{label} path identity changed while being read"
                )
        return b"".join(chunks)
    except HarnessError:
        raise
    except OSError as error:
        raise InputRefused(f"{label} cannot be opened safely") from error
    finally:
        if file_descriptor is not None:
            try:
                os.close(file_descriptor)
            except OSError:
                pass
        for descriptor in reversed(directory_descriptors):
            try:
                os.close(descriptor)
            except OSError:
                pass


def write_once(path: Path, payload: bytes) -> str:
    check_cancel()
    if len(payload) > CAPS["artifact_bytes"]:
        raise EvidenceFailed(
            f"artifact exceeds {CAPS['artifact_bytes']} byte cap: "
            f"{path.relative_to(REPO_ROOT)}"
        )
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        if not path.is_file():
            raise EvidenceFailed(
                f"artifact target is not a regular file: {path.relative_to(REPO_ROOT)}"
            )
        if bounded_read(path, cap=CAPS["artifact_bytes"]) != payload:
            raise EvidenceFailed(
                f"refusing to overwrite non-identical artifact: "
                f"{path.relative_to(REPO_ROOT)}"
            )
        return "existing-identical"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    descriptor = os.open(path, flags, 0o644)
    try:
        with os.fdopen(descriptor, "wb", closefd=True) as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
    except BaseException:
        # No unlink is attempted: repository policy forbids file deletion.
        raise
    return "created"


def _run_command_unscoped(
    argv: Sequence[str],
    *,
    input_text: str | None = None,
    expected: Iterable[int] = (0,),
    command_cwd: Path | None = None,
    environment_overrides: Mapping[str, str] | None = None,
    honor_cancel: bool = True,
    record_global_receipt: bool = True,
    receipt_sink: Callable[[dict[str, Any]], None] | None = None,
    stdin_bytes_cap: int | None = None,
    stdout_bytes_cap: int | None = None,
    stderr_bytes_cap: int | None = None,
) -> subprocess.CompletedProcess[str]:
    if honor_cancel:
        check_cancel()
    argv_values = [str(value) for value in argv]
    if not argv_values:
        raise InfrastructureFailed("bounded command capture received no argv")
    sanitized_argv = v2_sanitized_argv(argv_values)
    command_name = sanitized_argv[0]
    environment = os.environ.copy()
    for name in SANITIZED_ENV_NAMES:
        environment.pop(name, None)
    if environment_overrides is not None:
        environment.update(
            {
                str(name): str(value)
                for name, value in environment_overrides.items()
            }
        )
    input_bytes = (
        input_text.encode("utf-8") if input_text is not None else None
    )
    default_stream_cap = CAPS["subprocess_stdout_bytes"]
    effective_stream_caps = {
        "stdin": (
            default_stream_cap if stdin_bytes_cap is None else stdin_bytes_cap
        ),
        "stdout": (
            default_stream_cap
            if stdout_bytes_cap is None
            else stdout_bytes_cap
        ),
        "stderr": (
            default_stream_cap
            if stderr_bytes_cap is None
            else stderr_bytes_cap
        ),
    }
    if any(
        type(value) is not int
        or value < 0
        or value > default_stream_cap
        for value in effective_stream_caps.values()
    ):
        raise EvidenceFailed(
            "command stream override exceeds the global bounded byte cap"
        )
    if (
        input_bytes is not None
        and len(input_bytes) > effective_stream_caps["stdin"]
    ):
        raise EvidenceFailed("command stdin exceeds the bounded byte cap")
    expected_codes = set(expected)
    stdout_buffer = bytearray()
    stderr_buffer = bytearray()
    cleanup_errors: list[str] = []

    def append_receipt(*, category: str, exit_code: int) -> None:
        stdout_bytes = bytes(stdout_buffer)
        stderr_bytes = bytes(stderr_buffer)
        receipt = {
            "argv": sanitized_argv,
            "exit_code": int(exit_code),
            "category": category,
            "stdout": {
                "bytes": len(stdout_bytes),
                "root": (
                    "sha256-v1:"
                    + hashlib.sha256(stdout_bytes).hexdigest()
                ),
                "body_retained": False,
            },
            "stderr": {
                "bytes": len(stderr_bytes),
                "root": (
                    "sha256-v1:"
                    + hashlib.sha256(stderr_bytes).hexdigest()
                ),
                "body_retained": False,
            },
            "cleanup_error_count": len(cleanup_errors),
            "cleanup_error_kinds": list(cleanup_errors),
            "redaction_verdict": "RAW_STREAM_BODIES_NOT_RETAINED",
        }
        if record_global_receipt:
            _command_receipts.append(receipt)
        if receipt_sink is not None:
            receipt_sink(dict(receipt))

    try:
        process = subprocess.Popen(
            argv_values,
            cwd=command_cwd or REPO_ROOT,
            stdin=subprocess.PIPE if input_bytes is not None else subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=environment,
            start_new_session=True,
        )
    except FileNotFoundError as error:
        append_receipt(category="START_FAILED", exit_code=-1)
        raise InfrastructureFailed(
            f"required tool not found: {command_name}"
        ) from error
    except OSError as error:
        append_receipt(category="START_FAILED", exit_code=-1)
        raise InfrastructureFailed(
            f"required tool could not be started: {command_name}"
        ) from error

    def drain_process() -> None:
        # Signal the process group even if the session leader has exited:
        # descendants may still own the captured pipes.
        group_observed = True
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            group_observed = False
        except OSError as error:
            cleanup_errors.append(
                f"SIGTERM_PROCESS_GROUP_ERRNO_{error.errno}"
            )
        if group_observed:
            # Escalate immediately. Waiting after a reaped session leader can
            # allow its numeric process-group ID to be reused by an unrelated
            # process before the second signal.
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                # ESRCH proves that no process group remains at this identity.
                pass
            except PermissionError as error:
                # EPERM does not prove retirement. Retain the cleanup failure
                # so no caller can report a successfully drained group.
                cleanup_errors.append(
                    f"SIGKILL_PROCESS_GROUP_ERRNO_{error.errno}"
                )
            except OSError as error:
                cleanup_errors.append(
                    f"SIGKILL_PROCESS_GROUP_ERRNO_{error.errno}"
                )
        if process.poll() is None:
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                cleanup_errors.append("WAIT_AFTER_SIGKILL_TIMEOUT")
            except OSError as error:
                cleanup_errors.append(
                    f"WAIT_AFTER_SIGKILL_ERRNO_{error.errno}"
                )
        for stream_name, stream in (
            ("stdin", process.stdin),
            ("stdout", process.stdout),
            ("stderr", process.stderr),
        ):
            if stream is not None and not stream.closed:
                try:
                    stream.close()
                except OSError as error:
                    cleanup_errors.append(
                        f"CLOSE_{stream_name.upper()}_ERRNO_{error.errno}"
                    )

    streams: selectors.BaseSelector | None = None
    failure_category = "CAPTURE_FAILED"

    def close_selector() -> None:
        nonlocal streams
        selected = streams
        streams = None
        if selected is None:
            return
        try:
            selected.close()
        except OSError as error:
            cleanup_errors.append(
                f"CLOSE_SELECTOR_ERRNO_{error.errno}"
            )

    try:
        streams = selectors.DefaultSelector()
        if process.stdout is None or process.stderr is None:
            raise InfrastructureFailed(
                "bounded command capture lacks required output pipes"
            )
        for stream, name in (
            (process.stdout, "stdout"),
            (process.stderr, "stderr"),
        ):
            os.set_blocking(stream.fileno(), False)
            streams.register(stream, selectors.EVENT_READ, name)
        if input_bytes is not None:
            if process.stdin is None:
                raise InfrastructureFailed(
                    "bounded command capture lacks its requested input pipe"
                )
            os.set_blocking(process.stdin.fileno(), False)
            streams.register(process.stdin, selectors.EVENT_WRITE, "stdin")
        input_offset = 0
        deadline = time.monotonic() + CAPS["subprocess_timeout_seconds"]
        while streams.get_map() or process.poll() is None:
            if honor_cancel and _cancel_requested:
                failure_category = "CANCELLED"
                raise CancelledDrained(
                    "cancellation requested; subprocess group was drained"
                )
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                failure_category = "TIMEOUT"
                raise InfrastructureFailed(
                    f"command exceeded "
                    f"{CAPS['subprocess_timeout_seconds']}s: {command_name}"
                )
            for key, _ in streams.select(timeout=min(0.05, remaining)):
                stream = key.fileobj
                if key.data == "stdin":
                    assert input_bytes is not None
                    try:
                        written = os.write(
                            stream.fileno(),
                            input_bytes[input_offset : input_offset + 65_536],
                        )
                    except (BlockingIOError, InterruptedError):
                        continue
                    except BrokenPipeError:
                        written = 0
                    input_offset += written
                    if written == 0 or input_offset == len(input_bytes):
                        streams.unregister(stream)
                        stream.close()
                    continue
                try:
                    chunk = os.read(stream.fileno(), 65_536)
                except BlockingIOError:
                    continue
                if not chunk:
                    streams.unregister(stream)
                    stream.close()
                    continue
                target = (
                    stdout_buffer
                    if key.data == "stdout"
                    else stderr_buffer
                )
                cap = effective_stream_caps[key.data]
                available = max(0, cap - len(target))
                target.extend(chunk[:available])
                if len(chunk) > available:
                    failure_category = (
                        "STDOUT_LIMIT"
                        if key.data == "stdout"
                        else "STDERR_LIMIT"
                    )
                    raise InfrastructureFailed(
                        f"{command_name} {key.data} exceeded the bounded cap"
                    )
        return_code = process.wait(timeout=1)
    except HarnessError as harness_error:
        drain_process()
        close_selector()
        append_receipt(
            category=failure_category,
            exit_code=(
                process.returncode
                if process.returncode is not None
                else -1
            ),
        )
        if cleanup_errors:
            raise InfrastructureFailed(
                "subprocess cleanup could not prove process-group retirement; "
                "inspect the retained cleanup error kinds"
            ) from harness_error
        raise
    except (OSError, ValueError, subprocess.TimeoutExpired) as error:
        drain_process()
        close_selector()
        append_receipt(
            category="CAPTURE_FAILED",
            exit_code=(
                process.returncode
                if process.returncode is not None
                else -1
            ),
        )
        raise InfrastructureFailed(
            f"{command_name} failed during bounded command capture"
        ) from error
    finally:
        close_selector()
        if process.poll() is None:
            drain_process()
    stdout_bytes = bytes(stdout_buffer)
    stderr_bytes = bytes(stderr_buffer)
    try:
        stdout = stdout_bytes.decode("utf-8")
        stderr = stderr_bytes.decode("utf-8")
    except UnicodeDecodeError as error:
        append_receipt(category="NON_UTF8", exit_code=return_code)
        raise InfrastructureFailed(
            f"{command_name} emitted non-UTF-8 command output"
        ) from error
    completed = subprocess.CompletedProcess(
        argv_values,
        return_code,
        stdout,
        stderr,
    )
    if honor_cancel and _cancel_requested:
        drain_process()
        append_receipt(category="CANCELLED_AFTER_EXIT", exit_code=return_code)
        if cleanup_errors:
            raise InfrastructureFailed(
                "post-exit cancellation could not prove process-group "
                "retirement; inspect the retained cleanup error kinds"
            )
        raise CancelledDrained(
            "cancellation requested after subprocess exit; capture was drained"
        )
    category = (
        "SUCCESS"
        if completed.returncode in expected_codes
        else "UNEXPECTED_EXIT"
    )
    append_receipt(category=category, exit_code=return_code)
    if completed.returncode not in expected_codes:
        raise InfrastructureFailed(
            f"{command_name} returned {completed.returncode}; "
            "raw diagnostic body withheld, inspect its retained stream root"
        )
    return completed


def run_command(
    argv: Sequence[str],
    *,
    input_text: str | None = None,
    expected: Iterable[int] = (0,),
    command_cwd: Path | None = None,
    environment_overrides: Mapping[str, str] | None = None,
    honor_cancel: bool = True,
    record_global_receipt: bool = True,
    receipt_sink: Callable[[dict[str, Any]], None] | None = None,
    stdin_bytes_cap: int | None = None,
    stdout_bytes_cap: int | None = None,
    stderr_bytes_cap: int | None = None,
) -> subprocess.CompletedProcess[str]:
    global _v2_active_subprocesses
    with _v2_offline_replay_scope_lock:
        if _v2_offline_replay_depth > 0:
            raise EvidenceFailed(
                "offline v2 replay forbids every subprocess invocation"
            )
        _v2_active_subprocesses += 1
    try:
        return _run_command_unscoped(
            argv,
            input_text=input_text,
            expected=expected,
            command_cwd=command_cwd,
            environment_overrides=environment_overrides,
            honor_cancel=honor_cancel,
            record_global_receipt=record_global_receipt,
            receipt_sink=receipt_sink,
            stdin_bytes_cap=stdin_bytes_cap,
            stdout_bytes_cap=stdout_bytes_cap,
            stderr_bytes_cap=stderr_bytes_cap,
        )
    finally:
        with _v2_offline_replay_scope_lock:
            if _v2_active_subprocesses <= 0:
                raise EvidenceFailed("subprocess guard depth underflow")
            _v2_active_subprocesses -= 1


def br_json(
    *arguments: str,
    br_cwd: Path = REPO_ROOT,
) -> Any:
    completed = run_command(("br", *arguments), command_cwd=br_cwd)
    try:
        return strict_json_loads(
            completed.stdout.encode("utf-8"),
            label=f"br {' '.join(arguments[:2])} output",
            require_canonical=False,
        )
    except InputRefused as error:
        raise InfrastructureFailed(
            f"br {' '.join(arguments[:2])} emitted malformed JSON"
        ) from error


def br_read_json(
    *arguments: str,
    br_cwd: Path = REPO_ROOT,
) -> Any:
    return br_json(*arguments, *BR_READ_FLAGS, br_cwd=br_cwd)


def br_version(*, br_cwd: Path = REPO_ROOT) -> dict[str, Any]:
    document = br_read_json("version", "--json", br_cwd=br_cwd)
    if not isinstance(document, dict):
        raise InfrastructureFailed("br version --json did not return an object")
    required = {"version", "build", "commit", "target", "features"}
    if not required.issubset(document):
        raise InfrastructureFailed("br version identity is incomplete")
    return {key: document[key] for key in sorted(required)}


def v2_normalize_br_capability_commands(
    value: Any,
    *,
    error_type: type[HarnessError],
) -> list[dict[str, Any]]:
    fields = {
        "name",
        "summary",
        "operation",
        "workspace",
        "machine_output",
        "examples",
    }
    if not isinstance(value, list) or len(value) > V2_COMMAND_ARGUMENTS_CAP:
        raise error_type("br capabilities commands are malformed or over cap")
    normalized: list[dict[str, Any]] = []
    for index, row in enumerate(value):
        if not isinstance(row, dict) or set(row) != fields:
            raise error_type(
                f"br capabilities command {index} has a non-closed schema"
            )
        if any(
            not isinstance(row[field], str) or not row[field]
            for field in ("name", "summary", "operation", "workspace")
        ) or row["operation"] not in {"read", "write", "mixed", "unknown"}:
            raise error_type(
                f"br capabilities command {index} has invalid scalars"
            )
        for field in ("machine_output", "examples"):
            values = row[field]
            if (
                not isinstance(values, list)
                or len(values) > V2_COMMAND_ARGUMENTS_CAP
                or any(not isinstance(item, str) or not item for item in values)
                or len(values) != len(set(values))
            ):
                raise error_type(
                    f"br capabilities command {index} has invalid {field}"
                )
        normalized.append(
            {
                "name": row["name"],
                "summary": row["summary"],
                "operation": row["operation"],
                "workspace": row["workspace"],
                "machine_output": list(row["machine_output"]),
                "examples": list(row["examples"]),
            }
        )
    names = [row["name"] for row in normalized]
    if names != sorted(set(names)):
        raise error_type("br capabilities command names are noncanonical")
    return normalized


def br_capabilities(*, br_cwd: Path = REPO_ROOT) -> dict[str, Any]:
    document = br_read_json("capabilities", "--json", br_cwd=br_cwd)
    if not isinstance(document, dict):
        raise InfrastructureFailed("br capabilities --json did not return an object")
    if document.get("contract_version") != "br.capabilities.v1":
        raise InfrastructureFailed("unknown br capabilities contract")
    commands = v2_normalize_br_capability_commands(
        document.get("commands"),
        error_type=InfrastructureFailed,
    )
    return {
        "contract_version": document["contract_version"],
        "commands": commands,
        "operation_count": len(commands),
    }


def file_identity(relative: str) -> dict[str, Any]:
    path = REPO_ROOT / relative
    if not path.exists():
        return {"path": relative, "present": False}
    if not path.is_file():
        raise InfrastructureFailed(f"identity path is not a file: {relative}")
    digest = hashlib.sha256()
    total = 0
    with path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            digest.update(chunk)
    return {
        "path": relative,
        "present": True,
        "bytes": total,
        "identity": "sha256-v1:" + digest.hexdigest(),
    }


def source_file_identities() -> list[dict[str, Any]]:
    return [
        file_identity(".beads/beads.db"),
        file_identity(".beads/beads.db-wal"),
        file_identity(".beads/issues.jsonl"),
        file_identity(str(SCRIPT_REL)),
        file_identity(str(CASE_MANIFEST_REL)),
    ]


def normalize_document(document: Any, *, label: str) -> list[dict[str, Any]]:
    if isinstance(document, list):
        issues = document
        has_more = False
    elif isinstance(document, dict):
        issues = document.get("issues")
        has_more = bool(document.get("has_more"))
    else:
        issues = None
        has_more = False
    if not isinstance(issues, list):
        raise InfrastructureFailed(f"{label} has no issues array")
    if has_more:
        raise InfrastructureFailed(f"{label} is truncated")
    if len(issues) > CAPS["issues"]:
        raise InfrastructureFailed(f"{label} exceeds {CAPS['issues']} issue cap")
    return issues


def v2_list_issue_ids(
    document: Any,
    *,
    label: str,
) -> list[str]:
    expected_fields = {"issues", "has_more", "limit", "offset", "total"}
    if not isinstance(document, dict) or set(document) != expected_fields:
        raise InfrastructureFailed(
            f"{label} does not use the exact released-br list envelope"
        )
    rows = document["issues"]
    if (
        not isinstance(rows, list)
        or type(document["has_more"]) is not bool
        or document["has_more"] is not False
        or type(document["limit"]) is not int
        or document["limit"] != 0
        or type(document["offset"]) is not int
        or document["offset"] != 0
        or type(document["total"]) is not int
        or document["total"] != len(rows)
        or len(rows) > CAPS["issues"]
    ):
        raise InfrastructureFailed(
            f"{label} has a malformed, truncated, or inconsistent list envelope"
        )
    issue_ids: list[str] = []
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            raise InfrastructureFailed(
                f"{label} row {index} is not an object"
            )
        issue_id = row.get("id")
        if not isinstance(issue_id, str) or not issue_id:
            raise InfrastructureFailed(
                f"{label} row {index} has an invalid issue ID"
            )
        issue_ids.append(issue_id)
    issue_ids.sort()
    v2_assert_unique(issue_ids, label=f"{label} issue IDs")
    return issue_ids


def load_case_manifest() -> dict[str, Any]:
    path = resolve_safe(str(CASE_MANIFEST_REL), label="case manifest", must_exist=True)
    try:
        document = tomllib.loads(bounded_read(path).decode("utf-8"))
    except (UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        raise InputRefused(f"case manifest is malformed: {error}") from error
    if document.get("schema") != CASE_MANIFEST_SCHEMA:
        raise InputRefused("case manifest has an unknown schema")
    cases = document.get("case")
    if not isinstance(cases, list):
        raise InputRefused("case manifest must contain [[case]] rows")
    ids = [str(row.get("id", "")) for row in cases if isinstance(row, dict)]
    if len(ids) != len(set(ids)):
        raise InputRefused("case manifest contains duplicate case IDs")
    if tuple(ids) != EXPECTED_CASE_IDS:
        raise InputRefused(
            "case manifest membership/order differs from the frozen 21-case registry"
        )
    if tuple(str(value) for value in document.get("case_order", ())) != EXPECTED_CASE_IDS:
        raise InputRefused("case_order differs from the frozen 21-case registry")
    if int(document.get("case_count", -1)) != len(EXPECTED_CASE_IDS):
        raise InputRefused("case_count differs from the frozen registry")
    schema_contract = document.get("schema_contract")
    if not isinstance(schema_contract, dict):
        raise InputRefused("case manifest lacks schema_contract")
    required_case_fields = schema_contract.get("required_case_fields")
    if not isinstance(required_case_fields, list):
        raise InputRefused("schema_contract lacks required_case_fields")
    allowed_roles = set(str(value) for value in schema_contract.get("allowed_roles", ()))
    allowed_modes = set(str(value) for value in schema_contract.get("allowed_modes", ()))
    allowed_terminals = set(
        str(value) for value in schema_contract.get("allowed_terminals", ())
    )
    allowed_subject_terminals = set(
        str(value)
        for value in schema_contract.get("allowed_subject_terminals", ())
    )
    allowed_mutations = set(
        str(value)
        for value in schema_contract.get("allowed_mutation_bindings", ())
    )
    allowed_replays = set(
        str(value)
        for value in schema_contract.get("allowed_replay_bindings", ())
    )
    allowed_inner_categories = set(
        str(value)
        for value in schema_contract.get("allowed_inner_br_categories", ())
    )
    case_pattern = re.compile(str(schema_contract.get("case_id_pattern", r"$^")))
    for index, row in enumerate(cases):
        if not isinstance(row, dict):
            raise InputRefused(f"case row {index} is not a table")
        required = set(str(value) for value in required_case_fields)
        missing = sorted(required - set(row))
        if missing:
            raise InputRefused(f"{row.get('id', index)} lacks fields {missing}")
        extra = sorted(set(row) - required)
        if extra:
            raise InputRefused(f"{row['id']} has unknown fields {extra}")
        if int(row.get("ordinal", -1)) != index + 1:
            raise InputRefused(f"{row['id']} has a non-dense ordinal")
        if not case_pattern.fullmatch(str(row["id"])):
            raise InputRefused(f"{row['id']} has an invalid case ID")
        if str(row["role"]) not in allowed_roles:
            raise InputRefused(f"{row['id']} has an unknown role")
        if str(row["mode"]) not in allowed_modes:
            raise InputRefused(f"{row['id']} has an unknown mode")
        terminal = str(row["expected_terminal"])
        if terminal not in allowed_terminals:
            raise InputRefused(f"{row['id']} has unknown terminal {terminal}")
        if int(row["expected_exit"]) != 0:
            raise InputRefused(f"{row['id']} expectation harness must exit zero")
        if str(row["expected_subject_terminal"]) not in allowed_subject_terminals:
            raise InputRefused(f"{row['id']} has an unknown subject terminal")
        if str(row["mutation"]) not in allowed_mutations:
            raise InputRefused(f"{row['id']} has an unknown mutation binding")
        if str(row["replay"]) not in allowed_replays:
            raise InputRefused(f"{row['id']} has an unknown replay binding")
        if str(row["expected_inner_br_category"]) not in allowed_inner_categories:
            raise InputRefused(f"{row['id']} has an unknown inner br category")
        if row["expected_live_target_mutation"] is not False:
            raise InputRefused(f"{row['id']} may not mutate the live target")
        if bool(row["inverse_required"]) != (str(row["replay"]) == "inverse"):
            raise InputRefused(f"{row['id']} inverse/replay binding disagrees")
        if str(row["mode"]) == "--replay REL" and str(row["replay"]) != "artifact-only":
            raise InputRefused(f"{row['id']} --replay must be artifact-only")
    manifest_caps = document.get("caps")
    if not isinstance(manifest_caps, dict):
        raise InputRefused("case manifest lacks caps")
    if int(manifest_caps.get("max_targets_per_plan_shard", -1)) != CAPS[
        "plan_shard_rows"
    ]:
        raise InputRefused("manifest planning cap differs from harness")
    if int(manifest_caps.get("max_targets_per_apply_manifest", -1)) != CAPS[
        "apply_rows"
    ]:
        raise InputRefused("manifest apply cap differs from harness")
    document["case_count"] = len(cases)
    document["semantic_root"] = semantic_root(
        {key: value for key, value in document.items() if key != "semantic_root"}
    )
    return document


