        "allowed_fixture_engines",
        "expected_outer_terminal",
        "expected_outer_exit",
        "expected_live_tracker_mutation",
        "expected_refusal_requires_unchanged_projection",
        "expected_nodata_requires_unchanged_projection",
        "assertion_evidence_required",
        "assertion_skip_is_pass",
        "aggregate_count_only_is_pass",
        "exact_check_obligation_required",
        "compiled_executor_id",
        "runner",
    },
}


def v2_manifest_closed_field_list(
    value: Any,
    expected: Iterable[str],
) -> bool:
    return (
        isinstance(value, list)
        and all(isinstance(field, str) and field for field in value)
        and len(value) == len(set(value))
        and set(value) == set(expected)
    )


def v2_manifest_ordered_string_list(
    value: Any,
    expected: Sequence[str],
) -> bool:
    return (
        isinstance(value, list)
        and all(isinstance(item, str) and item for item in value)
        and len(value) == len(set(value))
        and tuple(value) == tuple(expected)
    )


def v2_compile_manifest_pattern(value: Any, *, label: str) -> re.Pattern[str]:
    if not isinstance(value, str) or not value:
        raise InputRefused(f"v2 manifest {label} must be a nonempty string")
    try:
        return re.compile(value)
    except re.error as error:
        raise InputRefused(
            f"v2 manifest {label} is not a valid regular expression"
        ) from error


def v2_validate_cap_terminal_contract(caps: Mapping[str, Any]) -> None:
    if (
        caps.get("cap_exceeded_terminal") != V2_CAP_EXCEEDED_TERMINAL
        or type(caps.get("cap_exceeded_live_target_mutation")) is not bool
        or caps["cap_exceeded_live_target_mutation"] is not False
    ):
        raise InputRefused("v2 manifest cap terminal contract is malformed")


def v2_validate_accepted_manifest_payload(payload: bytes) -> str:
    if re.fullmatch(
        r"sha256-v1:[0-9a-f]{64}",
        V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY,
    ) is None:
        raise EvidenceFailed(
            "accepted v2 manifest content identity pin is malformed"
        )
    if not isinstance(payload, bytes):
        raise EvidenceFailed(
            "accepted v2 manifest identity input must be exact bytes"
        )
    observed = "sha256-v1:" + hashlib.sha256(payload).hexdigest()
    if observed != V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY:
        raise InputRefused("accepted v2 manifest content identity drifted")
    return observed


def v2_harness_contract_identity(payload: bytes) -> str:
    if not isinstance(payload, bytes):
        raise EvidenceFailed(
            "v2 harness contract identity input must be exact bytes"
        )
    pin_pattern = re.compile(
        rb'(?m)(^V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY = \(\n'
        rb'    ")sha256-v1:[0-9a-f]{64}("\n\)$)'
    )
    normalized_pin = b"sha256-v1:" + (b"0" * 64)
    normalized, replacement_count = pin_pattern.subn(
        lambda match: match.group(1) + normalized_pin + match.group(2),
        payload,
    )
    if replacement_count != 1:
        raise EvidenceFailed(
            "v2 harness manifest-pin normalization site is not unique"
        )
    return "sha256-v1:" + hashlib.sha256(normalized).hexdigest()


def v2_validate_harness_contract_payload(
    payload: bytes,
    expected_identity: Any,
) -> str:
    if (
        not isinstance(expected_identity, str)
        or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", expected_identity) is None
    ):
        raise InputRefused(
            "v2 manifest harness contract identity is malformed"
        )
    observed = v2_harness_contract_identity(payload)
    if observed != expected_identity:
        raise InputRefused("accepted v2 harness contract identity drifted")
    return observed


def v2_validate_check_id(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError] = EvidenceFailed,
) -> str:
    if (
        not isinstance(value, str)
        or not value
        or value != value.strip()
        or len(value.encode("utf-8")) > V2_CHECK_ID_BYTES_CAP
        or V2_CHECK_ID_PATTERN.fullmatch(value) is None
    ):
        raise error_type(f"{label} is not a canonical bounded check ID")
    return value


def v2_validate_check_obligation(
    case: Mapping[str, Any],
    obligation: Any,
    *,
    error_type: type[HarnessError] = InputRefused,
) -> Mapping[str, Any]:
    assertion_id = str(case.get("assertion_id") or "")
    if (
        not isinstance(obligation, dict)
        or set(obligation) != V2_CHECK_OBLIGATION_FIELDS
    ):
        raise error_type(
            f"{assertion_id} has a non-closed check obligation"
        )
    ordered_check_ids = obligation.get("ordered_check_ids")
    check_count = obligation.get("check_count")
    if (
        obligation.get("case_id") != case.get("id")
        or type(check_count) is not int
        or not 1 <= check_count <= V2_ASSERTION_CHECKS_CAP
        or not isinstance(ordered_check_ids, list)
        or len(ordered_check_ids) != check_count
    ):
        raise error_type(
            f"{assertion_id} has a malformed check obligation"
        )
    validated_ids = [
        v2_validate_check_id(
            value,
            label=f"{assertion_id} obligated check {index}",
            error_type=error_type,
        )
        for index, value in enumerate(ordered_check_ids)
    ]
    if len(validated_ids) != len(set(validated_ids)):
        raise error_type(
            f"{assertion_id} check obligation contains duplicate IDs"
        )
    return obligation


def v2_check_obligation_root(
    case: Mapping[str, Any],
    obligation: Mapping[str, Any],
) -> str:
    return semantic_root(
        {
            "case_id": case["id"],
            "assertion_id": case["assertion_id"],
            "subject": case["subject"],
            "check_count": obligation["check_count"],
            "ordered_check_ids": obligation["ordered_check_ids"],
        }
    )


def v2_validate_check_obligation_registry(
    cases: Sequence[Mapping[str, Any]],
    obligations: Any,
    *,
    error_type: type[HarnessError] = InputRefused,
) -> Mapping[str, Mapping[str, Any]]:
    assertion_ids = [str(case.get("assertion_id") or "") for case in cases]
    if (
        not isinstance(obligations, dict)
        or list(obligations) != assertion_ids
    ):
        raise error_type(
            "v2 check-obligation order or membership differs from assertions"
        )
    for case in cases:
        assertion_id = str(case["assertion_id"])
        v2_validate_check_obligation(
            case,
            obligations[assertion_id],
            error_type=error_type,
        )
    return obligations


def v2_clone_runner_manifest(
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    if not isinstance(manifest, dict):
        raise EvidenceFailed(
            "accepted v2 runner manifest is not an object"
        )
    if (
        manifest.get("semantic_root")
        != semantic_root(
            {
                key: value
                for key, value in manifest.items()
                if key != "semantic_root"
            }
        )
    ):
        raise EvidenceFailed(
            "accepted v2 runner manifest has a stale semantic root"
        )
    source_cases = manifest.get("case")
    source_obligations = manifest.get("check_obligations")
    if not isinstance(source_cases, list):
        raise EvidenceFailed(
            "accepted v2 runner manifest has no ordered case registry"
        )
    v2_validate_check_obligation_registry(
        source_cases,
        source_obligations,
        error_type=EvidenceFailed,
    )
    snapshot = strict_json_loads(
        canonical_bytes(manifest),
        label="accepted v2 runner manifest snapshot",
        require_canonical=True,
    )
    if snapshot != manifest:
        raise EvidenceFailed(
            "accepted v2 runner manifest could not be cloned exactly"
        )
    snapshot_cases = snapshot.get("case")
    snapshot_obligations = snapshot.get("check_obligations")
    if (
        not isinstance(snapshot_cases, list)
        or not isinstance(snapshot_obligations, dict)
    ):
        raise EvidenceFailed(
            "accepted v2 runner manifest snapshot lost its registries"
        )
    assertion_ids = [
        str(case.get("assertion_id") or "") for case in snapshot_cases
    ]
    if set(snapshot_obligations) != set(assertion_ids):
        raise EvidenceFailed(
            "accepted v2 runner manifest snapshot changed obligation membership"
        )
    snapshot["check_obligations"] = {
        assertion_id: snapshot_obligations[assertion_id]
        for assertion_id in assertion_ids
    }
    v2_validate_check_obligation_registry(
        snapshot_cases,
        snapshot["check_obligations"],
        error_type=EvidenceFailed,
    )
    return snapshot


def load_case_manifest_v2() -> dict[str, Any]:
    if os.environ.get("FS_TEMPLATE_HYGIENE_FORBID_V2_LOAD") == "1":
        raise EvidenceFailed(
            "v2 manifest loading was forbidden by the v1 regression guard"
        )
    path = resolve_safe(
        str(CASE_MANIFEST_V2_REL),
        label="v2 case manifest",
        must_exist=True,
    )
    payload = bounded_read(path)
    content_identity = v2_validate_accepted_manifest_payload(payload)
    try:
        document = tomllib.loads(payload.decode("utf-8"))
    except (UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        raise InputRefused(f"v2 case manifest is malformed: {error}") from error
    if not isinstance(document, dict):
        raise InputRefused("v2 case manifest root must be a table")
    v2_exact_keys(document, V2_MANIFEST_TOP_LEVEL_KEYS, label="v2 case manifest")
    if (
        not isinstance(document["schema"], str)
        or type(document["schema_version"]) is not int
        or document["schema"] != V2_MANIFEST_SCHEMA
        or document["schema_version"] != 2
    ):
        raise InputRefused("v2 case manifest has an unknown schema or version")
    if (
        not isinstance(document["manifest_id"], str)
        or not isinstance(document["suite_id"], str)
        or not isinstance(document["bead_id"], str)
        or not isinstance(document["manifest_path"], str)
        or not isinstance(document["harness_path"], str)
        or type(document["immutable_after_acceptance"]) is not bool
        or not isinstance(document["tracker_authority"], str)
        or not isinstance(document["authority"], str)
        or not isinstance(document["no_claim"], str)
        or type(document["criterion_count"]) is not int
        or type(document["case_count"]) is not int
        or type(document["assertion_count"]) is not int
        or not isinstance(document["suite_status"], str)
        or document["suite_status"] != V2_SUITE_STATUS
        or not isinstance(document["harness_contract_identity"], str)
        or not isinstance(document["case_order"], list)
        or not all(
            isinstance(value, str) and value
            for value in document["case_order"]
        )
        or len(document["case_order"]) != len(set(document["case_order"]))
        or
        document["manifest_path"] != str(CASE_MANIFEST_V2_REL)
        or document["harness_path"] != str(SCRIPT_REL)
        or document["immutable_after_acceptance"] is not True
        or document["tracker_authority"] != "READ_ONLY"
    ):
        raise InputRefused("v2 manifest identity or authority contract drifted")
    harness_contract_identity = v2_validate_harness_contract_payload(
        bounded_read(REPO_ROOT / SCRIPT_REL),
        document["harness_contract_identity"],
    )
    for table_name, expected_keys in V2_MANIFEST_TABLE_KEYS.items():
        table = document.get(table_name)
        if not isinstance(table, dict):
            raise InputRefused(f"v2 manifest lacks table {table_name}")
        v2_exact_keys(table, expected_keys, label=f"v2 manifest {table_name}")
    if not v2_manifest_closed_field_list(
        document["schema_contract"]["allowed_top_level_keys"],
        V2_MANIFEST_TOP_LEVEL_KEYS,
    ):
        raise InputRefused("v2 allowed-top-level set differs from the harness")
    schema_contract = document["schema_contract"]
    if (
        schema_contract["criterion_bijection"] is not True
        or schema_contract["closed_inline_tables"] is not True
        or schema_contract["prose_assertions_authorize_pass"] is not False
        or schema_contract["compiled_executor_required"] is not True
        or schema_contract["aggregate_check_count_authorizes_pass"] is not False
        or schema_contract["check_obligation_policy"]
        != "EXACT_ORDERED_CHECK_IDS_CASE_ASSERTION_SUBJECT_AND_COUNT"
        or schema_contract["accepted_content_identity_policy"]
        != V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY_POLICY
        or schema_contract["harness_contract_identity_policy"]
        != V2_HARNESS_CONTRACT_IDENTITY_POLICY
        or schema_contract["retained_run_artifact_policy"]
        != V2_RETAINED_RUN_ARTIFACT_POLICY
        or schema_contract["portable_retained_run_proof"] is not False
        or schema_contract["check_id_pattern"]
        != V2_CHECK_ID_PATTERN_TEXT
    ):
        raise InputRefused(
            "v2 manifest assertion-obligation or identity policy drifted"
        )

    cases = document.get("case")
    criteria = document.get("criterion")
    if not isinstance(cases, list) or not isinstance(criteria, list):
        raise InputRefused("v2 manifest requires [[case]] and [[criterion]] rows")
    if len(cases) != 96 or document["case_count"] != 96:
        raise InputRefused("v2 manifest must contain exactly 96 cases")
    if document["assertion_count"] != len(cases):
        raise InputRefused("v2 assertion count must equal the case count")
    if len(criteria) != 25 or document["criterion_count"] != 25:
        raise InputRefused("v2 manifest must contain exactly AC01 through AC25")

    case_contract = document["case_contract"]
    if (
        not v2_manifest_closed_field_list(
            case_contract["required_fields"],
            V2_CASE_FIELDS,
        )
        or not v2_manifest_ordered_string_list(
            case_contract["allowed_kinds"],
            V2_CASE_KINDS,
        )
        or not v2_manifest_ordered_string_list(
            case_contract["allowed_fixture_engines"],
            V2_FIXTURE_ENGINES,
        )
    ):
        raise InputRefused("v2 case schema or enumerations differ from the harness")
    required_case_fields = set(V2_CASE_FIELDS)
    case_pattern_text = document["schema_contract"]["case_id_pattern"]
    assertion_pattern_text = document["schema_contract"][
        "assertion_id_pattern"
    ]
    case_pattern = v2_compile_manifest_pattern(
        case_pattern_text,
        label="case ID pattern",
    )
    assertion_pattern = v2_compile_manifest_pattern(
        assertion_pattern_text,
        label="assertion ID pattern",
    )
    allowed_kinds = set(V2_CASE_KINDS)
    allowed_engines = set(V2_FIXTURE_ENGINES)
    case_ids: list[str] = []
    assertion_ids: list[str] = []
    calculated_criteria: dict[str, list[str]] = defaultdict(list)
    for index, row in enumerate(cases):
        if not isinstance(row, dict):
            raise InputRefused(f"v2 case row {index} is not a table")
        v2_exact_keys(row, required_case_fields, label=f"v2 case row {index}")
        if (
            type(row["ordinal"]) is not int
            or not isinstance(row["id"], str)
            or not isinstance(row["assertion_id"], str)
            or not isinstance(row["fixture_engine"], str)
            or not isinstance(row["subject"], str)
        ):
            raise InputRefused(f"v2 case row {index} has invalid scalar types")
        case_id = row["id"]
        assertion_id = row["assertion_id"]
        if row["ordinal"] != index + 1:
            raise InputRefused(f"{case_id} has a non-dense v2 ordinal")
        if not case_pattern.fullmatch(case_id):
            raise InputRefused(f"{case_id} has an invalid v2 case ID")
        expected_assertion = "v2.case." + case_id.removeprefix(
            "template-lint-v2."
        )
        if (
            assertion_id != expected_assertion
            or not assertion_pattern.fullmatch(assertion_id)
        ):
            raise InputRefused(f"{case_id} has a non-derived assertion ID")
        row_kinds = row["kinds"]
        row_criteria = row["criterion_ids"]
        if (
            not isinstance(row_kinds, list)
            or not row_kinds
            or any(not isinstance(value, str) for value in row_kinds)
            or not set(row_kinds).issubset(allowed_kinds)
            or len(row_kinds) != len(set(row_kinds))
        ):
            raise InputRefused(f"{case_id} has malformed test kinds")
        if row["fixture_engine"] not in allowed_engines:
            raise InputRefused(f"{case_id} has an unknown fixture engine")
        if (
            not isinstance(row_criteria, list)
            or not row_criteria
            or any(not isinstance(value, str) for value in row_criteria)
            or len(row_criteria) != len(set(row_criteria))
        ):
            raise InputRefused(f"{case_id} has malformed criterion IDs")
        for criterion_id in row_criteria:
            calculated_criteria[criterion_id].append(assertion_id)
        case_ids.append(case_id)
        assertion_ids.append(assertion_id)
    v2_assert_unique(case_ids, label="v2 case IDs")
    v2_assert_unique(assertion_ids, label="v2 assertion IDs")
    if document["case_order"] != case_ids:
        raise InputRefused("v2 case_order differs from dense case rows")
    v2_validate_check_obligation_registry(
        cases,
        document["check_obligations"],
    )

    criterion_ids = [f"AC{index:02d}" for index in range(1, 26)]
    actual_criterion_ids: list[str] = []
    for index, row in enumerate(criteria):
        if not isinstance(row, dict):
            raise InputRefused(f"v2 criterion row {index} is not a table")
        v2_exact_keys(
            row,
            {"id", "assertion_ids"},
            label=f"v2 criterion row {index}",
        )
        criterion_id = str(row["id"])
        if (
            not isinstance(row["id"], str)
            or not isinstance(row["assertion_ids"], list)
            or any(
                not isinstance(value, str)
                for value in row["assertion_ids"]
            )
        ):
            raise InputRefused(
                f"v2 criterion row {index} has invalid scalar types"
            )
        criterion_id = row["id"]
        actual_criterion_ids.append(criterion_id)
        expected_assertions = calculated_criteria.get(criterion_id, [])
        if row["assertion_ids"] != expected_assertions:
            raise InputRefused(
                f"{criterion_id} assertion links differ from case declarations"
            )
    if actual_criterion_ids != criterion_ids:
        raise InputRefused("v2 criteria are not exactly ordered AC01 through AC25")
    unknown_criteria = sorted(set(calculated_criteria) - set(criterion_ids))
    if unknown_criteria:
        raise InputRefused(f"v2 cases reference unknown criteria {unknown_criteria}")

    caps = document["caps"]
    expected_caps = {
        "max_inventory_rows": V2_INVENTORY_ROWS_CAP,
        "max_warning_rows": V2_WARNING_ROWS_CAP,
        "max_warnings_per_issue": V2_WARNINGS_PER_ISSUE_CAP,
        "default_targets_per_child": V2_REVIEW_TARGET_DEFAULT,
        "hard_max_targets_per_child": V2_REVIEW_TARGET_HARD_MAX,
        "max_review_minutes_per_child": V2_REVIEW_MINUTES_CAP,
        "max_retained_child_payload_bytes": V2_CHILD_PAYLOAD_CAP,
        "max_generated_child_payload_bytes": (
            V2_GENERATED_CHILD_PAYLOAD_CAP
        ),
        "max_description_bytes": V2_CHILD_DESCRIPTION_CAP,
        "max_acceptance_bytes": V2_CHILD_ACCEPTANCE_CAP,
        "max_design_bytes": V2_CHILD_DESIGN_CAP,
        "max_notes_bytes": V2_CHILD_NOTES_CAP,
        "max_aggregate_non_description_argv_bytes": (
            V2_CHILD_ARGV_AGGREGATE_CAP
        ),
        "max_child_transport_cache_entries": (
            V2_CHILD_TRANSPORT_CACHE_ENTRIES_CAP
        ),
        "max_clause_bytes": V2_CLAUSE_BYTES_CAP,
        "max_clause_rows_per_issue": V2_CLAUSE_ROWS_CAP,
        "max_labels_per_issue": V2_LABELS_PER_ISSUE_CAP,
        "max_relations_per_direction": V2_RELATIONS_PER_DIRECTION_CAP,
        "max_audit_events_per_issue": V2_AUDIT_EVENTS_PER_ISSUE_CAP,
        "max_audit_stream_bytes": V2_AUDIT_STREAM_BYTES_CAP,
        "max_audit_capture_bytes": V2_AUDIT_CAPTURE_BYTES_CAP,
        "max_source_projection_bytes": V2_SOURCE_PROJECTION_BYTES_CAP,
        "max_history_citations_per_issue": (
            V2_HISTORY_CITATIONS_PER_ISSUE_CAP
        ),
        "max_compatibility_targets_per_receipt": (
            V2_COMPATIBILITY_TARGETS_PER_RECEIPT_CAP
        ),
        "max_command_arguments": V2_COMMAND_ARGUMENTS_CAP,
        "max_command_argument_bytes": V2_COMMAND_ARGUMENT_BYTES_CAP,
        "max_authority_identity_bytes": V2_AUTHORITY_IDENTITY_BYTES_CAP,
        "max_relative_path_bytes": CAPS["relative_path_bytes"],
        "max_path_component_bytes": CAPS["path_component_bytes"],
        "max_path_depth": CAPS["path_depth"],
        "max_artifact_bytes": RUN_ARTIFACT_CAP,
        "max_log_events": V2_LOG_EVENTS_CAP,
        "max_log_line_bytes": V2_LOG_LINE_BYTES_CAP,
        "max_assertion_checks": V2_ASSERTION_CHECKS_CAP,
        "max_check_id_bytes": V2_CHECK_ID_BYTES_CAP,
        "max_diagnostic_summary_bytes": V2_DIAGNOSTIC_SUMMARY_BYTES_CAP,
        "max_synopsis_bytes": V2_SYNOPSIS_BYTES_CAP,
        "max_synopsis_selected_ids": V2_SYNOPSIS_ID_PREVIEW_CAP,
        "max_subprocess_stdin_bytes": CAPS["subprocess_stdout_bytes"],
        "max_subprocess_stdout_bytes": CAPS["subprocess_stdout_bytes"],
        "max_subprocess_stderr_bytes": CAPS["subprocess_stdout_bytes"],
        "subprocess_timeout_seconds": CAPS["subprocess_timeout_seconds"],
        "max_persistent_attempts": V2_PERSISTENT_ATTEMPTS_CAP,
        "max_bundle_files": V2_BUNDLE_FILES_CAP,
        "max_bundle_directories": V2_BUNDLE_DIRECTORIES_CAP,
        "max_bundle_enumerated_path_bytes": (
            V2_BUNDLE_ENUMERATED_PATH_BYTES_CAP
        ),
        "max_cases": 96,
        "exact_optimality_max_targets": V2_EXACT_OPTIMALITY_MAX_TARGETS,
    }
    for name, expected in expected_caps.items():
        if type(caps[name]) is not int or caps[name] != expected:
            raise InputRefused(f"v2 manifest cap {name} differs from the harness")
    v2_validate_cap_terminal_contract(caps)
    if document["case_contract"]["exact_check_obligation_required"] is not True:
        raise InputRefused(
            "v2 case contract does not require exact check obligations"
        )
    if not v2_manifest_ordered_string_list(
        document["artifact_contract"]["base_set"],
        V2_RUN_ARTIFACTS,
    ):
        raise InputRefused("v2 manifest base artifact set differs from the harness")
    if (
        not v2_manifest_closed_field_list(
            document["artifact_contract"][
                "oversize_inventory_required_fields"
            ],
            V2_OVERSIZE_REGISTRY_FIELDS,
        )
        or not v2_manifest_closed_field_list(
            document["artifact_contract"][
                "not_requested_required_fields"
            ],
            V2_NOT_REQUESTED_FIELDS,
        )
        or document["artifact_contract"]["not_requested_state"]
        != "NOT_REQUESTED"
        or document["artifact_contract"]["review_plan_selected"]
        != "review-plan-v2.json"
        or document["artifact_contract"]["review_plan_not_requested"]
        != "history-v2.json"
        or document["artifact_contract"]["history_plan_selected"]
        != "history-v2.json"
        or document["artifact_contract"]["history_plan_not_requested"]
        != "review-plan-v2.json"
        or document["artifact_contract"]["publication_root_creation"]
        != "OPENAT_MKDIRAT_O_NOFOLLOW_FROM_REPOSITORY_DESCRIPTOR"
        or document["artifact_contract"]["publication_parent_durability"]
        != "FSYNC_EACH_PARENT_AFTER_CHILD_CREATION"
    ):
        raise InputRefused("v2 artifact publication contract differs")
    logging_contract = document["logging_contract"]
    if (
        logging_contract["format"] != "JSONL"
        or logging_contract["encoding"] != "UTF-8"
        or logging_contract["schema"] != V2_EVENT_SCHEMA
        or logging_contract["self_test_schema"] != V2_TEST_EVENT_SCHEMA
        or logging_contract["self_test_terminal_schema"]
        != V2_TEST_TERMINAL_SCHEMA
        or logging_contract["preflight_terminal_schema"]
