    "no_claim",
}
V2_REVIEW_RECEIPT_SCOPE_SCHEMA = (
    "frankensim.beads-template-hygiene.review-receipt-scope.v2"
)
V2_REVIEW_RECEIPT_PROVENANCE_FIELDS = (
    "inventory_root",
    "campaign_epoch_root",
)
V2_REVIEW_RECEIPT_SCOPE_FIELDS = (
    "target_id",
    "target_root",
    "reviewer",
    "reviewer_kind",
    "coordination_assignee",
    "declared_domain_owner",
    "declared_acceptance_owner",
    "implementation_owner",
    "evidence_owner",
    "terminal_consumer",
    "source_closure",
    "user_effect",
    "review_minutes",
    "semantic_review_disposition",
    "semantic_review_dimensions",
    "semantic_review_rationale",
    "semantic_review_falsifier",
    "compatibility_key",
    "compatibility_target_ids",
    "compatibility_receipt_root",
    "compatibility_rationale",
    "compatibility_falsifier",
    "manual_authorization",
    "manual_authorization_source",
    "external_authority_adapter",
    "external_authority_receipt_root",
    "external_authority_verdict",
    "conditional_capability_identity",
    "conditional_capability_receipt_root",
    "conditional_capability_verdict",
    "gate_admission_receipt_root",
    "gate_admission_verdict",
    "no_claim",
)
if (
    len(V2_REVIEW_RECEIPT_SCOPE_FIELDS)
    != len(set(V2_REVIEW_RECEIPT_SCOPE_FIELDS))
    or len(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS)
    != len(set(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS))
    or bool(
        set(V2_REVIEW_RECEIPT_SCOPE_FIELDS)
        & set(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS)
    )
    or (
        set(V2_REVIEW_RECEIPT_SCOPE_FIELDS)
        | set(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS)
    )
    != V2_REVIEW_RECEIPT_FIELDS
):
    raise RuntimeError(
        "review receipt scope/provenance fields do not exactly partition "
        "the closed receipt schema"
    )


def v2_review_receipt_scope_root(receipt: Mapping[str, Any]) -> str:
    receipt_fields = set(receipt) - {"semantic_root"}
    if receipt_fields != V2_REVIEW_RECEIPT_FIELDS:
        raise InputRefused(
            "review receipt scope root requires the exact closed row schema"
        )
    return semantic_root(
        {
            "schema": V2_REVIEW_RECEIPT_SCOPE_SCHEMA,
            "receipt": {
                field: receipt[field]
                for field in V2_REVIEW_RECEIPT_SCOPE_FIELDS
            },
        }
    )


def v2_validate_review_receipt_document_provenance(
    receipt_document: Mapping[str, Any],
    receipts: Sequence[Any],
    *,
    inventory: Mapping[str, Any] | None,
    label: str,
) -> None:
    for field in V2_REVIEW_RECEIPT_PROVENANCE_FIELDS:
        value = receipt_document.get(field)
        if (
            not isinstance(value, str)
            or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", value) is None
        ):
            raise InputRefused(f"{label} {field} is malformed")
    if not receipts and inventory is not None and (
        receipt_document["inventory_root"] != inventory.get("semantic_root")
        or receipt_document["campaign_epoch_root"]
        != inventory.get("campaign_epoch_root")
    ):
        raise InputRefused(
            f"{label} empty envelope does not bind the current campaign"
        )


def v2_validate_review_receipt_row_provenance(
    receipt: Mapping[str, Any],
    receipt_document: Mapping[str, Any],
    *,
    label: str,
) -> None:
    for field in V2_REVIEW_RECEIPT_PROVENANCE_FIELDS:
        value = receipt.get(field)
        if (
            not isinstance(value, str)
            or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", value) is None
            or value != receipt_document[field]
        ):
            raise InputRefused(
                f"{label} {field} differs from its provenance envelope"
            )

V2_AUTHORITY_IDENTITY_FIELDS = (
    "reviewer",
    "reviewer_kind",
    "coordination_assignee",
    "declared_domain_owner",
    "declared_acceptance_owner",
    "implementation_owner",
    "evidence_owner",
    "terminal_consumer",
    "manual_authorization_source",
    "external_authority_adapter",
    "conditional_capability_identity",
)


def v2_validate_receipt_authority_identities(
    receipt: Mapping[str, Any],
    *,
    target_id: str,
) -> None:
    for field_name in V2_AUTHORITY_IDENTITY_FIELDS:
        value = receipt.get(field_name)
        if (
            not isinstance(value, str)
            or value != value.strip()
            or value != unicodedata.normalize("NFC", value)
            or len(value.encode("utf-8")) > V2_AUTHORITY_IDENTITY_BYTES_CAP
            or any(
                unicodedata.category(character) in {"Cc", "Cf", "Cs"}
                for character in value
            )
        ):
            raise InputRefused(
                "review receipt authority identity is noncanonical for "
                f"{target_id}: {field_name}"
            )
    reserved_presence_keys = {
        "nodata",
        "unresolved",
        "unknown",
        "none",
        "notprovided",
        "unassigned",
        "unset",
        "missing",
        "na",
        "notapplicable",
        "notset",
        "null",
        "nil",
        "tbd",
        "tba",
        "noowner",
        "noreviewer",
    }
    for field_name in V2_AUTHORITY_IDENTITY_FIELDS:
        value = receipt[field_name]
        compatibility_normalized = unicodedata.normalize(
            "NFKC",
            value,
        ).casefold()
        normalized_presence = "".join(
            character
            for character in compatibility_normalized
            if character.isalnum()
        )
        if value and not normalized_presence:
            raise InputRefused(
                "review receipt authority identity contains no alphanumeric "
                f"identity for {target_id}: {field_name}"
            )
        if normalized_presence in reserved_presence_keys:
            raise InputRefused(
                "review receipt authority identity uses a reserved no-data "
                f"sentinel for {target_id}: {field_name}"
            )
    reviewer_present = bool(receipt["reviewer"])
    reviewer_kind_present = bool(receipt["reviewer_kind"])
    if reviewer_present != reviewer_kind_present:
        raise InputRefused(
            f"review receipt reviewer identity is incomplete for {target_id}"
        )
    manual_authorization = receipt.get("manual_authorization")
    manual_source = receipt["manual_authorization_source"]
    if type(manual_authorization) is not bool:
        raise InputRefused(
            f"review receipt manual authorization is not boolean for {target_id}"
        )
    if manual_authorization:
        if (
            not manual_source
            or not reviewer_present
            or not receipt["declared_acceptance_owner"]
        ):
            raise InputRefused(
                "review receipt manual authorization lacks its canonical "
                f"reviewer, acceptance owner, or source for {target_id}"
            )
    elif manual_source:
        raise InputRefused(
            "review receipt has a manual-authorization source while manual "
            f"authorization is false for {target_id}"
        )


def v2_validate_source_closure_transition(
    *,
    target: Mapping[str, Any],
    receipt: Mapping[str, Any],
    semantic_complete: bool,
) -> None:
    target_id = str(target["id"])
    target_closure = target.get("source_closure")
    receipt_closure = receipt.get("source_closure")
    for label, closure in (
        ("target", target_closure),
        ("receipt", receipt_closure),
    ):
        if not isinstance(closure, dict):
            raise InputRefused(
                f"review receipt {label} source closure is not an object "
                f"for {target_id}"
            )
        v2_exact_keys(
            closure,
            {"required", "state"},
            label=f"review receipt {label} source closure for {target_id}",
        )
        if (
            type(closure["required"]) is not bool
            or not isinstance(closure["state"], str)
            or closure["state"] not in V2_SOURCE_CLOSURE_STATES
        ):
            raise InputRefused(
                f"review receipt {label} source closure is outside its "
                f"closed state set for {target_id}"
            )
    if receipt_closure["required"] != target_closure["required"]:
        raise InputRefused(
            f"review receipt changes the source-closure obligation for {target_id}"
        )
    if not target_closure["required"]:
        if receipt_closure != target_closure:
            raise InputRefused(
                f"review receipt changes a not-required source closure for {target_id}"
            )
        return
    if target_closure["state"] != "REVIEW_REQUIRED":
        raise InputRefused(
            f"required target source closure has an invalid base state for {target_id}"
        )
    expected_state = "REVIEW_REQUIRED"
    if semantic_complete:
        dimensions = {
            str(row["dimension"]): str(row["verdict"])
            for row in receipt["semantic_review_dimensions"]
        }
        closure_verdict = dimensions["source_and_terminal_closure"]
        if closure_verdict == "SATISFIED":
            expected_state = "ROOT_BOUND_REVIEWED_COMPLETE"
        elif closure_verdict == "NOT_APPLICABLE":
            expected_state = "ROOT_BOUND_NOT_APPLICABLE"
        else:
            expected_state = "ROOT_BOUND_REVIEW_BLOCKED"
    if receipt_closure["state"] != expected_state:
        raise InputRefused(
            "review receipt source-closure transition disagrees with its "
            f"root-bound semantic disposition for {target_id}"
        )


def v2_empty_review_receipts(
    *, inventory_root: str, campaign_epoch_root: str
) -> dict[str, Any]:
    return v2_rooted(
        {
            "schema": V2_REVIEW_RECEIPTS_SCHEMA,
            "inventory_root": inventory_root,
            "campaign_epoch_root": campaign_epoch_root,
            "receipts": [],
            "source": "NOT_PROVIDED",
            "no_claim": V2_REVIEW_RECEIPTS_NO_CLAIM,
        }
    )


def v2_load_review_receipts(
    relative: str | None,
    *,
    inventory: Mapping[str, Any],
) -> dict[str, Any]:
    if relative is None:
        return v2_empty_review_receipts(
            inventory_root=str(inventory["semantic_root"]),
            campaign_epoch_root=str(inventory["campaign_epoch_root"]),
        )
    relative_path = safe_relative(relative, label="review receipts")
    if relative_path.suffix != ".json":
        raise InputRefused("review receipts must be a closed JSON document")
    payload = v2_read_repo_relative_file_strict(
        relative,
        label="review receipts",
    )
    document = strict_json_loads(
        payload,
        label="review receipts",
        require_canonical=True,
    )
    if not isinstance(document, dict):
        raise InputRefused("review receipts must be an object")
    v2_exact_keys(
        document,
        {
            "schema",
            "inventory_root",
            "campaign_epoch_root",
            "receipts",
            "source",
            "no_claim",
        },
        label="review receipts",
    )
    if document["schema"] != V2_REVIEW_RECEIPTS_SCHEMA:
        raise InputRefused("unknown review-receipts schema")
    if (
        not isinstance(document["inventory_root"], str)
        or not isinstance(document["campaign_epoch_root"], str)
        or not isinstance(document["source"], str)
        or not document["source"].strip()
        or document["no_claim"] != V2_REVIEW_RECEIPTS_NO_CLAIM
    ):
        raise InputRefused("review receipts contain invalid document scalars")
    receipts = document["receipts"]
    if not isinstance(receipts, list):
        raise InputRefused("review receipts must contain an array")
    if len(receipts) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused("review receipts exceed the inventory-row cap")
    v2_validate_review_receipt_document_provenance(
        document,
        receipts,
        inventory=inventory,
        label="review receipts",
    )
    inventory_by_id = {row["id"]: row for row in inventory["rows"]}
    normalized: list[dict[str, Any]] = []
    for index, receipt in enumerate(receipts):
        if not isinstance(receipt, dict):
            raise InputRefused(f"review receipt {index} is not an object")
        v2_exact_keys(
            receipt,
            V2_REVIEW_RECEIPT_FIELDS,
            label=f"review receipt {index}",
        )
        if not isinstance(receipt["target_id"], str) or not receipt["target_id"]:
            raise InputRefused(f"review receipt {index} has an invalid target ID")
        target_id = receipt["target_id"]
        if target_id not in inventory_by_id:
            raise InputRefused(f"review receipt targets unknown {target_id}")
        if receipt["target_root"] != inventory_by_id[target_id]["target_root"]:
            raise InputRefused(f"review receipt target root drifted for {target_id}")
        v2_validate_review_receipt_row_provenance(
            receipt,
            document,
            label=f"review receipt {target_id}",
        )
        review_minutes = receipt["review_minutes"]
        if type(review_minutes) is not int or review_minutes < 0:
            raise InputRefused(f"review receipt minutes are invalid for {target_id}")
        if receipt["external_authority_verdict"] not in {
            "NODATA",
            "VALID",
            "INVALID",
            "REVOKED",
            "EXPIRED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt external-authority verdict is unknown for {target_id}"
            )
        if receipt["conditional_capability_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "LYING",
            "NON_ATOMIC",
            "VERSION_MISMATCHED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt conditional-capability verdict is unknown for {target_id}"
            )
        if receipt["gate_admission_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt gate-admission verdict is unknown for {target_id}"
            )
        targets = v2_validate_compatibility_target_ids(
            receipt["compatibility_target_ids"],
            label=f"compatibility target IDs for {target_id}",
        )
        if targets and target_id not in targets:
            raise InputRefused(
                f"compatibility set does not include its target {target_id}"
            )
        if any(value not in inventory_by_id for value in targets):
            raise InputRefused(
                f"compatibility set includes an unknown target for {target_id}"
            )
        string_fields = V2_REVIEW_RECEIPT_FIELDS - {
            "compatibility_target_ids",
            "review_minutes",
            "manual_authorization",
            "source_closure",
            "semantic_review_dimensions",
        }
        if any(not isinstance(receipt[field], str) for field in string_fields):
            raise InputRefused(
                f"review receipt contains a non-string scalar for {target_id}"
            )
        if receipt["no_claim"] != V2_REVIEW_RECEIPT_ROW_NO_CLAIM:
            raise InputRefused(
                f"review receipt no-claim boundary differs for {target_id}"
            )
        if type(receipt["manual_authorization"]) is not bool:
            raise InputRefused(
                f"review receipt manual authorization is not boolean for {target_id}"
            )
        v2_validate_receipt_authority_identities(
            receipt,
            target_id=target_id,
        )
        if not isinstance(receipt["source_closure"], dict):
            raise InputRefused(
                f"review receipt source closure is not an object for {target_id}"
            )
        v2_exact_keys(
            receipt["source_closure"],
            {"required", "state"},
            label=f"review receipt source closure for {target_id}",
        )
        if (
            type(receipt["source_closure"]["required"]) is not bool
            or not isinstance(receipt["source_closure"]["state"], str)
            or not receipt["source_closure"]["state"]
        ):
            raise InputRefused(
                f"review receipt source closure scalars are invalid for {target_id}"
            )
        for root_field in (
            "compatibility_receipt_root",
            "external_authority_receipt_root",
            "conditional_capability_receipt_root",
            "gate_admission_receipt_root",
        ):
            root_value = str(receipt[root_field])
            if root_value and not re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                root_value,
            ):
                raise InputRefused(
                    f"review receipt {root_field} is malformed for {target_id}"
                )
        semantic_disposition = receipt["semantic_review_disposition"]
        if semantic_disposition not in V2_SEMANTIC_REVIEW_DISPOSITIONS:
            raise InputRefused(
                f"review receipt semantic disposition is unknown for {target_id}"
            )
        semantic_complete = v2_validate_semantic_dimension_receipts(
            receipt["semantic_review_dimensions"],
            target_root=str(receipt["target_root"]),
            disposition=semantic_disposition,
            allow_empty=True,
            label=f"review receipt semantic dimensions for {target_id}",
        )
        v2_validate_source_closure_transition(
            target=inventory_by_id[target_id],
            receipt=receipt,
            semantic_complete=semantic_complete,
        )
        if semantic_complete:
            if (
                not receipt["reviewer"].strip()
                or not receipt["reviewer_kind"].strip()
                or not receipt["semantic_review_rationale"].strip()
                or not receipt["semantic_review_falsifier"].strip()
            ):
                raise InputRefused(
                    f"review receipt semantic adjudication is incomplete for {target_id}"
                )
        elif (
            receipt["semantic_review_rationale"]
            or receipt["semantic_review_falsifier"]
            or semantic_disposition
            != inventory_by_id[target_id]["semantic_review_disposition"]
        ):
            raise InputRefused(
                f"review receipt claims semantic adjudication without dimensions for {target_id}"
            )
        normalized.append(v2_rooted(receipt))
    original_target_ids = [row["target_id"] for row in normalized]
    v2_assert_unique(
        original_target_ids,
        label="review receipt target IDs",
    )
    if original_target_ids != sorted(original_target_ids):
        raise InputRefused("review receipt rows are not in canonical target order")
    normalized.sort(key=lambda row: row["target_id"])
    result = dict(document)
    result["receipts"] = normalized
    result["source_identity"] = {
        "path": relative,
        "bytes": len(payload),
        "root": "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
    }
    rooted = v2_rooted(result)
    v2_validate_receipt_bindings(rooted, inventory)
    return rooted


def v2_validate_compatibility_receipts(
    receipts: Mapping[str, Mapping[str, Any]],
    inventory: Mapping[str, Any],
) -> None:
    inventory_by_id = {row["id"]: row for row in inventory["rows"]}
    groups: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for receipt in receipts.values():
        key = str(receipt.get("compatibility_key") or "")
        if key:
            groups[key].append(receipt)
        elif any(
            receipt.get(field)
            for field in (
                "compatibility_target_ids",
                "compatibility_receipt_root",
                "compatibility_rationale",
                "compatibility_falsifier",
            )
        ):
            raise InputRefused(
                f"target {receipt['target_id']} has compatibility data without a key"
            )
    for key, group in groups.items():
        expected_ids = sorted(str(row["target_id"]) for row in group)
        roots = {str(row.get("compatibility_receipt_root") or "") for row in group}
        rationales = {str(row.get("compatibility_rationale") or "") for row in group}
        falsifiers = {str(row.get("compatibility_falsifier") or "") for row in group}
        declared_sets = {
            tuple(sorted(str(value) for value in row["compatibility_target_ids"]))
            for row in group
        }
        if (
            "" in roots
            or "" in rationales
            or "" in falsifiers
            or len(roots) != 1
            or len(rationales) != 1
            or len(falsifiers) != 1
            or declared_sets != {tuple(expected_ids)}
        ):
            raise InputRefused(
                f"compatibility receipt {key!r} is not target-complete"
            )
        coordination = sorted(
            {
                str(row["target_id"]): str(row["coordination_assignee"])
                for row in group
            }.items()
        )
        declared_domain = sorted(
            {
                str(row["target_id"]): str(row["declared_domain_owner"])
                for row in group
            }.items()
        )
        user_effect = sorted(
            {
                str(row["target_id"]): str(row["user_effect"])
                for row in group
            }.items()
        )
        dependency_neighborhood = sorted(
            (
                target_id,
                str(inventory_by_id[target_id]["dependency_neighborhood_root"]),
            )
            for target_id in expected_ids
        )
        target_roots = sorted(
            (
                target_id,
                str(inventory_by_id[target_id]["target_root"]),
            )
            for target_id in expected_ids
        )
        computed = semantic_root(
            {
                "compatibility_key": key,
                "coordination": coordination,
                "declared_domain": declared_domain,
                "user_effect": user_effect,
                "dependency_neighborhood": dependency_neighborhood,
                "target_ids": expected_ids,
                "target_roots": target_roots,
                "rationale": next(iter(rationales)),
                "falsifier": next(iter(falsifiers)),
            }
        )
        if roots != {computed}:
            raise InputRefused(
                f"compatibility receipt {key!r} root does not match its scope"
            )


def v2_reconstructed_review_receipt_source_payload(
    receipt_document: Mapping[str, Any],
) -> bytes:
    source_document = {
        key: value
        for key, value in receipt_document.items()
        if key not in {"semantic_root", "source_identity"}
    }
    rows = source_document.get("receipts")
    if not isinstance(rows, list) or any(
        not isinstance(row, dict) for row in rows
    ):
        raise InputRefused(
            "review receipt source payload cannot be reconstructed"
        )
    if len(rows) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "review receipt source payload exceeds the inventory-row cap"
        )
    source_document["receipts"] = [
        {
            key: value
            for key, value in row.items()
            if key != "semantic_root"
        }
        for row in rows
    ]
    return canonical_bytes(source_document)


def v2_validate_review_receipt_source_identity(
    receipt_document: Mapping[str, Any],
    *,
    label: str,
) -> None:
    source = receipt_document.get("source")
    source_identity = receipt_document.get("source_identity")
    generated_sources = {"NOT_PROVIDED", "SYNTHETIC_FIXTURE"}
    if source in generated_sources:
        if source_identity is not None:
            raise InputRefused(
                f"{label} generated source must not carry a file identity"
            )
        return
    if source_identity is None:
        raise InputRefused(f"{label} lacks its required file identity")
    if not isinstance(source_identity, dict):
        raise InputRefused(f"{label} source identity is not an object")
    v2_exact_keys(
        source_identity,
        {"path", "bytes", "root"},
        label=f"{label} source identity",
    )
    try:
        normalized_path = str(
            safe_relative(
                source_identity["path"],
                label=f"{label} source identity path",
            )
        )
    except (KeyError, TypeError, UsageRefused) as error:
        raise InputRefused(f"{label} source identity path is malformed") from error
    reconstructed = v2_reconstructed_review_receipt_source_payload(
        receipt_document
    )
    expected_root = (
        "sha256-v1:" + hashlib.sha256(reconstructed).hexdigest()
    )
    if (
        normalized_path != source_identity["path"]
        or type(source_identity["bytes"]) is not int
        or source_identity["bytes"] != len(reconstructed)
        or not isinstance(source_identity["root"], str)
        or source_identity["root"] != expected_root
    ):
        raise InputRefused(
            f"{label} source identity does not bind reconstructed canonical bytes"
        )


def v2_validate_compatibility_target_ids(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError] = InputRefused,
) -> list[str]:
    if not isinstance(value, list):
        raise error_type(f"{label} must be an array")
    if len(value) > V2_COMPATIBILITY_TARGETS_PER_RECEIPT_CAP:
        raise error_type(f"{label} exceed their cap")
    if any(
        not isinstance(target_id, str)
        or not target_id
        or target_id != target_id.strip()
        for target_id in value
    ):
        raise error_type(f"{label} are malformed")
    if value != sorted(set(value)):
        raise error_type(f"{label} are noncanonical")
    return value


def v2_fixture_gate_receipt_root(
    gate: str,
    *,
    target_root: str,
) -> str:
    if gate not in {"external", "conditional", "admission"}:
        raise EvidenceFailed(f"unsupported synthetic fixture gate {gate!r}")
    return semantic_root(
        {
            "gate": gate,
            "target_root": target_root,
        }
    )


def v2_validate_receipt_bindings(
    receipt_document: Mapping[str, Any],
    inventory: Mapping[str, Any],
) -> None:
    allowed_document_keys = {
        "schema",
        "inventory_root",
        "campaign_epoch_root",
        "receipts",
        "source",
        "source_identity",
        "no_claim",
        "semantic_root",
    }
    required_document_keys = allowed_document_keys - {"source_identity"}
    if (
        not required_document_keys.issubset(receipt_document)
        or not set(receipt_document).issubset(allowed_document_keys)
        or receipt_document.get("schema") != V2_REVIEW_RECEIPTS_SCHEMA
        or not isinstance(receipt_document.get("source"), str)
        or not str(receipt_document.get("source")).strip()
        or receipt_document.get("no_claim")
        != V2_REVIEW_RECEIPTS_NO_CLAIM
    ):
        raise InputRefused("review receipts bind a different source or schema")
    rows = receipt_document.get("receipts")
    if (
        not isinstance(rows, list)
        or len(rows) > V2_INVENTORY_ROWS_CAP
    ):
        raise InputRefused("review receipts must contain an array")
    v2_validate_review_receipt_document_provenance(
        receipt_document,
        rows,
        inventory=inventory,
        label="review receipts",
    )
    verify_semantic_root(receipt_document, label="v2 review receipts")
    v2_validate_review_receipt_source_identity(
        receipt_document,
        label="review receipts",
    )
    inventory_by_id = {row["id"]: row for row in inventory["rows"]}
    observed_ids: list[str] = []
    for index, receipt in enumerate(rows):
        if not isinstance(receipt, dict):
            raise InputRefused(f"review receipt {index} is not an object")
        v2_exact_keys(
            receipt,
            {*V2_REVIEW_RECEIPT_FIELDS, "semantic_root"},
            label=f"review receipt {index}",
        )
        verify_semantic_root(receipt, label=f"review receipt {index}")
        target_id = receipt["target_id"]
        if not isinstance(target_id, str) or not target_id:
            raise InputRefused(f"review receipt {index} has an invalid target ID")
        if target_id not in inventory_by_id:
            raise InputRefused(f"review receipt targets unknown {target_id}")
        target = inventory_by_id[target_id]
        if receipt["target_root"] != target["target_root"]:
            raise InputRefused(
                f"review receipt target root drifted for {target_id}"
            )
        v2_validate_review_receipt_row_provenance(
            receipt,
            receipt_document,
            label=f"review receipt {target_id}",
        )
        review_minutes = receipt["review_minutes"]
        if type(review_minutes) is not int or review_minutes < 0:
            raise InputRefused(f"review receipt minutes are invalid for {target_id}")
        string_fields = V2_REVIEW_RECEIPT_FIELDS - {
            "compatibility_target_ids",
            "review_minutes",
            "manual_authorization",
            "source_closure",
            "semantic_review_dimensions",
        }
        if any(not isinstance(receipt[field], str) for field in string_fields):
            raise InputRefused(
                f"review receipt contains a non-string scalar for {target_id}"
            )
        if receipt["no_claim"] != V2_REVIEW_RECEIPT_ROW_NO_CLAIM:
            raise InputRefused(
                f"review receipt no-claim boundary differs for {target_id}"
            )
        if type(receipt["manual_authorization"]) is not bool:
            raise InputRefused(
                f"review receipt manual authorization is not boolean for {target_id}"
            )
        v2_validate_receipt_authority_identities(
            receipt,
            target_id=target_id,
        )
        if receipt["external_authority_verdict"] not in {
            "NODATA",
            "VALID",
            "INVALID",
            "REVOKED",
            "EXPIRED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt external-authority verdict is unknown for {target_id}"
            )
        if receipt["conditional_capability_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "LYING",
            "NON_ATOMIC",
            "VERSION_MISMATCHED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt conditional-capability verdict is unknown for {target_id}"
            )
        if receipt["gate_admission_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt gate-admission verdict is unknown for {target_id}"
            )
        targets = v2_validate_compatibility_target_ids(
            receipt["compatibility_target_ids"],
            label=f"compatibility target IDs for {target_id}",
        )
        if targets and target_id not in targets:
            raise InputRefused(
                f"compatibility set does not include its target {target_id}"
            )
        if any(value not in inventory_by_id for value in targets):
            raise InputRefused(
                f"compatibility set includes an unknown target for {target_id}"
            )
        source_closure = receipt["source_closure"]
        if not isinstance(source_closure, dict):
            raise InputRefused(
                f"review receipt source closure is not an object for {target_id}"
            )
        v2_exact_keys(
            source_closure,
            {"required", "state"},
            label=f"review receipt source closure for {target_id}",
        )
        if (
            type(source_closure["required"]) is not bool
            or not isinstance(source_closure["state"], str)
            or not source_closure["state"]
        ):
            raise InputRefused(
                f"review receipt source closure scalars are invalid for {target_id}"
            )
        for root_field in (
            "compatibility_receipt_root",
            "external_authority_receipt_root",
            "conditional_capability_receipt_root",
            "gate_admission_receipt_root",
        ):
            root_value = receipt[root_field]
            if root_value and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                root_value,
            ) is None:
                raise InputRefused(
                    f"review receipt {root_field} is malformed for {target_id}"
                )
        if receipt_document["source"] == "SYNTHETIC_FIXTURE":
            for gate, verdict_field, root_field in (
                (
                    "external",
                    "external_authority_verdict",
                    "external_authority_receipt_root",
                ),
                (
                    "conditional",
                    "conditional_capability_verdict",
                    "conditional_capability_receipt_root",
                ),
                (
                    "admission",
                    "gate_admission_verdict",
                    "gate_admission_receipt_root",
                ),
            ):
                if (
                    receipt[verdict_field] == "VALID"
                    and receipt[root_field]
                    != v2_fixture_gate_receipt_root(
                        gate,
                        target_root=target["target_root"],
                    )
                ):
                    raise InputRefused(
                        "synthetic fixture "
                        f"{gate} receipt root is not target-scoped for {target_id}"
                    )
        semantic_disposition = receipt["semantic_review_disposition"]
        if semantic_disposition not in V2_SEMANTIC_REVIEW_DISPOSITIONS:
            raise InputRefused(
                f"review receipt semantic disposition is unknown for {target_id}"
            )
        semantic_complete = v2_validate_semantic_dimension_receipts(
            receipt["semantic_review_dimensions"],
            target_root=str(receipt["target_root"]),
            disposition=semantic_disposition,
            allow_empty=True,
            label=f"review receipt semantic dimensions for {target_id}",
        )
        v2_validate_source_closure_transition(
            target=target,
            receipt=receipt,
            semantic_complete=semantic_complete,
        )
        if semantic_complete:
            if (
                not receipt["reviewer"].strip()
                or not receipt["reviewer_kind"].strip()
                or not receipt["semantic_review_rationale"].strip()
                or not receipt["semantic_review_falsifier"].strip()
            ):
                raise InputRefused(
                    f"review receipt semantic adjudication is incomplete for {target_id}"
                )
        elif (
            receipt["semantic_review_rationale"]
            or receipt["semantic_review_falsifier"]
            or semantic_disposition
            != inventory_by_id[target_id]["semantic_review_disposition"]
        ):
            raise InputRefused(
                f"review receipt claims semantic adjudication without dimensions for {target_id}"
            )
        observed_ids.append(target_id)
    v2_assert_unique(observed_ids, label="review receipt target IDs")
    if observed_ids != sorted(observed_ids):
        raise InputRefused("review receipt rows are not in canonical target order")


def v2_derive_authority(
    inventory: Mapping[str, Any],
    receipt_document: Mapping[str, Any],
    *,
    current_br_version: str,
    allow_mechanical_fixture: bool = False,
) -> dict[str, Any]:
    v2_validate_receipt_bindings(receipt_document, inventory)
    receipts = {
        row["target_id"]: row for row in receipt_document.get("receipts", [])
    }
    v2_validate_compatibility_receipts(receipts, inventory)
    decisions: list[dict[str, Any]] = []
    for target in inventory["rows"]:
        v2_validate_unreviewed_semantic_contract(
            target,
            label=f"authority inventory target {target['id']}",
        )
        receipt = receipts.get(target["id"])
        receipt_scope_root = (
            v2_review_receipt_scope_root(receipt)
            if receipt is not None
            else None
        )
        semantic_review_complete = bool(
            receipt and receipt["semantic_review_dimensions"]
        )
        semantic_review_disposition = (
            receipt["semantic_review_disposition"]
            if semantic_review_complete and receipt
            else target["semantic_review_disposition"]
        )
        semantic_review_receipt_state = (
            "ROOT_BOUND_REVIEWED"
            if semantic_review_complete
            else "UNREVIEWED"
        )
        semantic_review_receipt_root = (
            receipt_scope_root
            if semantic_review_complete and receipt
            else None
        )
        reviewed_no_change_receipt_root = (
            semantic_review_receipt_root
            if semantic_review_disposition == "REVIEWED_NO_CHANGE"
            and semantic_review_complete
            else None
        )
        if not semantic_review_complete:
            semantic_review_action = "SEMANTIC_REVIEW_REQUIRED"
        elif semantic_review_disposition == "REMEDIATION_REQUIRED":
            semantic_review_action = "REMEDIATION_CANDIDATE"
        elif semantic_review_disposition == "BLOCKED_AUTHORITY":
            semantic_review_action = "AUTHORITY_RESOLUTION_REQUIRED"
        else:
            semantic_review_action = "RETAINED_ADJUDICATION"
        review_declared = bool(
            receipt
            and receipt["reviewer"].strip()
            and receipt["reviewer_kind"].strip()
        )
        authority_declared = bool(
            review_declared
            and receipt
            and receipt["declared_acceptance_owner"].strip()
        )
        external_receipt_valid = bool(
            receipt
            and receipt["external_authority_verdict"] == "VALID"
            and receipt["external_authority_adapter"].strip()
            and receipt["external_authority_receipt_root"]
        )
        conditional_receipt_valid = bool(
            receipt
            and receipt["conditional_capability_verdict"] == "VALID"
            and receipt["conditional_capability_identity"].strip()
            and receipt["conditional_capability_receipt_root"]
        )
        gate_receipt_valid = bool(
            receipt
            and receipt["gate_admission_verdict"] == "VALID"
            and receipt["gate_admission_receipt_root"]
        )
        fixture_source = (
            allow_mechanical_fixture
            and receipt_document["source"] == "SYNTHETIC_FIXTURE"
        )
        external_fixture_bound = bool(
            receipt
            and receipt["external_authority_receipt_root"]
            == v2_fixture_gate_receipt_root(
                "external",
                target_root=target["target_root"],
            )
        )
        conditional_fixture_bound = bool(
            receipt
            and receipt["conditional_capability_receipt_root"]
            == v2_fixture_gate_receipt_root(
                "conditional",
                target_root=target["target_root"],
            )
        )
        gate_fixture_bound = bool(
            receipt
            and receipt["gate_admission_receipt_root"]
            == v2_fixture_gate_receipt_root(
                "admission",
                target_root=target["target_root"],
            )
        )
        current_tool_nodata = current_br_version == "0.2.19"
        external_verified = bool(
            fixture_source
            and external_receipt_valid
            and external_fixture_bound
        )
        conditional_verified = bool(
            fixture_source
            and not current_tool_nodata
            and conditional_receipt_valid
            and conditional_fixture_bound
        )
        gate_admitted = bool(
            fixture_source
            and not current_tool_nodata
            and gate_receipt_valid
            and gate_fixture_bound
        )
        mechanically_eligible = bool(
            fixture_source
            and not current_tool_nodata
            and external_verified
            and conditional_verified
            and gate_admitted
        )
        if mechanically_eligible:
            readiness = "MECHANICALLY_APPLY_ELIGIBLE"
        elif authority_declared or external_verified or conditional_verified:
            readiness = "DECLARED_READY"
        else:
            readiness = "REVIEW_ONLY"
        active_context = target["active_work_context"]
        if target["status"] == "deferred" or active_context["conflict"]:
            route = "ANALYSIS_ONLY"
            deferred_prohibition = target["status"] == "deferred"
        elif mechanically_eligible:
            route = "AUTOMATED_CONDITIONAL"
            deferred_prohibition = False
        elif (
            authority_declared
            and receipt
            and receipt["manual_authorization"]
        ):
            route = "MANUAL_BR_REVIEW"
            deferred_prohibition = False
        else:
            route = "ANALYSIS_ONLY"
            deferred_prohibition = False
        decision = {
            "target_id": target["id"],
            "target_root": target["target_root"],
            "tracker_assignee": target["tracker_assignee"],
            "tracker_owner": target["tracker_owner"],
            "coordination_assignee": (
                receipt["coordination_assignee"]
                if receipt and receipt["coordination_assignee"]
                else target["tracker_assignee"]
            ),
            "domain_candidates": target["domain_candidates"],
            "declared_domain_owner": (
                receipt["declared_domain_owner"] if receipt else ""
            ),
            "declared_acceptance_owner": (
                receipt["declared_acceptance_owner"]
                if authority_declared and receipt
                else ""
            ),
            "implementation_owner": (
                receipt["implementation_owner"]
                if (
                    authority_declared
                    and receipt
                    and receipt["implementation_owner"]
                )
                else "UNRESOLVED"
            ),
            "evidence_owner": (
                receipt["evidence_owner"]
                if (
                    authority_declared
                    and receipt
                    and receipt["evidence_owner"]
                )
                else "UNRESOLVED"
            ),
            "terminal_consumer": (
                receipt["terminal_consumer"]
                if (
                    authority_declared
                    and receipt
                    and receipt["terminal_consumer"]
                )
                else "UNRESOLVED"
            ),
            "reviewer_provenance": {
                "reviewer": (
                    receipt["reviewer"]
                    if review_declared and receipt
                    else ""
                ),
                "reviewer_kind": (
                    receipt["reviewer_kind"]
                    if review_declared and receipt
                    else "NODATA"
                ),
                "receipt_root": (
                    receipt_scope_root
                    if review_declared and receipt
                    else None
                ),
                "self_report_ceiling": "DECLARED_READY",
            },
            "source_closure": (
                receipt["source_closure"]
                if receipt
                else target["source_closure"]
            ),
            "user_effect": (
                receipt["user_effect"]
                if receipt
                else target["user_effect"]
            ),
            "template_warning_state": target["template_warning_state"],
            "semantic_review_disposition": semantic_review_disposition,
            "semantic_review_receipt_state": (
                semantic_review_receipt_state
            ),
            "semantic_review_dimensions": (
                receipt["semantic_review_dimensions"]
                if semantic_review_complete and receipt
                else target["semantic_review_dimensions"]
            ),
            "semantic_review_receipt_root": (
                semantic_review_receipt_root
            ),
            "reviewed_no_change_receipt_root": (
                reviewed_no_change_receipt_root
            ),
            "semantic_review_action": semantic_review_action,
            "semantic_review_rationale": (
                receipt["semantic_review_rationale"]
                if semantic_review_complete and receipt
                else ""
            ),
            "semantic_review_falsifier": (
                receipt["semantic_review_falsifier"]
                if semantic_review_complete and receipt
                else target["disposition_falsifier"]
            ),
            "field_roots": target["field_roots"],
            "target_implementation_estimated_minutes": target[
                "target_implementation_estimated_minutes"
            ],
            "target_implementation_estimate_state": target[
                "target_implementation_estimate_state"
            ],
            "review_minutes": (
                receipt["review_minutes"]
                if receipt
                else target["review_minutes"]
            ),
            "external_authority": {
                "adapter": (
                    receipt["external_authority_adapter"] if receipt else ""
                ),
                "receipt_root": (
                    receipt["external_authority_receipt_root"] if receipt else ""
                ),
                "verdict": (
                    receipt["external_authority_verdict"] if receipt else "NODATA"
                ),
                "verified": external_verified,
                "structurally_valid": external_receipt_valid,
                "trust_registry": (
                    "FIXTURE_INDEPENDENT"
                    if external_verified
                    else "NODATA"
                ),
            },
            "conditional_write_capability": {
                "identity": (
                    receipt["conditional_capability_identity"] if receipt else ""
                ),
                "receipt_root": (
                    receipt["conditional_capability_receipt_root"]
                    if receipt
                    else ""
                ),
                "verdict": (
                    receipt["conditional_capability_verdict"]
                    if receipt
                    else "NODATA"
                ),
                "verified": conditional_verified,
                "structurally_valid": conditional_receipt_valid,
                "current_tool_verdict": (
                    "AUTOMATION_NODATA"
                    if current_tool_nodata
                    else "REQUIRES_1_3_ADMISSION"
                ),
            },
            "gate_admission": {
                "receipt_root": (
                    receipt["gate_admission_receipt_root"] if receipt else ""
                ),
                "verdict": (
                    receipt["gate_admission_verdict"] if receipt else "NODATA"
                ),
                "verified": gate_admitted,
                "structurally_valid": gate_receipt_valid,
            },
            "readiness": readiness,
            "remediation_route": route,
            "manual_authorization": {
                "declared": bool(
                    authority_declared
                    and receipt
                    and receipt["manual_authorization"]
                ),
                "source": (
                    receipt["manual_authorization_source"]
                    if (
                        authority_declared
                        and receipt
                        and receipt["manual_authorization"]
                    )
                    else ""
                ),
                "mechanical_authority": False,
                "no_cas_no_clobber_no_exactly_once": True,
            },
            "compatibility": {
                "key": (
                    receipt["compatibility_key"]
                    if receipt
                    else ""
                ),
                "target_ids": (
                    receipt["compatibility_target_ids"]
                    if receipt
                    else []
                ),
                "receipt_root": (
                    receipt["compatibility_receipt_root"]
                    if receipt
                    else ""
                ),
                "rationale": (
                    receipt["compatibility_rationale"]
                    if receipt
                    else ""
                ),
                "falsifier": (
                    receipt["compatibility_falsifier"]
                    if receipt
                    else ""
                ),
                "target_complete": bool(
                    receipt and receipt["compatibility_key"]
                ),
            },
            "active_work_context": active_context,
            "deferred_apply_prohibition": deferred_prohibition,
            "no_claim": (
                "authority and readiness are planning projections only; current "
                "br 0.2.19 cannot satisfy the atomic conditional-write gate"
            ),
        }
        if decision["readiness"] not in V2_READINESS_STATES:
            raise EvidenceFailed("v2 readiness escaped its closed state set")
        if decision["remediation_route"] not in V2_REMEDIATION_ROUTES:
            raise EvidenceFailed("v2 remediation route escaped its closed state set")
        if (
            decision["semantic_review_disposition"]
            not in V2_SEMANTIC_REVIEW_DISPOSITIONS
            or decision["semantic_review_receipt_state"]
            not in V2_SEMANTIC_REVIEW_RECEIPT_STATES
            or decision["semantic_review_action"]
            not in V2_SEMANTIC_REVIEW_ACTIONS
        ):
            raise EvidenceFailed("v2 semantic review escaped its closed state sets")
        decisions.append(v2_rooted(decision))
    decisions.sort(key=lambda row: row["target_id"])
    target_by_id = {row["id"]: row for row in inventory["rows"]}
    normalized_rows = []
    for decision in decisions:
        target = target_by_id[decision["target_id"]]
        normalized_rows.append(
            v2_rooted(
                {
                    "issue_id": target["id"],
                    "title": target["title"],
                    "issue_type": target["type"],
                    "priority": target["priority"],
                    "status": target["status"],
                    "missing_sections": target["missing_sections"],
                    "disposition": target["disposition"],
                    "template_warning_state": decision[
                        "template_warning_state"
                    ],
                    "semantic_review_disposition": decision[
                        "semantic_review_disposition"
                    ],
                    "semantic_review_receipt_state": decision[
                        "semantic_review_receipt_state"
                    ],
                    "semantic_review_dimensions": decision[
                        "semantic_review_dimensions"
                    ],
                    "semantic_review_receipt_root": decision[
                        "semantic_review_receipt_root"
                    ],
                    "reviewed_no_change_receipt_root": decision[
                        "reviewed_no_change_receipt_root"
                    ],
                    "semantic_review_action": decision[
                        "semantic_review_action"
                    ],
                    "semantic_review_rationale": decision[
                        "semantic_review_rationale"
                    ],
                    "semantic_review_falsifier": decision[
                        "semantic_review_falsifier"
                    ],
                    "coordination_assignee": decision[
                        "coordination_assignee"
                    ],
                    "tracker_owner": target["tracker_owner"],
                    "domain_candidate": decision["domain_candidates"],
                    "declared_domain_owner": decision[
                        "declared_domain_owner"
                    ],
                    "declared_acceptance_owner": decision[
                        "declared_acceptance_owner"
                    ],
                    "implementation_owner": decision[
                        "implementation_owner"
                    ],
                    "evidence_owner": decision["evidence_owner"],
                    "terminal_consumer": decision["terminal_consumer"],
                    "reviewer_provenance": decision["reviewer_provenance"],
                    "source_closure": decision["source_closure"],
                    "user_effect": decision["user_effect"],
                    "field_roots": decision["field_roots"],
                    "target_implementation_estimated_minutes": decision[
                        "target_implementation_estimated_minutes"
                    ],
                    "target_implementation_estimate_state": decision[
                        "target_implementation_estimate_state"
                    ],
                    "review_minutes": decision["review_minutes"],
                    "generated_child_estimated_minutes": decision[
                        "review_minutes"
                    ],
                    "external_authority_adapter_identity": decision[
                        "external_authority"
                    ]["adapter"],
                    "external_authority_receipt_root": decision[
                        "external_authority"
                    ]["receipt_root"],
                    "external_authority_verdict": decision[
                        "external_authority"
                    ]["verdict"],
                    "conditional_write_capability_identity": decision[
                        "conditional_write_capability"
                    ]["identity"],
                    "conditional_write_receipt_root": decision[
                        "conditional_write_capability"
                    ]["receipt_root"],
                    "conditional_write_verdict": decision[
                        "conditional_write_capability"
                    ]["verdict"],
                    "readiness": decision["readiness"],
                    "remediation_route": decision["remediation_route"],
                    "active_work_context": decision["active_work_context"],
                    "campaign_epoch_root": target["campaign_epoch_root"],
                    "lane": target["lane"],
                    "movement_destination": target[
                        "movement_destination"
                    ],
                    "no_claim": decision["no_claim"],
                }
            )
        )
    for index, normalized_row in enumerate(normalized_rows):
        v2_exact_keys(
            normalized_row,
            V2_NORMALIZED_ROW_FIELDS,
            label=f"normalized authority row {index}",
        )
    document = {
        "schema": V2_AUTHORITY_SCHEMA,
        "inventory_root": inventory["semantic_root"],
        "review_receipts_root": receipt_document["semantic_root"],
        "current_br_version": current_br_version,
        "current_br_conditional_write_capability": (
            "AUTOMATION_NODATA"
            if current_br_version == "0.2.19"
            else "REQUIRES_1_3_ADMISSION"
        ),
        "decisions": decisions,
        "normalized_rows": normalized_rows,
        "counts": {
            "readiness": dict(
                sorted(Counter(row["readiness"] for row in decisions).items())
            ),
            "routes": dict(
                sorted(
                    Counter(row["remediation_route"] for row in decisions).items()
                )
            ),
            "active_conflicts": sum(
                bool(row["active_work_context"]["conflict"]) for row in decisions
            ),
            "semantic_review_states": dict(
                sorted(
                    Counter(
                        row["semantic_review_receipt_state"]
                        for row in decisions
                    ).items()
                )
            ),
            "semantic_review_dispositions": dict(
                sorted(
                    Counter(
                        row["semantic_review_disposition"]
                        for row in decisions
                    ).items()
                )
            ),
            "semantic_review_actions": dict(
                sorted(
                    Counter(
                        row["semantic_review_action"]
                        for row in decisions
                    ).items()
                )
            ),
        },
        "no_claim": (
            "self-report, assignment, labels, and repository data cannot mint "
            "external review authority or atomic conditional-write capability"
        ),
    }
    return v2_rooted(document)


def v2_lane_parent(priority: int) -> str:
    return {
        0: "frankensim-semantic-bead-template-hygiene-961yr.2",
        1: "frankensim-semantic-bead-template-hygiene-961yr.3",
        2: "frankensim-semantic-bead-template-hygiene-961yr.4.1",
        3: "frankensim-semantic-bead-template-hygiene-961yr.4.2",
        4: "frankensim-semantic-bead-template-hygiene-961yr.4.3",
    }[priority]


def v2_hard_vector(
    target: Mapping[str, Any], authority: Mapping[str, Any]
) -> tuple[Any, ...]:
    return (
        int(target["priority"]),
        str(target["status"]),
        str(target["disposition"]),
        str(target["type"]),
        tuple(sorted(str(value) for value in target["missing_sections"])),
        str(authority["semantic_review_disposition"]),
        str(authority["semantic_review_receipt_state"]),
        str(authority["semantic_review_action"]),
        str(authority["readiness"]),
        str(authority["remediation_route"]),
    )


def v2_packing_group_key(
    target: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> tuple[Any, ...]:
    compatibility_key = str(authority["compatibility"]["key"] or "")
    grouping_identity = compatibility_key or f"singleton:{target['id']}"
    return (
        *v2_hard_vector(target, authority),
        grouping_identity,
    )


def v2_packing_input_bindings(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
) -> tuple[str, str]:
    group_keys = {
        v2_packing_group_key(target, authority)
        for target, authority in rows
    }
    if len(group_keys) != 1:
        raise EvidenceFailed(
            "packing input crosses a hard or compatibility group"
        )
    load_rows = [
        {
            "target_id": target["id"],
            "target_root": target["target_root"],
            "authority_decision_root": authority["semantic_root"],
            "review_minutes": authority["review_minutes"],
            "retained_payload_bytes": target["retained_payload_bytes"],
        }
        for target, authority in sorted(
            rows,
            key=lambda pair: pair[0]["id"],
        )
    ]
    return (
        semantic_root({"group_key": next(iter(group_keys))}),
        semantic_root(load_rows),
    )


def v2_load_tuple(target: Mapping[str, Any], authority: Mapping[str, Any]) -> tuple[int, int, int]:
    return (
        int(authority["review_minutes"]),
        int(target["retained_payload_bytes"]),
        1,
    )


def v2_bin_load(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]
) -> tuple[int, int, int]:
    return (
        sum(int(authority["review_minutes"]) for _, authority in rows),
        sum(int(target["retained_payload_bytes"]) for target, _ in rows),
        len(rows),
    )


def v2_bin_feasible(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> bool:
    minutes, retained_bytes, targets = v2_bin_load(rows)
    return (
        targets <= max_targets
        and minutes <= V2_REVIEW_MINUTES_CAP
        and retained_bytes <= V2_CHILD_PAYLOAD_CAP
        and not v2_child_transport_violations(rows)
    )


def v2_partition_objective(
    bins: Sequence[Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]],
) -> tuple[Any, ...]:
    loads = [v2_bin_load(rows) for rows in bins]
    memberships = tuple(
        sorted(tuple(sorted(target["id"] for target, _ in rows)) for rows in bins)
    )
    descending_loads = tuple(sorted(loads, reverse=True))
    return (
        len(bins),
        max((load[0] for load in loads), default=0),
        max((load[1] for load in loads), default=0),
        max((load[2] for load in loads), default=0),
        descending_loads,
        memberships,
    )


def v2_objective_document(
    bins: Sequence[Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]],
) -> dict[str, Any]:
    objective = v2_partition_objective(bins)
    return {
        "child_count": objective[0],
        "maximum_review_minutes": objective[1],
        "maximum_retained_payload_bytes": objective[2],
        "maximum_target_count": objective[3],
        "descending_load_vectors": [
            list(load) for load in objective[4]
        ],
        "lexicographic_memberships": [
            list(membership) for membership in objective[5]
        ],
    }


def v2_exact_partition(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]]:
    ordered = sorted(rows, key=lambda pair: pair[0]["id"])
    count = len(ordered)
    if count > V2_EXACT_OPTIMALITY_MAX_TARGETS:
        raise EvidenceFailed("exact partition called above its frozen target cutoff")
    feasible_masks: dict[int, list[int]] = defaultdict(list)
    for mask in range(1, 1 << count):
        selected = [ordered[index] for index in range(count) if mask & (1 << index)]
        if v2_bin_feasible(selected, max_targets=max_targets):
            pivot = (mask & -mask).bit_length() - 1
            feasible_masks[pivot].append(mask)
    memo: dict[int, list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]]] = {
        0: []
    }

    def solve(mask: int) -> list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]]:
        if mask in memo:
            return memo[mask]
        pivot = (mask & -mask).bit_length() - 1
        best: list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]] | None = None
        for subset in feasible_masks[pivot]:
            if subset & mask != subset:
                continue
            selected = [
                ordered[index] for index in range(count) if subset & (1 << index)
            ]
            candidate = [selected, *solve(mask ^ subset)]
            if best is None or v2_partition_objective(candidate) < v2_partition_objective(best):
                best = candidate
        if best is None:
            raise EvidenceFailed("no feasible exact review partition exists")
        memo[mask] = best
        return best

    return solve((1 << count) - 1)


def v2_large_partition(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> tuple[
    list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]],
    dict[str, Any],
]:
    ordered = sorted(
        rows,
        key=lambda pair: (
            -int(pair[1]["review_minutes"]),
            -int(pair[0]["retained_payload_bytes"]),
            pair[0]["id"],
        ),
    )
    group_key_root, ordered_load_rows_root = v2_packing_input_bindings(
        ordered
    )
    total_minutes = sum(int(pair[1]["review_minutes"]) for pair in ordered)
    total_bytes = sum(int(pair[0]["retained_payload_bytes"]) for pair in ordered)
    lower_bound = max(
        math.ceil(len(ordered) / max_targets),
        math.ceil(total_minutes / V2_REVIEW_MINUTES_CAP),
        math.ceil(total_bytes / V2_CHILD_PAYLOAD_CAP),
        1,
    )
    bin_count = lower_bound
    while bin_count <= len(ordered):
        bins: list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]] = [
            [] for _ in range(bin_count)
        ]
        admitted = True
        for row in ordered:
            candidates = sorted(
                range(bin_count),
                key=lambda index: (
                    v2_bin_load(bins[index]),
                    tuple(target["id"] for target, _ in bins[index]),
                    index,
                ),
            )
            destination = next(
                (
                    index
                    for index in candidates
                    if v2_bin_feasible(
                        [*bins[index], row],
                        max_targets=max_targets,
                    )
                ),
                None,
            )
            if destination is None:
                admitted = False
                break
            bins[destination].append(row)
        if admitted and all(bins):
            achieved = v2_objective_document(bins)
            witness = {
                "algorithm": "DETERMINISTIC_LPT_VECTOR_PACKING",
                "group_key_root": group_key_root,
                "ordered_load_rows_root": ordered_load_rows_root,
                "lower_bound_children": lower_bound,
                "observed_children": bin_count,
                "child_count_gap": bin_count - lower_bound,
                "lower_bound_vector": {
                    "targets": math.ceil(len(ordered) / max_targets),
                    "review_minutes": math.ceil(
                        total_minutes / V2_REVIEW_MINUTES_CAP
                    ),
                    "retained_payload_bytes": math.ceil(
                        total_bytes / V2_CHILD_PAYLOAD_CAP
                    ),
                },
                "transport_constraint_root": (
                    v2_partition_transport_constraint_root(bins)
                ),
                "achieved_objective": achieved,
                "gap_witness": {
                    "child_count": bin_count - lower_bound,
                    "maximum_review_minutes_above_average": (
                        achieved["maximum_review_minutes"]
                        - math.ceil(total_minutes / bin_count)
                    ),
                    "maximum_retained_bytes_above_average": (
                        achieved["maximum_retained_payload_bytes"]
                        - math.ceil(total_bytes / bin_count)
                    ),
                },
                "exact_optimality_claim": False,
                "max_targets_per_child": max_targets,
                "rationale": (
                    "deterministic largest-first vector placement starts at "
                    "the independently computed multidimensional lower bound"
                ),
                "falsifier": (
                    "a feasible plan with a lexicographically smaller frozen "
                    "objective or an incorrect lower bound invalidates this witness"
                ),
            }
            return bins, v2_rooted(witness)
        bin_count += 1
    raise EvidenceFailed("large-instance review packing has no feasible partition")


def v2_pack_group(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> tuple[
    list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]],
    dict[str, Any],
]:
    if not 1 <= max_targets <= V2_REVIEW_TARGET_HARD_MAX:
        raise UsageRefused(
            f"--max-targets-per-child must be in 1..{V2_REVIEW_TARGET_HARD_MAX}"
        )
    if any(
        int(authority["review_minutes"]) > V2_REVIEW_MINUTES_CAP
        or int(target["retained_payload_bytes"]) > V2_CHILD_PAYLOAD_CAP
        or bool(v2_child_transport_violations([(target, authority)]))
        for target, authority in rows
    ):
        raise EvidenceFailed("oversize rows must be removed before standard packing")
    group_key_root, ordered_load_rows_root = v2_packing_input_bindings(rows)
    if len(rows) <= V2_EXACT_OPTIMALITY_MAX_TARGETS:
        bins = v2_exact_partition(rows, max_targets=max_targets)
        witness = v2_rooted(
            {
                "algorithm": "EXACT_SUBSET_PARTITION",
                "group_key_root": group_key_root,
                "ordered_load_rows_root": ordered_load_rows_root,
                "exact_optimality_max_targets": V2_EXACT_OPTIMALITY_MAX_TARGETS,
                "exact_optimality_claim": True,
                "objective": v2_objective_document(bins),
                "transport_constraint_root": (
                    v2_partition_transport_constraint_root(bins)
                ),
                "max_targets_per_child": max_targets,
                "rationale": (
                    "the exact subset search minimizes the frozen objective "
                    "over every feasible partition"
                ),
                "falsifier": (
                    "a feasible partition with a lexicographically smaller "
                    "objective invalidates this witness"
                ),
            }
        )
        return bins, witness
    return v2_large_partition(rows, max_targets=max_targets)


def v2_markdown_inline_code(value: str) -> str:
    longest = max(
        (len(match.group(0)) for match in re.finditer(r"`+", value)),
        default=0,
    )
    fence = "`" * (longest + 1)
    padding = " " if value.startswith("`") or value.endswith("`") else ""
    return f"{fence}{padding}{value}{padding}{fence}"


def v2_child_text(
    targets: Sequence[Mapping[str, Any]],
    authorities: Sequence[Mapping[str, Any]],
    *,
    oversize: bool,
) -> tuple[str, str, str, str]:
    target_ids = [target["id"] for target in targets]
    disposition = str(targets[0]["disposition"])
    workflow_obligations = {
        "MALFORMED_OR_WRONG_TYPE": (
            "Validate the declared issue type and repair malformed template "
            "structure without changing the underlying scope; add focused type "
            "and schema unit tests."
        ),
        "ROLLUP_CHILD_SET_GAP": (
            "Reconstruct the exact child/dependency set, prove the rollup union "
            "and zero cells, and retain graph-aware E2E evidence."
        ),
        "OWNER_REVIEW_REQUIRED": (
            "Obtain root-bound answers from the current semantic owner for "
            "acceptance, implementation, evidence, and terminal-consumer questions."
        ),
        "SUBSTANTIVE_SEMANTIC_OMISSION": (
            "Add issue-specific acceptance and success proof obligations, "
            "including unit/property coverage, authentic E2E, detailed logging, "
            "offline replay, cancellation, and no-claim boundaries."
        ),
        "SECTION_NAME_ONLY": (
            "Preserve every existing byte of substantive prose and make only "
            "the independently reviewed heading/placement correction."
        ),
        "HISTORICAL_IMMUTABLE_REVIEW": (
            "Do not mutate the closed source; account for closer provenance, "
            "citations, candidate consumers, and proof NoData in history."
        ),
    }.get(
        disposition,
        "Resolve the exact rooted disposition without generic replacement text.",
    )
    target_lines = "\n".join(
        f"- `{target['id']}` target_root `{target['target_root']}` "
        + (
            f"template findings {', '.join(target['missing_sections'])}"
            if target["missing_sections"]
            else (
                "template findings NONE; comprehensive semantic review "
                "remains UNREVIEWED"
            )
        )
        + (
            f"; semantic action `{authority['semantic_review_action']}` "
            f"with disposition `{authority['semantic_review_disposition']}`"
        )
        + (
            "; responsibilities "
            "implementation="
            f"{v2_markdown_inline_code(authority['implementation_owner'])}, "
            "evidence="
            f"{v2_markdown_inline_code(authority['evidence_owner'])}, "
            "terminal-consumer="
            f"{v2_markdown_inline_code(authority['terminal_consumer'])}"
        )
        for target, authority in zip(targets, authorities, strict=True)
    )
    description = (
        "Review the exact semantic Bead plan quality for the targets below. "
        "Use each retained target and field root; do not replace issue-specific "
        "meaning with generic boilerplate.\n\n"
        f"{target_lines}\n\n"
        "This generated plan is tracker-read-only. The future publisher must "
        "re-observe every target and preserve all target semantics.\n\n"
        f"Disposition-specific workflow: {workflow_obligations}"
    )
    if oversize:
        description += (
            "\n\nThis is an OVERSIZE_REVIEW_REQUIRED escalation. The bounded "
            "index is explicitly incomplete; the retained full-plan artifact "
            "and canonical `br show ID --json` reproduction are authoritative "
            "for source retrieval."
        )
    acceptance = (
        "1. Review every exact target and field root without dropping or "
        "duplicating membership.\n"
        "2. Resolve the named disposition using issue-specific acceptance, "
        "unit/property tests, authentic E2E, deterministic logging, and replay.\n"
        "3. Preserve target implementation estimates separately from review "
        "effort and keep authority/readiness/route boundaries explicit.\n"
        "4. Retain the exact semantic-review disposition, dimension receipts, "
        "and root-bound adjudication; only REMEDIATION_REQUIRED may become a "
        "future corrective-materialization candidate.\n"
        "5. Refuse stale roots, active conflicts, deferred apply, semantic "
        "truncation, generic merges, and unverified evidence.\n"
        "6. Close only through the canonical generated-leaf terminal protocol."
        f"\n7. Disposition-specific acceptance: {workflow_obligations}"
    )
    design = (
        "Hard partition vector: priority/status/disposition/type/missing-set/"
        "semantic-disposition/semantic-receipt-state/semantic-action/readiness/"
        "remediation-route. Compatibility is valid only through the retained "
        "target-complete receipt. "
        f"Workflow `{disposition}`: {workflow_obligations}"
    )
    notes = (
        f"Targets: {', '.join(target_ids)}. Readiness: "
        f"{', '.join(sorted({row['readiness'] for row in authorities}))}. "
        "No external-human, target-implementation, science, performance, "
        "product, promotion, or release authority is minted."
    )
    return description, acceptance, design, notes


def v2_validate_child_payload(child: Mapping[str, Any]) -> None:
    if not isinstance(child, dict):
        raise EvidenceFailed("planned child is not an object")
    root_pattern = re.compile(r"sha256-v1:[0-9a-f]{64}")
    v2_exact_keys(
        child,
        V2_PLANNED_CHILD_FIELDS,
        label=f"planned child {child.get('child_key')}",
    )
    target_ids = child["target_ids"]
    if (
        not isinstance(target_ids, list)
        or not 1 <= len(target_ids) <= V2_REVIEW_TARGET_HARD_MAX
        or not all(isinstance(value, str) and value for value in target_ids)
        or target_ids != sorted(target_ids)
        or len(target_ids) != len(set(target_ids))
    ):
        raise EvidenceFailed(
            "planned child target membership exceeds its hard cap or is "
            "malformed"
        )
    target_count = len(target_ids)
    target_indexed_fields = (
        "target_roots",
        "source_dependency_snapshot",
        "target_implementation_estimates",
        "target_implementation_estimated_minutes",
        "target_implementation_estimate_states",
        "responsibility_assignments",
        "semantic_review_receipt_roots",
        "reviewed_no_change_receipt_roots",
        "external_authority",
        "external_authority_receipt_root",
        "external_authority_verdict",
        "conditional_write_capability",
        "conditional_write_receipt_root",
        "conditional_write_verdict",
    )
    if any(
        not isinstance(child[field], list)
        or len(child[field]) != target_count
        for field in target_indexed_fields
    ):
        raise EvidenceFailed(
            "planned child target-indexed collection cardinality differs"
        )
    if (
        not isinstance(child["labels"], list)
        or len(child["labels"]) > V2_LABELS_PER_ISSUE_CAP
        or not isinstance(child["intended_generated_edges"], list)
        or len(child["intended_generated_edges"]) != 2
    ):
        raise EvidenceFailed(
            "planned child label or generated-edge cardinality differs"
        )
    key_inputs_preflight = child["external_ref_key_inputs"]
    key_input_target_fields = (
        "target_ids",
        "target_roots",
        "semantic_review_receipt_roots",
        "responsibility_assignments",
        "authority_decision_roots",
    )
    if (
        not isinstance(key_inputs_preflight, dict)
        or any(
            not isinstance(key_inputs_preflight.get(field), list)
            or len(key_inputs_preflight[field]) != target_count
            for field in key_input_target_fields
        )
    ):
        raise EvidenceFailed(
            "planned child external identity collection cardinality differs"
        )
    compatibility_preflight = child["compatibility"]
    if (
        not isinstance(compatibility_preflight, dict)
        or not isinstance(
            compatibility_preflight.get("target_ids"),
            list,
        )
        or len(compatibility_preflight["target_ids"])
        > V2_COMPATIBILITY_TARGETS_PER_RECEIPT_CAP
    ):
        raise EvidenceFailed(
            "planned child compatibility collection exceeds its cap or is "
            "malformed"
        )
    v2_validate_canonical_byte_size(
        child,
        cap=V2_GENERATED_CHILD_PAYLOAD_CAP,
        label="planned child generated payload",
    )
    verify_semantic_root(child, label="planned child")
    if (
        child["schema"]
        != "frankensim.beads-template-hygiene.planned-child.v2"
        or not all(
            isinstance(child[field], str) and child[field]
            for field in (
                "child_key",
                "title",
                "issue_type",
                "desired_status",
                "lane_parent",
                "external_ref",
                "acceptance_criteria",
                "acceptance",
                "design",
                "notes",
                "disposition_workflow",
                "semantic_review_disposition",
                "semantic_review_receipt_state",
                "semantic_review_action",
                "readiness",
                "remediation_route",
                "packing_witness_root",
                "falsifier",
                "description_root",
                "no_claim",
                "semantic_root",
            )
        )
        or not isinstance(child["coordination_assignee"], str)
        or type(child["priority"]) is not int
        or child["priority"] not in range(5)
        or child["lane_parent"] != v2_lane_parent(child["priority"])
        or child["issue_type"] != "task"
        or not isinstance(child["labels"], list)
        or not all(isinstance(value, str) and value for value in child["labels"])
        or child["labels"] != sorted(set(child["labels"]))
        or child["desired_status"] not in {"open", "deferred"}
        or child["readiness"] not in V2_READINESS_STATES
        or child["remediation_route"] not in V2_REMEDIATION_ROUTES
        or child["semantic_review_disposition"]
        not in V2_SEMANTIC_REVIEW_DISPOSITIONS
        or child["semantic_review_receipt_state"]
        not in V2_SEMANTIC_REVIEW_RECEIPT_STATES
        or child["semantic_review_action"] not in V2_SEMANTIC_REVIEW_ACTIONS
        or child["disposition_workflow"]
        not in {*DISPOSITIONS, "OVERSIZE_REVIEW_REQUIRED"}
        or child["no_claim"] != V2_PLANNED_CHILD_NO_CLAIM
        or root_pattern.fullmatch(child["packing_witness_root"]) is None
    ):
        raise EvidenceFailed("planned child scalar or enum contract differs")
    description = child["description_file_artifact"]
    if not isinstance(description, dict):
        raise EvidenceFailed("planned child description artifact is malformed")
    v2_exact_keys(
        description,
        {"media_type", "bytes", "root", "content", "transport"},
        label="planned child description artifact",
    )
    if (
        description["media_type"] != "text/markdown; charset=utf-8"
        or type(description["bytes"]) is not int
        or description["bytes"] < 0
        or not isinstance(description["root"], str)
        or not isinstance(description["content"], str)
        or description["transport"] != "br create --description-file -"
    ):
        raise EvidenceFailed(
            "planned child description transport scalar contract differs"
        )
    payloads = {
        "description": description["content"].encode("utf-8"),
        "acceptance": child["acceptance_criteria"].encode("utf-8"),
        "design": child["design"].encode("utf-8"),
        "notes": child["notes"].encode("utf-8"),
    }
    limits = {
        "description": V2_CHILD_DESCRIPTION_CAP,
        "acceptance": V2_CHILD_ACCEPTANCE_CAP,
        "design": V2_CHILD_DESIGN_CAP,
        "notes": V2_CHILD_NOTES_CAP,
    }
    for field, payload in payloads.items():
        if len(payload) > limits[field]:
            raise EvidenceFailed(f"planned child {field} exceeds its transport cap")
    if (
        description["bytes"] != len(payloads["description"])
        or description["root"] != text_root(description["content"])
        or child["description_root"] != description["root"]
        or child["acceptance"] != child["acceptance_criteria"]
    ):
        raise EvidenceFailed("planned child transport roots or aliases disagree")
    argv_bytes = sum(
        len(payloads[field]) for field in ("acceptance", "design", "notes")
    )
    if argv_bytes > V2_CHILD_ARGV_AGGREGATE_CAP:
        raise EvidenceFailed("planned child aggregate non-description argv exceeds cap")
    if (
        type(child["review_minutes"]) is not int
        or child["review_minutes"] < 0
        or child["review_minutes"] > V2_REVIEW_MINUTES_CAP
        or type(child["estimated_minutes"]) is not int
        or type(child["generated_child_estimated_minutes"]) is not int
        or child["estimated_minutes"] != child["review_minutes"]
        or child["generated_child_estimated_minutes"]
        != child["review_minutes"]
    ):
        raise EvidenceFailed("planned child review-minute aliases disagree")
    target_roots = child["target_roots"]
    if (
        not isinstance(target_roots, list)
        or len(target_roots) != len(target_ids)
        or not all(
            isinstance(value, str)
            and root_pattern.fullmatch(value) is not None
            for value in target_roots
        )
        or len(target_roots) != len(set(target_roots))
    ):
        raise EvidenceFailed("planned child target membership or roots are malformed")
    dependency_snapshot = child["source_dependency_snapshot"]
    if (
        not isinstance(dependency_snapshot, list)
        or len(dependency_snapshot) != len(target_ids)
        or not all(isinstance(row, dict) for row in dependency_snapshot)
        or any(
            set(row)
            != {"target_id", "dependency_neighborhood_root"}
            or not isinstance(row["target_id"], str)
            or not isinstance(row["dependency_neighborhood_root"], str)
            or root_pattern.fullmatch(
                row["dependency_neighborhood_root"]
            )
            is None
            for row in dependency_snapshot
        )
        or [row["target_id"] for row in dependency_snapshot] != target_ids
    ):
        raise EvidenceFailed(
            "planned child dependency snapshot is malformed or misordered"
        )
    estimate_rows = child["target_implementation_estimates"]
    estimate_aliases = child["target_implementation_estimated_minutes"]
    estimate_states = child["target_implementation_estimate_states"]
    if not all(
        isinstance(rows, list) and len(rows) == len(target_ids)
        for rows in (estimate_rows, estimate_aliases, estimate_states)
    ):
        raise EvidenceFailed("planned child implementation estimates are malformed")
    for target_id, estimate, alias, state_row in zip(
        target_ids,
        estimate_rows,
        estimate_aliases,
        estimate_states,
    ):
        if (
            not isinstance(estimate, dict)
            or set(estimate) != {"target_id", "state", "estimated_minutes"}
            or not isinstance(alias, dict)
            or set(alias) != {"target_id", "estimated_minutes"}
            or not isinstance(state_row, dict)
            or set(state_row) != {"target_id", "state"}
            or estimate["target_id"] != target_id
            or alias["target_id"] != target_id
            or state_row["target_id"] != target_id
            or estimate["state"] != state_row["state"]
            or estimate["state"] not in {"DECLARED", "NODATA"}
            or estimate["estimated_minutes"] != alias["estimated_minutes"]
            or (
                estimate["state"] == "DECLARED"
                and (
                    type(estimate["estimated_minutes"]) is not int
                    or estimate["estimated_minutes"] < 0
                )
            )
            or (
                estimate["state"] == "NODATA"
                and estimate["estimated_minutes"] is not None
            )
        ):
            raise EvidenceFailed(
                "planned child implementation estimate state/value disagrees"
            )

    def target_indexed_rows(
        field: str,
        expected_fields: set[str],
    ) -> list[Mapping[str, Any]]:
        rows = child[field]
        if (
            not isinstance(rows, list)
            or len(rows) != len(target_ids)
            or not all(isinstance(row, dict) for row in rows)
            or any(set(row) != expected_fields for row in rows)
            or [row["target_id"] for row in rows] != target_ids
        ):
            raise EvidenceFailed(
                f"planned child {field} target-indexed rows are malformed"
            )
        return rows

    semantic_root_rows = target_indexed_rows(
        "semantic_review_receipt_roots",
        {"target_id", "receipt_root"},
    )
    reviewed_no_change_rows = target_indexed_rows(
        "reviewed_no_change_receipt_roots",
        {"target_id", "receipt_root"},
    )
    responsibility_rows = target_indexed_rows(
        "responsibility_assignments",
        {
            "target_id",
            "implementation_owner",
            "evidence_owner",
            "terminal_consumer",
        },
    )
    for row in responsibility_rows:
        if any(
            not isinstance(row[field], str)
            or not row[field]
            or row[field] != row[field].strip()
            for field in (
                "implementation_owner",
                "evidence_owner",
                "terminal_consumer",
            )
        ):
            raise EvidenceFailed(
                "planned child responsibility assignment is noncanonical"
            )
    for semantic_row, no_change_row in zip(
        semantic_root_rows,
        reviewed_no_change_rows,
        strict=True,
    ):
        semantic_receipt_root = semantic_row["receipt_root"]
        no_change_root = no_change_row["receipt_root"]
        if (
            semantic_receipt_root is not None
            and (
                not isinstance(semantic_receipt_root, str)
                or root_pattern.fullmatch(semantic_receipt_root) is None
            )
        ):
            raise EvidenceFailed(
                "planned child semantic-review receipt root is malformed"
            )
        if (
            no_change_root is not None
            and (
                not isinstance(no_change_root, str)
                or root_pattern.fullmatch(no_change_root) is None
            )
        ):
            raise EvidenceFailed(
                "planned child reviewed-no-change root is malformed"
            )
        if (
            child["semantic_review_receipt_state"] == "UNREVIEWED"
            and semantic_receipt_root is not None
        ):
            raise EvidenceFailed(
                "unreviewed planned child carries a semantic receipt root"
            )
        if (
            child["semantic_review_disposition"] == "REVIEWED_NO_CHANGE"
            and no_change_root != semantic_receipt_root
        ) or (
            child["semantic_review_disposition"] != "REVIEWED_NO_CHANGE"
            and no_change_root is not None
        ):
            raise EvidenceFailed(
                "planned child reviewed-no-change root disagrees with disposition"
            )

    external_rows = target_indexed_rows(
        "external_authority",
        {
            "target_id",
            "adapter",
            "receipt_root",
            "verdict",
            "verified",
            "structurally_valid",
            "trust_registry",
        },
    )
    external_root_rows = target_indexed_rows(
        "external_authority_receipt_root",
        {"target_id", "receipt_root"},
    )
    external_verdict_rows = target_indexed_rows(
        "external_authority_verdict",
        {"target_id", "verdict"},
    )
    conditional_rows = target_indexed_rows(
        "conditional_write_capability",
        {
            "target_id",
            "identity",
            "receipt_root",
            "verdict",
            "verified",
            "structurally_valid",
            "current_tool_verdict",
        },
    )
    conditional_root_rows = target_indexed_rows(
        "conditional_write_receipt_root",
        {"target_id", "receipt_root"},
    )
    conditional_verdict_rows = target_indexed_rows(
        "conditional_write_verdict",
        {"target_id", "verdict"},
    )
    for index, target_id in enumerate(target_ids):
        external = external_rows[index]
        conditional = conditional_rows[index]
        if (
            external["receipt_root"]
            != external_root_rows[index]["receipt_root"]
            or external["verdict"]
            != external_verdict_rows[index]["verdict"]
            or external["verdict"]
            not in {
                "NODATA",
                "VALID",
                "INVALID",
                "REVOKED",
                "EXPIRED",
                "CONFLICTED",
            }
            or type(external["verified"]) is not bool
            or type(external["structurally_valid"]) is not bool
            or not isinstance(external["receipt_root"], str)
            or (
                external["receipt_root"] != ""
                and root_pattern.fullmatch(external["receipt_root"])
                is None
            )
            or conditional["receipt_root"]
            != conditional_root_rows[index]["receipt_root"]
            or conditional["verdict"]
            != conditional_verdict_rows[index]["verdict"]
            or conditional["verdict"]
            not in {
                "NODATA",
                "VALID",
                "FAILED",
                "LYING",
                "NON_ATOMIC",
                "VERSION_MISMATCHED",
                "CONFLICTED",
            }
            or type(conditional["verified"]) is not bool
            or type(conditional["structurally_valid"]) is not bool
            or not isinstance(conditional["receipt_root"], str)
            or (
                conditional["receipt_root"] != ""
                and root_pattern.fullmatch(conditional["receipt_root"])
                is None
            )
            or not all(
                isinstance(external[field], str)
                for field in (
                    "adapter",
                    "receipt_root",
                    "verdict",
                    "trust_registry",
                )
            )
            or not all(
                isinstance(conditional[field], str)
                for field in (
                    "identity",
                    "receipt_root",
                    "verdict",
                    "current_tool_verdict",
                )
            )
        ):
            raise EvidenceFailed(
                "planned child authority/capability aliases disagree for "
                f"{target_id}"
            )
    compatibility = child["compatibility"]
    if not isinstance(compatibility, dict):
        raise EvidenceFailed("planned child compatibility receipt is malformed")
    v2_exact_keys(
        compatibility,
        {
            "key",
            "target_ids",
            "receipt_root",
            "rationale",
            "falsifier",
            "target_complete",
        },
        label="planned child compatibility receipt",
    )
    if (
        not all(
            isinstance(compatibility[field], str)
            for field in (
                "key",
                "receipt_root",
                "rationale",
                "falsifier",
            )
        )
        or type(compatibility["target_complete"]) is not bool
        or (
            compatibility["receipt_root"] != ""
            and root_pattern.fullmatch(
                compatibility["receipt_root"]
            )
            is None
        )
    ):
        raise EvidenceFailed("planned child compatibility scalars are malformed")
    compatibility_target_ids = v2_validate_compatibility_target_ids(
        compatibility["target_ids"],
        label="planned child compatibility target IDs",
        error_type=EvidenceFailed,
    )
    if compatibility["target_complete"]:
        if (
            any(
                not compatibility[field]
                or compatibility[field]
                != compatibility[field].strip()
                for field in (
                    "key",
                    "receipt_root",
                    "rationale",
                    "falsifier",
                )
            )
            or root_pattern.fullmatch(
                compatibility["receipt_root"]
            )
            is None
            or not set(target_ids).issubset(
                compatibility_target_ids
            )
        ):
            raise EvidenceFailed(
                "planned child target-complete compatibility receipt "
                "does not cover its child"
            )
    elif (
        len(target_ids) != 1
        or compatibility != {
            "key": "",
            "target_ids": [],
            "receipt_root": "",
            "rationale": V2_SINGLETON_NO_COMPATIBILITY_RATIONALE,
            "falsifier": V2_SINGLETON_NO_COMPATIBILITY_FALSIFIER,
            "target_complete": False,
        }
    ):
        raise EvidenceFailed(
            "planned child no-compatibility singleton receipt differs"
        )
    child_key = str(child["child_key"])
    generated = f"generated:{child_key}"
    expected_edges = [
        {
            "from": generated,
            "to": child["lane_parent"],
            "type": "parent-child",
        },
        {
            "from": V2_GENERATION_GATE_ID,
            "to": generated,
            "type": "blocks",
        },
    ]
    if child["intended_generated_edges"] != expected_edges:
        raise EvidenceFailed(
            "planned child generated-edge membership, direction, or type differs"
        )
    key_inputs = child["external_ref_key_inputs"]
    if not isinstance(key_inputs, dict):
        raise EvidenceFailed("planned child external identity inputs are malformed")
    v2_exact_keys(
        key_inputs,
        {
            "schema",
            "priority",
            "lane_parent",
            "generation_gate_id",
            "status",
            "disposition",
            "type",
            "missing_sections",
            "semantic_review_disposition",
            "semantic_review_receipt_state",
            "semantic_review_action",
            "semantic_review_receipt_roots",
            "responsibility_assignments",
            "readiness",
            "remediation_route",
            "target_ids",
            "target_roots",
            "authority_decision_roots",
            "compatibility",
        },
        label="planned child external identity inputs",
    )
    decision_roots = key_inputs["authority_decision_roots"]
    if (
        not isinstance(decision_roots, list)
        or len(decision_roots) != len(target_ids)
        or not all(isinstance(row, dict) for row in decision_roots)
        or any(
            set(row) != {"target_id", "decision_root"}
            or not isinstance(row["target_id"], str)
            or not isinstance(row["decision_root"], str)
            or root_pattern.fullmatch(row["decision_root"]) is None
            for row in decision_roots
        )
        or [row["target_id"] for row in decision_roots] != target_ids
    ):
        raise EvidenceFailed(
            "planned child authority-decision identity roots are malformed"
        )
    if (
        child["external_ref"] != f"fs-template-hygiene:v2:{child_key}"
        or key_inputs["lane_parent"] != child["lane_parent"]
        or key_inputs["generation_gate_id"] != V2_GENERATION_GATE_ID
        or key_inputs["target_ids"] != target_ids
        or key_inputs["target_roots"] != target_roots
        or key_inputs["semantic_review_disposition"]
        != child["semantic_review_disposition"]
        or key_inputs["semantic_review_receipt_state"]
        != child["semantic_review_receipt_state"]
        or key_inputs["semantic_review_action"]
        != child["semantic_review_action"]
        or key_inputs["semantic_review_receipt_roots"]
        != child["semantic_review_receipt_roots"]
        or key_inputs["responsibility_assignments"]
        != child["responsibility_assignments"]
        or key_inputs["compatibility"] != compatibility
        or semantic_root(key_inputs).split(":", 1)[1] != child_key
    ):
        raise EvidenceFailed("planned child external identity inputs disagree")


def v2_make_child(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    packing_witness: Mapping[str, Any],
    oversize: bool = False,
    oversize_artifact: Mapping[str, Any] | None = None,
    _validate_payload: bool = True,
) -> dict[str, Any]:
    targets = [pair[0] for pair in rows]
    authorities = [pair[1] for pair in rows]
    target_ids = sorted(target["id"] for target in targets)
    target_by_id = {target["id"]: target for target in targets}
    authority_by_id = {
        authority["target_id"]: authority for authority in authorities
    }
    ordered_targets = [target_by_id[target_id] for target_id in target_ids]
    ordered_authorities = [authority_by_id[target_id] for target_id in target_ids]
    priority = int(ordered_targets[0]["priority"])
    hard_vectors = {
        v2_hard_vector(target, authority)
        for target, authority in zip(ordered_targets, ordered_authorities)
    }
    if len(hard_vectors) != 1:
        raise EvidenceFailed("planned child crosses a hard partition vector")
    if len(ordered_targets) > 1:
        compatibility_roots = {
            authority["compatibility"]["receipt_root"]
            for authority in ordered_authorities
        }
        if "" in compatibility_roots or len(compatibility_roots) != 1:
            raise EvidenceFailed("multi-target child lacks one compatibility receipt")
    compatibility = dict(ordered_authorities[0]["compatibility"])
    if len(ordered_targets) == 1 and not compatibility["key"]:
        compatibility["rationale"] = (
            V2_SINGLETON_NO_COMPATIBILITY_RATIONALE
        )
        compatibility["falsifier"] = (
            V2_SINGLETON_NO_COMPATIBILITY_FALSIFIER
        )
    lane_parent = v2_lane_parent(priority)
    description, acceptance, design, notes = v2_child_text(
        ordered_targets,
        ordered_authorities,
        oversize=oversize,
    )
    responsibility_assignments = [
        {
            "target_id": authority["target_id"],
            "implementation_owner": authority["implementation_owner"],
            "evidence_owner": authority["evidence_owner"],
            "terminal_consumer": authority["terminal_consumer"],
        }
        for authority in ordered_authorities
    ]
    stable_key_inputs = {
        "schema": V2_REVIEW_PLAN_SCHEMA,
        "priority": priority,
        "lane_parent": lane_parent,
        "generation_gate_id": V2_GENERATION_GATE_ID,
        "status": ordered_targets[0]["status"],
        "disposition": ordered_targets[0]["disposition"],
        "type": ordered_targets[0]["type"],
        "missing_sections": ordered_targets[0]["missing_sections"],
        "semantic_review_disposition": ordered_authorities[0][
            "semantic_review_disposition"
        ],
        "semantic_review_receipt_state": ordered_authorities[0][
            "semantic_review_receipt_state"
        ],
        "semantic_review_action": ordered_authorities[0][
            "semantic_review_action"
        ],
        "semantic_review_receipt_roots": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority[
                    "semantic_review_receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "responsibility_assignments": responsibility_assignments,
        "readiness": ordered_authorities[0]["readiness"],
        "remediation_route": ordered_authorities[0]["remediation_route"],
        "target_ids": target_ids,
        "target_roots": [target["target_root"] for target in ordered_targets],
        "authority_decision_roots": [
            {
                "target_id": authority["target_id"],
                "decision_root": authority["semantic_root"],
            }
            for authority in ordered_authorities
        ],
        "compatibility": compatibility,
    }
    child_key = semantic_root(stable_key_inputs).split(":", 1)[1]
    actual_review_minutes = sum(
        int(authority["review_minutes"]) for authority in ordered_authorities
    )
    review_minutes = (
        min(actual_review_minutes, V2_REVIEW_MINUTES_CAP)
        if oversize
        else actual_review_minutes
    )
    desired_status = (
        "deferred"
        if any(
            target["status"] in {"blocked", "deferred", "in_progress"}
            or authority["active_work_context"]["conflict"]
            for target, authority in zip(ordered_targets, ordered_authorities)
        )
        else "open"
    )
    coordination_assignees = sorted(
        {
            str(authority["coordination_assignee"])
            for authority in ordered_authorities
            if authority["coordination_assignee"]
        }
    )
    coordination_assignee = (
        coordination_assignees[0] if len(coordination_assignees) == 1 else ""
    )
    disposition = (
        "OVERSIZE_REVIEW_REQUIRED"
        if oversize
        else ordered_targets[0]["disposition"]
    )
    title = (
        f"Review {disposition} template debt for "
        f"{target_ids[0]}"
        if len(target_ids) == 1
        else f"Review {disposition} template debt for {len(target_ids)} targets"
    )
    description_artifact = {
        "media_type": "text/markdown; charset=utf-8",
        "bytes": len(description.encode("utf-8")),
        "root": text_root(description),
        "content": description,
        "transport": "br create --description-file -",
    }
    child = {
        "schema": "frankensim.beads-template-hygiene.planned-child.v2",
        "child_key": child_key,
        "title": title,
        "issue_type": "task",
        "priority": priority,
        "desired_status": desired_status,
        "coordination_assignee": coordination_assignee,
        "labels": sorted(
            {
                "generated-template-review",
                "plan-hygiene",
                "testing",
                "e2e",
                "logging",
                "replay",
                f"priority-p{priority}",
                f"readiness-{ordered_authorities[0]['readiness'].lower()}",
                (
                    "oversize-review-required"
                    if oversize
                    else "bounded-review-shard"
                ),
            }
        ),
        "lane_parent": lane_parent,
        "external_ref": f"fs-template-hygiene:v2:{child_key}",
        "external_ref_key_inputs": stable_key_inputs,
        "source_dependency_snapshot": [
            {
                "target_id": target["id"],
                "dependency_neighborhood_root": target[
                    "dependency_neighborhood_root"
                ],
            }
            for target in ordered_targets
        ],
        "intended_generated_edges": [
            {
                "from": f"generated:{child_key}",
                "to": lane_parent,
                "type": "parent-child",
            },
            {
                "from": V2_GENERATION_GATE_ID,
                "to": f"generated:{child_key}",
                "type": "blocks",
            },
        ],
        "description_file_artifact": description_artifact,
        "description_root": description_artifact["root"],
        "acceptance_criteria": acceptance,
        "acceptance": acceptance,
        "design": design,
        "notes": notes,
        "review_minutes": review_minutes,
        "estimated_minutes": review_minutes,
        "generated_child_estimated_minutes": review_minutes,
        "target_implementation_estimates": [
            {
                "target_id": target["id"],
                "state": target["target_implementation_estimate_state"],
                "estimated_minutes": target[
                    "target_implementation_estimated_minutes"
                ],
            }
            for target in ordered_targets
        ],
        "target_implementation_estimated_minutes": [
            {
                "target_id": target["id"],
                "estimated_minutes": target[
                    "target_implementation_estimated_minutes"
                ],
            }
            for target in ordered_targets
        ],
        "target_implementation_estimate_states": [
            {
                "target_id": target["id"],
                "state": target["target_implementation_estimate_state"],
            }
            for target in ordered_targets
        ],
        "responsibility_assignments": responsibility_assignments,
        "target_ids": target_ids,
        "target_roots": [
            target_by_id[target_id]["target_root"] for target_id in target_ids
        ],
        "disposition_workflow": disposition,
        "semantic_review_disposition": ordered_authorities[0][
            "semantic_review_disposition"
        ],
        "semantic_review_receipt_state": ordered_authorities[0][
            "semantic_review_receipt_state"
        ],
        "semantic_review_action": ordered_authorities[0][
            "semantic_review_action"
        ],
        "semantic_review_receipt_roots": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority[
                    "semantic_review_receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "reviewed_no_change_receipt_roots": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority[
                    "reviewed_no_change_receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "external_authority": [
            {
                "target_id": authority["target_id"],
                **authority["external_authority"],
            }
            for authority in ordered_authorities
        ],
        "external_authority_receipt_root": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority["external_authority"]["receipt_root"],
            }
            for authority in ordered_authorities
        ],
        "external_authority_verdict": [
            {
                "target_id": authority["target_id"],
                "verdict": authority["external_authority"]["verdict"],
            }
            for authority in ordered_authorities
        ],
        "conditional_write_capability": [
            {
                "target_id": authority["target_id"],
                **authority["conditional_write_capability"],
            }
            for authority in ordered_authorities
        ],
        "conditional_write_receipt_root": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority["conditional_write_capability"][
                    "receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "conditional_write_verdict": [
            {
                "target_id": authority["target_id"],
                "verdict": authority["conditional_write_capability"]["verdict"],
            }
            for authority in ordered_authorities
        ],
        "readiness": ordered_authorities[0]["readiness"],
        "remediation_route": ordered_authorities[0]["remediation_route"],
        "packing_witness_root": packing_witness["semantic_root"],
        "compatibility": compatibility,
        "falsifier": (
            "any stale target root, missing payload field, incompatible hard "
            "vector, incomplete compatibility scope, or lost target refuses"
        ),
        "no_claim": V2_PLANNED_CHILD_NO_CLAIM,
    }
    if oversize and oversize_artifact is not None:
        child["notes"] += (
            f" Actual unbounded review estimate: {actual_review_minutes} minutes. "
            f"Full retained oversize artifact: {oversize_artifact['relative_path']} "
            f"root {oversize_artifact['semantic_root']}."
        )
    rooted = v2_rooted(child)
    if _validate_payload:
        v2_validate_child_payload(rooted)
    return rooted


_v2_child_transport_cache: OrderedDict[
    tuple[Any, ...],
    dict[str, int],
] = OrderedDict()


def v2_child_transport_observations(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    oversize: bool = False,
    oversize_artifact: Mapping[str, Any] | None = None,
) -> dict[str, int]:
    cache_key = (
        tuple(
            sorted(
                (
                    str(target["id"]),
                    str(target["target_root"]),
                    str(authority["semantic_root"]),
                )
                for target, authority in rows
            )
        ),
        oversize,
        (
            str(oversize_artifact.get("relative_path")),
            str(oversize_artifact.get("semantic_root")),
        )
        if oversize_artifact is not None
        else None,
    )
    cached = _v2_child_transport_cache.get(cache_key)
    if cached is not None:
        _v2_child_transport_cache.move_to_end(cache_key)
        return dict(cached)
    candidate = v2_make_child(
        rows,
        packing_witness={
            "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
        },
        oversize=oversize,
        oversize_artifact=oversize_artifact,
        _validate_payload=False,
    )
    description = candidate["description_file_artifact"]["content"].encode(
        "utf-8"
    )
    acceptance = candidate["acceptance_criteria"].encode("utf-8")
    design = candidate["design"].encode("utf-8")
    notes = candidate["notes"].encode("utf-8")
    observations = {
        "description_bytes": len(description),
        "acceptance_bytes": len(acceptance),
        "design_bytes": len(design),
        "notes_bytes": len(notes),
        "aggregate_non_description_argv_bytes": (
            len(acceptance) + len(design) + len(notes)
        ),
        "generated_child_payload_bytes": len(canonical_bytes(candidate)),
    }
    _v2_child_transport_cache[cache_key] = dict(observations)
    _v2_child_transport_cache.move_to_end(cache_key)
    while (
        len(_v2_child_transport_cache)
        > V2_CHILD_TRANSPORT_CACHE_ENTRIES_CAP
    ):
        _v2_child_transport_cache.popitem(last=False)
    return observations


def v2_child_transport_violations(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    oversize: bool = False,
    oversize_artifact: Mapping[str, Any] | None = None,
) -> list[dict[str, Any]]:
    observations = v2_child_transport_observations(
        rows,
        oversize=oversize,
        oversize_artifact=oversize_artifact,
    )
    contracts = (
        (
            "max_description_bytes",
            "rendered_child.description_bytes",
            "description_bytes",
            V2_CHILD_DESCRIPTION_CAP,
        ),
        (
            "max_acceptance_bytes",
            "rendered_child.acceptance_bytes",
            "acceptance_bytes",
            V2_CHILD_ACCEPTANCE_CAP,
        ),
        (
            "max_design_bytes",
            "rendered_child.design_bytes",
            "design_bytes",
            V2_CHILD_DESIGN_CAP,
        ),
        (
            "max_notes_bytes",
            "rendered_child.notes_bytes",
            "notes_bytes",
            V2_CHILD_NOTES_CAP,
        ),
        (
            "max_aggregate_non_description_argv_bytes",
            "rendered_child.aggregate_non_description_argv_bytes",
            "aggregate_non_description_argv_bytes",
            V2_CHILD_ARGV_AGGREGATE_CAP,
        ),
        (
            "max_generated_child_payload_bytes",
            "rendered_child.generated_child_payload_bytes",
            "generated_child_payload_bytes",
            V2_GENERATED_CHILD_PAYLOAD_CAP,
        ),
    )
    target_ids = sorted(str(target["id"]) for target, _ in rows)
    return [
        {
            "cap": cap_name,
            "source_path": source_path,
            "observed": observations[observation_name],
            "limit": limit,
            "violation_count": 1,
            "violating_membership_root": semantic_root(target_ids),
        }
        for cap_name, source_path, observation_name, limit in contracts
        if observations[observation_name] > limit
    ]


def v2_partition_transport_constraint_root(
    bins: Sequence[
        Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]
    ],
) -> str:
    rows = [
        {
            "target_ids": sorted(
                str(target["id"]) for target, _ in batch
            ),
            "observations": v2_child_transport_observations(batch),
        }
        for batch in bins
    ]
    rows.sort(key=lambda row: row["target_ids"])
    return semantic_root(
        {
            "caps": {
                "description_bytes": V2_CHILD_DESCRIPTION_CAP,
                "acceptance_bytes": V2_CHILD_ACCEPTANCE_CAP,
                "design_bytes": V2_CHILD_DESIGN_CAP,
                "notes_bytes": V2_CHILD_NOTES_CAP,
                "aggregate_non_description_argv_bytes": (
                    V2_CHILD_ARGV_AGGREGATE_CAP
                ),
                "generated_child_payload_bytes": (
                    V2_GENERATED_CHILD_PAYLOAD_CAP
                ),
            },
            "bins": rows,
        }
    )


def v2_verify_packing_witness_independent(
    *,
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    grouped_children: Sequence[Mapping[str, Any]],
    witness: Mapping[str, Any],
    max_targets: int,
) -> None:
    if not rows:
        raise EvidenceFailed("packing witness has no input rows")
    group_key_root, ordered_load_rows_root = v2_packing_input_bindings(rows)
    if (
        witness.get("group_key_root") != group_key_root
        or witness.get("ordered_load_rows_root") != ordered_load_rows_root
    ):
        raise EvidenceFailed("packing witness input bindings differ")
    load_by_id = {
        str(target["id"]): (
            int(authority["review_minutes"]),
            int(target["retained_payload_bytes"]),
            1,
        )
        for target, authority in rows
    }
    row_by_id = {
        str(target["id"]): (target, authority)
        for target, authority in rows
    }
    expected_ids = sorted(load_by_id)
    memberships = sorted(
        sorted(str(value) for value in child["target_ids"])
        for child in grouped_children
    )
    flattened = [target_id for group in memberships for target_id in group]
    if (
        sorted(flattened) != expected_ids
        or len(flattened) != len(set(flattened))
    ):
        raise EvidenceFailed(
            "packing witness membership is not an exact partition: "
            f"expected={expected_ids!r} observed={memberships!r}"
        )

    def load(membership: Sequence[str]) -> tuple[int, int, int]:
        return (
            sum(load_by_id[target_id][0] for target_id in membership),
            sum(load_by_id[target_id][1] for target_id in membership),
            len(membership),
        )

    def objective_key(
        partition: Sequence[Sequence[str]],
    ) -> tuple[Any, ...]:
        loads = [load(membership) for membership in partition]
        return (
            len(partition),
            max((value[0] for value in loads), default=0),
            max((value[1] for value in loads), default=0),
            max((value[2] for value in loads), default=0),
            tuple(sorted(loads, reverse=True)),
            tuple(
                sorted(tuple(sorted(membership)) for membership in partition)
            ),
        )

    def objective_document(
        partition: Sequence[Sequence[str]],
    ) -> dict[str, Any]:
        key = objective_key(partition)
        return {
            "child_count": key[0],
            "maximum_review_minutes": key[1],
            "maximum_retained_payload_bytes": key[2],
            "maximum_target_count": key[3],
            "descending_load_vectors": [
                list(value) for value in key[4]
            ],
            "lexicographic_memberships": [
                list(value) for value in key[5]
            ],
        }

    for membership in memberships:
        minutes, retained_bytes, target_count = load(membership)
        if (
            not membership
            or target_count > max_targets
            or minutes > V2_REVIEW_MINUTES_CAP
            or retained_bytes > V2_CHILD_PAYLOAD_CAP
            or not v2_bin_feasible(
                [row_by_id[target_id] for target_id in membership],
                max_targets=max_targets,
            )
        ):
            raise EvidenceFailed("packing witness contains an infeasible child")
    observed_objective = objective_document(memberships)
    algorithm = witness.get("algorithm")
    if algorithm == "EXACT_SUBSET_PARTITION":
        v2_exact_keys(
            witness,
            {
                "algorithm",
                "group_key_root",
                "ordered_load_rows_root",
                "exact_optimality_max_targets",
                "exact_optimality_claim",
                "objective",
                "transport_constraint_root",
                "max_targets_per_child",
                "rationale",
                "falsifier",
                "semantic_root",
            },
            label="exact packing witness",
        )
        if (
            len(expected_ids) > V2_EXACT_OPTIMALITY_MAX_TARGETS
            or witness["exact_optimality_max_targets"]
            != V2_EXACT_OPTIMALITY_MAX_TARGETS
            or witness["exact_optimality_claim"] is not True
            or witness["transport_constraint_root"]
            != v2_partition_transport_constraint_root(
                [
                    [
                        row_by_id[target_id]
                        for target_id in membership
                    ]
                    for membership in memberships
                ]
            )
            or witness["max_targets_per_child"] != max_targets
            or not isinstance(witness["rationale"], str)
            or not witness["rationale"]
            or not isinstance(witness["falsifier"], str)
            or not witness["falsifier"]
        ):
            raise EvidenceFailed("exact packing witness scalar contract differs")
        count = len(expected_ids)
        feasible_masks: dict[int, list[int]] = defaultdict(list)
        for mask in range(1, 1 << count):
            membership = [
                expected_ids[index]
                for index in range(count)
                if mask & (1 << index)
            ]
            minutes, retained_bytes, target_count = load(membership)
            if (
                target_count <= max_targets
                and minutes <= V2_REVIEW_MINUTES_CAP
                and retained_bytes <= V2_CHILD_PAYLOAD_CAP
                and v2_bin_feasible(
                    [row_by_id[target_id] for target_id in membership],
                    max_targets=max_targets,
                )
            ):
                pivot = (mask & -mask).bit_length() - 1
                feasible_masks[pivot].append(mask)
        memo: dict[int, tuple[tuple[str, ...], ...]] = {0: ()}

        def solve(mask: int) -> tuple[tuple[str, ...], ...]:
            if mask in memo:
                return memo[mask]
            pivot = (mask & -mask).bit_length() - 1
            best: tuple[tuple[str, ...], ...] | None = None
            best_key: tuple[Any, ...] | None = None
            for subset in feasible_masks[pivot]:
                if subset & mask != subset:
                    continue
                membership = tuple(
                    expected_ids[index]
                    for index in range(count)
                    if subset & (1 << index)
                )
                candidate = tuple(
                    sorted((membership, *solve(mask ^ subset)))
                )
                candidate_key = objective_key(candidate)
                if best_key is None or candidate_key < best_key:
                    best = candidate
                    best_key = candidate_key
            if best is None:
                raise EvidenceFailed(
                    "independent exact verifier found no feasible partition"
                )
            memo[mask] = best
            return best

        optimum = solve((1 << count) - 1)
        if (
            objective_key(memberships) != objective_key(optimum)
            or witness["objective"] != observed_objective
        ):
            raise EvidenceFailed(
                "exact packing witness is not independently optimal"
            )
        return
    if algorithm == "DETERMINISTIC_LPT_VECTOR_PACKING":
        v2_exact_keys(
            witness,
            {
                "algorithm",
                "group_key_root",
                "ordered_load_rows_root",
                "lower_bound_children",
                "observed_children",
                "child_count_gap",
                "lower_bound_vector",
                "transport_constraint_root",
                "achieved_objective",
                "gap_witness",
                "exact_optimality_claim",
                "max_targets_per_child",
                "rationale",
                "falsifier",
                "semantic_root",
            },
            label="large packing witness",
        )
        total_minutes = sum(value[0] for value in load_by_id.values())
        total_bytes = sum(value[1] for value in load_by_id.values())
        lower_bound_vector = {
            "targets": math.ceil(len(expected_ids) / max_targets),
            "review_minutes": math.ceil(
                total_minutes / V2_REVIEW_MINUTES_CAP
            ),
            "retained_payload_bytes": math.ceil(
                total_bytes / V2_CHILD_PAYLOAD_CAP
            ),
        }
        lower_bound = max(*lower_bound_vector.values(), 1)
        observed_children = len(memberships)
        gap = observed_children - lower_bound
        expected_gap = {
            "child_count": gap,
            "maximum_review_minutes_above_average": (
                observed_objective["maximum_review_minutes"]
                - math.ceil(total_minutes / observed_children)
            ),
            "maximum_retained_bytes_above_average": (
                observed_objective["maximum_retained_payload_bytes"]
                - math.ceil(total_bytes / observed_children)
            ),
        }
        if (
            len(expected_ids) <= V2_EXACT_OPTIMALITY_MAX_TARGETS
            or witness["lower_bound_vector"] != lower_bound_vector
            or witness["transport_constraint_root"]
            != v2_partition_transport_constraint_root(
                [
                    [
                        row_by_id[target_id]
                        for target_id in membership
                    ]
                    for membership in memberships
                ]
            )
            or witness["lower_bound_children"] != lower_bound
            or witness["observed_children"] != observed_children
            or witness["child_count_gap"] != gap
            or witness["achieved_objective"] != observed_objective
            or witness["gap_witness"] != expected_gap
            or witness["exact_optimality_claim"] is not False
            or witness["max_targets_per_child"] != max_targets
            or gap < 0
            or any(value < 0 for value in expected_gap.values())
            or not isinstance(witness["rationale"], str)
            or not witness["rationale"]
            or not isinstance(witness["falsifier"], str)
            or not witness["falsifier"]
        ):
            raise EvidenceFailed("large packing witness arithmetic differs")
        return
    raise EvidenceFailed("independent packing verifier received an unknown algorithm")


def v2_review_plan_universe(
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> tuple[dict[str, Mapping[str, Any]], dict[str, Mapping[str, Any]]]:
    upstream_targets = {
        row["id"]: row
        for row in inventory["rows"]
        if row["status"] != "closed"
    }
    upstream_authority = {
        row["target_id"]: row
        for row in authority["decisions"]
        if row["target_id"] in upstream_targets
    }
    if set(upstream_authority) != set(upstream_targets):
        raise EvidenceFailed(
            "v2 review-plan lacks an authority decision for its upstream universe"
        )
    filters = inventory.get("filters")
    if not isinstance(filters, dict):
        raise EvidenceFailed("v2 review-plan inventory filters are malformed")
    readiness = set(filters.get("readiness") or [])
    routes = set(filters.get("routes") or [])
    selected_ids = sorted(
        target_id
        for target_id, decision in upstream_authority.items()
        if (not readiness or decision["readiness"] in readiness)
        and (
            not routes
            or decision["remediation_route"] in routes
        )
    )
    return (
        {
            target_id: upstream_targets[target_id]
            for target_id in selected_ids
        },
        {
            target_id: upstream_authority[target_id]
            for target_id in selected_ids
        },
    )


def v2_preflight_review_plan_collections(
    review_plan: Mapping[str, Any],
) -> tuple[
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
]:
    bounded_fields = (
        ("children", "children"),
        ("packing_witnesses", "packing witnesses"),
        ("semantic_adjudications", "semantic adjudications"),
        (
            "retained_without_direct_child",
            "retained-without-direct-child rows",
        ),
        ("remediation_candidates", "remediation candidates"),
        ("oversize_content", "oversize registry"),
    )
    collections: list[list[dict[str, Any]]] = []
    for field, label in bounded_fields:
        rows = review_plan.get(field)
        if not isinstance(rows, list):
            raise EvidenceFailed(f"v2 review-plan {label} are malformed")
        if len(rows) > V2_INVENTORY_ROWS_CAP:
            raise EvidenceFailed(
                f"v2 review-plan {label} exceed the "
                f"{V2_INVENTORY_ROWS_CAP}-row cap"
            )
        if any(not isinstance(row, dict) for row in rows):
            raise EvidenceFailed(f"v2 review-plan {label} are malformed")
        collections.append(rows)
    sized_review_plan = (
        review_plan
        if "semantic_root" in review_plan
        else {
            **review_plan,
            "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
        }
    )
    v2_validate_canonical_byte_size(
        sized_review_plan,
        cap=RUN_ARTIFACT_CAP,
        label="v2 review plan",
    )
    return (
        collections[0],
        collections[1],
        collections[2],
        collections[3],
        collections[4],
        collections[5],
    )


def v2_validate_review_plan(
    review_plan: Mapping[str, Any],
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> None:
    if not isinstance(review_plan, dict):
        raise EvidenceFailed("v2 review plan is not an object")
    v2_exact_keys(
        review_plan,
        V2_REVIEW_PLAN_FIELDS,
        label="v2 review plan",
    )
    (
        children,
        witnesses,
        adjudications,
        retained_without_direct_child,
        remediation_candidates,
        oversize_content,
    ) = v2_preflight_review_plan_collections(review_plan)
    verify_semantic_root(review_plan, label="v2 review plan")
    counts = review_plan["counts"]
    work = review_plan["work"]
    if not isinstance(counts, dict) or not isinstance(work, dict):
        raise EvidenceFailed("v2 review-plan counts or work projection is malformed")
    v2_exact_keys(
        counts,
        V2_REVIEW_PLAN_COUNT_FIELDS,
        label="v2 review-plan counts",
    )
    v2_exact_keys(
        work,
        V2_REVIEW_PLAN_WORK_FIELDS,
        label="v2 review-plan work",
    )
    if (
        review_plan.get("schema") != V2_REVIEW_PLAN_SCHEMA
        or review_plan.get("state") != "POPULATED"
        or review_plan.get("inventory_root") != inventory.get("semantic_root")
        or review_plan.get("authority_root") != authority.get("semantic_root")
        or review_plan.get("campaign_epoch_root")
        != inventory.get("campaign_epoch_root")
        or review_plan.get("hard_max_targets_per_child")
        != V2_REVIEW_TARGET_HARD_MAX
        or review_plan.get("review_minutes_cap") != V2_REVIEW_MINUTES_CAP
        or review_plan.get("retained_child_bytes_cap") != V2_CHILD_PAYLOAD_CAP
        or review_plan.get("no_claim") != V2_REVIEW_PLAN_NO_CLAIM
    ):
        raise EvidenceFailed(
            "v2 review-plan identity, cap, or source bindings disagree"
        )
    witness_by_root: dict[str, Mapping[str, Any]] = {}
    for witness in witnesses:
        verify_semantic_root(witness, label="v2 packing witness")
        witness_root = str(witness["semantic_root"])
        if witness_root in witness_by_root:
            raise EvidenceFailed("v2 review-plan duplicates a packing witness")
        witness_by_root[witness_root] = witness
    target_by_id, authority_by_id = v2_review_plan_universe(
        inventory,
        authority,
    )
    expected_scheduled_ids = sorted(
        target_id
        for target_id, decision in authority_by_id.items()
        if decision["semantic_review_action"]
        != "RETAINED_ADJUDICATION"
    )
    expected_adjudications: list[dict[str, Any]] = []
    for target_id, decision in sorted(authority_by_id.items()):
        if (
            decision["semantic_review_receipt_state"]
            != "ROOT_BOUND_REVIEWED"
        ):
            continue
        expected_adjudications.append(
            v2_rooted(
                {
                    "target_id": target_id,
                    "target_root": target_by_id[target_id]["target_root"],
                    "authority_decision_root": decision["semantic_root"],
                    "semantic_review_disposition": decision[
                        "semantic_review_disposition"
                    ],
                    "semantic_review_receipt_state": decision[
                        "semantic_review_receipt_state"
                    ],
                    "semantic_review_action": decision[
                        "semantic_review_action"
                    ],
                    "semantic_review_receipt_root": decision[
                        "semantic_review_receipt_root"
                    ],
                    "reviewed_no_change_receipt_root": decision[
                        "reviewed_no_change_receipt_root"
                    ],
                    "future_corrective_materialization_eligible": (
                        decision["semantic_review_disposition"]
                        == "REMEDIATION_REQUIRED"
                    ),
                    "no_claim": (
                        "root-bound semantic adjudication is retained planning "
                        "evidence and does not itself mutate or complete a target"
                    ),
                }
            )
        )
    expected_retained = [
        row
        for row in expected_adjudications
        if row["semantic_review_action"] == "RETAINED_ADJUDICATION"
    ]
    expected_remediation = [
        row
        for row in expected_adjudications
        if row["future_corrective_materialization_eligible"]
    ]
    if (
        adjudications != expected_adjudications
        or retained_without_direct_child != expected_retained
        or remediation_candidates != expected_remediation
    ):
        raise EvidenceFailed(
            "v2 review-plan semantic adjudication projection differs"
        )
    observed_ids: list[str] = []
    for child in children:
        v2_validate_child_payload(child)
        ids = child["target_ids"]
        roots = child["target_roots"]
        if any(target_id not in target_by_id for target_id in ids):
            raise EvidenceFailed("v2 review-plan child substitutes an unknown target")
        expected_roots = [target_by_id[target_id]["target_root"] for target_id in ids]
        if roots != expected_roots:
            raise EvidenceFailed("v2 review-plan child target roots disagree")
        for target_id in ids:
            target = target_by_id[target_id]
            decision = authority_by_id[target_id]
            expected_vector = v2_hard_vector(target, decision)
            observed_vector = (
                child["priority"],
                target["status"],
                child["disposition_workflow"],
                target["type"],
                tuple(target["missing_sections"]),
                child["semantic_review_disposition"],
                child["semantic_review_receipt_state"],
                child["semantic_review_action"],
                child["readiness"],
                child["remediation_route"],
            )
            if child["disposition_workflow"] == "OVERSIZE_REVIEW_REQUIRED":
                observed_vector = (
                    child["priority"],
                    target["status"],
                    target["disposition"],
                    target["type"],
                    tuple(target["missing_sections"]),
                    child["semantic_review_disposition"],
                    child["semantic_review_receipt_state"],
                    child["semantic_review_action"],
                    child["readiness"],
                    child["remediation_route"],
                )
            if observed_vector != expected_vector:
                raise EvidenceFailed(
                    "v2 review-plan child crosses a hard partition vector"
                )
        observed_ids.extend(ids)
    expected_ids = expected_scheduled_ids
    if (
        sorted(observed_ids) != expected_ids
        or len(observed_ids) != len(set(observed_ids))
    ):
        raise EvidenceFailed(
            "v2 review-plan target mapping is dropped, duplicated, or substituted"
        )
    retained_ids = sorted(
        row["target_id"] for row in expected_retained
    )
    if sorted([*observed_ids, *retained_ids]) != sorted(target_by_id):
        raise EvidenceFailed(
            "v2 review-plan scheduled and retained target universe differs"
        )
    if (
        counts.get("targets") != len(target_by_id)
        or counts.get("scheduled_targets") != len(expected_ids)
        or counts.get("retained_without_direct_child")
        != len(expected_retained)
        or counts.get("semantic_adjudications")
        != len(expected_adjudications)
        or counts.get("remediation_candidates")
        != len(expected_remediation)
    ):
        raise EvidenceFailed("v2 review-plan target counts disagree with membership")
    children_by_witness: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for child in children:
        witness_root = str(child["packing_witness_root"])
        if witness_root not in witness_by_root:
            raise EvidenceFailed(
                "v2 review-plan child references an unknown packing witness"
            )
        children_by_witness[witness_root].append(child)
    if set(children_by_witness) != set(witness_by_root):
        raise EvidenceFailed("v2 review-plan retains an unused packing witness")
    max_targets = review_plan.get("max_targets_per_child")
    if (
        type(max_targets) is not int
        or not 1 <= max_targets <= V2_REVIEW_TARGET_HARD_MAX
    ):
        raise EvidenceFailed("v2 review-plan target cap is malformed")
    oversize_by_target: dict[str, Mapping[str, Any]] = {}
    oversize_paths: set[str] = set()
    for index, entry in enumerate(oversize_content):
        if not isinstance(entry, dict):
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} is malformed"
            )
        v2_exact_keys(
            entry,
            V2_OVERSIZE_REGISTRY_FIELDS,
            label=f"v2 review-plan oversize row {index}",
        )
        target_roots = entry["target_roots"]
        if (
            not isinstance(target_roots, list)
            or len(target_roots) != 1
            or not isinstance(target_roots[0], str)
        ):
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} has malformed target roots"
            )
        target_root = target_roots[0]
        matching_targets = [
            target
            for target in target_by_id.values()
            if target["target_root"] == target_root
        ]
        if len(matching_targets) != 1:
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} names an unknown target"
            )
        target = matching_targets[0]
        decision = authority_by_id[target["id"]]
        expected_exceeded = v2_oversize_exceeded_caps(target, decision)
        relative = str(
            safe_relative(
                entry["relative_path"],
                label=f"v2 review-plan oversize row {index}",
            )
        )
        expected_relative = (
            "oversize/"
            f"{str(target_root).split(':', 1)[-1]}.json"
        )
        if (
            target_root in oversize_by_target
            or relative in oversize_paths
            or relative != expected_relative
            or entry["media_kind"] != "application/json"
            or entry["schema_kind"]
            != "frankensim.beads-template-hygiene.oversize-review.v2"
            or type(entry["byte_length"]) is not int
            or entry["byte_length"] < 0
            or type(entry["aggregate_cap_accounting"]) is not int
            or entry["aggregate_cap_accounting"] != entry["byte_length"]
            or not isinstance(entry["semantic_root"], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                entry["semantic_root"],
            )
            is None
            or entry["field_roots"] != target["field_roots"]
            or entry["clause_roots"] != target["clause_roots"]
            or entry["exceeded_caps"] != expected_exceeded
            or not expected_exceeded
        ):
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} differs from its target"
            )
        oversize_by_target[target_root] = entry
        oversize_paths.add(relative)
    expected_oversize_roots = {
        target_by_id[target_id]["target_root"]
        for target_id in expected_scheduled_ids
        if v2_oversize_exceeded_caps(
            target_by_id[target_id],
            authority_by_id[target_id],
        )
    }
    if set(oversize_by_target) != expected_oversize_roots:
        raise EvidenceFailed(
            "v2 review-plan oversize registry membership differs from source"
        )
    if (
        children
        != sorted(
            children,
            key=lambda child: (child["priority"], child["child_key"]),
        )
        or witnesses
        != sorted(witnesses, key=lambda witness: witness["semantic_root"])
        or oversize_content
        != sorted(
            oversize_content,
            key=lambda entry: entry["relative_path"],
        )
    ):
        raise EvidenceFailed(
            "v2 review-plan child, witness, or oversize ordering is noncanonical"
        )
    for witness_root, grouped_children in children_by_witness.items():
        witness = witness_by_root[witness_root]
        algorithm = witness.get("algorithm")
        grouped_ids = sorted(
            target_id
            for child in grouped_children
            for target_id in child["target_ids"]
        )
        if algorithm == "OVERSIZE_ESCALATION":
            v2_exact_keys(
                witness,
                V2_OVERSIZE_WITNESS_FIELDS,
                label="oversize packing witness",
            )
            if (
                len(grouped_children) != 1
                or len(grouped_ids) != 1
                or witness.get("target_id") != grouped_ids[0]
                or grouped_children[0]["disposition_workflow"]
                != "OVERSIZE_REVIEW_REQUIRED"
                or witness.get("exact_optimality_claim") is not False
                or not isinstance(witness.get("reason"), str)
                or not witness["reason"]
            ):
                raise EvidenceFailed(
                    "v2 oversize witness membership or disposition disagrees"
                )
            target_root = target_by_id[grouped_ids[0]]["target_root"]
            entry = oversize_by_target.get(target_root)
            oversize_rows = [
                (
                    target_by_id[grouped_ids[0]],
                    authority_by_id[grouped_ids[0]],
                )
            ]
            group_key_root, ordered_load_rows_root = (
                v2_packing_input_bindings(oversize_rows)
            )
            expected_exceeded_caps = v2_oversize_exceeded_caps(
                oversize_rows[0][0],
                oversize_rows[0][1],
            )
            if (
                entry is None
                or witness.get("full_artifact_root")
                != entry.get("semantic_root")
                or witness.get("group_key_root") != group_key_root
                or witness.get("ordered_load_rows_root")
                != ordered_load_rows_root
                or witness.get("exceeded_caps") != expected_exceeded_caps
                or entry.get("exceeded_caps") != expected_exceeded_caps
                or witness.get("reason")
                != (
                    "single target exceeds "
                    + ", ".join(
                        row["cap"] for row in expected_exceeded_caps
                    )
                )
            ):
                raise EvidenceFailed(
                    "v2 oversize witness is not bound to its registered artifact"
                )
            continue
        if algorithm not in {
            "EXACT_SUBSET_PARTITION",
            "DETERMINISTIC_LPT_VECTOR_PACKING",
        }:
            raise EvidenceFailed("v2 packing witness uses an unknown algorithm")
        grouped_rows = [
            (target_by_id[target_id], authority_by_id[target_id])
            for target_id in grouped_ids
        ]
        v2_verify_packing_witness_independent(
            rows=grouped_rows,
            grouped_children=grouped_children,
            witness=witness,
            max_targets=max_targets,
        )
    for child in children:
        child_ids = list(child["target_ids"])
        witness = witness_by_root[str(child["packing_witness_root"])]
        child_rows = [
            (target_by_id[target_id], authority_by_id[target_id])
            for target_id in child_ids
        ]
        if witness.get("algorithm") == "OVERSIZE_ESCALATION":
            target_root = target_by_id[child_ids[0]]["target_root"]
            expected_child = v2_make_child(
                child_rows,
                packing_witness=witness,
                oversize=True,
                oversize_artifact=oversize_by_target.get(target_root),
            )
        else:
            expected_child = v2_make_child(
                child_rows,
                packing_witness=witness,
            )
        if child != expected_child:
            divergence = first_projection_divergence(
                expected_child,
                child,
            )
            raise EvidenceFailed(
                "v2 review-plan child differs from its exact source-derived "
                f"projection at {divergence or '$'}"
            )
    expected_counts = {
        "targets": len(target_by_id),
        "scheduled_targets": len(expected_ids),
        "retained_without_direct_child": len(expected_retained),
        "semantic_adjudications": len(expected_adjudications),
        "remediation_candidates": len(expected_remediation),
        "children": len(children),
        "oversize_targets": len(expected_oversize_roots),
        "readiness": dict(
            sorted(
                Counter(
                    decision["readiness"]
                    for decision in authority_by_id.values()
                ).items()
            )
        ),
        "routes": dict(
            sorted(
                Counter(
                    decision["remediation_route"]
                    for decision in authority_by_id.values()
                ).items()
            )
        ),
    }
    expected_work = {
        "total_review_minutes": sum(
            int(authority_by_id[target_id]["review_minutes"])
            for target_id in expected_ids
        ),
        "total_bounded_child_review_minutes": sum(
            int(child["review_minutes"]) for child in children
        ),
        "total_underlying_target_review_minutes": sum(
            int(decision["review_minutes"])
            for decision in authority_by_id.values()
        ),
        "total_completed_adjudication_minutes": sum(
            int(authority_by_id[row["target_id"]]["review_minutes"])
            for row in expected_retained
        ),
        "minimum_child_review_minutes": min(
            (int(child["review_minutes"]) for child in children),
            default=0,
        ),
        "maximum_child_review_minutes": max(
            (int(child["review_minutes"]) for child in children),
            default=0,
        ),
    }
    if counts != expected_counts or work != expected_work:
        divergence = first_projection_divergence(
            {"counts": expected_counts, "work": expected_work},
            {"counts": counts, "work": work},
        )
        raise EvidenceFailed(
            "v2 review-plan count or work projection differs at "
            f"{divergence or '$'}"
        )


def v2_oversize_exceeded_caps(
    target: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> list[dict[str, Any]]:
    candidates = [
        (
            "max_review_minutes_per_child",
            "authority.review_minutes",
            int(authority["review_minutes"]),
            V2_REVIEW_MINUTES_CAP,
        ),
        (
            "max_retained_child_payload_bytes",
            "target.retained_payload_bytes",
            int(target["retained_payload_bytes"]),
            V2_CHILD_PAYLOAD_CAP,
        ),
        (
            "max_description_bytes",
            "target.field_byte_lengths.description",
            int(target["field_byte_lengths"]["description"]),
            V2_CHILD_DESCRIPTION_CAP,
        ),
        (
            "max_acceptance_bytes",
            "target.field_byte_lengths.acceptance_criteria",
            int(target["field_byte_lengths"]["acceptance_criteria"]),
            V2_CHILD_ACCEPTANCE_CAP,
        ),
        (
            "max_design_bytes",
            "target.field_byte_lengths.design",
            int(target["field_byte_lengths"]["design"]),
            V2_CHILD_DESIGN_CAP,
        ),
        (
            "max_notes_bytes",
            "target.field_byte_lengths.notes",
            int(target["field_byte_lengths"]["notes"]),
            V2_CHILD_NOTES_CAP,
        ),
    ]
    exceeded = [
        {
            "cap": cap_name,
            "source_path": source_path,
            "observed": observed,
            "limit": limit,
            "violation_count": 1,
            "violating_membership_root": semantic_root(
                [
                    {
                        "source_path": source_path,
                        "observed": observed,
                    }
                ]
            ),
        }
        for cap_name, source_path, observed, limit in candidates
        if observed > limit
    ]
    exceeded.extend(
        v2_child_transport_violations([(target, authority)])
    )
    clause_index = target["clause_roots"]
    v2_validate_clause_index(clause_index)
    if clause_index["row_count"] > V2_CLAUSE_ROWS_CAP:
        exceeded.append(
            {
                "cap": "max_clause_rows_per_issue",
                "source_path": "target.clause_roots.row_count",
                "observed": int(clause_index["row_count"]),
                "limit": V2_CLAUSE_ROWS_CAP,
                "violation_count": (
                    int(clause_index["row_count"]) - V2_CLAUSE_ROWS_CAP
                ),
                "violating_membership_root": str(
                    clause_index["over_row_cap_membership_root"]
                ),
            }
        )
    if clause_index["over_byte_cap_count"]:
        exceeded.append(
            {
                "cap": "max_clause_bytes",
                "source_path": "target.clause_roots.maximum_clause_bytes",
                "observed": int(clause_index["maximum_clause_bytes"]),
                "limit": V2_CLAUSE_BYTES_CAP,
                "violation_count": int(
                    clause_index["over_byte_cap_count"]
                ),
                "violating_membership_root": str(
                    clause_index["over_byte_cap_membership_root"]
                ),
            }
        )
    exceeded.sort(
        key=lambda row: (
            str(row["cap"]).encode("utf-8"),
            str(row["source_path"]).encode("utf-8"),
        )
    )
    if any(set(row) != V2_OVERSIZE_EXCEEDED_CAP_FIELDS for row in exceeded):
        raise EvidenceFailed("v2 oversize cap diagnostics escaped their schema")
    return exceeded


def v2_build_review_plan(
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    *,
    max_targets: int,
) -> tuple[dict[str, Any], dict[str, bytes]]:
    all_target_by_id, all_authority_by_id = v2_review_plan_universe(
        inventory,
        authority,
    )
    scheduled_ids = sorted(
        target_id
        for target_id, decision in all_authority_by_id.items()
        if decision["semantic_review_action"]
        != "RETAINED_ADJUDICATION"
    )
    target_by_id = {
        target_id: all_target_by_id[target_id] for target_id in scheduled_ids
    }
    authority_by_id = {
        target_id: all_authority_by_id[target_id]
        for target_id in scheduled_ids
    }
    semantic_adjudications = [
        v2_rooted(
            {
                "target_id": target_id,
                "target_root": all_target_by_id[target_id]["target_root"],
                "authority_decision_root": decision["semantic_root"],
                "semantic_review_disposition": decision[
                    "semantic_review_disposition"
                ],
                "semantic_review_receipt_state": decision[
                    "semantic_review_receipt_state"
                ],
                "semantic_review_action": decision[
                    "semantic_review_action"
                ],
                "semantic_review_receipt_root": decision[
                    "semantic_review_receipt_root"
                ],
                "reviewed_no_change_receipt_root": decision[
                    "reviewed_no_change_receipt_root"
                ],
                "future_corrective_materialization_eligible": (
                    decision["semantic_review_receipt_state"]
                    == "ROOT_BOUND_REVIEWED"
                    and decision["semantic_review_disposition"]
                    == "REMEDIATION_REQUIRED"
                ),
                "no_claim": (
                    "root-bound semantic adjudication is retained planning "
                    "evidence and does not itself mutate or complete a target"
                ),
            }
        )
        for target_id, decision in sorted(all_authority_by_id.items())
        if decision["semantic_review_receipt_state"]
        == "ROOT_BOUND_REVIEWED"
    ]
    retained_without_direct_child = [
        row
        for row in semantic_adjudications
        if row["semantic_review_action"] == "RETAINED_ADJUDICATION"
    ]
    remediation_candidates = [
        row
        for row in semantic_adjudications
        if row["future_corrective_materialization_eligible"]
    ]
    groups: dict[tuple[Any, ...], list[tuple[Mapping[str, Any], Mapping[str, Any]]]] = (
        defaultdict(list)
    )
    oversize_rows: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
    for target_id in scheduled_ids:
        target = target_by_id[target_id]
        decision = authority_by_id[target_id]
        if v2_oversize_exceeded_caps(target, decision):
            oversize_rows.append((target, decision))
            continue
        key = v2_packing_group_key(target, decision)
        groups[key].append((target, decision))

    children: list[dict[str, Any]] = []
    packing_witnesses: list[dict[str, Any]] = []
    for key in sorted(groups, key=lambda value: repr(value)):
        rows = groups[key]
        bins, witness = v2_pack_group(rows, max_targets=max_targets)
        packing_witnesses.append(witness)
        for batch in bins:
            children.append(
                v2_make_child(batch, packing_witness=witness)
            )

    oversize_payloads: dict[str, bytes] = {}
    oversize_inventory: list[dict[str, Any]] = []
    for target, decision in oversize_rows:
        exceeded_caps = v2_oversize_exceeded_caps(target, decision)
        if not exceeded_caps:
            raise EvidenceFailed(
                "v2 oversize routing lacks an independently exceeded cap"
            )
        relative = (
            "oversize/"
            f"{str(target['target_root']).split(':', 1)[-1]}.json"
        )
        complete_plan = {
            "target": target,
            "authority": decision,
            "actual_review_minutes": int(decision["review_minutes"]),
        }
        complete_plan_root = semantic_root(complete_plan)
        full = v2_rooted(
            {
                "schema": (
                    "frankensim.beads-template-hygiene.oversize-review.v2"
                ),
                "source_roots": [
                    target["target_root"],
                    target["v1_row_root"],
                    target["campaign_epoch_root"],
                ],
                "field_roots": target["field_roots"],
                "clause_roots": target["clause_roots"],
                "exceeded_caps": exceeded_caps,
                "bounded_incomplete_index": {
                    "complete": False,
                    "target_id": target["id"],
                    "missing_sections": target["missing_sections"],
                },
                "canonical_br_show_argv": [
                    "br",
                    "show",
                    target["id"],
                    "--json",
                    *BR_READ_FLAGS,
                ],
                "retained_full_plan_path": relative,
                "retained_full_plan_root": complete_plan_root,
                "complete_plan": complete_plan,
                "owner_questions": list(V2_OVERSIZE_OWNER_QUESTIONS),
                "no_claim": V2_OVERSIZE_NO_CLAIM,
            }
        )
        payload = canonical_bytes(full)
        oversize_payloads[relative] = payload
        entry = {
            "relative_path": relative,
            "media_kind": "application/json",
            "schema_kind": full["schema"],
            "byte_length": len(payload),
            "semantic_root": full["semantic_root"],
            "target_roots": [target["target_root"]],
            "field_roots": target["field_roots"],
            "clause_roots": target["clause_roots"],
            "exceeded_caps": exceeded_caps,
            "aggregate_cap_accounting": len(payload),
        }
        oversize_transport_violations = v2_child_transport_violations(
            [(target, decision)],
            oversize=True,
            oversize_artifact=entry,
        )
        if oversize_transport_violations:
            raise InputRefused(
                "UNREPRESENTABLE_CHILD_TRANSPORT: even the bounded oversize "
                "handoff exceeds "
                + ", ".join(
                    row["cap"] for row in oversize_transport_violations
                )
            )
        oversize_inventory.append(entry)
        group_key_root, ordered_load_rows_root = v2_packing_input_bindings(
            [(target, decision)]
        )
        witness = v2_rooted(
            {
                "algorithm": "OVERSIZE_ESCALATION",
                "group_key_root": group_key_root,
                "ordered_load_rows_root": ordered_load_rows_root,
                "target_id": target["id"],
                "exceeded_caps": exceeded_caps,
                "reason": (
                    "single target exceeds "
                    + ", ".join(row["cap"] for row in exceeded_caps)
                ),
                "full_artifact_root": full["semantic_root"],
                "exact_optimality_claim": False,
            }
        )
        packing_witnesses.append(witness)
        children.append(
            v2_make_child(
                [(target, decision)],
                packing_witness=witness,
                oversize=True,
                oversize_artifact=entry,
            )
        )

    children.sort(key=lambda child: (child["priority"], child["child_key"]))
    mapped_ids = [target_id for child in children for target_id in child["target_ids"]]
    expected_scheduled_ids = scheduled_ids
    if (
        sorted(mapped_ids) != expected_scheduled_ids
        or len(mapped_ids) != len(set(mapped_ids))
    ):
        raise EvidenceFailed(
            "v2 plan does not exact-map every scheduled target once"
        )
    retained_ids = sorted(
        row["target_id"] for row in retained_without_direct_child
    )
    if (
        sorted([*mapped_ids, *retained_ids])
        != sorted(all_target_by_id)
        or set(mapped_ids) & set(retained_ids)
    ):
        raise EvidenceFailed(
            "v2 plan does not exactly partition scheduled and retained targets"
        )
    document = {
        "schema": V2_REVIEW_PLAN_SCHEMA,
        "state": "POPULATED",
        "inventory_root": inventory["semantic_root"],
        "authority_root": authority["semantic_root"],
        "campaign_epoch_root": inventory["campaign_epoch_root"],
        "max_targets_per_child": max_targets,
        "hard_max_targets_per_child": V2_REVIEW_TARGET_HARD_MAX,
        "review_minutes_cap": V2_REVIEW_MINUTES_CAP,
        "retained_child_bytes_cap": V2_CHILD_PAYLOAD_CAP,
        "children": children,
        "semantic_adjudications": semantic_adjudications,
        "retained_without_direct_child": retained_without_direct_child,
        "remediation_candidates": remediation_candidates,
        "packing_witnesses": sorted(
            packing_witnesses, key=lambda row: row["semantic_root"]
        ),
        "oversize_content": sorted(
            oversize_inventory, key=lambda row: row["relative_path"]
        ),
        "counts": {
            "targets": len(all_target_by_id),
            "scheduled_targets": len(expected_scheduled_ids),
            "retained_without_direct_child": len(
                retained_without_direct_child
            ),
            "semantic_adjudications": len(semantic_adjudications),
            "remediation_candidates": len(remediation_candidates),
            "children": len(children),
            "oversize_targets": len(oversize_rows),
            "readiness": dict(
                sorted(
                    Counter(
                        decision["readiness"]
                        for decision in all_authority_by_id.values()
                    ).items()
                )
            ),
            "routes": dict(
                sorted(
                    Counter(
                        decision["remediation_route"]
                        for decision in all_authority_by_id.values()
                    ).items()
                )
            ),
        },
        "work": {
            "total_review_minutes": sum(
                int(decision["review_minutes"])
                for decision in authority_by_id.values()
            ),
            "total_bounded_child_review_minutes": sum(
                int(child["review_minutes"]) for child in children
            ),
            "total_underlying_target_review_minutes": sum(
                int(decision["review_minutes"])
                for decision in all_authority_by_id.values()
            ),
            "total_completed_adjudication_minutes": sum(
                int(all_authority_by_id[row["target_id"]]["review_minutes"])
                for row in retained_without_direct_child
            ),
            "minimum_child_review_minutes": min(
                (int(child["review_minutes"]) for child in children),
                default=0,
            ),
            "maximum_child_review_minutes": max(
                (int(child["review_minutes"]) for child in children),
                default=0,
            ),
        },
        "no_claim": V2_REVIEW_PLAN_NO_CLAIM,
    }
    v2_preflight_review_plan_collections(document)
    rooted = v2_rooted(document)
    v2_validate_review_plan(rooted, inventory, authority)
    return rooted, oversize_payloads


def v2_reproduction_argv(
    *,
    mode: str,
    artifact_root: str,
    artifact_dir: str,
    review_receipts: str | None = None,
    prior_campaign: str | None = None,
    priorities: str | None = None,
    statuses: str | None = None,
    targets: str | None = None,
    readiness: str | None = None,
    routes: str | None = None,
    max_targets: int = V2_REVIEW_TARGET_DEFAULT,
    explain_target: str | None = None,
    replay_input: str | None = None,
) -> list[str]:
    if mode == "replay":
        if replay_input is None:
            raise EvidenceFailed("v2 replay reproduction lacks its input")
        return [
            str(SCRIPT_REL),
            "--replay-v2",
            str(safe_relative(replay_input, label="replay input")),
            "--artifact-root",
            str(safe_relative(artifact_root, label="artifact root")),
            "--artifact-dir",
            str(safe_relative(artifact_dir, label="artifact dir")),
        ]
    flag = {
        "review-plan": "--review-plan",
        "history-plan": "--history-plan",
    }.get(mode)
    if flag is None:
        raise EvidenceFailed(f"unsupported v2 reproduction mode {mode}")
    argv = [
        str(SCRIPT_REL),
        flag,
        "--artifact-root",
        str(safe_relative(artifact_root, label="artifact root")),
        "--artifact-dir",
        str(safe_relative(artifact_dir, label="artifact dir")),
    ]
    for option, value in (
        ("--review-receipts", review_receipts),
        ("--prior-campaign", prior_campaign),
        ("--priorities", priorities),
        ("--statuses", statuses),
        ("--targets", targets),
        ("--readiness", readiness),
        ("--routes", routes),
        ("--explain-target", explain_target),
    ):
        if value is not None:
            argv.extend((option, value))
    if max_targets != V2_REVIEW_TARGET_DEFAULT:
        argv.extend(("--max-targets-per-child", str(max_targets)))
    return argv


V2_SENSITIVE_KEY_TERMINALS = frozenset(
    {"password", "passwd", "secret", "credential", "token"}
)
V2_SENSITIVE_KEYS = frozenset(
    {
        "api_key",
        "private_key",
        "authorization",
        "proxy_authorization",
    }
)


def v2_is_sensitive_key(value: Any) -> bool:
    normalized = str(value).strip().lower().replace("-", "_")
    normalized = normalized.lstrip("_")
    segments = [
        segment
        for segment in re.split(r"[./:\[\]]+", normalized)
        if segment
    ]
    if not segments:
        return False
    final = segments[-1]
    return (
        final in V2_SENSITIVE_KEYS
        or final.split("_")[-1] in V2_SENSITIVE_KEY_TERMINALS
    )


def v2_redacted_value(value: str) -> str:
    if re.fullmatch(r"<redacted(?::[0-9a-f]{64})?>", value):
        return value
    return (
        "<redacted:"
        + hashlib.sha256(value.encode("utf-8")).hexdigest()
        + ">"
    )


def v2_contains_absolute_path(value: str) -> bool:
    return bool(
        value.startswith("/")
        or str(REPO_ROOT) in value
        or re.search(r"(?<![A-Za-z0-9_.-])/[A-Za-z0-9_.~-]", value)
        or re.search(r"(?i)(?<![A-Za-z0-9])(?:[A-Z]:\\\\|\\\\\\\\)", value)
    )


def v2_sanitized_argv(argv: Sequence[Any]) -> list[str]:
    if len(argv) > V2_COMMAND_ARGUMENTS_CAP:
        raise EvidenceFailed("v2 command receipt exceeds its argument-count cap")
    result: list[str] = []
    sensitive_value_pending = False
    for raw in argv:
        value = str(raw)
        if len(value.encode("utf-8")) > V2_COMMAND_ARGUMENT_BYTES_CAP:
            raise EvidenceFailed("v2 command receipt exceeds its argument-byte cap")
        already_redacted = re.fullmatch(
            r"<redacted(?::[0-9a-f]{64})?>", value
        ) is not None
        if sensitive_value_pending:
            result.append(value if already_redacted else v2_redacted_value(value))
            sensitive_value_pending = False
            continue
        option_name = value.split("=", 1)[0]
        sensitive_flag = (
            option_name.startswith("-")
            and "=" not in value
            and v2_is_sensitive_key(option_name.lstrip("-"))
        )
        assignment_key = value.split("=", 1)[0] if "=" in value else ""
        sensitive_assignment = bool(
            assignment_key
            and v2_is_sensitive_key(assignment_key.lstrip("-"))
        )
        authorization_header = bool(
            re.match(r"(?i)^(?:proxy-)?authorization\s*:", value)
            or re.search(r"(?i)\bbearer\s+\S+", value)
        )
        if sensitive_flag:
            result.append(value)
            sensitive_value_pending = True
            continue
        if (
            sensitive_assignment
            or authorization_header
            or v2_contains_absolute_path(value)
        ):
            result.append(v2_redacted_value(value))
        else:
            result.append(value)
    return result


def v2_redact_contextual_text(value: str) -> str:
    text = value.replace(str(REPO_ROOT), "<repo>")

    authorization_header = re.compile(
        r"(?im)(?P<prefix>\b(?:Proxy-)?Authorization\s*:\s*)"
        r"(?P<body>[^\r\n]*)"
    )

    def redact_authorization(match: re.Match[str]) -> str:
        return match.group("prefix") + "<redacted>"

    text = authorization_header.sub(redact_authorization, text)

    quoted_assignment = re.compile(
        r"(?P<key>[A-Za-z][A-Za-z0-9_.-]{0,127})"
        r"(?P<sep>\s*[:=]\s*)"
        r"(?P<quote>[\"'])(?P<body>.*?)(?P=quote)"
        ,
        flags=re.DOTALL,
    )

    def redact_quoted(match: re.Match[str]) -> str:
        if not v2_is_sensitive_key(match.group("key")):
            return match.group(0)
        body = match.group("body")
        replacement = body if body == "<redacted>" else "<redacted>"
        return (
            match.group("key")
            + match.group("sep")
            + match.group("quote")
            + replacement
            + match.group("quote")
        )

    text = quoted_assignment.sub(redact_quoted, text)
    for quote in ('"', "'"):
        unclosed_quote = re.compile(
            r"(?P<key>[A-Za-z][A-Za-z0-9_.-]{0,127})"
            r"(?P<sep>\s*[:=]\s*)"
            + re.escape(quote)
            + r"(?P<body>[^" + re.escape(quote) + r"]*)\Z",
            flags=re.DOTALL,
        )

        def redact_unclosed(
            match: re.Match[str],
            *,
            quote_character: str = quote,
        ) -> str:
            if not v2_is_sensitive_key(match.group("key")):
                return match.group(0)
            return (
                match.group("key")
                + match.group("sep")
                + quote_character
                + "<redacted>"
            )

        text = unclosed_quote.sub(redact_unclosed, text)
    unquoted_assignment = re.compile(
        r"(?P<key>[A-Za-z][A-Za-z0-9_.-]{0,127})"
        r"(?P<sep>\s*[:=]\s*)"
        r"(?P<body>[^\s,;]+)"
    )

    def redact_unquoted(match: re.Match[str]) -> str:
        if not v2_is_sensitive_key(match.group("key")):
            return match.group(0)
        body = match.group("body")
        replacement = body if body == "<redacted>" else "<redacted>"
        return match.group("key") + match.group("sep") + replacement

    text = unquoted_assignment.sub(redact_unquoted, text)
    split_option = re.compile(
        r"(?P<key>--?[A-Za-z][A-Za-z0-9_-]{0,127})"
        r"(?P<sep>\s+)"
        r"(?P<body>\"[^\"]*\"|'[^']*'|[^\s,;]+)"
    )

    def redact_split(match: re.Match[str]) -> str:
        if not v2_is_sensitive_key(match.group("key").lstrip("-")):
            return match.group(0)
        return match.group("key") + match.group("sep") + "<redacted>"

    text = split_option.sub(redact_split, text)
    text = re.sub(
        r"(?i)\b(Bearer)(\s+)(?!<redacted>)[^\s,;]+",
        r"\1\2<redacted>",
        text,
    )
    text = re.sub(
        r"(?<![A-Za-z0-9_.-])/(?:[^\s/:]+/)*[^\s,;:]*",
        "<absolute-path>",
        text,
    )
    text = re.sub(
        r"(?i)(?<![A-Za-z0-9])(?:[A-Z]:\\\\|\\\\\\\\)[^\s,;]+",
        "<absolute-path>",
        text,
    )
    return text


def v2_bounded_diagnostic_summary(value: Any) -> str:
    text = v2_redact_contextual_text(str(value))
    text = " ".join(text.split())
    encoded = text.encode("utf-8")
    if len(encoded) <= V2_DIAGNOSTIC_SUMMARY_BYTES_CAP:
        return text
    suffix = "...<truncated:" + text_root(text) + ">"
    prefix_budget = (
        V2_DIAGNOSTIC_SUMMARY_BYTES_CAP - len(suffix.encode("utf-8"))
    )
    prefix = encoded[:prefix_budget].decode("utf-8", errors="ignore")
    return prefix + suffix


def v2_assertion_evidence_projection(
    value: Any,
    *,
    sensitive: bool = False,
    depth: int = 0,
) -> Any:
    if depth > 32:
        raise EvidenceFailed("assertion evidence exceeds its projection depth cap")
    if sensitive:
        projection = {
            "type": f"{type(value).__module__}.{type(value).__qualname__}",
            "value": v2_state_projection_value(value),
        }
        return {
            "kind": "redacted",
            "content_root": "sha256-v1:"
            + hashlib.sha256(canonical_bytes(projection)).hexdigest(),
        }
    if value is None or type(value) in {bool, int, float}:
        return value
    if isinstance(value, str):
        if sensitive or v2_contains_absolute_path(value):
            return v2_redacted_value(value)
        redacted = v2_redact_contextual_text(value)
        return redacted
    if isinstance(value, (bytes, bytearray, memoryview)):
        payload = value.tobytes() if isinstance(value, memoryview) else bytes(value)
        return {
            "kind": "bytes",
            "byte_length": len(payload),
            "content_root": "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
        }
    if isinstance(value, Mapping):
        projected: dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise EvidenceFailed(
                    "assertion evidence mapping keys must be exact strings"
                )
            redacted_key = v2_redact_contextual_text(key)
            projected_key = (
                key
                if redacted_key == key and not v2_contains_absolute_path(key)
                else "<redacted-key:"
                + hashlib.sha256(key.encode("utf-8")).hexdigest()
                + ">"
            )
            if projected_key in projected:
                raise EvidenceFailed(
                    "assertion evidence mapping keys collide after projection"
                )
            projected[projected_key] = v2_assertion_evidence_projection(
                item,
                sensitive=v2_is_sensitive_key(key),
                depth=depth + 1,
            )
        return projected
    if isinstance(value, (list, tuple)):
        return [
            v2_assertion_evidence_projection(
                item,
                sensitive=sensitive,
                depth=depth + 1,
            )
            for item in value
        ]
    if isinstance(value, (set, frozenset)):
        projected = [
            v2_assertion_evidence_projection(
                item,
                sensitive=sensitive,
                depth=depth + 1,
            )
            for item in value
        ]
        projected.sort(key=canonical_bytes)
        return projected
    return {
        "kind": "opaque",
        "type": f"{type(value).__module__}.{type(value).__qualname__}",
    }


def v2_source_command_receipts(
    source: Mapping[str, Any],
) -> list[dict[str, Any]]:
    captured = source["captured"]
    observation = captured["observation"]
    receipts: list[dict[str, Any]] = []
    for row in observation.get("command_receipts", []):
        receipts.append(
            {
                "ordering": (
                    0,
                    int(row["capture_sequence"]),
                    "",
                ),
                "argv": row["argv"],
                "exit_code": row["exit_code"],
                "result_category": row["category"],
                "stdout_byte_length": row["stdout"]["bytes"],
                "stdout_root": row["stdout"]["root"],
                "stderr_byte_length": row["stderr"]["bytes"],
                "stderr_root": row["stderr"]["root"],
            }
        )
    for row in captured["audit_capture"].get("command_receipts", []):
        receipts.append(
            {
                "ordering": (
                    int(row["capture_ordinal"]),
                    1_000_000,
                    str(row["issue_id"]),
                ),
                "argv": row["argv"],
                "exit_code": row["exit_code"],
                "result_category": row["result_category"],
                "stdout_byte_length": row["stdout_byte_length"],
                "stdout_root": row["stdout_root"],
                "stderr_byte_length": row["stderr_byte_length"],
                "stderr_root": row["stderr_root"],
            }
        )
    receipts.sort(
        key=lambda row: (
            row["ordering"],
            tuple(str(value) for value in row["argv"]),
        )
    )
    return receipts


def v2_validate_log_event_count(
    count: int,
    *,
    error_type: type[HarnessError],
) -> None:
    if type(count) is not int or count < 0:
        raise error_type("v2 event count uses an invalid counter")
    if count > V2_LOG_EVENTS_CAP:
        raise error_type("v2 event count exceeds its cap")


def v2_event_rows(
    *,
    mode: str,
    subject_mode: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    review_plan: Mapping[str, Any],
    history: Mapping[str, Any],
    zero_sets: Mapping[str, Any],
    safe_artifacts: Sequence[str],
    reproduction: Sequence[str],
) -> list[dict[str, Any]]:
    case_id, assertion_id = {
        "review-plan": (
            "template-lint-v2.nomock-review-plan",
            "v2.case.nomock-review-plan",
        ),
        "history-plan": (
            "template-lint-v2.nomock-history-plan",
            "v2.case.nomock-history-plan",
        ),
        "replay": (
            "template-lint-v2.nomock-offline-replay",
            "v2.case.nomock-offline-replay",
        ),
    }[mode]
    empty_root = "sha256-v1:" + hashlib.sha256(b"").hexdigest()
    safe_artifact_projection = {
        "base": list(V2_RUN_ARTIFACTS),
        "optional_count": len(safe_artifacts) - len(V2_RUN_ARTIFACTS),
        "optional_paths_root": semantic_root(
            sorted(
                set(safe_artifacts) - set(V2_RUN_ARTIFACTS),
                key=lambda value: value.encode("utf-8"),
            )
        ),
    }
    events: list[dict[str, Any]] = []

    def append(
        stage: str,
        *,
        argv: Sequence[Any] = (),
        exit_code: int = 0,
        result_category: str = "PASS",
        semantic_projection: Mapping[str, Any] | None = None,
        stdout_byte_length: int = 0,
        stdout_root: str = empty_root,
        stderr_byte_length: int = 0,
        stderr_root: str = empty_root,
        terminal: str | None = None,
    ) -> None:
        parameter = {
            "mode": mode,
            "subject_mode": subject_mode,
            "stage": stage,
            "sequence": len(events),
        }
        row = {
            "schema": V2_EVENT_SCHEMA,
            "case_id": case_id,
            "assertion_id": assertion_id,
            "executor_id": assertion_id,
            "parameter_root": semantic_root(parameter),
            "stage": stage,
            "sequence": len(events),
            "argv": v2_sanitized_argv(argv),
            "exit_code": int(exit_code),
            "result_category": result_category,
            "semantic_projection": dict(semantic_projection or {}),
            "stdout_byte_length": int(stdout_byte_length),
            "stdout_root": stdout_root,
            "stderr_byte_length": int(stderr_byte_length),
            "stderr_root": stderr_root,
            "first_divergence": None,
            "recovery": "NOT_REQUIRED",
            "terminal": terminal,
            "safe_relative_artifacts": safe_artifact_projection,
            "no_claim": (
                "the event is redacted deterministic planning evidence and "
                "mints no semantic, human, write, implementation, or release authority"
            ),
        }
        v2_validate_log_event_count(
            len(events) + 1,
            error_type=EvidenceFailed,
        )
        if len(canonical_bytes(row)) > V2_LOG_LINE_BYTES_CAP:
            raise EvidenceFailed("v2 event line exceeds its byte cap")
        events.append(row)

    append(
        "assertion-start",
        argv=reproduction,
        semantic_projection={
            "source_root": source["semantic_root"],
            "manifest_root": source["manifest"]["semantic_root"],
        },
    )
    for index, receipt in enumerate(v2_source_command_receipts(source)):
        append(
            f"source-command-{index:06d}",
            argv=receipt["argv"],
            exit_code=receipt["exit_code"],
            result_category=receipt["result_category"],
            semantic_projection={
                "command_receipt_root": semantic_root(
                    {key: value for key, value in receipt.items() if key != "ordering"}
                )
            },
            stdout_byte_length=receipt["stdout_byte_length"],
            stdout_root=receipt["stdout_root"],
            stderr_byte_length=receipt["stderr_byte_length"],
            stderr_root=receipt["stderr_root"],
        )
    for stage, document in (
        ("inventory-derived", inventory),
        ("authority-derived", authority),
        ("review-projection-derived", review_plan),
        ("history-projection-derived", history),
        ("zero-sets-derived", zero_sets),
    ):
        append(
            stage,
            semantic_projection={"semantic_root": document["semantic_root"]},
        )
    append(
        "assertion-terminal",
        semantic_projection={
            "source_root": source["semantic_root"],
            "inventory_root": inventory["semantic_root"],
            "authority_root": authority["semantic_root"],
            "review_plan_root": review_plan["semantic_root"],
            "history_root": history["semantic_root"],
            "zero_sets_root": zero_sets["semantic_root"],
        },
    )
    append(
        "suite-terminal",
        semantic_projection={
            "subject_mode": subject_mode,
            "prior_event_roots": [
                semantic_root(row) for row in events
            ],
        },
        terminal="Pass",
    )
    if (
        [row["sequence"] for row in events] != list(range(len(events)))
        or sum(row["terminal"] is not None for row in events) != 1
        or events[-1]["terminal"] != "Pass"
    ):
        raise EvidenceFailed("v2 terminal event is not unique and last")
    return events


def v2_artifact_identity(
    *,
    relative_path: str,
    schema_kind: str,
    payload: bytes,
) -> str:
    return semantic_root(
        {
            "relative_path": str(
                safe_relative(relative_path, label="v2 artifact")
            ),
            "schema_kind": schema_kind,
            "byte_length": len(payload),
            "content_root": (
                "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            ),
        }
    )


def v2_bundle_payloads(
    *,
    mode: str,
    subject_mode: str,
    artifact_root: str,
    artifact_dir: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    review_plan: Mapping[str, Any],
    history: Mapping[str, Any],
    zero_sets: Mapping[str, Any],
    optional_payloads: Mapping[str, bytes],
    reproduction: Sequence[str],
    replay_equivalence: Mapping[str, Any] | None = None,
) -> dict[str, bytes]:
    v2_validate_source_document(source)
    if subject_mode == "review-plan":
        if "state" not in source["captured"]["audit_capture"]:
            raise EvidenceFailed(
                "v2 review-plan source unexpectedly retains a history audit"
            )
        v2_validate_review_plan(review_plan, inventory, authority)
        v2_validate_not_requested(
            history,
            schema=V2_HISTORY_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="history",
        )
    elif subject_mode == "history-plan":
        if "state" in source["captured"]["audit_capture"]:
            raise EvidenceFailed(
                "v2 history-plan source lacks its requested history audit"
            )
        v2_validate_not_requested(
            review_plan,
            schema=V2_REVIEW_PLAN_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="review-plan",
        )
        expected_history = v2_build_history(
            source_root=source["semantic_root"],
            inventory=inventory,
            authority=authority,
            all_issues=source["captured"]["all_issues"],
            audit_capture=source["captured"]["audit_capture"],
            history_contract=source["contracts"]["history"],
        )
        if history != expected_history:
            divergence = first_projection_divergence(
                expected_history,
                history,
            )
            raise EvidenceFailed(
                "v2 history projection differs from its exact source-derived "
                f"projection at {divergence or '$'}"
            )
    else:
        raise EvidenceFailed("v2 bundle subject mode is unknown")
    registry = review_plan.get("oversize_content") or []
    if not isinstance(registry, list):
        raise EvidenceFailed("v2 oversize registry is not an array")
    registry_by_path: dict[str, Mapping[str, Any]] = {}
    for index, entry in enumerate(registry):
        if not isinstance(entry, dict):
            raise EvidenceFailed(f"v2 oversize registry row {index} is malformed")
        v2_exact_keys(
            entry,
            V2_OVERSIZE_REGISTRY_FIELDS,
            label=f"v2 oversize registry row {index}",
        )
        relative = str(
            safe_relative(entry["relative_path"], label="v2 oversize artifact")
        )
        if relative in V2_RUN_ARTIFACTS or relative in registry_by_path:
            raise EvidenceFailed("v2 oversize registry duplicates an artifact")
        registry_by_path[relative] = entry
    if set(optional_payloads) != set(registry_by_path):
        raise EvidenceFailed("v2 optional payload membership differs from its registry")
    inventory_by_id = {
        row["id"]: row for row in inventory.get("rows", [])
    }
    authority_by_id = {
        row["target_id"]: row
        for row in authority.get("decisions", [])
    }
    for relative, payload in optional_payloads.items():
        if len(payload) > RUN_ARTIFACT_CAP:
            raise EvidenceFailed(f"v2 optional artifact {relative} exceeds cap")
        document = strict_json_loads(
            payload,
            label=f"v2 optional artifact {relative}",
            require_canonical=True,
        )
        if not isinstance(document, dict):
            raise EvidenceFailed(f"v2 optional artifact {relative} is not an object")
        v2_exact_keys(
            document,
            V2_OVERSIZE_ARTIFACT_FIELDS,
            label=f"v2 optional artifact {relative}",
        )
        verify_semantic_root(document, label=f"v2 optional artifact {relative}")
        entry = registry_by_path[relative]
        complete_plan = document.get("complete_plan")
        bounded_index = document.get("bounded_incomplete_index")
        if (
            not isinstance(complete_plan, dict)
            or set(complete_plan)
            != {"target", "authority", "actual_review_minutes"}
            or not isinstance(complete_plan.get("target"), dict)
            or not isinstance(complete_plan.get("authority"), dict)
            or not isinstance(bounded_index, dict)
            or set(bounded_index)
            != {"complete", "target_id", "missing_sections"}
            or bounded_index["complete"] is not False
            or not isinstance(bounded_index["target_id"], str)
            or not isinstance(bounded_index["missing_sections"], list)
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} has a malformed full plan"
            )
        target_id = bounded_index["target_id"]
        expected_target = inventory_by_id.get(target_id)
        expected_authority = authority_by_id.get(target_id)
        if expected_target is None or expected_authority is None:
            raise EvidenceFailed(
                f"v2 optional artifact {relative} names an unknown target"
            )
        expected_complete_plan = {
            "target": expected_target,
            "authority": expected_authority,
            "actual_review_minutes": int(
                expected_authority["review_minutes"]
            ),
        }
        expected_exceeded_caps = v2_oversize_exceeded_caps(
            expected_target,
            expected_authority,
        )
        expected_relative = (
            "oversize/"
            f"{str(expected_target['target_root']).split(':', 1)[-1]}.json"
        )
        if (
            relative != expected_relative
            or complete_plan != expected_complete_plan
            or bounded_index["missing_sections"]
            != expected_target["missing_sections"]
            or document["source_roots"]
            != [
                expected_target["target_root"],
                expected_target["v1_row_root"],
                expected_target["campaign_epoch_root"],
            ]
            or document["field_roots"] != expected_target["field_roots"]
            or document["clause_roots"] != expected_target["clause_roots"]
            or document["exceeded_caps"] != expected_exceeded_caps
            or not expected_exceeded_caps
            or document["canonical_br_show_argv"]
            != ["br", "show", target_id, "--json", *BR_READ_FLAGS]
            or document["retained_full_plan_path"] != relative
            or document["retained_full_plan_root"]
            != semantic_root(expected_complete_plan)
            or document["owner_questions"]
            != list(V2_OVERSIZE_OWNER_QUESTIONS)
            or document["no_claim"] != V2_OVERSIZE_NO_CLAIM
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} differs from source projections"
            )
        exceeded_caps = document["exceeded_caps"]
        if (
            not isinstance(exceeded_caps, list)
            or not exceeded_caps
            or any(
                not isinstance(row, dict)
                or set(row) != V2_OVERSIZE_EXCEEDED_CAP_FIELDS
                or not isinstance(row["cap"], str)
                or not row["cap"]
                or not isinstance(row["source_path"], str)
                or not row["source_path"]
                or type(row["observed"]) is not int
                or type(row["limit"]) is not int
                or row["observed"] <= row["limit"]
                or type(row["violation_count"]) is not int
                or row["violation_count"] < 1
                or not isinstance(row["violating_membership_root"], str)
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    row["violating_membership_root"],
                )
                is None
                for row in exceeded_caps
            )
            or exceeded_caps
            != sorted(
                exceeded_caps,
                key=lambda row: (
                    row["cap"].encode("utf-8"),
                    row["source_path"].encode("utf-8"),
                ),
            )
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} has malformed cap diagnostics"
            )
        if (
            entry["byte_length"] != len(payload)
            or entry["semantic_root"] != document["semantic_root"]
            or entry["aggregate_cap_accounting"] != len(payload)
            or entry["schema_kind"] != document.get("schema")
            or entry["media_kind"] != "application/json"
            or entry["target_roots"] != [expected_target["target_root"]]
            or entry["field_roots"] != document.get("field_roots")
            or entry["clause_roots"] != document.get("clause_roots")
            or entry["exceeded_caps"] != document.get("exceeded_caps")
            or document.get("retained_full_plan_path") != relative
            or document.get("retained_full_plan_root")
            != semantic_root(document["complete_plan"])
        ):
            raise EvidenceFailed(f"v2 optional registry identity differs for {relative}")

    safe_artifacts = sorted(
        [*V2_RUN_ARTIFACTS, *optional_payloads],
        key=lambda value: value.encode("utf-8"),
    )
    events = v2_event_rows(
        mode=mode,
        subject_mode=subject_mode,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review_plan,
        history=history,
        zero_sets=zero_sets,
        safe_artifacts=safe_artifacts,
        reproduction=reproduction,
    )
    payloads: dict[str, bytes] = {
        "source-v2.json": canonical_bytes(source),
        "inventory-v2.json": canonical_bytes(inventory),
        "authority-v2.json": canonical_bytes(authority),
        "review-plan-v2.json": canonical_bytes(review_plan),
        "history-v2.json": canonical_bytes(history),
        "zero-sets-v2.json": canonical_bytes(zero_sets),
        "events.jsonl": b"".join(canonical_bytes(row) for row in events),
        "reproduce.txt": canonical_bytes(list(reproduction)),
        **dict(optional_payloads),
    }
    schema_by_name = {
        "source-v2.json": V2_SOURCE_SCHEMA,
        "inventory-v2.json": V2_INVENTORY_SCHEMA,
        "authority-v2.json": V2_AUTHORITY_SCHEMA,
        "review-plan-v2.json": V2_REVIEW_PLAN_SCHEMA,
        "history-v2.json": V2_HISTORY_SCHEMA,
        "zero-sets-v2.json": V2_ZERO_SETS_SCHEMA,
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
        **{
            relative: str(registry_by_path[relative]["schema_kind"])
            for relative in optional_payloads
        },
    }
    identities = {
        name: v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        for name in sorted(payloads, key=lambda value: value.encode("utf-8"))
    }
    terminal = v2_rooted(
        {
            "schema": V2_TERMINAL_SCHEMA,
            "mode": mode,
            "subject_mode": subject_mode,
            "bundle_state": "COMPLETE_GREEN",
            "terminal": "Pass",
            "exit_code": 0,
            "artifact_root": str(
                safe_relative(artifact_root, label="artifact root")
            ),
            "artifact_dir": str(
                safe_relative(artifact_dir, label="artifact dir")
            ),
            "base_artifacts": list(V2_RUN_ARTIFACTS),
            "safe_relative_artifacts": safe_artifacts,
            "artifact_identities": identities,
            "optional_content_registry": registry,
            "manifest_root": source["manifest"]["semantic_root"],
            "source_root": source["semantic_root"],
            "inventory_root": inventory["semantic_root"],
            "authority_root": authority["semantic_root"],
            "review_plan_root": review_plan["semantic_root"],
            "history_root": history["semantic_root"],
            "zero_sets_root": zero_sets["semantic_root"],
            "events_content_root": (
                "sha256-v1:"
                + hashlib.sha256(payloads["events.jsonl"]).hexdigest()
            ),
            "event_count": len(events),
            "event_sequence": list(range(len(events))),
            "event_roots": [semantic_root(row) for row in events],
            "terminal_event_root": semantic_root(events[-1]),
            "reproduction": list(reproduction),
            "replay_equivalence": dict(replay_equivalence or {}),
            "first_divergence": None,
            "recovery": "NOT_REQUIRED",
            "complete_evidence_bundle": True,
            "complete_green_prefix": True,
            "retry_requires_fresh_run_dir": False,
            "no_claim": (
                "the final seal proves deterministic bundle construction only; "
                "it does not prove current state on replay or mint any authority"
            ),
        }
    )
    payloads["terminal.json"] = canonical_bytes(terminal)
    if set(payloads) != set(V2_RUN_ARTIFACTS) | set(optional_payloads):
        raise EvidenceFailed("v2 payload membership differs from its exact contract")
    for name, payload in payloads.items():
        if len(payload) > RUN_ARTIFACT_CAP:
            raise EvidenceFailed(f"v2 artifact {name} exceeds its 64 MiB cap")
    return payloads


def v2_refusal_event_rows(
    *,
    mode: str,
    terminal_name: str,
    failure: Mapping[str, Any],
    reproduction: Sequence[str],
) -> list[dict[str, Any]]:
    if mode not in {"review-plan", "history-plan"}:
        raise EvidenceFailed("v2 refusal event mode is unknown")
    if terminal_name not in V2_SEMANTIC_REFUSAL_TERMINALS:
        raise EvidenceFailed("v2 refusal event terminal is not semantic")
    if (
        len(reproduction) > V2_COMMAND_ARGUMENTS_CAP
        or any(
            not isinstance(value, str)
            or len(value.encode("utf-8")) > V2_COMMAND_ARGUMENT_BYTES_CAP
            for value in reproduction
        )
        or v2_sanitized_argv(reproduction) != list(reproduction)
    ):
        raise EvidenceFailed("v2 refusal reproduction is not bounded and sanitized")
    case_id = (
        "template-lint-v2.nomock-review-plan"
        if mode == "review-plan"
        else "template-lint-v2.nomock-history-plan"
    )
    assertion_id = (
        "v2.case.nomock-review-plan"
        if mode == "review-plan"
        else "v2.case.nomock-history-plan"
    )
    safe_artifact_projection = {
        "base": list(V2_RUN_ARTIFACTS),
        "optional_count": 0,
        "optional_paths_root": semantic_root([]),
    }
    empty_root = "sha256-v1:" + hashlib.sha256(b"").hexdigest()
    stages = (
        "assertion-start",
        "assertion-terminal",
        "suite-terminal",
    )
    events: list[dict[str, Any]] = []
    for sequence, event_stage in enumerate(stages):
        is_failure_event = event_stage != "assertion-start"
        is_terminal_event = event_stage == "suite-terminal"
        parameter = {
            "mode": mode,
            "subject_mode": mode,
            "stage": event_stage,
            "sequence": sequence,
        }
        event = {
            "schema": V2_EVENT_SCHEMA,
            "case_id": case_id,
            "assertion_id": assertion_id,
            "executor_id": assertion_id,
            "parameter_root": semantic_root(parameter),
            "stage": event_stage,
            "sequence": sequence,
            "argv": list(reproduction) if sequence == 0 else [],
            "exit_code": (
                TERMINAL_EXIT[terminal_name] if is_failure_event else 0
            ),
            "result_category": (
                "SEMANTIC_REFUSAL" if is_failure_event else "STARTED"
            ),
            "semantic_projection": {
                "failure_root": failure["semantic_root"],
                "available_roots": failure["available_roots"],
                "prior_event_roots": (
                    [semantic_root(row) for row in events]
                    if is_terminal_event
                    else []
                ),
            },
            "stdout_byte_length": 0,
            "stdout_root": empty_root,
            "stderr_byte_length": 0,
            "stderr_root": empty_root,
            "first_divergence": (
                failure["first_divergence"]
                if is_failure_event
                else None
            ),
            "recovery": (
                failure["recovery"]
                if is_failure_event
                else "NOT_REQUIRED"
            ),
            "terminal": terminal_name if is_terminal_event else None,
            "safe_relative_artifacts": safe_artifact_projection,
            "no_claim": (
                "the event retains only rooted refusal evidence and no raw "
                "streams, tracker bodies, credentials, or authority"
            ),
        }
        if len(canonical_bytes(event)) > V2_LOG_LINE_BYTES_CAP:
            raise EvidenceFailed("v2 refusal event exceeds its line cap")
        events.append(event)
    return events


def v2_refusal_bundle_payloads(
    *,
    mode: str,
    artifact_root: str,
    artifact_dir: str,
    manifest: Mapping[str, Any],
    error: HarnessError,
    stage: str,
    available_roots: Mapping[str, str | None],
    argv: Sequence[Any],
) -> tuple[dict[str, bytes], dict[str, Any]]:
    terminal_name = error.terminal
    if terminal_name not in V2_SEMANTIC_REFUSAL_TERMINALS:
        raise EvidenceFailed("non-semantic failure cannot mint a refusal bundle")
    raw_argv = [str(raw) for raw in argv]
    if len(raw_argv) > V2_COMMAND_ARGUMENTS_CAP:
        omitted = raw_argv[V2_COMMAND_ARGUMENTS_CAP - 1 :]
        raw_argv = [
            *raw_argv[: V2_COMMAND_ARGUMENTS_CAP - 1],
            (
                f"<omitted:{len(omitted)}:"
                f"{semantic_root(omitted)}>"
            ),
        ]
    prebounded_argv: list[str] = []
    for value in raw_argv:
        if len(value.encode("utf-8")) > V2_COMMAND_ARGUMENT_BYTES_CAP:
            prebounded_argv.append(
                "<redacted:"
                + hashlib.sha256(value.encode("utf-8")).hexdigest()
                + ">"
            )
        else:
            prebounded_argv.append(value)
    bounded_argv = v2_sanitized_argv(prebounded_argv)
    failure = v2_failure_evidence(
        stage=stage,
        detail=str(error),
        terminal=terminal_name,
        manifest_root=str(manifest["semantic_root"]),
        available_roots=available_roots,
    )
    projection_names = {
        "source-v2.json": ("source", V2_SOURCE_SCHEMA),
        "inventory-v2.json": ("inventory", V2_INVENTORY_SCHEMA),
        "authority-v2.json": ("authority", V2_AUTHORITY_SCHEMA),
        "review-plan-v2.json": ("review-plan", V2_REVIEW_PLAN_SCHEMA),
        "history-v2.json": ("history", V2_HISTORY_SCHEMA),
        "zero-sets-v2.json": ("zero-sets", V2_ZERO_SETS_SCHEMA),
    }
    documents: dict[str, dict[str, Any]] = {}
    available_key_by_projection = {
        "source": "source",
        "inventory": "inventory",
        "authority": "authority",
        "review-plan": "review_plan",
        "history": "history",
        "zero-sets": "zero_sets",
    }
    for artifact_name, (projection, expected_schema) in projection_names.items():
        available_key = available_key_by_projection[projection]
        documents[artifact_name] = v2_rooted(
            {
                "schema": V2_REFUSAL_PROJECTION_SCHEMA,
                "artifact_name": artifact_name,
                "projection": projection,
                "expected_success_schema": expected_schema,
                "mode": mode,
                "state": "REFUSED",
                "manifest_root": manifest["semantic_root"],
                "failure_root": failure["semantic_root"],
                "available_projection_root": available_roots.get(available_key),
                "complete_green_prefix": False,
                "no_claim": (
                    "this closed refusal envelope is complete failure evidence "
                    "and is not a successful planner projection"
                ),
            }
        )
    events = v2_refusal_event_rows(
        mode=mode,
        terminal_name=terminal_name,
        failure=failure,
        reproduction=bounded_argv,
    )
    payloads: dict[str, bytes] = {
        **{
            name: canonical_bytes(document)
            for name, document in documents.items()
        },
        "events.jsonl": b"".join(canonical_bytes(row) for row in events),
        "reproduce.txt": canonical_bytes(bounded_argv),
    }
    schema_by_name = {
        **{
            name: V2_REFUSAL_PROJECTION_SCHEMA for name in projection_names
        },
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
    }
    identities = {
        name: v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        for name in sorted(payloads, key=lambda value: value.encode("utf-8"))
    }
    terminal = v2_rooted(
        {
            "schema": V2_TERMINAL_SCHEMA,
            "mode": mode,
            "subject_mode": mode,
            "bundle_state": "COMPLETE_NON_GREEN",
            "terminal": terminal_name,
            "exit_code": TERMINAL_EXIT[terminal_name],
            "artifact_root": str(
                safe_relative(artifact_root, label="artifact root")
            ),
            "artifact_dir": str(
                safe_relative(artifact_dir, label="artifact dir")
            ),
            "base_artifacts": list(V2_RUN_ARTIFACTS),
            "safe_relative_artifacts": list(V2_RUN_ARTIFACTS),
            "artifact_identities": identities,
            "optional_content_registry": [],
            "manifest_root": manifest["semantic_root"],
            "manifest_content_identity": manifest["content_identity"],
            "source_root": documents["source-v2.json"]["semantic_root"],
            "inventory_root": documents["inventory-v2.json"]["semantic_root"],
            "authority_root": documents["authority-v2.json"]["semantic_root"],
            "review_plan_root": documents["review-plan-v2.json"][
                "semantic_root"
            ],
            "history_root": documents["history-v2.json"]["semantic_root"],
            "zero_sets_root": documents["zero-sets-v2.json"]["semantic_root"],
            "events_content_root": (
                "sha256-v1:"
                + hashlib.sha256(payloads["events.jsonl"]).hexdigest()
            ),
            "event_count": len(events),
            "event_sequence": list(range(len(events))),
            "event_roots": [semantic_root(row) for row in events],
            "terminal_event_root": semantic_root(events[-1]),
            "reproduction": bounded_argv,
            "replay_equivalence": {},
            "failure_evidence": failure,
            "failure_root": failure["semantic_root"],
            "first_divergence": failure["first_divergence"],
            "recovery": failure["recovery"],
            "complete_evidence_bundle": True,
            "complete_green_prefix": False,
            "retry_requires_fresh_run_dir": True,
            "no_claim": (
                "the complete non-green seal proves only a typed semantic "
                "refusal and can never be promoted or replayed as Pass"
            ),
        }
    )
    payloads["terminal.json"] = canonical_bytes(terminal)
    if set(payloads) != set(V2_RUN_ARTIFACTS):
        raise EvidenceFailed("v2 refusal payload membership is not exactly nine")
    if any(len(payload) > RUN_ARTIFACT_CAP for payload in payloads.values()):
        raise EvidenceFailed("v2 refusal payload exceeds an artifact cap")
    return payloads, failure


def v2_write_exclusive(path: Path, payload: bytes) -> None:
    if len(payload) > RUN_ARTIFACT_CAP:
        raise EvidenceFailed("v2 writer received an over-cap payload")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    flags |= getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags, 0o644)
    except FileExistsError as error:
        raise EvidenceFailed(
            f"v2 overwrite is forbidden for {path.relative_to(REPO_ROOT)}"
        ) from error
    except OSError as error:
        raise InfrastructureFailed(
            f"v2 exclusive writer could not create {path.relative_to(REPO_ROOT)}"
        ) from error
    try:
        with os.fdopen(descriptor, "wb", closefd=True) as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
    except OSError as error:
        raise InfrastructureFailed(
            f"v2 exclusive writer failed for {path.relative_to(REPO_ROOT)}"
        ) from error
    except BaseException:
        # Repository policy forbids deletion; an incomplete prefix deliberately
        # remains without a valid terminal seal for manual recovery.
        raise


def v2_fsync_directory(path: Path) -> None:
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError as error:
        raise InfrastructureFailed("v2 directory could not be opened for fsync") from error
    try:
        os.fsync(descriptor)
    except OSError as error:
        raise InfrastructureFailed("v2 directory fsync failed") from error
    finally:
        try:
            os.close(descriptor)
        except OSError:
            # The durability operation has already completed or raised its
            # typed failure. A close error must not replace either outcome.
            pass


@dataclass
class V2BundleReservation:
    output: Path
    artifact_root: str
    artifact_dir: str
    terminal_descriptor: int | None
    output_descriptor: int | None
    parent_descriptor: int | None
    path_anchors: tuple[tuple[Path, int, int, int], ...]
    written_identities: dict[str, dict[str, int]] = field(default_factory=dict)
    terminal_assignment_started: bool = False
    terminal_assignment_committed: bool = False
    sealed: bool = False


def v2_capture_path_anchor(
    path: Path,
    *,
    expect_directory: bool,
) -> tuple[Path, int, int, int]:
    value = os.lstat(path)
    expected = stat.S_ISDIR(value.st_mode) if expect_directory else stat.S_ISREG(
        value.st_mode
    )
    if not expected:
        raise EvidenceFailed("v2 reservation path has the wrong filesystem kind")
    return (
        path,
        int(value.st_dev),
        int(value.st_ino),
        int(stat.S_IFMT(value.st_mode)),
    )


def v2_assert_reservation_anchors(
    reservation: V2BundleReservation,
) -> None:
    for path, device, inode, file_type in reservation.path_anchors:
        try:
            value = os.lstat(path)
        except OSError as error:
            raise InfrastructureFailed(
                "v2 reserved publication path disappeared"
            ) from error
        if (
            value.st_dev != device
            or value.st_ino != inode
            or stat.S_IFMT(value.st_mode) != file_type
        ):
            raise InfrastructureFailed(
                "v2 reserved publication path changed identity"
            )
    descriptor = reservation.terminal_descriptor
    output_descriptor = reservation.output_descriptor
    parent_descriptor = reservation.parent_descriptor
    if (
        descriptor is None
        or output_descriptor is None
        or parent_descriptor is None
    ):
        raise EvidenceFailed("v2 bundle reservation descriptors are not open")
    terminal_path, device, inode, file_type = reservation.path_anchors[-1]
    descriptor_stat = os.fstat(descriptor)
    if (
        terminal_path != reservation.output / "terminal.json"
        or descriptor_stat.st_dev != device
        or descriptor_stat.st_ino != inode
        or stat.S_IFMT(descriptor_stat.st_mode) != file_type
        or not stat.S_ISREG(descriptor_stat.st_mode)
        or descriptor_stat.st_nlink != 1
    ):
        raise InfrastructureFailed(
            "v2 reserved terminal descriptor lost its path identity"
        )
    output_path_anchor = next(
        anchor
        for anchor in reservation.path_anchors
        if anchor[0] == reservation.output
    )
    output_stat = os.fstat(output_descriptor)
    if (
        output_stat.st_dev != output_path_anchor[1]
        or output_stat.st_ino != output_path_anchor[2]
        or stat.S_IFMT(output_stat.st_mode) != output_path_anchor[3]
        or not stat.S_ISDIR(output_stat.st_mode)
    ):
        raise InfrastructureFailed(
            "v2 reserved output directory descriptor lost its path identity"
        )
    parent_stat = os.fstat(parent_descriptor)
    parent_anchor = next(
        anchor
        for anchor in reservation.path_anchors
        if anchor[0] == reservation.output.parent
    )
    if (
        parent_stat.st_dev != parent_anchor[1]
        or parent_stat.st_ino != parent_anchor[2]
        or stat.S_IFMT(parent_stat.st_mode) != parent_anchor[3]
        or not stat.S_ISDIR(parent_stat.st_mode)
    ):
        raise InfrastructureFailed(
            "v2 reserved parent directory descriptor lost its path identity"
        )


def v2_close_reservation(reservation: V2BundleReservation) -> None:
    descriptors = (
        reservation.terminal_descriptor,
        reservation.output_descriptor,
        reservation.parent_descriptor,
    )
    reservation.terminal_descriptor = None
    reservation.output_descriptor = None
    reservation.parent_descriptor = None
    for descriptor in descriptors:
        if descriptor is None:
            continue
        try:
            os.close(descriptor)
        except OSError:
            # Closing an already-fsynced final-seal descriptor is best-effort.
            # It must not turn a durable terminal into a contradictory result.
            pass


def v2_open_or_create_directory_chain(
    relative: PurePosixPath,
    *,
    label: str,
) -> int:
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(REPO_ROOT, directory_flags)
    except OSError as error:
        raise InfrastructureFailed(
            "v2 repository root could not be opened for reservation"
        ) from error
    try:
        for part in relative.parts:
            try:
                os.mkdir(part, 0o755, dir_fd=descriptor)
            except FileExistsError:
                pass
            except OSError as error:
                if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                    raise EvidenceFailed(
                        f"{label} contains an unsafe path component"
                    ) from error
                raise
            try:
                next_descriptor = os.open(
                    part,
                    directory_flags,
                    dir_fd=descriptor,
                )
            except OSError as error:
                if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                    raise EvidenceFailed(
                        f"{label} contains a symlink or non-directory component"
                    ) from error
                raise
            try:
                value = os.fstat(next_descriptor)
                if not stat.S_ISDIR(value.st_mode):
                    raise EvidenceFailed(
                        f"{label} contains a non-directory component"
                    )
                # The adopted entry is now descriptor-bound. Durably commit
                # its parent entry before advancing into that child.
                os.fsync(descriptor)
                os.close(descriptor)
            except BaseException:
                try:
                    os.close(next_descriptor)
                except OSError:
                    pass
                raise
            descriptor = next_descriptor
        return descriptor
    except BaseException:
        try:
            os.close(descriptor)
        except OSError:
            pass
        raise


def _v2_reserve_bundle(
    *,
    artifact_root: str,
    artifact_dir: str,
) -> V2BundleReservation:
    root_relative = safe_relative(
        artifact_root,
        label="v2 artifact root",
    )
    dir_relative = safe_relative(
        artifact_dir,
        label="v2 artifact dir",
    )
    combined_relative = root_relative / dir_relative
    if len(str(combined_relative).encode("utf-8")) > 512:
        raise UsageRefused(
            "v2 artifact dir exceeds the 512-byte relative path cap"
        )
    root = REPO_ROOT.joinpath(*root_relative.parts)
    output = REPO_ROOT.joinpath(*combined_relative.parts)
    parent_relative = root_relative.joinpath(*dir_relative.parts[:-1])
    terminal_path = output / "terminal.json"
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    parent_descriptor: int | None = None
    output_descriptor: int | None = None
    terminal_descriptor: int | None = None
    try:
        parent_descriptor = v2_open_or_create_directory_chain(
            parent_relative,
            label="v2 artifact-dir parent",
        )
        try:
            os.mkdir(
                dir_relative.name,
                0o755,
                dir_fd=parent_descriptor,
            )
        except FileExistsError as error:
            raise EvidenceFailed(
                "v2 artifact run directory already exists"
            ) from error
        os.fsync(parent_descriptor)
        try:
            output_descriptor = os.open(
                dir_relative.name,
                directory_flags,
                dir_fd=parent_descriptor,
            )
        except OSError as error:
            if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                raise EvidenceFailed(
                    "v2 artifact run directory is unsafe"
                ) from error
            raise
        terminal_flags = os.O_RDWR | os.O_CREAT | os.O_EXCL
        terminal_flags |= getattr(os, "O_NOFOLLOW", 0)
        try:
            terminal_descriptor = os.open(
                "terminal.json",
                terminal_flags,
                0o644,
                dir_fd=output_descriptor,
            )
        except FileExistsError as error:
            raise EvidenceFailed(
                "v2 terminal reservation already exists"
            ) from error
        os.fsync(terminal_descriptor)
        os.fsync(output_descriptor)
        os.fsync(parent_descriptor)
        anchor_paths: list[Path] = [root]
        cursor = root
        for part in output.relative_to(root).parts:
            cursor = cursor / part
            anchor_paths.append(cursor)
        path_anchors = tuple(
            [
                *(
                    v2_capture_path_anchor(path, expect_directory=True)
                    for path in anchor_paths
                ),
                v2_capture_path_anchor(
                    terminal_path,
                    expect_directory=False,
                ),
            ]
        )
        reservation = V2BundleReservation(
            output=output,
            artifact_root=artifact_root,
            artifact_dir=artifact_dir,
            terminal_descriptor=terminal_descriptor,
            output_descriptor=output_descriptor,
            parent_descriptor=parent_descriptor,
            path_anchors=path_anchors,
        )
        reservation.written_identities["terminal.json"] = v2_stat_identity(
            os.fstat(terminal_descriptor)
        )
        v2_assert_reservation_anchors(reservation)
        return reservation
    except BaseException:
        for descriptor in (
            terminal_descriptor,
            output_descriptor,
            parent_descriptor,
        ):
            if descriptor is None:
                continue
            try:
                os.close(descriptor)
            except OSError:
                pass
        raise


def v2_reserve_bundle(
    *,
    artifact_root: str,
    artifact_dir: str,
) -> V2BundleReservation:
    try:
        return _v2_reserve_bundle(
            artifact_root=artifact_root,
            artifact_dir=artifact_dir,
        )
    except HarnessError:
        raise
    except OSError as error:
        raise InfrastructureFailed(
            "v2 bundle reservation failed at the filesystem boundary"
        ) from error


def v2_expected_bundle_directories(
    names: Iterable[str],
) -> list[str]:
    expected: set[str] = set()
    for name in names:
        parent = PurePosixPath(name).parent
        while str(parent) != ".":
            expected.add(str(parent))
            parent = parent.parent
    return sorted(expected, key=lambda value: value.encode("utf-8"))


def v2_validate_bundle_enumeration_budget(
    *,
    file_count: int,
    directory_count: int,
    path_bytes: int,
    error_type: type[HarnessError] = EvidenceFailed,
) -> None:
    values = (file_count, directory_count, path_bytes)
    if any(type(value) is not int or value < 0 for value in values):
        raise error_type("v2 bundle enumeration budget uses invalid counters")
    if file_count > V2_BUNDLE_FILES_CAP:
        raise error_type("v2 bundle exceeds its file-count cap")
    if directory_count > V2_BUNDLE_DIRECTORIES_CAP:
        raise error_type("v2 bundle exceeds its directory-count cap")
    if file_count + directory_count > (
        V2_BUNDLE_FILES_CAP + V2_BUNDLE_DIRECTORIES_CAP
    ):
        raise error_type("v2 bundle exceeds its aggregate entry cap")
    if path_bytes > V2_BUNDLE_ENUMERATED_PATH_BYTES_CAP:
        raise error_type("v2 bundle exceeds its enumerated-path byte cap")


def v2_validate_artifact_size(
    byte_length: int,
    *,
    label: str,
    error_type: type[HarnessError] = EvidenceFailed,
) -> None:
    if type(byte_length) is not int or byte_length < 0:
        raise error_type(f"{label} uses an invalid artifact byte count")
    if byte_length > RUN_ARTIFACT_CAP:
        raise error_type(f"{label} exceeds its artifact cap")


def v2_validate_aggregate_byte_count(
    byte_length: int,
    *,
    cap: int,
    label: str,
    error_type: type[HarnessError] = EvidenceFailed,
) -> None:
    if (
        type(byte_length) is not int
        or byte_length < 0
        or type(cap) is not int
        or cap < 0
    ):
        raise error_type(f"{label} uses an invalid aggregate byte count")
    if byte_length > cap:
        raise error_type(f"{label} exceeds its aggregate byte cap")


def v2_validate_canonical_byte_size(
    value: Any,
    *,
    cap: int,
    label: str,
    error_type: type[HarnessError] = EvidenceFailed,
) -> int:
    if type(cap) is not int or cap < 0:
        raise error_type(f"{label} uses an invalid canonical byte cap")
    byte_length = 1  # canonical_bytes appends one terminal newline.
    encoder = json.JSONEncoder(
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )
    try:
        for chunk in encoder.iterencode(value):
            byte_length += len(chunk.encode("utf-8"))
            if byte_length > cap:
                raise error_type(
                    f"{label} exceeds its aggregate byte cap"
                )
    except error_type:
        raise
    except (TypeError, ValueError) as error:
        raise error_type(
            f"{label} is not canonically JSON serializable"
        ) from error
    return byte_length


def v2_preflight_publication_topology(
    payloads: Mapping[str, bytes],
) -> tuple[list[str], list[str]]:
    v2_validate_bundle_enumeration_budget(
        file_count=len(payloads),
        directory_count=0,
        path_bytes=0,
    )
    names: list[str] = []
    for raw_name, payload in payloads.items():
        if not isinstance(raw_name, str) or not isinstance(payload, bytes):
            raise EvidenceFailed(
                "v2 publication payload keys and values must be strings and bytes"
            )
        try:
            relative = safe_relative(raw_name, label="v2 artifact member")
        except UsageRefused as error:
            raise EvidenceFailed("v2 publication member path is unsafe") from error
        if str(relative) != raw_name:
            raise EvidenceFailed("v2 publication member path is noncanonical")
        v2_validate_artifact_size(
            len(payload),
            label=f"v2 publication member {raw_name}",
        )
        names.append(raw_name)
    names.sort(key=lambda value: value.encode("utf-8"))
    if len(names) != len(set(names)) or "terminal.json" not in names:
        raise EvidenceFailed(
            "v2 publication topology lacks unique terminal membership"
        )
    directories = v2_expected_bundle_directories(names)
    v2_validate_bundle_enumeration_budget(
        file_count=len(names),
        directory_count=len(directories),
        path_bytes=sum(
            len(value.encode("utf-8"))
            for value in [*names, *directories]
        ),
    )
    if set(names) & set(directories):
        raise EvidenceFailed(
            "v2 publication topology contains a file/directory prefix collision"
        )
    aliases: dict[str, str] = {}
    for relative in [*directories, *names]:
        alias = unicodedata.normalize("NFC", relative).casefold()
        if alias in aliases and aliases[alias] != relative:
            raise EvidenceFailed(
                "v2 publication topology contains a Unicode/case alias"
            )
        aliases[alias] = relative
    return names, directories


def v2_open_reserved_directory(
    reservation: V2BundleReservation,
    relative: PurePosixPath,
    *,
    create: bool,
) -> int:
    output_descriptor = reservation.output_descriptor
    if output_descriptor is None:
        raise EvidenceFailed("v2 output directory descriptor is closed")
    descriptor = os.dup(output_descriptor)
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_flags |= getattr(os, "O_NOFOLLOW", 0)
    try:
        for part in relative.parts:
            if part in {"", "."}:
                continue
            if create:
                try:
                    os.mkdir(part, 0o755, dir_fd=descriptor)
                except FileExistsError:
                    pass
            try:
                next_descriptor = os.open(
                    part,
                    directory_flags,
                    dir_fd=descriptor,
                )
            except OSError as error:
                if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                    raise EvidenceFailed(
                        "v2 publication path component is unsafe"
                    ) from error
                raise
            try:
                value = os.fstat(next_descriptor)
                if not stat.S_ISDIR(value.st_mode):
                    raise EvidenceFailed(
                        "v2 publication path component is not a directory"
                    )
                if create:
                    os.fsync(descriptor)
                os.close(descriptor)
            except BaseException:
                try:
                    os.close(next_descriptor)
                except OSError:
                    pass
                raise
            descriptor = next_descriptor
        return descriptor
    except BaseException:
        try:
            os.close(descriptor)
        except OSError:
            pass
        raise


def v2_write_reserved_member(
    reservation: V2BundleReservation,
    *,
    relative: PurePosixPath,
    payload: bytes,
) -> dict[str, int]:
    v2_validate_artifact_size(
        len(payload),
        label="v2 writer payload",
    )
    parent_descriptor = v2_open_reserved_directory(
        reservation,
        relative.parent,
        create=True,
    )
    descriptor: int | None = None
    try:
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        flags |= getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(
                relative.name,
                flags,
                0o644,
                dir_fd=parent_descriptor,
            )
        except FileExistsError as error:
            raise EvidenceFailed(
                f"v2 overwrite is forbidden for {relative}"
            ) from error
        written = 0
        while written < len(payload):
            count = os.write(descriptor, payload[written:])
            if count <= 0:
                raise OSError("short write to reserved v2 member")
            written += count
        os.fsync(descriptor)
        identity = v2_stat_identity(os.fstat(descriptor))
        os.fsync(parent_descriptor)
        return identity
    except HarnessError:
        raise
    except OSError as error:
        raise InfrastructureFailed(
            f"v2 descriptor-relative write failed for {relative}"
        ) from error
    finally:
        if descriptor is not None:
            try:
                os.close(descriptor)
            except OSError:
                pass
        try:
            os.close(parent_descriptor)
        except OSError:
            pass


def v2_read_descriptor_strict(
    descriptor: int,
    *,
    label: str,
    expected_identity: Mapping[str, int] | None = None,
) -> bytes:
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
            raise InputRefused(f"{label} is not a uniquely linked regular file")
        identity = v2_stat_identity(before)
        if expected_identity is not None and identity != dict(expected_identity):
            raise InputRefused(f"{label} changed descriptor identity")
        if before.st_size > RUN_ARTIFACT_CAP:
            raise InputRefused(f"{label} exceeds the v2 artifact cap")
        chunks: list[bytes] = []
        offset = 0
        while offset < before.st_size:
            chunk = os.pread(
                descriptor,
                min(1024 * 1024, before.st_size - offset),
                offset,
            )
            if not chunk:
                raise InputRefused(f"{label} changed while being read")
            chunks.append(chunk)
            offset += len(chunk)
        if os.pread(descriptor, 1, offset):
            raise InputRefused(f"{label} grew while being read")
        after = os.fstat(descriptor)
        if after.st_nlink != 1 or v2_stat_identity(after) != identity:
            raise InputRefused(f"{label} changed while being read")
        return b"".join(chunks)
    except InputRefused:
        raise
    except OSError as error:
        raise InputRefused(f"{label} failed during strict descriptor read") from error


def v2_read_reserved_member(
    reservation: V2BundleReservation,
    *,
    name: str,
    expected_identity: Mapping[str, int],
) -> bytes:
    if name == "terminal.json":
        descriptor = reservation.terminal_descriptor
        if descriptor is None:
            raise EvidenceFailed("v2 terminal descriptor is closed")
        return v2_read_descriptor_strict(
            descriptor,
            label="v2 reserved terminal",
            expected_identity=expected_identity,
        )
    relative = PurePosixPath(name)
    parent_descriptor = v2_open_reserved_directory(
        reservation,
        relative.parent,
        create=False,
    )
    descriptor: int | None = None
    try:
        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(
            relative.name,
            flags,
            dir_fd=parent_descriptor,
        )
        return v2_read_descriptor_strict(
            descriptor,
            label=f"v2 reserved artifact {name}",
            expected_identity=expected_identity,
        )
    except InputRefused:
        raise
    except OSError as error:
        raise InputRefused(
            f"v2 reserved artifact {name} cannot be opened safely"
        ) from error
    finally:
        if descriptor is not None:
            try:
                os.close(descriptor)
            except OSError:
                pass
        try:
            os.close(parent_descriptor)
        except OSError:
            pass


def v2_verify_reserved_publication(
    reservation: V2BundleReservation,
    *,
    payloads: Mapping[str, bytes],
    terminal_sealed: bool,
) -> None:
    v2_assert_reservation_anchors(reservation)
    expected_files, expected_directories = v2_preflight_publication_topology(
        payloads
    )
    try:
        observed_files, observed_directories, identities = v2_enumerate_bundle(
            reservation.output
        )
        if (
            observed_files != expected_files
            or observed_directories != expected_directories
        ):
            raise InfrastructureFailed(
                "v2 publication tree differs from its exact file/directory contract"
            )
        for name in expected_files:
            path_observed = v2_read_file_strict(
                reservation.output.joinpath(*PurePosixPath(name).parts),
                label=f"v2 published artifact {name}",
                expected_identity=identities[name],
            )
            writer_identity = reservation.written_identities.get(name)
            if writer_identity != identities[name]:
                raise InfrastructureFailed(
                    f"v2 writer/enumerator identity differs for {name}"
                )
            descriptor_observed = v2_read_reserved_member(
                reservation,
                name=name,
                expected_identity=writer_identity,
            )
            expected = (
                payloads[name]
                if name != "terminal.json" or terminal_sealed
                else b""
            )
            if path_observed != expected or descriptor_observed != expected:
                raise InfrastructureFailed(
                    f"v2 published bytes differ for {name}"
                )
    except InputRefused as error:
        raise InfrastructureFailed(
            "v2 publication could not be verified safely"
        ) from error
    v2_assert_reservation_anchors(reservation)


def _v2_publish_reserved_bundle(
    reservation: V2BundleReservation,
    *,
    payloads: Mapping[str, bytes],
) -> dict[str, Any]:
    if reservation.sealed or reservation.terminal_descriptor is None:
        raise EvidenceFailed("v2 artifact reservation is already consumed")
    expected_files, _ = v2_preflight_publication_topology(payloads)
    payload_map = {name: payloads[name] for name in expected_files}
    output_descriptor = reservation.output_descriptor
    descriptor = reservation.terminal_descriptor
    if output_descriptor is None or descriptor is None:
        raise EvidenceFailed("v2 artifact reservation descriptors are closed")

    # The reservation owns a fresh directory containing only its empty
    # terminal placeholder. Validate that exact prefix before writing any
    # caller-provided byte.
    v2_verify_reserved_publication(
        reservation,
        payloads={"terminal.json": payload_map["terminal.json"]},
        terminal_sealed=False,
    )
    nonterminal = [
        name for name in expected_files if name != "terminal.json"
    ]
    writes: list[str] = []
    for name in nonterminal:
        v2_assert_reservation_anchors(reservation)
        check_cancel()
        relative = PurePosixPath(name)
        reservation.written_identities[name] = v2_write_reserved_member(
            reservation,
            relative=relative,
            payload=payload_map[name],
        )
        writes.append(name)
        v2_assert_reservation_anchors(reservation)
    os.fsync(output_descriptor)
    v2_verify_reserved_publication(
        reservation,
        payloads=payload_map,
        terminal_sealed=False,
    )

    terminal_payload = payload_map["terminal.json"]
    # This is the final cancellation boundary. Everything after
    # terminal_assignment_started is a bounded, non-cancellable seal
    # transaction whose exact state is reported to the caller.
    v2_assert_reservation_anchors(reservation)
    check_cancel()
    reservation.terminal_assignment_started = True
    try:
        os.lseek(descriptor, 0, os.SEEK_SET)
        written = 0
        while written < len(terminal_payload):
            count = os.write(descriptor, terminal_payload[written:])
            if count <= 0:
                raise OSError("short write to reserved v2 terminal")
            written += count
        os.ftruncate(descriptor, len(terminal_payload))
        os.fsync(descriptor)
        terminal_identity = v2_stat_identity(os.fstat(descriptor))
        reservation.written_identities["terminal.json"] = terminal_identity
        observed_terminal = v2_read_descriptor_strict(
            descriptor,
            label="v2 committed terminal descriptor",
            expected_identity=terminal_identity,
        )
        if observed_terminal != terminal_payload:
            raise InfrastructureFailed(
                "v2 committed terminal descriptor differs from its payload"
            )
        reservation.terminal_assignment_committed = True
    except OSError as error:
        raise InfrastructureFailed(
            "v2 reserved terminal seal could not be finalized"
        ) from error
    except InputRefused as error:
        raise InfrastructureFailed(
            "v2 reserved terminal seal could not be read back safely"
        ) from error
    v2_verify_reserved_publication(
        reservation,
        payloads=payload_map,
        terminal_sealed=True,
    )
    reservation.sealed = True
    writes.append("terminal.json")
    return {
        "artifact_dir": str(
            safe_relative(reservation.artifact_root, label="artifact root")
            / safe_relative(reservation.artifact_dir, label="artifact dir")
        ),
        "publication_order": writes,
        "terminal_content_sealed_last": True,
    }


def v2_publish_reserved_bundle(
    reservation: V2BundleReservation,
    *,
    payloads: Mapping[str, bytes],
) -> dict[str, Any]:
    try:
        return _v2_publish_reserved_bundle(
            reservation,
            payloads=payloads,
        )
    except HarnessError:
        raise
    except OSError as error:
        raise InfrastructureFailed(
            "v2 publication failed at the filesystem boundary"
        ) from error


def v2_publish_bundle(
    *,
    artifact_root: str,
    artifact_dir: str,
    payloads: Mapping[str, bytes],
) -> dict[str, Any]:
    reservation = v2_reserve_bundle(
        artifact_root=artifact_root,
        artifact_dir=artifact_dir,
    )
    try:
        try:
            result = v2_publish_reserved_bundle(
                reservation,
                payloads=payloads,
            )
        except CancelledDrained as cancellation:
            raise v2_contextual_cancellation_error(
                reservation,
                publication_started=True,
            ) from cancellation
        if _cancel_requested:
            raise v2_contextual_cancellation_error(
                reservation,
                publication_started=True,
            )
        return result
    finally:
        v2_close_reservation(reservation)


def v2_synopsis(
    *,
    subject_mode: str,
    review_plan: Mapping[str, Any],
    history: Mapping[str, Any],
    authority: Mapping[str, Any],
    zero_sets: Mapping[str, Any],
    artifact_dir: str,
    reproduction: Sequence[str],
    explain_target: str | None,
) -> dict[str, Any]:
    children = review_plan.get("children") or []
    retained_without_direct_child = (
        review_plan.get("retained_without_direct_child") or []
    )
    selected_ids = sorted(
        {
            target_id
            for child in children
            for target_id in child.get("target_ids", [])
        }
        | {
            row["target_id"] for row in retained_without_direct_child
        }
        | {
            row["issue_id"] for row in history.get("rows", [])
        }
    )
    if explain_target is not None and explain_target not in selected_ids:
        raise InputRefused(f"--explain-target is not selected: {explain_target}")
    shown_ids = selected_ids[:V2_SYNOPSIS_ID_PREVIEW_CAP]
    work = review_plan.get("work") or {
        "total_review_minutes": 0,
        "minimum_child_review_minutes": 0,
        "maximum_child_review_minutes": 0,
    }
    decisions = authority.get("decisions") or []
    decision_by_target = {
        row.get("target_id"): row
        for row in decisions
        if isinstance(row, dict)
        and isinstance(row.get("target_id"), str)
        and row["target_id"]
    }
    selected_decisions = [
        decision_by_target[target_id]
        for target_id in selected_ids
        if target_id in decision_by_target
    ]
    if (
        explain_target is not None
        and explain_target not in decision_by_target
    ):
        raise EvidenceFailed(
            "--explain-target lacks an authority decision: "
            f"{explain_target}"
        )
    synopsis = {
        "schema": "frankensim.beads-template-hygiene.synopsis.v2",
        "mode": subject_mode,
        "counts": {
            "targets": len(selected_ids),
            "children": len(children),
            "readiness": dict(
                sorted(
                    Counter(
                        row["readiness"] for row in selected_decisions
                    ).items()
                )
            ),
            "routes": dict(
                sorted(
                    Counter(
                        row["remediation_route"]
                        for row in selected_decisions
                    ).items()
                )
            ),
            "owners": len(
                {
                    row["coordination_assignee"]
                    for row in selected_decisions
                    if row["coordination_assignee"]
                }
            ),
            "oversize": len(review_plan.get("oversize_content") or []),
            "zero_receipts": zero_sets.get("counts", {}).get(
                "zero_receipts", 0
            ),
        },
        "work": {
            "total_review_minutes": int(
                work.get("total_review_minutes", 0)
            ),
            "minimum_review_minutes": int(
                work.get("minimum_child_review_minutes", 0)
            ),
            "maximum_review_minutes": int(
                work.get("maximum_child_review_minutes", 0)
            ),
        },
        "capacity_wave_forecast": {
            f"P{priority}": sum(
                child.get("priority") == priority for child in children
            )
            for priority in range(5)
        },
        "active_conflicts": [
            row["target_id"]
            for row in selected_decisions
            if row["active_work_context"]["conflict"]
        ][:V2_SYNOPSIS_ID_PREVIEW_CAP],
        "top_blockers": [
            row["target_id"]
            for row in selected_decisions
            if row["readiness"] != "MECHANICALLY_APPLY_ELIGIBLE"
        ][:V2_SYNOPSIS_ID_PREVIEW_CAP],
        "selected_ids": {
            "total": len(selected_ids),
            "shown": len(shown_ids),
            "ids": shown_ids,
            "truncated": len(shown_ids) < len(selected_ids),
            "notice": (
                "synopsis-only ID preview truncated; machine artifacts are complete"
                if len(shown_ids) < len(selected_ids)
                else None
            ),
        },
        "why_grouped": (
            "hard priority/status/disposition/type/missing-set/semantic-"
            "disposition/semantic-receipt-state/semantic-action/readiness/"
            "remediation-route partitions plus target-complete compatibility "
            "receipts"
        ),
        "explanation": (
            {
                "target_id": explain_target,
                "authority_root": decision_by_target[explain_target][
                    "semantic_root"
                ],
            }
            if explain_target is not None
            else None
        ),
        "safe_next_action": (
            "review the retained child/history payload and its authority route; "
            "do not mutate a target from this planner"
        ),
        "artifacts": artifact_dir,
        "reproduction": list(reproduction),
        "no_claim": (
            "the synopsis is bounded operator guidance; complete machine "
            "artifacts remain untruncated and no authority is minted"
        ),
    }
    if len(canonical_bytes(synopsis)) > V2_SYNOPSIS_BYTES_CAP:
        raise EvidenceFailed("v2 synopsis exceeds its frozen UTF-8 byte cap")
    return synopsis


def v2_contextual_cancellation_error(
    reservation: V2BundleReservation,
    *,
    publication_started: bool,
) -> HarnessError:
    try:
        v2_assert_reservation_anchors(reservation)
    except (HarnessError, OSError):
        return InfrastructureFailed(
            "v2 cancellation coincided with reservation path-identity loss; "
            "manual verification of the reserved bundle is required"
        )
    if reservation.sealed or reservation.terminal_assignment_committed:
        return InfrastructureFailed(
            "v2 cancellation surfaced after a durable terminal commit; "
            "manual verification of the reserved bundle is required"
        )
    if reservation.terminal_assignment_started:
        return InfrastructureFailed(
            "v2 cancellation surfaced after terminal assignment began but "
            "before a verified durable commit; manual verification of the "
            "reserved bundle is required"
        )
    nonterminal_members = sorted(
        set(reservation.written_identities) - {"terminal.json"},
        key=lambda value: value.encode("utf-8"),
    )
    if publication_started or nonterminal_members:
        if nonterminal_members:
            return CancelledDrained(
                "cancellation requested; a retained incomplete nonterminal "
                f"publication prefix with {len(nonterminal_members)} member(s) "
                "remains unsealed; retry with a fresh run directory; no Bead "
                "mutation occurred"
            )
        return CancelledDrained(
            "cancellation requested at publication start; an empty "
            "terminal-only reservation remains unsealed; retry with a fresh "
            "run directory; no Bead mutation occurred"
        )
    return CancelledDrained(
        "cancellation requested before publication; an empty terminal-only "
        "reservation remains unsealed; retry with a fresh run directory; no "
        "Bead mutation occurred"
    )


def v2_execute_live_plan(
    *,
    mode: str,
    parsed: argparse.Namespace,
    manifest: Mapping[str, Any],
    br_cwd: Path = REPO_ROOT,
) -> dict[str, Any]:
    artifact_dir = require_v2_artifact_grammar(parsed)
    output = resolve_run_dir(
        parsed.artifact_root,
        artifact_dir,
        label="v2 artifact dir",
    )
    require_fresh_run_dir(output, label="v2 artifact run directory")
    priority_filter = v2_parse_csv_set(
        parsed.priorities,
        allowed={f"P{priority}" for priority in range(5)},
        label="--priorities",
    )
    status_filter = v2_parse_csv_set(
        parsed.statuses,
        allowed={"open", "in_progress", "blocked", "deferred", "closed"},
        label="--statuses",
    )
    target_filter = v2_parse_target_set(
        parsed.targets,
        label="--targets",
    )
    readiness_filter = v2_parse_csv_set(
        parsed.readiness,
        allowed=V2_READINESS_STATES,
        label="--readiness",
    )
    route_filter = v2_parse_csv_set(
        parsed.routes,
        allowed=V2_REMEDIATION_ROUTES,
        label="--routes",
    )
    if mode == "history-plan" and (
        readiness_filter is not None or route_filter is not None
    ):
        raise UsageRefused(
            "--readiness and --routes select review-plan authority decisions; "
            "history-plan accepts status, priority, and exact target filters"
        )
    reproduction = v2_reproduction_argv(
        mode=mode,
        artifact_root=parsed.artifact_root,
        artifact_dir=artifact_dir,
        review_receipts=parsed.review_receipts,
        prior_campaign=parsed.prior_campaign,
        priorities=(
            ",".join(sorted(priority_filter))
            if priority_filter is not None
            else None
        ),
        statuses=(
            ",".join(sorted(status_filter))
            if status_filter is not None
            else None
        ),
        targets=(
            ",".join(sorted(target_filter))
            if target_filter is not None
            else None
        ),
        readiness=(
            ",".join(sorted(readiness_filter))
            if readiness_filter is not None
            else None
        ),
        routes=(
            ",".join(sorted(route_filter))
            if route_filter is not None
            else None
        ),
        max_targets=parsed.max_targets_per_child,
        explain_target=parsed.explain_target,
    )
    reservation = v2_reserve_bundle(
        artifact_root=parsed.artifact_root,
        artifact_dir=artifact_dir,
    )
    stage = "source_capture_round_1"
    publication_started = False
    available_roots: dict[str, str | None] = {
        "source": None,
        "inventory": None,
        "authority": None,
        "review_plan": None,
        "history": None,
        "zero_sets": None,
    }
    try:
        _command_receipts.clear()
        rule_contract = v2_source_rule_contract()
        before = v2_capture_live_round(
            manifest,
            rule_contract,
            ordinal=1,
            br_cwd=br_cwd,
        )
        stage = "history_audit_between_source_rounds"
        if mode == "history-plan":
            audit_ids = v2_history_audit_ids_from_round(
                before,
                manifest=manifest,
                priority_filter=priority_filter,
                status_filter=status_filter,
                target_filter=target_filter,
            )
            audit_capture = v2_capture_histories(
                audit_ids,
                br_cwd=br_cwd,
            )
        else:
            audit_capture = v2_not_requested_audit_capture()
        stage = "source_capture_round_2"
        after = v2_capture_live_round(
            manifest,
            rule_contract,
            ordinal=2,
            br_cwd=br_cwd,
        )
        stage = "source_capture_coherence"
        snapshot = v2_finalize_live_capture_pair(
            manifest,
            before=before,
            after=after,
            audit_capture=audit_capture,
        )
        stage = "campaign_epoch"
        campaign_root, _ = v2_campaign_epoch(snapshot)
        stage = "inventory"
        inventory = v2_build_inventory(
            snapshot,
            campaign_epoch_root=campaign_root,
            priority_filter=priority_filter,
            status_filter=status_filter,
            target_filter=target_filter,
            readiness_filter=readiness_filter,
            route_filter=route_filter,
        )
        available_roots["inventory"] = inventory["semantic_root"]
        if mode == "history-plan":
            expected_audit_ids = sorted(
                {
                    row["id"]
                    for row in inventory["rows"]
                    if row["status"] == "closed"
                }
                | {
                    str(
                        manifest["history_contract"][
                            "legacy_coverage_anchor_issue"
                        ]
                    )
                }
            )
            if audit_capture["issue_ids"] != expected_audit_ids:
                raise EvidenceFailed(
                    "v2 bracketed history audit membership differs from the "
                    "post-capture selected inventory"
                )
        stage = "review_receipt_admission"
        review_receipts = v2_load_review_receipts(
            parsed.review_receipts,
            inventory=inventory,
        )
        stage = "authority"
        version = str(snapshot.source["br_version"]["version"])
        authority = v2_derive_authority(
            inventory,
            review_receipts,
            current_br_version=version,
        )
        available_roots["authority"] = authority["semantic_root"]
        stage = "prior_campaign"
        prior_campaign = v2_load_prior_campaign(parsed.prior_campaign)
        stage = "source_assembly"
        source = v2_build_source_document(
            snapshot=snapshot,
            manifest=manifest,
            inventory=inventory,
            review_receipts=review_receipts,
            prior_campaign=prior_campaign,
            audit_capture=audit_capture,
            priority_filter=priority_filter,
            status_filter=status_filter,
            target_filter=target_filter,
            readiness_filter=readiness_filter,
            route_filter=route_filter,
        )
        available_roots["source"] = source["semantic_root"]
        stage = "selected_projection"
        if mode == "review-plan":
            review_plan, optional_payloads = v2_build_review_plan(
                inventory,
                authority,
                max_targets=parsed.max_targets_per_child,
            )
            history = v2_not_requested(
                schema=V2_HISTORY_SCHEMA,
                mode=mode,
                source_root=source["semantic_root"],
                inventory_root=inventory["semantic_root"],
                projection="history",
            )
        else:
            review_plan = v2_not_requested(
                schema=V2_REVIEW_PLAN_SCHEMA,
                mode=mode,
                source_root=source["semantic_root"],
                inventory_root=inventory["semantic_root"],
                projection="review-plan",
            )
            optional_payloads = {}
            history = v2_build_history(
                source_root=source["semantic_root"],
                inventory=inventory,
                authority=authority,
                all_issues=snapshot.all_issues,
                audit_capture=audit_capture,
                history_contract=manifest["history_contract"],
            )
        available_roots["review_plan"] = review_plan["semantic_root"]
        available_roots["history"] = history["semantic_root"]
        stage = "zero_sets"
        zero_sets = v2_build_zero_sets(
            source_root=source["semantic_root"],
            inventory=inventory,
            prior_campaign=prior_campaign,
            current_universe=snapshot.all_issues,
            current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
        )
        available_roots["zero_sets"] = zero_sets["semantic_root"]
        stage = "bundle_assembly"
        payloads = v2_bundle_payloads(
            mode=mode,
            subject_mode=mode,
            artifact_root=parsed.artifact_root,
            artifact_dir=artifact_dir,
            source=source,
            inventory=inventory,
            authority=authority,
            review_plan=review_plan,
            history=history,
            zero_sets=zero_sets,
            optional_payloads=optional_payloads,
            reproduction=reproduction,
        )
        stage = "synopsis"
        synopsis = v2_synopsis(
            subject_mode=mode,
            review_plan=review_plan,
            history=history,
            authority=authority,
            zero_sets=zero_sets,
            artifact_dir=str(
                safe_relative(parsed.artifact_root, label="artifact root")
                / safe_relative(artifact_dir, label="artifact dir")
            ),
            reproduction=reproduction,
            explain_target=parsed.explain_target,
        )
        check_cancel()
        stage = "publication"
        publication_started = True
        v2_publish_reserved_bundle(
            reservation,
            payloads=payloads,
        )
        if _cancel_requested:
            raise v2_contextual_cancellation_error(
                reservation,
                publication_started=True,
            )
        return synopsis
    except HarnessError as error:
        if isinstance(error, CancelledDrained):
            raise v2_contextual_cancellation_error(
                reservation,
                publication_started=publication_started,
            ) from error
        if (
            error.terminal in V2_SEMANTIC_REFUSAL_TERMINALS
            and not publication_started
            and not reservation.sealed
        ):
            refusal_payloads, failure = v2_refusal_bundle_payloads(
                mode=mode,
                artifact_root=parsed.artifact_root,
                artifact_dir=artifact_dir,
                manifest=manifest,
                error=error,
                stage=stage,
                available_roots=available_roots,
                argv=[str(SCRIPT_REL), *sys.argv[1:]],
            )
            try:
                v2_publish_reserved_bundle(
                    reservation,
                    payloads=refusal_payloads,
                )
                if _cancel_requested:
                    raise v2_contextual_cancellation_error(
                        reservation,
                        publication_started=True,
                    )
            except CancelledDrained as cancellation:
                raise v2_contextual_cancellation_error(
                    reservation,
                    publication_started=True,
                ) from cancellation
            terminal = strict_json_loads(
                refusal_payloads["terminal.json"],
                label="v2 refusal terminal",
                require_canonical=True,
            )
            result = v2_rooted(
                {
                    "schema": V2_REFUSAL_RESULT_SCHEMA,
                    "terminal": error.terminal,
                    "exit_code": TERMINAL_EXIT[error.terminal],
                    "subject_mode": mode,
                    "artifact_dir": str(
                        safe_relative(
                            parsed.artifact_root,
                            label="artifact root",
                        )
                        / safe_relative(artifact_dir, label="artifact dir")
                    ),
                    "terminal_root": terminal["semantic_root"],
                    "failure_root": failure["semantic_root"],
                    "first_divergence": failure["first_divergence"],
                    "recovery": failure["recovery"],
                    "complete_evidence_bundle": True,
                    "complete_green_prefix": False,
                    "no_claim": (
                        "the planner produced a complete typed refusal bundle "
                        "and did not mutate any Bead"
                    ),
                }
            )
            raise PublishedV2Refusal(
                terminal=error.terminal,
                document=result,
            ) from error
        if publication_started:
            if reservation.terminal_assignment_committed:
                detail = (
                    "terminal content was durably committed, but post-seal "
                    "verification failed"
                )
            elif reservation.terminal_assignment_started:
                detail = (
                    "terminal assignment began but did not reach a verified "
                    "durable commit"
                )
            else:
                detail = "terminal assignment never began"
            raise InfrastructureFailed(
                f"v2 publication failed; {detail}; manual recovery is required"
            ) from error
        raise
    finally:
        v2_close_reservation(reservation)


def v2_stat_identity(value: os.stat_result) -> dict[str, int]:
    return {
        "device": value.st_dev,
        "inode": value.st_ino,
        "mode": value.st_mode,
        "link_count": value.st_nlink,
        "size": value.st_size,
        "mtime_ns": value.st_mtime_ns,
        "ctime_ns": value.st_ctime_ns,
    }


def v2_read_file_strict(
    path: Path,
    *,
    label: str,
    expected_identity: Mapping[str, int] | None = None,
) -> bytes:
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError as error:
        raise InputRefused(f"{label} cannot be opened safely") from error
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise InputRefused(f"{label} is not a regular file")
        before_identity = v2_stat_identity(before)
        if before.st_nlink != 1:
            raise InputRefused(f"{label} has a hard-link alias")
        if (
            expected_identity is not None
            and before_identity != dict(expected_identity)
        ):
            raise InputRefused(f"{label} changed identity after enumeration")
        if before.st_size > RUN_ARTIFACT_CAP:
            raise InputRefused(f"{label} exceeds the v2 artifact cap")
        chunks: list[bytes] = []
        remaining = before.st_size
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise InputRefused(f"{label} changed while being read")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise InputRefused(f"{label} grew while being read")
        after = os.fstat(descriptor)
        if after.st_nlink != 1 or v2_stat_identity(after) != before_identity:
            raise InputRefused(f"{label} changed while being read")
        return b"".join(chunks)
    except InputRefused:
        raise
    except OSError as error:
        raise InputRefused(f"{label} failed during strict read") from error
    finally:
        try:
            os.close(descriptor)
        except OSError:
            # The strict read has already produced its typed result. Do not
            # mask it with a descriptor-close failure.
            pass


def v2_safe_member(value: str, *, label: str) -> str:
    try:
        return str(safe_relative(value, label=label))
    except UsageRefused as error:
        raise InputRefused(f"{label} is unsafe") from error


def v2_register_member_identity(
    seen: dict[tuple[int, int], str],
    *,
    device: int,
    inode: int,
    link_count: int,
    relative: str,
    kind: str,
) -> None:
    if kind not in {"directory", "file"}:
        raise EvidenceFailed("v2 bundle identity kind is unknown")
    identity = (device, inode)
    if identity in seen:
        raise InputRefused(
            "v2 bundle contains an inode alias between "
            f"{seen[identity]!r} and {relative!r}"
        )
    if kind == "file" and link_count != 1:
        raise InputRefused(
            f"v2 bundle file {relative!r} has an external hard-link alias"
        )
    seen[identity] = relative


def v2_enumerate_bundle(
    directory: Path,
) -> tuple[list[str], list[str], dict[str, dict[str, int]]]:
    files: list[str] = []
    directories: list[str] = []
    file_identities: dict[str, dict[str, int]] = {}
    identities: dict[tuple[int, int], str] = {}
    try:
        root_stat = os.lstat(directory)
    except OSError as error:
        raise InputRefused("v2 bundle root cannot be inspected safely") from error
    if not stat.S_ISDIR(root_stat.st_mode):
        raise InputRefused("v2 bundle root is not a directory")
    v2_register_member_identity(
        identities,
        device=root_stat.st_dev,
        inode=root_stat.st_ino,
        link_count=root_stat.st_nlink,
        relative=".",
        kind="directory",
    )
    stack = [directory]
    entry_count = 0
    enumerated_path_bytes = 0
    while stack:
        root = stack.pop()
        names: list[str] = []
        try:
            with os.scandir(root) as iterator:
                for entry in iterator:
                    entry_count += 1
                    if entry_count > (
                        V2_BUNDLE_FILES_CAP
                        + V2_BUNDLE_DIRECTORIES_CAP
                    ):
                        raise InputRefused(
                            "v2 bundle exceeds its aggregate entry cap"
                        )
                    names.append(entry.name)
        except InputRefused:
            raise
        except OSError as error:
            raise InputRefused(
                "v2 bundle directory changed during enumeration"
            ) from error
        child_directories: list[Path] = []
        for name in sorted(names, key=lambda value: value.encode("utf-8")):
            candidate = root / name
            try:
                member_stat = os.lstat(candidate)
            except OSError as error:
                raise InputRefused(
                    "v2 bundle member changed during enumeration"
                ) from error
            relative = candidate.relative_to(directory).as_posix()
            relative = v2_safe_member(relative, label="bundle member")
            enumerated_path_bytes += len(relative.encode("utf-8"))
            if (
                enumerated_path_bytes
                > V2_BUNDLE_ENUMERATED_PATH_BYTES_CAP
            ):
                raise InputRefused(
                    "v2 bundle exceeds its enumerated-path byte cap"
                )
            if stat.S_ISDIR(member_stat.st_mode):
                if len(directories) >= V2_BUNDLE_DIRECTORIES_CAP:
                    raise InputRefused(
                        "v2 bundle exceeds its directory-count cap"
                    )
                v2_register_member_identity(
                    identities,
                    device=member_stat.st_dev,
                    inode=member_stat.st_ino,
                    link_count=member_stat.st_nlink,
                    relative=relative,
                    kind="directory",
                )
                directories.append(relative)
                child_directories.append(candidate)
            elif stat.S_ISREG(member_stat.st_mode):
                if len(files) >= V2_BUNDLE_FILES_CAP:
                    raise InputRefused(
                        "v2 bundle exceeds its file-count cap"
                    )
                v2_register_member_identity(
                    identities,
                    device=member_stat.st_dev,
                    inode=member_stat.st_ino,
                    link_count=member_stat.st_nlink,
                    relative=relative,
                    kind="file",
                )
                files.append(relative)
                file_identities[relative] = v2_stat_identity(member_stat)
            else:
                raise InputRefused("v2 bundle contains an unsafe member")
        stack.extend(reversed(child_directories))
    files.sort(key=lambda value: value.encode("utf-8"))
    directories.sort(key=lambda value: value.encode("utf-8"))
    v2_assert_unique(files, label="v2 bundle files")
    aliases: dict[str, str] = {}
    for relative in [*directories, *files]:
        alias = unicodedata.normalize("NFC", relative).casefold()
        if alias in aliases and aliases[alias] != relative:
            raise InputRefused("v2 bundle contains a Unicode/case path alias")
        aliases[alias] = relative
    return files, directories, file_identities


def v2_read_event_stream(
    payload: bytes,
    *,
    expected_terminal: str = "Pass",
) -> list[dict[str, Any]]:
    if not payload or not payload.endswith(b"\n"):
        raise InputRefused("v2 events.jsonl lacks a terminal newline")
    lines = payload.splitlines(keepends=True)
    v2_validate_log_event_count(
        len(lines),
        error_type=InputRefused,
    )
    events: list[dict[str, Any]] = []
    for index, line in enumerate(lines):
        if len(line) > V2_LOG_LINE_BYTES_CAP:
            raise InputRefused(f"v2 event line {index} exceeds its cap")
        document = strict_json_loads(
            line,
            label=f"v2 event line {index}",
            require_canonical=True,
        )
        if not isinstance(document, dict):
            raise InputRefused(f"v2 event line {index} is not an object")
        v2_exact_keys(
            document,
            V2_EVENT_FIELDS,
            label=f"v2 event line {index}",
        )
        if document["schema"] != V2_EVENT_SCHEMA or document["sequence"] != index:
            raise EvidenceFailed(f"v2 event sequence/schema differs at {index}")
        events.append(document)
    if (
        sum(event["terminal"] is not None for event in events) != 1
        or not events
        or events[-1]["terminal"] != expected_terminal
        or events[-1]["exit_code"] != TERMINAL_EXIT[expected_terminal]
        or (
            expected_terminal == "Pass"
            and (
                events[-1]["first_divergence"] is not None
                or events[-1]["recovery"] != "NOT_REQUIRED"
            )
        )
        or (
            expected_terminal != "Pass"
            and (
                not isinstance(events[-1]["first_divergence"], str)
                or not events[-1]["first_divergence"]
                or not isinstance(events[-1]["recovery"], str)
                or events[-1]["recovery"] == "NOT_REQUIRED"
            )
        )
    ):
        raise EvidenceFailed("v2 retained terminal event is not unique and last")
    return events


def v2_validate_source_full_issue(
    issue: Any,
    *,
    index: int,
) -> None:
    if not isinstance(issue, dict):
        raise InputRefused(f"v2 source all-issue row {index} is not an object")
    v2_exact_keys(
        issue,
        V2_SOURCE_ALL_ISSUE_FIELDS,
        label=f"v2 source all-issue row {index}",
    )
    string_fields = (
        "id",
        "title",
        "type",
        "status",
        "assignee",
        "owner",
        "parent",
        "description",
        "acceptance_criteria",
        "design",
        "notes",
        "updated_at",
        "created_at",
        "created_by",
        "closed_at",
        "close_reason",
        "source_repo",
        "no_claim",
    )
    if (
        any(not isinstance(issue[field], str) for field in string_fields)
        or not issue["id"]
        or not issue["type"]
        or issue["status"] not in STATUS_SCOPES
        or type(issue["priority"]) is not int
        or issue["priority"] not in range(5)
        or type(issue["ephemeral"]) is not bool
        or issue["no_claim"] != V2_SOURCE_ISSUE_NO_CLAIM
        or (
            issue["estimated_minutes"] is not None
            and (
                type(issue["estimated_minutes"]) is not int
                or issue["estimated_minutes"] < 0
            )
        )
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} has invalid core scalars"
        )
    labels = issue["labels"]
    if (
        not isinstance(labels, list)
        or len(labels) > V2_LABELS_PER_ISSUE_CAP
        or any(not isinstance(value, str) or not value for value in labels)
        or labels != sorted(set(labels))
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} has noncanonical labels"
        )
    for relation_field in ("dependencies", "dependents"):
        relations = issue[relation_field]
        if (
            not isinstance(relations, list)
            or len(relations) > V2_RELATIONS_PER_DIRECTION_CAP
        ):
            raise InputRefused(
                f"v2 source all-issue row {index} has malformed "
                f"{relation_field}"
            )
        for relation_index, relation in enumerate(relations):
            if not isinstance(relation, dict):
                raise InputRefused(
                    f"v2 source {relation_field} row {relation_index} "
                    "is not an object"
                )
            v2_exact_keys(
                relation,
                V2_SOURCE_RELATION_FIELDS,
                label=(
                    f"v2 source all-issue row {index} "
                    f"{relation_field} row {relation_index}"
                ),
            )
            if (
                not isinstance(relation["id"], str)
                or not relation["id"]
                or relation["id"] == issue["id"]
                or (
                    relation["id"].startswith("external:")
                    and (
                        relation_field != "dependencies"
                        or not relation["id"].removeprefix("external:")
                        or relation["type"] == "parent-child"
                    )
                )
                or not isinstance(relation["type"], str)
                or not relation["type"]
                or (
                    relation["status"] not in STATUS_SCOPES
                )
                or (
                    type(relation["priority"]) is not int
                    or relation["priority"] not in range(5)
                )
            ):
                raise InputRefused(
                    f"v2 source all-issue row {index} has an invalid "
                    f"{relation_field} row"
                )
        relation_neighbors = [
            relation["id"] for relation in relations
        ]
        if len(relation_neighbors) != len(set(relation_neighbors)):
            raise InputRefused(
                f"v2 source all-issue row {index} duplicates a "
                f"{relation_field} neighbor"
            )
        if relations != sorted(
            relations,
            key=lambda row: (row["type"], row["id"]),
        ):
            raise InputRefused(
                f"v2 source all-issue row {index} has noncanonical "
                f"{relation_field}"
            )
    field_roots = issue["field_roots"]
    if (
        not isinstance(field_roots, dict)
        or set(field_roots)
        != {"description", "acceptance_criteria", "design", "notes"}
        or field_roots
        != {
            field: text_root(issue[field])
            for field in (
                "description",
                "acceptance_criteria",
                "design",
                "notes",
            )
        }
    ):
        raise EvidenceFailed(
            f"v2 source all-issue row {index} field roots disagree"
        )
    source_repo_path = issue["source_repo_path"]
    if (
        not isinstance(source_repo_path, dict)
        or set(source_repo_path) != {"body_retained", "root"}
        or source_repo_path["body_retained"] is not False
        or not isinstance(source_repo_path["root"], str)
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            source_repo_path["root"],
        )
        is None
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} source path receipt is malformed"
        )


def v2_validate_source_graph(
    all_issues: Sequence[Mapping[str, Any]],
) -> None:
    issue_by_id = {
        str(issue["id"]): issue
        for issue in all_issues
        if isinstance(issue, Mapping) and isinstance(issue.get("id"), str)
    }
    if len(issue_by_id) != len(all_issues):
        raise InputRefused("v2 source graph issue membership is malformed")
    reverse_field = {
        "dependencies": "dependents",
        "dependents": "dependencies",
    }
    def has_relation(
        relations: Sequence[Mapping[str, Any]],
        identity: tuple[str, str],
    ) -> bool:
        index = bisect_left(
            relations,
            identity,
            key=lambda row: (row["type"], row["id"]),
        )
        return (
            index < len(relations)
            and (
                relations[index]["type"],
                relations[index]["id"],
            )
            == identity
        )

    for issue_id, issue in sorted(issue_by_id.items()):
        for relation_field in reverse_field:
            neighbors = [
                relation["id"] for relation in issue[relation_field]
            ]
            if (
                issue_id in neighbors
                or len(neighbors) != len(set(neighbors))
            ):
                raise EvidenceFailed(
                    "v2 source graph contains a self edge or duplicate "
                    f"neighbor for {issue_id}.{relation_field}"
                )
        parent_edges = sorted(
            relation["id"]
            for relation in issue["dependencies"]
            if relation["type"] == "parent-child"
        )
        expected_parent_edges = [issue["parent"]] if issue["parent"] else []
        if parent_edges != expected_parent_edges:
            raise EvidenceFailed(
                "v2 source graph parent scalar and parent-child dependency "
                f"differ for {issue_id}"
            )
        for relation_field, reciprocal_field in reverse_field.items():
            for relation in issue[relation_field]:
                neighbor_id = relation["id"]
                if neighbor_id.startswith("external:"):
                    if (
                        relation_field != "dependencies"
                        or not neighbor_id.removeprefix("external:")
                        or relation["type"] == "parent-child"
                    ):
                        raise EvidenceFailed(
                            "v2 source graph external relation has an invalid "
                            "direction, type, or empty identity"
                        )
                    continue
                neighbor = issue_by_id.get(neighbor_id)
                if neighbor is None:
                    raise EvidenceFailed(
                        "v2 source graph relation names an absent neighbor: "
                        f"{issue_id}.{relation_field}->{neighbor_id}"
                    )
                if (
                    relation["status"] != neighbor["status"]
                    or relation["priority"] != neighbor["priority"]
                ):
                    raise EvidenceFailed(
                        "v2 source graph relation status or priority disagrees "
                        f"with neighbor {neighbor_id}"
                    )
                reciprocal_identity = (
                    relation["type"],
                    issue_id,
                )
                if not has_relation(
                    neighbor[reciprocal_field],
                    reciprocal_identity,
                ):
                    raise EvidenceFailed(
                        "v2 source graph relation lacks exact reciprocal edge: "
                        f"{issue_id}.{relation_field}->{neighbor_id}"
                    )
    blocking_types = {
        "blocks",
        "conditional-blocks",
        "waits-for",
    }

    def blocking_neighbors(issue_id: str) -> Iterable[str]:
        for relation in issue_by_id[issue_id]["dependencies"]:
            if (
                relation["type"] in blocking_types
                and not relation["id"].startswith("external:")
            ):
                yield relation["id"]

    def validate_acyclic(
        *,
        relation_label: str,
        neighbors_for: Callable[[str], Iterable[str]],
    ) -> None:
        visit_state: dict[str, int] = {}
        for start in sorted(issue_by_id):
            if visit_state.get(start, 0) != 0:
                continue
            visit_state[start] = 1
            stack: list[tuple[str, Any]] = [
                (start, iter(neighbors_for(start)))
            ]
            while stack:
                current, neighbors = stack[-1]
                try:
                    neighbor_id = next(neighbors)
                except StopIteration:
                    visit_state[current] = 2
                    stack.pop()
                    continue
                neighbor_state = visit_state.get(neighbor_id, 0)
                if neighbor_state == 1:
                    active_path = [node for node, _ in stack]
                    cycle_start = active_path.index(neighbor_id)
                    cycle = [
                        *active_path[cycle_start:],
                        neighbor_id,
                    ]
                    preview = " -> ".join(cycle[:8])
                    if len(cycle) > 8:
                        preview += " -> ..."
                    raise EvidenceFailed(
                        "v2 source graph contains a "
                        f"{relation_label}: nodes={len(cycle) - 1}, "
                        f"root={semantic_root(cycle)}, preview={preview}"
                    )
                if neighbor_state == 0:
                    visit_state[neighbor_id] = 1
                    stack.append(
                        (
                            neighbor_id,
                            iter(neighbors_for(neighbor_id)),
                        )
                    )

    validate_acyclic(
        relation_label="blocking dependency cycle",
        neighbors_for=blocking_neighbors,
    )

    def parent_neighbors(issue_id: str) -> Iterable[str]:
        parent_id = str(issue_by_id[issue_id]["parent"] or "")
        if parent_id:
            yield parent_id

    validate_acyclic(
        relation_label="parent hierarchy cycle",
        neighbors_for=parent_neighbors,
    )


def v2_validate_retained_argv(value: Any, *, label: str) -> list[str]:
    if (
        not isinstance(value, list)
        or not value
        or any(not isinstance(argument, str) for argument in value)
    ):
        raise InputRefused(f"{label} argv is malformed")
    try:
        sanitized = v2_sanitized_argv(value)
    except HarnessError as error:
        raise InputRefused(f"{label} argv exceeds its bounded contract") from error
    if sanitized != value:
        raise InputRefused(f"{label} argv retains an unsanitized value")
    return value


def v2_validate_source_stream_receipt(
    stream: Any,
    *,
    label: str,
) -> None:
    if not isinstance(stream, dict):
        raise InputRefused(f"{label} is not an object")
    v2_exact_keys(stream, V2_SOURCE_STREAM_RECEIPT_FIELDS, label=label)
    if (
        type(stream["bytes"]) is not int
        or stream["bytes"] < 0
        or stream["bytes"] > CAPS["subprocess_stdout_bytes"]
        or not isinstance(stream["root"], str)
        or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", stream["root"]) is None
        or stream["body_retained"] is not False
        or (
            stream["bytes"] == 0
            and stream["root"]
            != "sha256-v1:" + hashlib.sha256(b"").hexdigest()
        )
    ):
        raise InputRefused(f"{label} scalar or retention contract differs")


def v2_expected_observation_argv(
    issue_ids: Sequence[str],
) -> list[list[str]]:
    ordered_ids = sorted(issue_ids)
    commands: list[list[str]] = [
        ["br", "status", "--json", "--no-activity", *BR_READ_FLAGS],
        ["br", "sync", "--status", "--json", *BR_READ_FLAGS],
        ["br", "sync", "--witness", "--json", *BR_READ_FLAGS],
        ["br", "version", "--json", *BR_READ_FLAGS],
        ["br", "capabilities", "--json", *BR_READ_FLAGS],
        ["br", "list", "--all", "--json", "--limit", "0", *BR_READ_FLAGS],
    ]
    batch_size = min(CAPS["show_batch"], 56)
    commands.extend(
        [
            "br",
            "show",
            *ordered_ids[offset : offset + batch_size],
            "--json",
            *BR_READ_FLAGS,
        ]
        for offset in range(0, len(ordered_ids), batch_size)
    )
    commands.extend(
        [
            "br",
            "lint",
            "--status",
            scope,
            "--json",
            *BR_READ_FLAGS,
        ]
        for scope in LINT_SCOPES
    )
    return [*commands, *commands]


def v2_validate_source_command_receipts(
    observation: Mapping[str, Any],
    *,
    issue_ids: Sequence[str],
) -> list[Mapping[str, Any]]:
    receipts = observation.get("command_receipts")
    if not isinstance(receipts, list):
        raise InputRefused(
            "v2 source observation command receipts are not an array"
        )
    if len(receipts) > V2_LOG_EVENTS_CAP - 8:
        raise InputRefused(
            "v2 source observation command receipts exceed the event budget"
        )
    for index, receipt in enumerate(receipts):
        label = f"v2 source observation command receipt {index}"
        if not isinstance(receipt, dict):
            raise InputRefused(f"{label} is not an object")
        v2_exact_keys(
            receipt,
            V2_SOURCE_COMMAND_RECEIPT_FIELDS,
            label=label,
        )
        v2_validate_retained_argv(receipt["argv"], label=label)
        cleanup_kinds = receipt["cleanup_error_kinds"]
        if (
            type(receipt["capture_sequence"]) is not int
            or receipt["capture_sequence"] != index
            or type(receipt["exit_code"]) is not int
            or receipt["exit_code"] != 0
            or receipt["category"] != "SUCCESS"
            or type(receipt["cleanup_error_count"]) is not int
            or receipt["cleanup_error_count"] != 0
            or not isinstance(cleanup_kinds, list)
            or cleanup_kinds
            or receipt["redaction_verdict"]
            != "RAW_STREAM_BODIES_NOT_RETAINED"
        ):
            raise InputRefused(
                f"{label} sequence, terminal, or cleanup contract differs"
            )
        v2_validate_source_stream_receipt(
            receipt["stdout"],
            label=f"{label} stdout",
        )
        v2_validate_source_stream_receipt(
            receipt["stderr"],
            label=f"{label} stderr",
        )
    expected_argv = v2_expected_observation_argv(issue_ids)
    if [receipt["argv"] for receipt in receipts] != expected_argv:
        raise InputRefused(
            "v2 source observation command membership, order, or read-only "
            "grammar differs"
        )
    return receipts


def v2_validate_audit_capture(
    audit_capture: Mapping[str, Any],
    *,
    allowed_issue_ids: set[str],
) -> list[Mapping[str, Any]]:
    if "state" in audit_capture:
        v2_exact_keys(
            audit_capture,
            V2_AUDIT_CAPTURE_NOT_REQUESTED_FIELDS,
            label="v2 source audit capture not-requested envelope",
        )
        v2_validate_canonical_byte_size(
            audit_capture,
            cap=V2_AUDIT_CAPTURE_BYTES_CAP,
            label="v2 source audit capture",
            error_type=InputRefused,
        )
        expected = v2_rooted(
            {
                "state": "NOT_REQUESTED",
                "capture_count": 0,
                "issue_ids": [],
                "documents": [],
                "command_receipts": [],
                "raw_stream_bodies_retained": False,
                "no_claim": V2_AUDIT_NOT_REQUESTED_NO_CLAIM,
            }
        )
        if audit_capture != expected:
            divergence = first_projection_divergence(expected, audit_capture)
            raise InputRefused(
                "v2 source audit not-requested envelope differs at "
                f"{divergence or '$'}"
            )
        return []

    v2_exact_keys(
        audit_capture,
        V2_AUDIT_CAPTURE_FIELDS,
        label="v2 source audit capture envelope",
    )
    issue_ids = audit_capture["issue_ids"]
    documents = audit_capture["documents"]
    receipts = audit_capture["command_receipts"]
    if (
        audit_capture["capture_count"] != 2
        or audit_capture["worker_bound"] != V2_AUDIT_WORKERS
        or not isinstance(issue_ids, list)
        or not isinstance(documents, list)
        or not isinstance(receipts, list)
        or len(issue_ids) > V2_INVENTORY_ROWS_CAP
        or len(documents) != len(issue_ids)
        or len(receipts) != 2 * len(issue_ids)
        or audit_capture["raw_stream_bodies_retained"] is not False
        or audit_capture["no_claim"] != V2_AUDIT_CAPTURE_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source audit capture cardinality or scalar contract differs"
        )
    v2_validate_canonical_byte_size(
        audit_capture,
        cap=V2_AUDIT_CAPTURE_BYTES_CAP,
        label="v2 source audit capture",
        error_type=InputRefused,
    )
    if (
        any(
            not isinstance(issue_id, str) or not issue_id
            for issue_id in issue_ids
        )
        or issue_ids != sorted(set(issue_ids))
        or not set(issue_ids).issubset(allowed_issue_ids)
    ):
        raise InputRefused(
            "v2 source audit capture membership contract differs"
        )
    document_ids = [
        document.get("issue_id")
        for document in documents
        if isinstance(document, dict)
    ]
    if len(document_ids) != len(documents) or document_ids != issue_ids:
        raise InputRefused(
            "v2 source audit document membership differs from issue IDs"
        )
    for index, document in enumerate(documents):
        try:
            expected_document = v2_normalize_audit_document(
                {
                    "issue_id": document["issue_id"],
                    "events": document.get("events"),
                },
                issue_id=document["issue_id"],
            )
        except (InfrastructureFailed, EvidenceFailed, KeyError) as error:
            raise InputRefused(
                f"v2 source audit document {index} is malformed or over cap"
            ) from error
        if document != expected_document:
            divergence = first_projection_divergence(
                expected_document,
                document,
            )
            raise InputRefused(
                "v2 source audit document differs from its normalized "
                f"projection at {divergence or '$'}"
            )
    expected_order = [
        (capture_ordinal, issue_id)
        for capture_ordinal in (1, 2)
        for issue_id in issue_ids
    ]
    observed_order: list[tuple[int, str]] = []
    for index, receipt in enumerate(receipts):
        label = f"v2 source audit command receipt {index}"
        if not isinstance(receipt, dict):
            raise InputRefused(f"{label} is not an object")
        v2_exact_keys(
            receipt,
            V2_AUDIT_COMMAND_RECEIPT_FIELDS,
            label=label,
        )
        issue_id = receipt["issue_id"]
        ordinal = receipt["capture_ordinal"]
        if (
            type(ordinal) is not int
            or ordinal not in {1, 2}
            or not isinstance(issue_id, str)
            or (ordinal, issue_id) != expected_order[index]
            or receipt["argv"]
            != [
                "br",
                "audit",
                "log",
                issue_id,
                "--json",
                *BR_READ_FLAGS,
            ]
            or receipt["exit_code"] != 0
            or type(receipt["exit_code"]) is not int
            or receipt["result_category"] != "SUCCESS"
            or type(receipt["stdout_byte_length"]) is not int
            or not 0
            < receipt["stdout_byte_length"]
            <= V2_AUDIT_STREAM_BYTES_CAP
            or type(receipt["stderr_byte_length"]) is not int
            or not 0
            <= receipt["stderr_byte_length"]
            <= V2_AUDIT_STREAM_BYTES_CAP
            or (
                receipt["stderr_byte_length"] == 0
                and receipt["stderr_root"]
                != "sha256-v1:" + hashlib.sha256(b"").hexdigest()
            )
            or any(
                not isinstance(receipt[field], str)
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    receipt[field],
                )
                is None
                for field in ("stdout_root", "stderr_root")
            )
            or receipt["raw_stream_bodies_retained"] is not False
        ):
            raise InputRefused(f"{label} identity or terminal contract differs")
        v2_validate_retained_argv(receipt["argv"], label=label)
        observed_order.append((ordinal, issue_id))
    if observed_order != expected_order:
        raise InputRefused(
            "v2 source audit command receipt order is noncanonical"
        )
    verify_semantic_root(
        audit_capture,
        label="v2 source audit capture envelope",
    )
    return receipts


def v2_validate_source_review_receipt_envelope(
    receipt_document: Mapping[str, Any],
) -> None:
    if not isinstance(receipt_document, dict):
        raise InputRefused("v2 source review receipts are not an object")
    allowed_fields = {
        "schema",
        "inventory_root",
        "campaign_epoch_root",
        "receipts",
        "source",
        "source_identity",
        "no_claim",
        "semantic_root",
    }
    required_fields = allowed_fields - {"source_identity"}
    if (
        not required_fields.issubset(receipt_document)
        or not set(receipt_document).issubset(allowed_fields)
    ):
        raise InputRefused(
            "v2 source review receipt envelope has a non-closed schema"
        )
    receipts = receipt_document.get("receipts")
    if (
        receipt_document["schema"] != V2_REVIEW_RECEIPTS_SCHEMA
        or any(
            not isinstance(receipt_document[field], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                receipt_document[field],
            )
            is None
            for field in ("inventory_root", "campaign_epoch_root")
        )
        or not isinstance(receipt_document["source"], str)
        or not receipt_document["source"].strip()
        or not isinstance(receipts, list)
        or len(receipts) > V2_INVENTORY_ROWS_CAP
        or receipt_document["no_claim"] != V2_REVIEW_RECEIPTS_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source review receipt envelope identity or no-claim differs"
        )
    v2_validate_review_receipt_document_provenance(
        receipt_document,
        receipts,
        inventory=None,
        label="v2 source review receipts",
    )
    verify_semantic_root(
        receipt_document,
        label="v2 source review receipt envelope",
    )
    v2_validate_review_receipt_source_identity(
        receipt_document,
        label="v2 source review receipts",
    )
    target_ids: list[str] = []
    for index, receipt in enumerate(receipts):
        if not isinstance(receipt, dict):
            raise InputRefused(
                f"v2 source review receipt row {index} is not an object"
            )
        v2_exact_keys(
            receipt,
            {*V2_REVIEW_RECEIPT_FIELDS, "semantic_root"},
            label=f"v2 source review receipt row {index}",
        )
        v2_validate_review_receipt_row_provenance(
            receipt,
            receipt_document,
            label=f"v2 source review receipt row {index}",
        )
        verify_semantic_root(
            receipt,
            label=f"v2 source review receipt row {index}",
        )
        target_id = receipt["target_id"]
        if (
            not isinstance(target_id, str)
            or not target_id
            or receipt["no_claim"] != V2_REVIEW_RECEIPT_ROW_NO_CLAIM
        ):
            raise InputRefused(
                f"v2 source review receipt row {index} identity or no-claim differs"
            )
        target_ids.append(target_id)
    if target_ids != sorted(target_ids) or len(target_ids) != len(
        set(target_ids)
    ):
        raise InputRefused(
            "v2 source review receipt membership is noncanonical"
        )


def v2_validate_source_prior_campaign_envelope(
    prior_campaign: Mapping[str, Any],
) -> None:
    if not isinstance(prior_campaign, dict):
        raise InputRefused("v2 source prior campaign is not an object")
    state = prior_campaign.get("state")
    if state == "NOT_PROVIDED":
        v2_exact_keys(
            prior_campaign,
            {
                "state",
                "bundle_path",
                "terminal_root",
                "inventory_root",
                "rows",
                "no_claim",
                "semantic_root",
            },
            label="v2 source prior campaign",
        )
        if (
            prior_campaign["bundle_path"] is not None
            or prior_campaign["terminal_root"] is not None
            or prior_campaign["inventory_root"] is not None
            or prior_campaign["rows"] != []
            or prior_campaign["no_claim"]
            != V2_PRIOR_CAMPAIGN_NOT_PROVIDED_NO_CLAIM
        ):
            raise InputRefused(
                "v2 source absent prior campaign carries evidence or authority"
            )
        verify_semantic_root(
            prior_campaign,
            label="v2 source prior campaign",
        )
        return
    if state != "PROVIDED":
        raise InputRefused("v2 source prior campaign has an unknown state")
    v2_exact_keys(
        prior_campaign,
        {
            "state",
            "bundle_path",
            "terminal_root",
            "inventory_root",
            "campaign_epoch_root",
            "rows",
            "no_claim",
            "semantic_root",
        },
        label="v2 source prior campaign",
    )
    try:
        normalized_path = str(
            safe_relative(
                prior_campaign["bundle_path"],
                label="v2 source prior campaign bundle path",
            )
        )
    except (KeyError, TypeError, UsageRefused) as error:
        raise InputRefused(
            "v2 source prior campaign bundle path is malformed"
        ) from error
    if (
        normalized_path != prior_campaign["bundle_path"]
        or any(
            not isinstance(prior_campaign[field], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                prior_campaign[field],
            )
            is None
            for field in (
                "terminal_root",
                "inventory_root",
                "campaign_epoch_root",
            )
        )
        or not isinstance(prior_campaign["rows"], list)
        or len(prior_campaign["rows"]) > V2_INVENTORY_ROWS_CAP
        or prior_campaign["no_claim"]
        != V2_PRIOR_CAMPAIGN_PROVIDED_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source prior campaign identity or no-claim differs"
        )
    verify_semantic_root(
        prior_campaign,
        label="v2 source prior campaign",
    )


def v2_preflight_source_v1_inventory_nested_lists(
    inventory: Mapping[str, Any],
) -> None:
    rows = inventory.get("rows")
    warning_rows = inventory.get("warning_rows")
    if not isinstance(rows, list):
        raise InputRefused("v2 source v1 inventory rows are not an array")
    if not isinstance(warning_rows, list):
        raise InputRefused(
            "v2 source v1 inventory warning rows are not an array"
        )
    if len(rows) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "v2 source v1 inventory rows exceed the inventory row cap"
        )
    if len(warning_rows) > V2_WARNING_ROWS_CAP:
        raise InputRefused(
            "v2 source v1 inventory warning rows exceed the warning row cap"
        )
    warning_count = 0
    maximum_warnings_per_issue = 0
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            raise InputRefused(
                f"v2 source v1 inventory row {index} is not an object"
            )
        missing_sections = row.get("missing_sections")
        if not isinstance(missing_sections, list):
            raise InputRefused(
                "v2 source v1 inventory row "
                f"{index} missing sections are not an array"
            )
        row_warning_count = len(missing_sections)
        maximum_warnings_per_issue = max(
            maximum_warnings_per_issue,
            row_warning_count,
        )
        warning_count += row_warning_count
        if warning_count > V2_WARNING_ROWS_CAP:
            raise InputRefused(
                "v2 source v1 inventory row warnings exceed the warning row cap"
            )
    v2_validate_source_limits(
        row_count=len(rows),
        warning_count=max(warning_count, len(warning_rows)),
        maximum_warnings_per_issue=maximum_warnings_per_issue,
    )


def v2_preflight_source_v1_lint_nested_lists(
    lint: Mapping[str, Any],
) -> None:
    for scope in LINT_SCOPES:
        projection = lint.get(scope)
        if not isinstance(projection, dict):
            raise InputRefused(
                f"v2 source v1 lint scope {scope} is not an object"
            )
        results = projection.get("results")
        declared_issues = projection.get("issues")
        declared_warnings = projection.get("total")
        if not isinstance(results, list):
            raise InputRefused(
                f"v2 source v1 lint scope {scope} results are not an array"
            )
        if (
            type(declared_issues) is not int
            or declared_issues < 0
            or type(declared_warnings) is not int
            or declared_warnings < 0
        ):
            raise InputRefused(
                f"v2 source v1 lint scope {scope} counts are malformed"
            )
        warning_count = 0
        maximum_warnings_per_issue = 0
        for index, row in enumerate(results):
            if not isinstance(row, dict):
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} is not an object"
                )
            missing_sections = row.get("missing")
            suggestions = row.get("suggestions")
            if not isinstance(missing_sections, list):
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} missing sections are not an array"
                )
            if suggestions is not None and not isinstance(suggestions, list):
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} suggestions are not an array"
                )
            if (
                isinstance(suggestions, list)
                and len(suggestions) > V2_WARNINGS_PER_ISSUE_CAP
            ):
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} suggestions exceed the per-issue cap"
                )
            row_warning_count = len(missing_sections)
            maximum_warnings_per_issue = max(
                maximum_warnings_per_issue,
                row_warning_count,
            )
            warning_count += row_warning_count
            if warning_count > V2_WARNING_ROWS_CAP:
                raise InputRefused(
                    f"v2 source v1 lint scope {scope} warnings exceed the cap"
                )
        v2_validate_source_limits(
            row_count=max(len(results), declared_issues),
            warning_count=max(warning_count, declared_warnings),
            maximum_warnings_per_issue=maximum_warnings_per_issue,
        )


def v2_preflight_source_observation_nested_lists(
    observation: Mapping[str, Any],
) -> None:
    source_files = observation.get("source_files")
    status_cut = observation.get("status_cut")
    command_receipts = observation.get("command_receipts")
    br_version = observation.get("br_version")
    features = (
        br_version.get("features")
        if isinstance(br_version, dict)
        else None
    )
    if not isinstance(source_files, list):
        raise InputRefused(
            "v2 source observation source files are not an array"
        )
    if len(source_files) > V2_BUNDLE_FILES_CAP:
        raise InputRefused(
            "v2 source observation source files exceed the bundle file cap"
        )
    if not isinstance(status_cut, list):
        raise InputRefused(
            "v2 source observation status cut is not an array"
        )
    if len(status_cut) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "v2 source observation status cut exceeds the inventory row cap"
        )
    if not isinstance(command_receipts, list):
        raise InputRefused(
            "v2 source observation command receipts are not an array"
        )
    if len(command_receipts) > V2_LOG_EVENTS_CAP - 8:
        raise InputRefused(
            "v2 source observation command receipts exceed the event budget"
        )
    if not isinstance(features, list):
        raise InputRefused(
            "v2 source observation br features are not an array"
        )
    if len(features) > V2_LOG_EVENTS_CAP:
        raise InputRefused(
            "v2 source observation br features exceed the event budget"
        )
    for index, receipt in enumerate(command_receipts):
        if not isinstance(receipt, dict):
            raise InputRefused(
                f"v2 source observation command receipt {index} is not an object"
            )
        for field in ("argv", "cleanup_error_kinds"):
            values = receipt.get(field)
            if not isinstance(values, list):
                raise InputRefused(
                    "v2 source observation command receipt "
                    f"{index} {field} is not an array"
                )
            if len(values) > V2_LOG_EVENTS_CAP:
                raise InputRefused(
                    "v2 source observation command receipt "
                    f"{index} {field} exceeds the event budget"
                )


def v2_validate_source_document(source: Mapping[str, Any]) -> None:
    if not isinstance(source, dict):
        raise InputRefused("v2 source artifact is not an object")
    if source.get("schema") != V2_SOURCE_SCHEMA:
        raise InputRefused("v2 source artifact has an unknown schema")
    v2_exact_keys(
        source,
        V2_SOURCE_FIELDS,
        label="source-v2.json",
    )
    if (
        source["schema"] != V2_SOURCE_SCHEMA
        or not isinstance(source["campaign_epoch_root"], str)
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            source["campaign_epoch_root"],
        )
        is None
        or source["tracker_authority"] != "READ_ONLY"
        or source["direct_tracker_file_access"] is not False
        or source["network_access"] is not False
        or source["no_claim"] != V2_SOURCE_NO_CLAIM
    ):
        raise InputRefused("v2 source artifact has invalid identity or authority")
    manifest = source["manifest"]
    if not isinstance(manifest, dict):
        raise InputRefused("v2 source retained manifest is not an object")
    v2_exact_keys(
        manifest,
        V2_SOURCE_MANIFEST_FIELDS,
        label="v2 source retained manifest",
    )
    if (
        manifest["path"] != str(CASE_MANIFEST_V2_REL)
        or not all(
            isinstance(manifest[field], str)
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                manifest[field],
            )
            is not None
            for field in (
                "semantic_root",
                "content_identity",
                "harness_contract_identity",
            )
        )
        or any(
            type(manifest[field]) is not int or manifest[field] < 0
            for field in ("case_count", "assertion_count", "criterion_count")
        )
    ):
        raise InputRefused("v2 source retained manifest scalars are invalid")
    contracts = source["contracts"]
    if (
        not isinstance(source["v1_baseline"], dict)
        or not isinstance(contracts, dict)
        or set(contracts) != V2_SOURCE_CONTRACT_FIELDS
        or any(not isinstance(value, dict) for value in contracts.values())
    ):
        raise InputRefused("v2 source retained contracts are malformed")
    captured = source["captured"]
    roots = source["capture_roots"]
    if not isinstance(captured, dict) or not isinstance(roots, dict):
        raise InputRefused("v2 source lacks captured inputs or roots")
    v2_exact_keys(
        captured,
        V2_SOURCE_CAPTURE_FIELDS,
        label="v2 source captured inputs",
    )
    v2_exact_keys(
        roots,
        V2_SOURCE_CAPTURE_ROOT_FIELDS,
        label="v2 source capture roots",
    )
    if (
        not isinstance(captured["all_issues"], list)
        or not isinstance(captured["v1_lint_projection"], dict)
        or any(
            not isinstance(captured[field], dict)
            for field in (
                "v1_inventory_projection",
                "observation",
                "campaign",
                "filters",
                "review_receipts",
                "prior_campaign",
                "audit_capture",
            )
        )
    ):
        raise InputRefused("v2 source captured input types are malformed")
    v2_preflight_source_v1_lint_nested_lists(
        captured["v1_lint_projection"]
    )
    v2_preflight_source_v1_inventory_nested_lists(
        captured["v1_inventory_projection"]
    )
    v2_preflight_source_observation_nested_lists(
        captured["observation"]
    )
    all_issues = captured["all_issues"]
    if len(all_issues) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "v2 source all-issue projection exceeds its row cap"
        )
    retained_projection_bytes = len(canonical_bytes([]))
    for index, row in enumerate(all_issues):
        v2_validate_source_full_issue(row, index=index)
        row_bytes = len(canonical_bytes(row))
        retained_projection_bytes = (
            row_bytes + 2
            if index == 0
            else retained_projection_bytes + row_bytes
        )
        v2_validate_aggregate_byte_count(
            retained_projection_bytes,
            cap=V2_SOURCE_PROJECTION_BYTES_CAP,
            label="v2 source all-issue projections",
            error_type=InputRefused,
        )
    v2_assert_unique(
        [row["id"] for row in all_issues],
        label="v2 source all-issue IDs",
    )
    if [row["id"] for row in all_issues] != sorted(
        row["id"] for row in all_issues
    ):
        raise InputRefused(
            "v2 source all-issue membership is noncanonical"
        )
    v2_validate_source_graph(all_issues)
    campaign = captured["campaign"]
    v2_exact_keys(
        campaign,
        {"issue_count", "issue_ids_root", "projection_root"},
        label="v2 source campaign receipt",
    )
    if (
        type(campaign["issue_count"]) is not int
        or campaign["issue_count"] < 0
        or campaign["projection_root"] != source["campaign_epoch_root"]
        or any(
            not isinstance(campaign[field], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                campaign[field],
            )
            is None
            for field in ("issue_ids_root", "projection_root")
        )
    ):
        raise EvidenceFailed("v2 source campaign receipt disagrees")
    for label, document in (
        ("v1 inventory", captured["v1_inventory_projection"]),
        ("observation", captured["observation"]),
    ):
        if "semantic_root" not in document:
            raise InputRefused(f"v2 source {label} lacks a semantic root")
        verify_semantic_root(document, label=f"source-v2 {label}")
    v2_validate_source_review_receipt_envelope(
        captured["review_receipts"]
    )
    v2_validate_source_prior_campaign_envelope(
        captured["prior_campaign"]
    )
    expected = {
        "all_issues": semantic_root(captured["all_issues"]),
        "v1_lint_projection": semantic_root(captured["v1_lint_projection"]),
        "v1_inventory_projection": captured["v1_inventory_projection"][
            "semantic_root"
        ],
        "observation": captured["observation"]["semantic_root"],
        "review_receipts": captured["review_receipts"]["semantic_root"],
        "prior_campaign": captured["prior_campaign"]["semantic_root"],
        "audit_capture": captured["audit_capture"]["semantic_root"],
    }
    if roots != expected:
        raise EvidenceFailed("v2 source captured-input roots disagree")
    campaign_issues = sorted(
        (row for row in all_issues if row["status"] != "closed"),
        key=lambda row: row["id"],
    )
    if (
        campaign["issue_count"] != len(campaign_issues)
        or campaign["issue_ids_root"]
        != semantic_root([row["id"] for row in campaign_issues])
        or campaign["projection_root"]
        != semantic_root(
            [v2_stable_issue_projection(row) for row in campaign_issues]
        )
    ):
        raise EvidenceFailed("v2 source campaign membership receipt disagrees")
    observation_preflight = captured["observation"]
    v2_exact_keys(
        observation_preflight,
        V2_SOURCE_OBSERVATION_FIELDS,
        label="v2 source observation",
    )
    if (
        observation_preflight["schema"] != V2_SOURCE_SCHEMA
        or observation_preflight["no_claim"]
        != V2_SOURCE_OBSERVATION_NO_CLAIM
        or not isinstance(observation_preflight["source_files"], list)
        or len(observation_preflight["source_files"]) != 3
        or any(
            not isinstance(identity, dict)
            or set(identity) != {"path", "bytes", "content_identity"}
            for identity in observation_preflight["source_files"]
        )
    ):
        raise InputRefused(
            "v2 source observation identity or capture contract is malformed"
        )
    current_source_files_preflight = v2_source_file_identities()
    expected_source_files_preflight = [
        current_source_files_preflight[0],
        current_source_files_preflight[1],
        {
            **current_source_files_preflight[2],
            "content_identity": manifest["content_identity"],
        },
    ]
    if (
        observation_preflight["source_files"]
        != expected_source_files_preflight
        or observation_preflight["source_files"][1]["content_identity"]
        != source["v1_baseline"].get("v1_manifest_content_root")
        or observation_preflight["source_files"][2]["content_identity"]
        != observation_preflight["case_manifest_content_identity"]
    ):
        raise EvidenceFailed(
            "v2 source observation source-file identities are not bound to "
            "the executing harness and retained manifest baselines"
        )
    try:
        independent_findings = {
            row["id"]: findings
            for row in all_issues
            if (findings := independent_template_findings(row))
        }
        lint_ids = set(
            lint_result_map(captured["v1_lint_projection"])
        )
        target_ids = sorted(
            {
                row["id"]
                for row in all_issues
                if row["status"] != "closed"
            }
            | lint_ids
            | set(independent_findings)
        )
        all_issue_by_id = {row["id"]: row for row in all_issues}
    except HarnessError:
        raise
    except (
        AttributeError,
        IndexError,
        KeyError,
        TypeError,
        ValueError,
    ) as error:
        raise InputRefused(
            "v2 source v1 lint or inventory projection is malformed"
        ) from error
    filters = captured["filters"]
    if (
        not isinstance(filters, dict)
        or set(filters)
        != {
            "priorities",
            "statuses",
            "targets",
            "readiness",
            "routes",
            "empty_means_all",
            "authority_filters_apply_to_selected_projection",
        }
        or not isinstance(filters["priorities"], list)
        or not isinstance(filters["statuses"], list)
        or not isinstance(filters["targets"], list)
        or not isinstance(filters["readiness"], list)
        or not isinstance(filters["routes"], list)
        or any(
            not isinstance(value, str)
            or value not in {f"P{priority}" for priority in range(5)}
            for value in filters["priorities"]
        )
        or any(
            not isinstance(value, str) or value not in STATUS_SCOPES
            for value in filters["statuses"]
        )
        or any(
            not isinstance(value, str)
            or re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9._:-]{0,255}",
                value,
            )
            is None
            for value in filters["targets"]
        )
        or any(
            not isinstance(value, str)
            or value not in V2_READINESS_STATES
            for value in filters["readiness"]
        )
        or any(
            not isinstance(value, str)
            or value not in V2_REMEDIATION_ROUTES
            for value in filters["routes"]
        )
        or filters["priorities"] != sorted(set(filters["priorities"]))
        or filters["statuses"] != sorted(set(filters["statuses"]))
        or filters["targets"] != sorted(set(filters["targets"]))
        or filters["readiness"] != sorted(set(filters["readiness"]))
        or filters["routes"] != sorted(set(filters["routes"]))
        or filters["empty_means_all"] is not True
        or filters["authority_filters_apply_to_selected_projection"] is not True
    ):
        raise EvidenceFailed("v2 source filter projection is malformed")
    observation = captured["observation"]
    v2_exact_keys(
        observation,
        V2_SOURCE_OBSERVATION_FIELDS,
        label="v2 source observation",
    )
    br_version = observation.get("br_version")
    capture_contract = observation.get("capture_contract")
    source_files = observation.get("source_files")
    normalized_capability_commands = v2_normalize_br_capability_commands(
        (
            observation.get("br_capabilities", {}).get("commands")
            if isinstance(observation.get("br_capabilities"), dict)
            else None
        ),
        error_type=InputRefused,
    )
    if (
        observation["schema"] != V2_SOURCE_SCHEMA
        or not isinstance(br_version, dict)
        or set(br_version)
        != {"build", "commit", "features", "target", "version"}
        or any(
            not isinstance(br_version.get(field), str)
            for field in ("build", "commit", "target", "version")
        )
        or not str(br_version.get("version")).strip()
        or not isinstance(br_version.get("features"), list)
        or any(
            not isinstance(feature, str) or not feature
            for feature in br_version.get("features", [])
        )
        or br_version.get("features")
        != sorted(set(br_version.get("features", [])))
        or not isinstance(observation["br_capabilities"], dict)
        or set(observation["br_capabilities"])
        != {"commands", "contract_version", "operation_count"}
        or observation["br_capabilities"]["contract_version"]
        != "br.capabilities.v1"
        or observation["br_capabilities"]["commands"]
        != normalized_capability_commands
        or type(observation["br_capabilities"]["operation_count"]) is not int
        or observation["br_capabilities"]["operation_count"]
        != len(normalized_capability_commands)
        or any(
            not isinstance(observation[field], dict)
            for field in ("tracker_status", "sync_status", "export_witness")
        )
        or not isinstance(source_files, list)
        or len(source_files) != 3
        or observation["no_claim"] != V2_SOURCE_OBSERVATION_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source observation identity or capture contract is malformed"
        )
    root_fields = (
        "coherent_capture_root",
        "rule_contract_root",
        "live_issue_projection_root",
        "lint_issue_ids_root",
        "independent_finding_issue_ids_root",
        "nonclosed_issue_ids_root",
        "selected_review_issue_ids_root",
    )
    if any(
        not isinstance(observation[field], str)
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            observation[field],
        )
        is None
        for field in root_fields
    ):
        raise InputRefused("v2 source observation contains a malformed root")
    v2_validate_source_capture_contract(
        capture_contract,
        audit_capture=captured["audit_capture"],
        coherent_capture_root=observation["coherent_capture_root"],
    )
    observed_source_paths: list[str] = []
    for index, identity in enumerate(source_files):
        if not isinstance(identity, dict):
            raise InputRefused(
                f"v2 source observation source file {index} is malformed"
            )
        v2_exact_keys(
            identity,
            {"path", "bytes", "content_identity"},
            label=f"v2 source observation source file {index}",
        )
        if (
            not isinstance(identity["path"], str)
            or type(identity["bytes"]) is not int
            or identity["bytes"] < 0
            or not isinstance(identity["content_identity"], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                identity["content_identity"],
            )
            is None
        ):
            raise InputRefused(
                f"v2 source observation source file {index} is malformed"
            )
        try:
            canonical_path = str(
                safe_relative(
                    identity["path"],
                    label=f"v2 source observation source file {index}",
                )
            )
        except UsageRefused as error:
            raise InputRefused(
                f"v2 source observation source file {index} path is unsafe"
            ) from error
        if canonical_path != identity["path"]:
            raise InputRefused(
                f"v2 source observation source file {index} path is noncanonical"
            )
        observed_source_paths.append(canonical_path)
    if len(observed_source_paths) != len(set(observed_source_paths)):
        raise InputRefused("v2 source observation duplicates a source file")
    if observed_source_paths != [
        str(SCRIPT_REL),
        str(CASE_MANIFEST_REL),
        str(CASE_MANIFEST_V2_REL),
    ]:
        raise InputRefused(
            "v2 source observation source-file membership or order differs"
        )
    current_source_files = v2_source_file_identities()
    expected_source_files = [
        current_source_files[0],
        current_source_files[1],
        {
            **current_source_files[2],
            "content_identity": manifest["content_identity"],
        },
    ]
    if (
        source_files != expected_source_files
        or source_files[1]["content_identity"]
        != source["v1_baseline"].get("v1_manifest_content_root")
        or source_files[2]["content_identity"]
        != observation["case_manifest_content_identity"]
    ):
        raise EvidenceFailed(
            "v2 source observation source-file identities are not bound to "
            "the executing harness and retained manifest baselines"
        )
    normalized_tracker_status = v2_normalize_br_status(
        observation["tracker_status"],
        error_type=InputRefused,
    )
    normalized_sync_status = v2_normalize_br_sync_status(
        observation["sync_status"],
        error_type=InputRefused,
    )
    normalized_export_witness = v2_normalize_br_export_witness(
        observation["export_witness"],
        error_type=InputRefused,
    )
    if (
        observation["tracker_status"] != normalized_tracker_status
        or observation["sync_status"] != normalized_sync_status
        or observation["export_witness"] != normalized_export_witness
    ):
        raise InputRefused(
            "v2 source observation br envelopes are not canonically normalized"
        )
    v2_validate_live_envelope_consistency(
        tracker_status=normalized_tracker_status,
        sync_status=normalized_sync_status,
        export_witness=normalized_export_witness,
        full_issues=all_issues,
        error_type=InputRefused,
    )
    observation_receipts = v2_validate_source_command_receipts(
        observation,
        issue_ids=[row["id"] for row in all_issues],
    )
    v1_inventory_rows = captured["v1_inventory_projection"].get("rows")
    if (
        not isinstance(v1_inventory_rows, list)
        or len(v1_inventory_rows) > V2_INVENTORY_ROWS_CAP
        or any(
            not isinstance(row, dict)
            or not isinstance(row.get("id"), str)
            or not row["id"]
            for row in v1_inventory_rows
        )
    ):
        raise InputRefused(
            "v2 source v1 inventory rows are malformed"
        )
    v1_inventory_ids = [row["id"] for row in v1_inventory_rows]
    if (
        v1_inventory_ids != sorted(v1_inventory_ids)
        or len(v1_inventory_ids) != len(set(v1_inventory_ids))
    ):
        raise InputRefused(
            "v2 source v1 inventory membership is noncanonical"
        )
    expected_lint_ids = sorted(lint_ids)
    expected_independent_ids = sorted(independent_findings)
    expected_nonclosed_ids = sorted(
        row["id"] for row in all_issues if row["status"] != "closed"
    )
    expected_finding_ids = set(expected_lint_ids) | set(
        expected_independent_ids
    )
    expected_selected_ids = sorted(
        set(expected_nonclosed_ids) | expected_finding_ids
    )
    expected_closed_finding_ids = (
        expected_finding_ids - set(expected_nonclosed_ids)
    )
    observation_counts = {
        "live_issue_count": len(all_issues),
        "selected_review_issue_count": len(expected_selected_ids),
        "nonclosed_issue_count": len(expected_nonclosed_ids),
        "closed_finding_issue_count": len(expected_closed_finding_ids),
    }
    if (
        observation["case_manifest_root"] != manifest["semantic_root"]
        or observation["case_manifest_content_identity"]
        != manifest["content_identity"]
        or observation["live_issue_projection_root"]
        != semantic_root(all_issues)
        or observation["lint_issue_ids_root"]
        != semantic_root(expected_lint_ids)
        or observation["independent_finding_issue_ids_root"]
        != semantic_root(expected_independent_ids)
        or observation["nonclosed_issue_ids_root"]
        != semantic_root(expected_nonclosed_ids)
        or observation["selected_review_issue_ids_root"]
        != semantic_root(expected_selected_ids)
        or observation["status_cut"] != list(STATUS_SCOPES)
        or v1_inventory_ids != expected_selected_ids
        or any(
            type(observation[field]) is not int
            or observation[field] != expected
            for field, expected in observation_counts.items()
        )
    ):
        raise EvidenceFailed(
            "v2 source observation membership, manifest, or count bindings "
            "disagree"
        )
    rule_contract = v2_source_rule_contract()
    expected_capture = v2_capture_state(
        issue_ids=sorted(row["id"] for row in all_issues),
        full_issues=all_issues,
        lint=captured["v1_lint_projection"],
        tracker_status=observation["tracker_status"],
        sync_status=observation["sync_status"],
        export_witness=observation["export_witness"],
        version=observation["br_version"],
        capabilities=observation["br_capabilities"],
        source_files=source_files,
        rule_contract=rule_contract,
    )
    if (
        observation["rule_contract_root"] != semantic_root(rule_contract)
        or observation["coherent_capture_root"]
        != expected_capture["semantic_root"]
    ):
        raise EvidenceFailed(
            "v2 source observation coherent-capture or rule-contract root "
            "cannot be reconstructed"
        )
    try:
        expected_v1_inventory = assemble_inventory(
            captured["v1_lint_projection"],
            [all_issue_by_id[issue_id] for issue_id in target_ids],
            observation,
            independent_findings,
            include_issue_rows_without_findings=True,
        )
    except HarnessError:
        raise
    except (
        AttributeError,
        IndexError,
        KeyError,
        TypeError,
        ValueError,
    ) as error:
        raise InputRefused(
            "v2 source v1 inventory projection cannot be reconstructed"
        ) from error
    if expected_v1_inventory != captured["v1_inventory_projection"]:
        divergence = first_projection_divergence(
            expected_v1_inventory,
            captured["v1_inventory_projection"],
        )
        raise EvidenceFailed(
            "v2 source v1 inventory cannot be reconstructed from captured "
            f"inputs at {divergence or '$'}"
        )
    audit_capture = captured["audit_capture"]
    audit_receipts = v2_validate_audit_capture(
        audit_capture,
        allowed_issue_ids={row["id"] for row in all_issues},
    )
    if len(observation_receipts) + len(audit_receipts) > (
        V2_LOG_EVENTS_CAP - 8
    ):
        raise InputRefused(
            "v2 source command receipts exceed the retained event budget"
        )
    if "state" not in audit_capture:
        all_issue_by_id = {row["id"]: row for row in all_issues}
        priority_filter = set(filters["priorities"])
        status_filter = set(filters["statuses"])
        target_filter = set(filters["targets"])
        expected_audit_ids = {
            issue_id
            for issue_id in v1_inventory_ids
            if issue_id in all_issue_by_id
            and all_issue_by_id[issue_id]["status"] == "closed"
            and (
                not priority_filter
                or f"P{all_issue_by_id[issue_id]['priority']}"
                in priority_filter
            )
            and (
                not status_filter
                or all_issue_by_id[issue_id]["status"] in status_filter
            )
            and (
                not target_filter
                or issue_id in target_filter
            )
        }
        expected_audit_ids.add(
            str(
                contracts["history"][
                    "legacy_coverage_anchor_issue"
                ]
            )
        )
        if audit_capture["issue_ids"] != sorted(expected_audit_ids):
            raise InputRefused(
                "v2 source audit capture membership differs from the selected "
                "closed/history universe"
            )
    documents = audit_capture.get("documents")
    if not isinstance(documents, list):
        raise EvidenceFailed("v2 source audit capture is malformed")
    audit_ids: list[str] = []
    for index, document in enumerate(documents):
        if not isinstance(document, dict):
            raise EvidenceFailed(f"v2 source audit row {index} is malformed")
        issue_id = str(document.get("issue_id") or "")
        try:
            normalized = v2_normalize_audit_document(
                {"issue_id": issue_id, "events": document.get("events")},
                issue_id=issue_id,
            )
        except InfrastructureFailed as error:
            raise InputRefused(
                f"v2 retained source audit row {index} is malformed"
            ) from error
        if normalized != document:
            raise EvidenceFailed(
                f"v2 source audit row {index} differs from strict normalization"
            )
        audit_ids.append(issue_id)
    v2_assert_unique(audit_ids, label="v2 source audit IDs")
    verify_semantic_root(source, label="source-v2.json")


def v2_validate_source_manifest_anchor(
    source: Mapping[str, Any],
    accepted_manifest: Mapping[str, Any],
) -> None:
    retained = source.get("manifest")
    if not isinstance(retained, dict):
        raise EvidenceFailed("v2 source lacks a retained manifest identity")
    if (
        retained.get("semantic_root") != accepted_manifest.get("semantic_root")
        or retained.get("content_identity")
        != accepted_manifest.get("content_identity")
        or retained.get("harness_contract_identity")
        != accepted_manifest.get("harness_contract_identity")
        or retained.get("case_count") != accepted_manifest.get("case_count")
        or retained.get("assertion_count")
        != accepted_manifest.get("assertion_count")
        or retained.get("criterion_count")
        != accepted_manifest.get("criterion_count")
    ):
        raise EvidenceFailed(
            "v2 retained manifest identity differs from the accepted trust anchor"
        )
    expected_contracts = {
        "source": dict(accepted_manifest["source_contract"]),
        "row": dict(accepted_manifest["row_contract"]),
        "authority": dict(accepted_manifest["authority_contract"]),
        "packing": dict(accepted_manifest["packing_contract"]),
        "history": dict(accepted_manifest["history_contract"]),
        "artifact": dict(accepted_manifest["artifact_contract"]),
        "logging": dict(accepted_manifest["logging_contract"]),
        "replay": dict(accepted_manifest["replay_contract"]),
        "caps": dict(accepted_manifest["caps"]),
    }
    if source.get("contracts") != expected_contracts:
        raise EvidenceFailed(
            "v2 retained contracts differ from the accepted manifest"
        )
    if source.get("v1_baseline") != accepted_manifest.get(
        "compatibility_contract"
    ):
        raise EvidenceFailed(
            "v2 retained v1 baseline differs from the accepted manifest"
        )


def v2_read_retained_bundle(
    *,
    artifact_root: str,
    input_dir: str,
) -> tuple[Path, dict[str, bytes], dict[str, Any], list[dict[str, Any]]]:
    directory = resolve_run_dir(
        artifact_root,
        input_dir,
        label="v2 replay input",
        must_exist=True,
    )
    if directory.is_symlink() or not directory.is_dir():
        raise InputRefused("v2 replay input is not a safe directory")
    observed_files, observed_directories, file_identities = v2_enumerate_bundle(
        directory
    )
    if "terminal.json" not in file_identities:
        raise InputRefused("v2 replay input lacks terminal.json")
    terminal_payload = v2_read_file_strict(
        directory / "terminal.json",
        label="v2 terminal.json",
        expected_identity=file_identities["terminal.json"],
    )
    terminal = strict_json_loads(
        terminal_payload,
        label="v2 terminal.json",
        require_canonical=True,
    )
    if not isinstance(terminal, dict) or terminal.get("schema") != V2_TERMINAL_SCHEMA:
        raise InputRefused("v2 terminal.json has an unknown schema")
    verify_semantic_root(terminal, label="terminal.json")
    registry = terminal.get("optional_content_registry")
    if not isinstance(registry, list):
        raise EvidenceFailed("v2 terminal optional registry is malformed")
    optional_paths: list[str] = []
    for index, entry in enumerate(registry):
        if not isinstance(entry, dict):
            raise EvidenceFailed(f"v2 terminal optional row {index} is malformed")
        optional_paths.append(
            v2_safe_member(
                str(entry.get("relative_path") or ""),
                label=f"v2 terminal optional row {index}",
            )
        )
    v2_assert_unique(optional_paths, label="v2 terminal optional paths")
    expected_files = sorted(
        [*V2_RUN_ARTIFACTS, *optional_paths],
        key=lambda value: value.encode("utf-8"),
    )
    if observed_files != expected_files:
        missing = sorted(set(expected_files) - set(observed_files))
        extra = sorted(set(observed_files) - set(expected_files))
        first = (missing or extra or ["membership"])[0]
        raise InputRefused(
            f"v2 replay first divergence at {first}: missing={missing[:1]} extra={extra[:1]}"
        )
    expected_directory_set: set[str] = set()
    for path in optional_paths:
        parent = PurePosixPath(path).parent
        while str(parent) != ".":
            expected_directory_set.add(str(parent))
            parent = parent.parent
    expected_directories = sorted(
        expected_directory_set,
        key=lambda value: value.encode("utf-8"),
    )
    if observed_directories != expected_directories:
        raise InputRefused("v2 replay contains an unlisted directory")
    payloads = {
        name: v2_read_file_strict(
            directory.joinpath(*PurePosixPath(name).parts),
            label=f"v2 artifact {name}",
            expected_identity=file_identities[name],
        )
        for name in observed_files
    }
    if payloads["terminal.json"] != terminal_payload:
        raise InputRefused("v2 terminal changed between strict reads")
    expected_terminal = terminal.get("terminal")
    if not isinstance(expected_terminal, str) or expected_terminal not in TERMINAL_EXIT:
        raise EvidenceFailed("v2 terminal names an unknown terminal state")
    events = v2_read_event_stream(
        payloads["events.jsonl"],
        expected_terminal=expected_terminal,
    )
    return directory, payloads, terminal, events


def v2_validate_refusal_bundle(
    *,
    artifact_root: str,
    input_dir: str,
    payloads: Mapping[str, bytes],
    terminal: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    accepted_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    terminal_fields = {
        "schema",
        "mode",
        "subject_mode",
        "bundle_state",
        "terminal",
        "exit_code",
        "artifact_root",
        "artifact_dir",
        "base_artifacts",
        "safe_relative_artifacts",
        "artifact_identities",
        "optional_content_registry",
        "manifest_root",
        "manifest_content_identity",
        "source_root",
        "inventory_root",
        "authority_root",
        "review_plan_root",
        "history_root",
        "zero_sets_root",
        "events_content_root",
        "event_count",
        "event_sequence",
        "event_roots",
        "terminal_event_root",
        "reproduction",
        "replay_equivalence",
        "failure_evidence",
        "failure_root",
        "first_divergence",
        "recovery",
        "complete_evidence_bundle",
        "complete_green_prefix",
        "retry_requires_fresh_run_dir",
        "no_claim",
        "semantic_root",
    }
    v2_exact_keys(
        terminal,
        terminal_fields,
        label="v2 refusal terminal",
    )
    verify_semantic_root(terminal, label="v2 refusal terminal")
    terminal_name = terminal["terminal"]
    expected_recovery = {
        "InputRefused": "CORRECT_INPUT_AND_RETRY_IN_FRESH_RUN_DIR",
        "NoData": "PROVIDE_REQUIRED_DATA_AND_RETRY_IN_FRESH_RUN_DIR",
        "EvidenceFailed": "MANUAL_RECOVERY_REQUIRED",
    }.get(terminal_name)
    expected_terminal_no_claim = (
        "the complete non-green seal proves only a typed semantic "
        "refusal and can never be promoted or replayed as Pass"
    )
    if (
        terminal["schema"] != V2_TERMINAL_SCHEMA
        or terminal["bundle_state"] != "COMPLETE_NON_GREEN"
        or terminal_name not in V2_SEMANTIC_REFUSAL_TERMINALS
        or terminal["exit_code"] != TERMINAL_EXIT[terminal_name]
        or terminal["mode"] not in {"review-plan", "history-plan"}
        or terminal["subject_mode"] != terminal["mode"]
        or terminal["artifact_root"]
        != str(safe_relative(artifact_root, label="artifact root"))
        or terminal["artifact_dir"]
        != str(safe_relative(input_dir, label="artifact dir"))
        or terminal["base_artifacts"] != list(V2_RUN_ARTIFACTS)
        or terminal["safe_relative_artifacts"] != list(V2_RUN_ARTIFACTS)
        or terminal["optional_content_registry"] != []
        or terminal["manifest_root"] != accepted_manifest["semantic_root"]
        or terminal["manifest_content_identity"]
        != accepted_manifest["content_identity"]
        or terminal["complete_evidence_bundle"] is not True
        or terminal["complete_green_prefix"] is not False
        or terminal["retry_requires_fresh_run_dir"] is not True
        or terminal["replay_equivalence"] != {}
        or not isinstance(terminal["first_divergence"], str)
        or not terminal["first_divergence"]
        or terminal["recovery"] != expected_recovery
        or terminal["no_claim"] != expected_terminal_no_claim
    ):
        raise EvidenceFailed("v2 refusal terminal contract differs")
    if set(payloads) != set(V2_RUN_ARTIFACTS):
        raise EvidenceFailed("v2 refusal artifact membership is not exactly nine")
    if payloads["terminal.json"] != canonical_bytes(terminal):
        raise EvidenceFailed("v2 refusal terminal payload differs from its document")
    failure = terminal["failure_evidence"]
    if not isinstance(failure, dict):
        raise EvidenceFailed("v2 refusal terminal lacks failure evidence")
    failure_fields = {
        "schema",
        "result_category",
        "stage",
        "terminal",
        "exit_code",
        "diagnostic_code",
        "detail_root",
        "first_divergence",
        "recovery",
        "manifest_root",
        "available_roots",
        "output_reserved",
        "complete_evidence_bundle",
        "complete_green_prefix",
        "retry_requires_fresh_run_dir",
        "no_claim",
        "semantic_root",
    }
    v2_exact_keys(failure, failure_fields, label="v2 failure evidence")
    verify_semantic_root(failure, label="v2 failure evidence")
    expected_failure_no_claim = (
        "failure evidence identifies recovery work and never seals a "
        "partial or ambiguous publication as green"
    )
    available_roots = failure["available_roots"]
    expected_available_root_keys = {
        "source",
        "inventory",
        "authority",
        "review_plan",
        "history",
        "zero_sets",
    }
    if (
        failure["schema"] != V2_FAILURE_EVIDENCE_SCHEMA
        or failure["result_category"] != "SEMANTIC_REFUSAL"
        or failure["terminal"] != terminal_name
        or failure["exit_code"] != terminal["exit_code"]
        or failure["diagnostic_code"]
        != f"{terminal_name}:{failure['stage']}"
        or failure["manifest_root"] != accepted_manifest["semantic_root"]
        or failure["semantic_root"] != terminal["failure_root"]
        or failure["first_divergence"] != terminal["first_divergence"]
        or failure["recovery"] != expected_recovery
        or not isinstance(available_roots, dict)
        or set(available_roots) != expected_available_root_keys
        or any(
            value is not None
            and (
                not isinstance(value, str)
                or not value.startswith("sha256-v1:")
            )
            for value in available_roots.values()
        )
        or failure["output_reserved"] is not True
        or failure["complete_evidence_bundle"] is not True
        or failure["complete_green_prefix"] is not False
        or failure["retry_requires_fresh_run_dir"] is not True
        or failure["no_claim"] != expected_failure_no_claim
    ):
        raise EvidenceFailed("v2 refusal failure bindings disagree")
    projection_names = {
        "source-v2.json": ("source", V2_SOURCE_SCHEMA, "source_root"),
        "inventory-v2.json": (
            "inventory",
            V2_INVENTORY_SCHEMA,
            "inventory_root",
        ),
        "authority-v2.json": (
            "authority",
            V2_AUTHORITY_SCHEMA,
            "authority_root",
        ),
        "review-plan-v2.json": (
            "review-plan",
            V2_REVIEW_PLAN_SCHEMA,
            "review_plan_root",
        ),
        "history-v2.json": (
            "history",
            V2_HISTORY_SCHEMA,
            "history_root",
        ),
        "zero-sets-v2.json": (
            "zero-sets",
            V2_ZERO_SETS_SCHEMA,
            "zero_sets_root",
        ),
    }
    envelope_fields = {
        "schema",
        "artifact_name",
        "projection",
        "expected_success_schema",
        "mode",
        "state",
        "manifest_root",
        "failure_root",
        "available_projection_root",
        "complete_green_prefix",
        "no_claim",
        "semantic_root",
    }
    schema_by_name: dict[str, str] = {
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
    }
    for name, (projection, success_schema, terminal_root_field) in (
        projection_names.items()
    ):
        document = strict_json_loads(
            payloads[name],
            label=f"v2 refusal artifact {name}",
            require_canonical=True,
        )
        if not isinstance(document, dict):
            raise EvidenceFailed(f"v2 refusal artifact {name} is not an object")
        v2_exact_keys(
            document,
            envelope_fields,
            label=f"v2 refusal artifact {name}",
        )
        verify_semantic_root(document, label=f"v2 refusal artifact {name}")
        expected_envelope_no_claim = (
            "this closed refusal envelope is complete failure evidence "
            "and is not a successful planner projection"
        )
        available_key = {
            "source": "source",
            "inventory": "inventory",
            "authority": "authority",
            "review-plan": "review_plan",
            "history": "history",
            "zero-sets": "zero_sets",
        }[projection]
        if (
            document["schema"] != V2_REFUSAL_PROJECTION_SCHEMA
            or document["artifact_name"] != name
            or document["projection"] != projection
            or document["expected_success_schema"] != success_schema
            or document["mode"] != terminal["subject_mode"]
            or document["state"] != "REFUSED"
            or document["manifest_root"] != accepted_manifest["semantic_root"]
            or document["failure_root"] != failure["semantic_root"]
            or document["available_projection_root"]
            != available_roots[available_key]
            or document["complete_green_prefix"] is not False
            or document["no_claim"] != expected_envelope_no_claim
            or terminal[terminal_root_field] != document["semantic_root"]
        ):
            raise EvidenceFailed(
                f"v2 refusal envelope bindings disagree for {name}"
            )
        schema_by_name[name] = V2_REFUSAL_PROJECTION_SCHEMA
    reproduction = strict_json_loads(
        payloads["reproduce.txt"],
        label="v2 refusal reproduce.txt",
        require_canonical=True,
    )
    if (
        not isinstance(reproduction, list)
        or not all(isinstance(value, str) for value in reproduction)
        or reproduction != terminal["reproduction"]
    ):
        raise EvidenceFailed("v2 refusal reproduction binding differs")
    expected_identity_names = set(payloads) - {"terminal.json"}
    if set(terminal["artifact_identities"]) != expected_identity_names:
        raise EvidenceFailed("v2 refusal artifact identity membership differs")
    for name in sorted(expected_identity_names):
        expected_identity = v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        if terminal["artifact_identities"][name] != expected_identity:
            raise EvidenceFailed(
                f"v2 refusal artifact identity differs for {name}"
            )
    expected_events = v2_refusal_event_rows(
        mode=terminal["mode"],
        terminal_name=terminal_name,
        failure=failure,
        reproduction=reproduction,
    )
    if list(events) != expected_events:
        raise EvidenceFailed("v2 refusal events differ from exact reconstruction")
    expected_event_payload = b"".join(
        canonical_bytes(row) for row in expected_events
    )
    if (
        payloads["events.jsonl"] != expected_event_payload
        or terminal["event_count"] != len(expected_events)
        or terminal["event_sequence"] != list(range(len(expected_events)))
        or terminal["event_roots"]
        != [semantic_root(row) for row in expected_events]
        or terminal["terminal_event_root"] != semantic_root(expected_events[-1])
        or terminal["events_content_root"]
        != "sha256-v1:" + hashlib.sha256(expected_event_payload).hexdigest()
    ):
        raise EvidenceFailed("v2 refusal event seal differs")
    return v2_rooted(
        {
            "schema": V2_REFUSAL_RESULT_SCHEMA,
            "terminal": terminal_name,
            "exit_code": terminal["exit_code"],
            "subject_mode": terminal["subject_mode"],
            "terminal_root": terminal["semantic_root"],
            "failure_root": failure["semantic_root"],
            "first_divergence": terminal["first_divergence"],
            "recovery": terminal["recovery"],
            "complete_evidence_bundle": True,
            "complete_green_prefix": False,
            "replay_validated_without_output": True,
            "no_claim": (
                "offline validation preserves the retained non-green result "
                "and cannot mint Pass or current tracker authority"
            ),
        }
    )


def v2_reconstruct_retained(
    *,
    artifact_root: str,
    input_dir: str,
    payloads: Mapping[str, bytes],
    terminal: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    accepted_manifest: Mapping[str, Any] | None = None,
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, bytes],
]:
    terminal_fields = {
        "schema",
        "mode",
        "subject_mode",
        "bundle_state",
        "terminal",
        "exit_code",
        "artifact_root",
        "artifact_dir",
        "base_artifacts",
        "safe_relative_artifacts",
        "artifact_identities",
        "optional_content_registry",
        "manifest_root",
        "source_root",
        "inventory_root",
        "authority_root",
        "review_plan_root",
        "history_root",
        "zero_sets_root",
        "events_content_root",
        "event_count",
        "event_sequence",
        "event_roots",
        "terminal_event_root",
        "reproduction",
        "replay_equivalence",
        "first_divergence",
        "recovery",
        "complete_evidence_bundle",
        "complete_green_prefix",
        "retry_requires_fresh_run_dir",
        "no_claim",
        "semantic_root",
    }
    v2_exact_keys(
        terminal,
        terminal_fields,
        label="v2 retained green terminal",
    )
    verify_semantic_root(terminal, label="v2 retained green terminal")
    registry = terminal.get("optional_content_registry")
    if not isinstance(registry, list):
        raise EvidenceFailed("v2 retained optional registry is malformed")
    optional_paths: list[str] = []
    for index, entry in enumerate(registry):
        if not isinstance(entry, dict):
            raise EvidenceFailed(
                f"v2 retained optional registry row {index} is malformed"
            )
        optional_paths.append(
            v2_safe_member(
                str(entry.get("relative_path") or ""),
                label=f"v2 retained optional registry row {index}",
            )
        )
    v2_assert_unique(
        optional_paths,
        label="v2 retained optional registry paths",
    )
    if any(path in V2_RUN_ARTIFACTS for path in optional_paths):
        raise EvidenceFailed("v2 retained optional registry shadows a base artifact")
    expected_payload_names = set(V2_RUN_ARTIFACTS) | set(optional_paths)
    if set(payloads) != expected_payload_names:
        raise EvidenceFailed("v2 reconstructed artifact membership differs")
    expected_safe_artifacts = sorted(
        expected_payload_names,
        key=lambda value: value.encode("utf-8"),
    )
    expected_terminal_no_claim = (
        "the final seal proves deterministic bundle construction only; "
        "it does not prove current state on replay or mint any authority"
    )
    if (
        terminal.get("schema") != V2_TERMINAL_SCHEMA
        or terminal.get("bundle_state") != "COMPLETE_GREEN"
        or terminal.get("terminal") != "Pass"
        or terminal.get("exit_code") != 0
        or terminal.get("mode")
        not in {terminal.get("subject_mode"), "replay"}
        or terminal.get("subject_mode")
        not in {"review-plan", "history-plan"}
        or terminal.get("artifact_root")
        != str(safe_relative(artifact_root, label="artifact root"))
        or terminal.get("artifact_dir")
        != str(safe_relative(input_dir, label="artifact dir"))
        or terminal.get("base_artifacts") != list(V2_RUN_ARTIFACTS)
        or terminal.get("safe_relative_artifacts")
        != expected_safe_artifacts
        or terminal.get("complete_evidence_bundle") is not True
        or terminal.get("complete_green_prefix") is not True
        or terminal.get("first_divergence") is not None
        or terminal.get("recovery") != "NOT_REQUIRED"
        or terminal.get("retry_requires_fresh_run_dir") is not False
        or terminal.get("no_claim") != expected_terminal_no_claim
    ):
        raise EvidenceFailed(
            "v2 retained reconstruction requires an explicit complete-green seal"
        )
    documents: dict[str, dict[str, Any]] = {}
    schemas = {
        "source-v2.json": V2_SOURCE_SCHEMA,
        "inventory-v2.json": V2_INVENTORY_SCHEMA,
        "authority-v2.json": V2_AUTHORITY_SCHEMA,
        "review-plan-v2.json": V2_REVIEW_PLAN_SCHEMA,
        "history-v2.json": V2_HISTORY_SCHEMA,
        "zero-sets-v2.json": V2_ZERO_SETS_SCHEMA,
    }
    for name, schema in schemas.items():
        document = strict_json_loads(
            payloads[name],
            label=f"v2 artifact {name}",
            require_canonical=True,
        )
        if not isinstance(document, dict) or document.get("schema") != schema:
            raise InputRefused(f"v2 artifact {name} has an unknown schema")
        verify_semantic_root(document, label=name)
        documents[name] = document
    source = documents["source-v2.json"]
    retained_inventory = documents["inventory-v2.json"]
    retained_authority = documents["authority-v2.json"]
    retained_review = documents["review-plan-v2.json"]
    retained_history = documents["history-v2.json"]
    retained_zero = documents["zero-sets-v2.json"]
    v2_validate_source_document(source)
    accepted = (
        accepted_manifest
        if accepted_manifest is not None
        else load_case_manifest_v2()
    )
    v2_validate_source_manifest_anchor(source, accepted)
    reproduction = strict_json_loads(
        payloads["reproduce.txt"],
        label="v2 reproduce.txt",
        require_canonical=True,
    )
    if not isinstance(reproduction, list) or not all(
        isinstance(value, str) for value in reproduction
    ):
        raise EvidenceFailed("v2 reproduce.txt is not an argv array")

    roots = {
        "manifest_root": source["manifest"]["semantic_root"],
        "source_root": source["semantic_root"],
        "inventory_root": retained_inventory["semantic_root"],
        "authority_root": retained_authority["semantic_root"],
        "review_plan_root": retained_review["semantic_root"],
        "history_root": retained_history["semantic_root"],
        "zero_sets_root": retained_zero["semantic_root"],
    }
    for field, expected in roots.items():
        if terminal.get(field) != expected:
            raise EvidenceFailed(f"v2 terminal root differs at {field}")
    if (
        terminal.get("event_count") != len(events)
        or terminal.get("event_sequence") != list(range(len(events)))
        or terminal.get("event_roots")
        != [semantic_root(row) for row in events]
        or terminal.get("terminal_event_root") != semantic_root(events[-1])
        or terminal.get("events_content_root")
        != "sha256-v1:" + hashlib.sha256(payloads["events.jsonl"]).hexdigest()
        or terminal.get("reproduction") != reproduction
    ):
        raise EvidenceFailed("v2 terminal event/reproduction seal differs")

    registry_by_path = {
        row["relative_path"]: row
        for row in terminal["optional_content_registry"]
    }
    schema_by_name = {
        **schemas,
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
        **{
            path: row["schema_kind"] for path, row in registry_by_path.items()
        },
    }
    expected_identity_names = set(payloads) - {"terminal.json"}
    if set(terminal.get("artifact_identities", {})) != expected_identity_names:
        raise EvidenceFailed("v2 terminal artifact identity membership differs")
    for name in sorted(expected_identity_names):
        expected_identity = v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        if terminal["artifact_identities"][name] != expected_identity:
            raise EvidenceFailed(f"v2 artifact identity differs for {name}")

    snapshot = v2_snapshot_from_source(source)
    campaign_root, _ = v2_campaign_epoch(snapshot)
    if campaign_root != source["campaign_epoch_root"]:
        raise EvidenceFailed("v2 retained campaign root cannot be reconstructed")
    filters = source["captured"]["filters"]
    priority_filter = set(filters["priorities"]) or None
    status_filter = set(filters["statuses"]) or None
    target_filter = set(filters["targets"]) or None
    readiness_filter = set(filters["readiness"]) or None
    route_filter = set(filters["routes"]) or None
    inventory = v2_build_inventory(
        snapshot,
        campaign_epoch_root=campaign_root,
        priority_filter=priority_filter,
        status_filter=status_filter,
        target_filter=target_filter,
        readiness_filter=readiness_filter,
        route_filter=route_filter,
    )
    authority = v2_derive_authority(
        inventory,
        source["captured"]["review_receipts"],
        current_br_version=str(
            source["captured"]["observation"]["br_version"]["version"]
        ),
    )
    v2_validate_zero_sets(
        retained_zero,
        source_root=source["semantic_root"],
        inventory=inventory,
        prior_campaign=source["captured"]["prior_campaign"],
        current_universe=snapshot.all_issues,
        current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
    )
    subject_mode = str(terminal.get("subject_mode") or terminal.get("mode") or "")
    if subject_mode == "review-plan":
        review, optional_payloads = v2_build_review_plan(
            inventory,
            authority,
            max_targets=int(retained_review["max_targets_per_child"]),
        )
        history = v2_not_requested(
            schema=V2_HISTORY_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="history",
        )
    elif subject_mode == "history-plan":
        review = v2_not_requested(
            schema=V2_REVIEW_PLAN_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="review-plan",
        )
        optional_payloads = {}
        history = v2_build_history(
            source_root=source["semantic_root"],
            inventory=inventory,
            authority=authority,
            all_issues=snapshot.all_issues,
            audit_capture=source["captured"]["audit_capture"],
            history_contract=source["contracts"]["history"],
        )
    else:
        raise EvidenceFailed("v2 terminal subject mode is unknown")
    zero_sets = v2_build_zero_sets(
        source_root=source["semantic_root"],
        inventory=inventory,
        prior_campaign=source["captured"]["prior_campaign"],
        current_universe=snapshot.all_issues,
        current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
    )
    reconstructed = v2_bundle_payloads(
        mode=str(terminal["mode"]),
        subject_mode=subject_mode,
        artifact_root=artifact_root,
        artifact_dir=input_dir,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review,
        history=history,
        zero_sets=zero_sets,
        optional_payloads=optional_payloads,
        reproduction=reproduction,
        replay_equivalence=terminal.get("replay_equivalence") or {},
    )
    if set(reconstructed) != set(payloads):
        raise EvidenceFailed("v2 reconstructed artifact membership differs")
    for name in sorted(reconstructed):
        if reconstructed[name] != payloads[name]:
            raise EvidenceFailed(f"v2 replay first byte divergence in {name}")
    return (
        source,
        inventory,
        authority,
        review,
        history,
        zero_sets,
        optional_payloads,
    )


def v2_validate_replay_result_document(
    document: Mapping[str, Any],
) -> None:
    if (
        not isinstance(document, dict)
        or set(document) != V2_REPLAY_RESULT_FIELDS
    ):
        raise EvidenceFailed("v2 replay result has a non-closed schema")
    try:
        artifact_dir = safe_relative(
            document["artifact_dir"],
            label="v2 replay result artifact directory",
        )
    except (TypeError, UsageRefused) as error:
        raise EvidenceFailed(
            "v2 replay result artifact directory is unsafe"
        ) from error
    roots = (
        document["retained_terminal_root"],
        document["replay_terminal_root"],
    )
    if (
        document["schema"] != V2_REPLAY_RESULT_SCHEMA
        or document["terminal"] != "Pass"
        or not isinstance(document["subject_mode"], str)
        or document["subject_mode"] not in {"review-plan", "history-plan"}
        or str(artifact_dir) != document["artifact_dir"]
        or any(
            not isinstance(root, str)
            or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", root) is None
            for root in roots
        )
        or document["live_tracker_reads"] is not False
        or document["live_tracker_writes"] is not False
        or document["network_access"] is not False
        or document["no_claim"] != V2_REPLAY_RESULT_NO_CLAIM
    ):
        raise EvidenceFailed("v2 replay result contract differs")
    verify_semantic_root(document, label="v2 replay result")


def _v2_replay_bundle_offline(
    *,
    artifact_root: str,
    input_dir: str,
    output_dir: str,
    accepted_manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    source_directory, retained_payloads, terminal, events = (
        v2_read_retained_bundle(
            artifact_root=artifact_root,
            input_dir=input_dir,
        )
    )
    accepted_manifest = (
        load_case_manifest_v2()
        if accepted_manifest is None
        else v2_clone_runner_manifest(accepted_manifest)
    )
    if terminal.get("bundle_state") == "COMPLETE_NON_GREEN":
        result = v2_validate_refusal_bundle(
            artifact_root=artifact_root,
            input_dir=input_dir,
            payloads=retained_payloads,
            terminal=terminal,
            events=events,
            accepted_manifest=accepted_manifest,
        )
        raise PublishedV2Refusal(
            terminal=str(result["terminal"]),
            document=result,
        )
    if terminal.get("bundle_state") != "COMPLETE_GREEN":
        raise EvidenceFailed("v2 replay bundle state is unknown")
    output_directory = resolve_run_dir(
        artifact_root,
        output_dir,
        label="v2 replay output",
    )
    source_resolved = source_directory.resolve(strict=True)
    output_resolved = output_directory.resolve(strict=False)
    if (
        source_resolved == output_resolved
        or source_resolved in output_resolved.parents
        or output_resolved in source_resolved.parents
    ):
        raise InputRefused("v2 replay input and output must be disjoint")
    (
        source,
        inventory,
        authority,
        review,
        history,
        zero_sets,
        optional_payloads,
    ) = v2_reconstruct_retained(
        artifact_root=artifact_root,
        input_dir=input_dir,
        payloads=retained_payloads,
        terminal=terminal,
        events=events,
        accepted_manifest=accepted_manifest,
    )
    reproduction = v2_reproduction_argv(
        mode="replay",
        artifact_root=artifact_root,
        artifact_dir=output_dir,
        replay_input=input_dir,
    )
    replay_equivalence = {
        "retained_terminal_root": terminal["semantic_root"],
        "retained_source_root": source["semantic_root"],
        "retained_inventory_root": inventory["semantic_root"],
        "retained_authority_root": authority["semantic_root"],
        "retained_review_plan_root": review["semantic_root"],
        "retained_history_root": history["semantic_root"],
        "retained_zero_sets_root": zero_sets["semantic_root"],
        "retained_events_content_root": terminal["events_content_root"],
        "live_tracker_reads": False,
        "live_tracker_writes": False,
        "network_access": False,
    }
    replay_payloads = v2_bundle_payloads(
        mode="replay",
        subject_mode=terminal["subject_mode"],
        artifact_root=artifact_root,
        artifact_dir=output_dir,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review,
        history=history,
        zero_sets=zero_sets,
        optional_payloads=optional_payloads,
        reproduction=reproduction,
        replay_equivalence=replay_equivalence,
    )
    publication = v2_publish_bundle(
        artifact_root=artifact_root,
        artifact_dir=output_dir,
        payloads=replay_payloads,
    )
    result = v2_rooted(
        {
            "schema": V2_REPLAY_RESULT_SCHEMA,
            "terminal": "Pass",
            "subject_mode": terminal["subject_mode"],
            "artifact_dir": publication["artifact_dir"],
            "retained_terminal_root": terminal["semantic_root"],
            "replay_terminal_root": strict_json_loads(
                replay_payloads["terminal.json"],
                label="v2 replay terminal",
                require_canonical=True,
            )["semantic_root"],
            "live_tracker_reads": False,
            "live_tracker_writes": False,
            "network_access": False,
            "no_claim": V2_REPLAY_RESULT_NO_CLAIM,
        }
    )
    v2_validate_replay_result_document(result)
    return result


def v2_replay_bundle(
    *,
    artifact_root: str,
    input_dir: str,
    output_dir: str,
    accepted_manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    with v2_offline_replay_scope():
        result = _v2_replay_bundle_offline(
            artifact_root=artifact_root,
            input_dir=input_dir,
            output_dir=output_dir,
            accepted_manifest=accepted_manifest,
        )
    v2_validate_replay_result_document(result)
    return result


def peek_replay_schema(artifact_root: str, input_dir: str) -> str:
    directory = resolve_run_dir(
        artifact_root,
        input_dir,
        label="replay input",
        must_exist=True,
    )
    payload = v2_read_file_strict(
        directory / "terminal.json",
        label="replay terminal",
    )
    document = strict_json_loads(payload, label="replay terminal")
    if not isinstance(document, dict) or not isinstance(document.get("schema"), str):
        raise InputRefused("replay terminal does not identify its schema")
    return document["schema"]


def v2_state_projection_value(
    value: Any,
    *,
    seen: set[int] | None = None,
    depth: int = 0,
) -> Any:
    if depth > 32:
        raise EvidenceFailed("refusal-state projection exceeds its depth cap")
    if value is None or type(value) in {bool, int, float, str}:
        return value
    if isinstance(value, (bytes, bytearray, memoryview)):
        payload = (
            value.tobytes()
            if isinstance(value, memoryview)
            else bytes(value)
        )
        return {
            "kind": type(value).__name__,
            "byte_length": len(payload),
            "content_root": "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
        }
    if isinstance(value, Path):
        return {
            "kind": "path",
            "path_root": text_root(str(value)),
        }
    if seen is None:
        seen = set()
    identity = id(value)
    if identity in seen:
        return {"kind": "cycle"}
    seen.add(identity)
    try:
        if isinstance(value, Mapping):
            entries = [
                {
                    "key": v2_state_projection_value(
                        key,
                        seen=seen,
                        depth=depth + 1,
                    ),
                    "value": v2_state_projection_value(
                        item,
                        seen=seen,
                        depth=depth + 1,
                    ),
                }
                for key, item in value.items()
            ]
            entries.sort(key=lambda entry: canonical_bytes(entry["key"]))
            return {"kind": "mapping", "entries": entries}
        if isinstance(value, (list, tuple)):
            return {
                "kind": type(value).__name__,
                "items": [
                    v2_state_projection_value(
                        item,
                        seen=seen,
                        depth=depth + 1,
                    )
                    for item in value
                ],
            }
        if isinstance(value, (set, frozenset)):
            items = [
                v2_state_projection_value(
                    item,
                    seen=seen,
                    depth=depth + 1,
                )
                for item in value
            ]
            items.sort(key=canonical_bytes)
            return {"kind": type(value).__name__, "items": items}
        if isinstance(value, argparse.Namespace):
            return {
                "kind": "argparse.Namespace",
                "attributes": v2_state_projection_value(
                    vars(value),
                    seen=seen,
                    depth=depth + 1,
                ),
            }
        return {
            "kind": "opaque",
            "type": (
                f"{type(value).__module__}.{type(value).__qualname__}"
            ),
        }
    finally:
        seen.remove(identity)


def v2_callback_refusal_projection(
    callback: Callable[[], Any],
    *,
    collector_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    closure_rows: list[dict[str, Any]] = []
    closure = callback.__closure__ or ()
    freevars = callback.__code__.co_freevars
    if len(closure) != len(freevars):
        raise EvidenceFailed("refusal callback closure metadata differs")
    for name, cell in sorted(
        zip(freevars, closure),
        key=lambda pair: pair[0].encode("utf-8"),
    ):
        try:
            value = cell.cell_contents
        except ValueError as error:
            raise EvidenceFailed(
                "refusal callback contains an empty closure cell"
            ) from error
        closure_rows.append(
            {
                "name": name,
                "state": v2_state_projection_value(value),
            }
        )
    global_rows: list[dict[str, Any]] = []
    for name in sorted(
        set(callback.__code__.co_names),
        key=lambda value: value.encode("utf-8"),
    ):
        value = callback.__globals__.get(name)
        if isinstance(value, (dict, list, set, bytearray)):
            global_rows.append(
                {
                    "name": name,
                    "state": v2_state_projection_value(value),
                }
            )
    return {
        "callback_closure": closure_rows,
        "mutable_callback_globals": global_rows,
        "collector_check_roots": [
            row["semantic_root"] for row in collector_rows
        ],
        "command_receipts": list(_command_receipts),
        "cancel_requested": _cancel_requested,
    }


class V2CheckCollector:
    def __init__(self, case_id: str, assertion_id: str) -> None:
        self.case_id = case_id
        self.assertion_id = assertion_id
        self.rows: list[dict[str, Any]] = []

    @staticmethod
    def _bounded(value: Any) -> Any:
        projected = v2_assertion_evidence_projection(value)
        payload = canonical_bytes(projected)
        if len(payload) <= 2_048:
            return projected
        return {
            "projection_root": semantic_root(projected),
            "canonical_bytes": len(payload),
        }

    def check(
        self,
        check_id: str,
        condition: bool,
        *,
        expected: Any,
        observed: Any,
    ) -> None:
        v2_validate_check_id(
            check_id,
            label=f"{self.case_id} emitted check",
        )
        if type(condition) is not bool:
            raise EvidenceFailed(
                f"{self.case_id}/{check_id} produced a non-boolean condition"
            )
        if check_id in {row["check_id"] for row in self.rows}:
            raise EvidenceFailed(
                f"{self.case_id} produced a duplicate or noncanonical check ID"
            )
        if len(self.rows) >= V2_ASSERTION_CHECKS_CAP:
            raise EvidenceFailed(
                f"{self.case_id} exceeds the bounded assertion-check cap"
            )
        row = v2_rooted(
            {
                "check_id": check_id,
                "expected": self._bounded(expected),
                "observed": self._bounded(observed),
                "passed": condition,
            }
        )
        self.rows.append(row)
        if condition is not True:
            raise EvidenceFailed(
                f"{self.case_id}/{check_id} failed: "
                "expected/observed projections retained by root; "
                f"expected_root={semantic_root(row['expected'])}, "
                f"observed_root={semantic_root(row['observed'])}"
            )

    def refuses(
        self,
        check_id: str,
        error_type: type[HarnessError],
        callback: Callable[[], Any],
        *,
        contains: str | None = None,
        projection: Callable[[], Any] | None = None,
        projection_label: str | None = None,
    ) -> None:
        if projection is None:
            projection = lambda: v2_callback_refusal_projection(
                callback,
                collector_rows=self.rows,
            )
            projection_label = "CALLBACK_CLOSURE_AND_HARNESS_STATE"
        elif not projection_label:
            raise EvidenceFailed(
                f"{self.case_id}/{check_id} stateful refusal lacks a projection label"
            )
        before_value = projection()
        before = semantic_root(before_value)
        error = expect_error(error_type, callback, contains=contains)
        after_value = projection()
        after = semantic_root(after_value)
        self.check(
            check_id,
            before == after and error.terminal == error_type.terminal,
            expected={
                "terminal": error_type.terminal,
                "unchanged_projection_root": before,
                "projection_label": projection_label,
            },
            observed={
                "terminal": error.terminal,
                "unchanged_projection_root": after,
                "projection_label": projection_label,
                "diagnostic_root": text_root(str(error)),
                "diagnostic_summary": v2_bounded_diagnostic_summary(error),
            },
        )

    def finish(self, parameters: Mapping[str, Any]) -> dict[str, Any]:
        if not self.rows:
            raise EvidenceFailed(f"{self.case_id} executed no assertion checks")
        document = {
            "schema": V2_ASSERTION_RESULT_SCHEMA,
            "case_id": self.case_id,
            "assertion_id": self.assertion_id,
            "executor_id": self.assertion_id,
            "parameters": dict(parameters),
            "parameter_root": semantic_root(parameters),
            "ordered_checks": self.rows,
            "ordered_check_roots": [row["semantic_root"] for row in self.rows],
            "check_count": len(self.rows),
            "terminal": "Pass",
            "no_claim": V2_ASSERTION_RESULT_NO_CLAIM,
        }
        return v2_rooted(document)


def v2_synthetic_source_issue(
    target: Mapping[str, Any],
) -> dict[str, Any]:
    """Reconstruct the production source shape from a normalized test row."""
    return {
        "id": str(target.get("id") or ""),
        "title": str(target.get("title") or ""),
        "type": str(
            target.get("type") or target.get("issue_type") or ""
        ),
        "status": str(target.get("status") or ""),
        "priority": target.get("priority"),
        "assignee": str(target.get("tracker_assignee") or ""),
        "owner": str(target.get("tracker_owner") or ""),
        "parent": str(target.get("parent") or ""),
        "labels": list(target.get("labels") or []),
        "field_roots": dict(target.get("field_roots") or {}),
        "missing_sections": list(target.get("missing_sections") or []),
        "disposition": str(target.get("disposition") or ""),
        "dependencies": list(target.get("dependencies") or []),
        "dependents": list(target.get("dependents") or []),
    }


def v2_validate_synthetic_target_identity(
    target: Mapping[str, Any],
) -> None:
    source_issue = v2_synthetic_source_issue(target)
    expected_target_root = v2_target_root(source_issue)
    expected_dependency_root = v2_dependency_neighborhood_root(
        source_issue
    )
    if target.get("target_root") != expected_target_root:
        raise EvidenceFailed(
            "synthetic target root differs from the production stable "
            "issue projection"
        )
    if (
        target.get("dependency_neighborhood_root")
        != expected_dependency_root
    ):
        raise EvidenceFailed(
            "synthetic dependency root differs from the production stable "
            "issue projection"
        )


def v2_synthetic_target(
    index: int,
    *,
    issue_id: str | None = None,
    priority: int = 2,
    status: str = "open",
    disposition: str = "SUBSTANTIVE_SEMANTIC_OMISSION",
    issue_type: str = "task",
    missing_sections: Sequence[str] = ("## Acceptance Criteria",),
    readiness_seed: str = "REVIEW_ONLY",
    review_minutes: int = 1,
    retained_payload_bytes: int = 512,
    assignee: str = "",
) -> dict[str, Any]:
    issue_id = issue_id or f"synthetic-{index:04d}"
    field_roots = {
        field: text_root(f"{issue_id}:{field}")
        for field in ("description", "acceptance_criteria", "design", "notes")
    }
    active_context = v2_active_work_context(
        {"status": status, "assignee": assignee}
    )
    target = {
            "id": issue_id,
            "issue_id": issue_id,
            "title": f"Synthetic target {index:04d}",
            "type": issue_type,
            "issue_type": issue_type,
            "status": status,
            "priority": priority,
            "priority_lane": f"P{priority}",
            "status_lane": status,
            "lane": f"P{priority}/{status}",
            "campaign_epoch_root": "",
            "destination": (
                "history-v2.json" if status == "closed" else "review-plan-v2.json"
            ),
            "movement_destination": (
                "history-v2.json" if status == "closed" else "review-plan-v2.json"
            ),
            "tracker_assignee": assignee,
            "coordination_assignee": assignee,
            "tracker_owner": "",
            "parent": "",
            "labels": [],
            "missing_sections": sorted(missing_sections),
            "disposition": disposition,
            "template_warning_state": (
                "PRESENT" if missing_sections else "NONE"
            ),
            "semantic_review_disposition": (
                "BLOCKED_AUTHORITY"
                if not missing_sections
                else "REMEDIATION_REQUIRED"
            ),
            "semantic_review_receipt_state": "UNREVIEWED",
            "semantic_review_dimensions": (
                v2_unreviewed_semantic_dimensions()
            ),
            "semantic_review_receipt_root": None,
            "reviewed_no_change_receipt_root": None,
            "disposition_rationale": "synthetic exact disposition",
            "disposition_falsifier": "a contrary rooted fixture invalidates it",
            "field_roots": field_roots,
            "field_byte_lengths": {
                "description": 32,
                "acceptance_criteria": 32,
                "design": 32,
                "notes": 32,
            },
            "clause_roots": v2_complete_clause_roots(
                {
                    "description": (
                        f"Acceptance clause for synthetic target {issue_id}"
                    ),
                    "acceptance_criteria": "",
                    "design": "",
                    "notes": "",
                }
            ),
            "v1_row_root": semantic_root({"id": issue_id, "v1": True}),
            "dependencies": [],
            "dependents": [],
            "domain_candidates": [],
            "domain_candidate": [],
            "declared_domain_owner": "",
            "declared_acceptance_owner": "",
            "implementation_owner": "UNRESOLVED",
            "evidence_owner": "UNRESOLVED",
            "terminal_consumer": "UNRESOLVED",
            "reviewer_provenance": {
                "state": "NODATA",
                "receipt_root": None,
            },
            "source_closure": {
                "required": False,
                "state": "NOT_REQUIRED_BY_V1_CLASSIFICATION",
            },
            "user_effect": "make exact review debt visible to users",
            "target_implementation_estimated_minutes": 60,
            "target_implementation_estimate_minutes": 60,
            "target_implementation_estimate_state": "DECLARED",
            "review_minutes": review_minutes,
            "generated_child_estimated_minutes": review_minutes,
            "retained_payload_bytes": retained_payload_bytes,
            "external_authority_adapter_identity": "",
            "external_authority_receipt_root": "",
            "external_authority_verdict": "NODATA",
            "conditional_write_capability_identity": "",
            "conditional_write_receipt_root": "",
            "conditional_write_verdict": "NODATA",
            "readiness": readiness_seed,
            "remediation_route": "ANALYSIS_ONLY",
            "active_work_context": active_context,
            "no_claim": "synthetic planning row grants no authority",
        }
    source_issue = v2_synthetic_source_issue(target)
    target["dependency_neighborhood_root"] = (
        v2_dependency_neighborhood_root(source_issue)
    )
    target["target_root"] = v2_target_root(source_issue)
    v2_validate_synthetic_target_identity(target)
    return v2_rooted(target)


def v2_synthetic_inventory(
    targets: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    for row in targets:
        if not isinstance(row, Mapping):
            raise EvidenceFailed(
                "synthetic inventory target is not an object"
            )
        v2_validate_synthetic_target_identity(row)
    campaign_root = semantic_root(
        [
            {"id": row["id"], "target_root": row["target_root"]}
            for row in sorted(targets, key=lambda value: value["id"])
        ]
    )
    rows: list[dict[str, Any]] = []
    for row in sorted(targets, key=lambda value: value["id"]):
        normalized = dict(row)
        normalized.pop("semantic_root", None)
        normalized["campaign_epoch_root"] = campaign_root
        v2_validate_unreviewed_semantic_contract(
            normalized,
            label=f"synthetic inventory target {normalized['id']}",
        )
        rows.append(v2_rooted(normalized))
    return v2_rooted(
        {
            "schema": V2_INVENTORY_SCHEMA,
            "v1_inventory_root": semantic_root({"synthetic": True}),
            "campaign_epoch_root": campaign_root,
            "filters": {
                "priorities": [],
                "statuses": [],
                "targets": [],
                "readiness": [],
                "routes": [],
                "empty_means_all": True,
                "authority_filters_apply_to_selected_projection": True,
            },
            "rows": rows,
            "counts": {
                "targets": len(rows),
                "nonclosed": sum(row["status"] != "closed" for row in rows),
                "history": sum(row["status"] == "closed" for row in rows),
                "warnings": sum(len(row["missing_sections"]) for row in rows),
            },
            "nonclosed_ids_root": semantic_root(
                sorted(row["id"] for row in rows if row["status"] != "closed")
            ),
            "history_ids_root": semantic_root(
                sorted(row["id"] for row in rows if row["status"] == "closed")
            ),
            "no_claim": "synthetic inventory is test evidence only",
        }
    )


def v2_synthetic_semantic_dimension_verdict(
    disposition: str,
    dimension: str,
) -> str:
    if disposition == "REMEDIATION_REQUIRED":
        return "FINDING" if dimension == "user_value" else "SATISFIED"
    if disposition == "REVIEWED_NO_CHANGE":
        return "SATISFIED"
    if disposition not in V2_SEMANTIC_EXACT_SIGNAL_DIMENSION:
        raise EvidenceFailed(
            f"unsupported synthetic semantic disposition {disposition!r}"
        )
    signal_dimension, signal = V2_SEMANTIC_EXACT_SIGNAL_DIMENSION[
        disposition
    ]
    return signal if dimension == signal_dimension else "SATISFIED"


def v2_synthetic_receipts(
    inventory: Mapping[str, Any],
    *,
    compatible: bool = False,
    declared: bool = False,
    manual: bool = False,
    semantic_reviewed: bool = False,
    semantic_disposition: str | None = None,
    external_verdict: str = "NODATA",
    conditional_verdict: str = "NODATA",
    gate_verdict: str = "NODATA",
) -> dict[str, Any]:
    rows = list(inventory["rows"])
    target_ids = sorted(row["id"] for row in rows)
    compatibility_key = "synthetic-compatible" if compatible else ""
    compatibility_root = ""
    if compatible:
        compatibility_root = semantic_root(
            {
                "compatibility_key": compatibility_key,
                "coordination": sorted((row["id"], "") for row in rows),
                "declared_domain": sorted(
                    (row["id"], "synthetic-domain") for row in rows
                ),
                "user_effect": sorted(
                    (row["id"], row["user_effect"]) for row in rows
                ),
                "dependency_neighborhood": sorted(
                    (row["id"], row["dependency_neighborhood_root"]) for row in rows
                ),
                "target_ids": target_ids,
                "target_roots": sorted(
                    (row["id"], row["target_root"]) for row in rows
                ),
                "rationale": "all bound synthetic dimensions agree",
                "falsifier": "any bound dimension differs",
            }
        )
    receipts: list[dict[str, Any]] = []
    for target in rows:
        target_semantic_disposition = (
            semantic_disposition
            or str(target["semantic_review_disposition"])
        )
        semantic_dimensions = (
            [
                v2_semantic_dimension_receipt(
                    target_root=target["target_root"],
                    dimension=dimension,
                    verdict=v2_synthetic_semantic_dimension_verdict(
                        target_semantic_disposition,
                        dimension,
                    ),
                    reason=(
                        f"synthetic reviewed reason for {dimension}"
                    ),
                    falsifier=(
                        f"synthetic reviewed falsifier for {dimension}"
                    ),
                )
                for dimension in V2_SEMANTIC_REVIEW_DIMENSIONS
            ]
            if semantic_reviewed
            else []
        )
        source_closure = dict(target["source_closure"])
        if source_closure["required"] and semantic_reviewed:
            closure_verdict = next(
                row["verdict"]
                for row in semantic_dimensions
                if row["dimension"] == "source_and_terminal_closure"
            )
            if closure_verdict == "SATISFIED":
                source_closure["state"] = "ROOT_BOUND_REVIEWED_COMPLETE"
            elif closure_verdict == "NOT_APPLICABLE":
                source_closure["state"] = "ROOT_BOUND_NOT_APPLICABLE"
            else:
                source_closure["state"] = "ROOT_BOUND_REVIEW_BLOCKED"
        receipt = {
            "target_id": target["id"],
            "target_root": target["target_root"],
            "inventory_root": inventory["semantic_root"],
            "campaign_epoch_root": inventory["campaign_epoch_root"],
            "reviewer": (
                "synthetic-reviewer"
                if declared or compatible or semantic_reviewed
                else ""
            ),
            "reviewer_kind": (
                "fixture"
                if declared or compatible or semantic_reviewed
                else ""
            ),
            "coordination_assignee": "",
            "declared_domain_owner": (
                "synthetic-domain"
                if compatible or declared or semantic_reviewed
                else ""
            ),
            "declared_acceptance_owner": (
                "synthetic-acceptance-owner"
                if declared or compatible or semantic_reviewed
                else ""
            ),
            "implementation_owner": "synthetic-implementer",
            "evidence_owner": "synthetic-evidence-owner",
            "terminal_consumer": "synthetic-consumer",
            "source_closure": source_closure,
            "user_effect": target["user_effect"],
            "review_minutes": target["review_minutes"],
            "semantic_review_disposition": target_semantic_disposition,
            "semantic_review_dimensions": semantic_dimensions,
            "semantic_review_rationale": (
                "synthetic root-bound semantic adjudication"
                if semantic_reviewed
                else ""
            ),
            "semantic_review_falsifier": (
                "any target or dimension root drift invalidates adjudication"
                if semantic_reviewed
                else ""
            ),
            "compatibility_key": compatibility_key,
            "compatibility_target_ids": target_ids if compatible else [],
            "compatibility_receipt_root": compatibility_root,
            "compatibility_rationale": (
                "all bound synthetic dimensions agree" if compatible else ""
            ),
            "compatibility_falsifier": (
                "any bound dimension differs" if compatible else ""
            ),
            "manual_authorization": manual,
            "manual_authorization_source": (
                "synthetic-owner-declaration" if manual else ""
            ),
            "external_authority_adapter": (
                "fixture-independent-adapter"
                if external_verdict == "VALID"
                else ""
            ),
            "external_authority_receipt_root": (
                v2_fixture_gate_receipt_root(
                    "external",
                    target_root=target["target_root"],
                )
                if external_verdict == "VALID"
                else ""
            ),
            "external_authority_verdict": external_verdict,
            "conditional_capability_identity": (
                "fixture-atomic-cas"
                if conditional_verdict == "VALID"
                else ""
            ),
            "conditional_capability_receipt_root": (
                v2_fixture_gate_receipt_root(
                    "conditional",
                    target_root=target["target_root"],
                )
                if conditional_verdict == "VALID"
                else ""
            ),
            "conditional_capability_verdict": conditional_verdict,
            "gate_admission_receipt_root": (
                v2_fixture_gate_receipt_root(
                    "admission",
                    target_root=target["target_root"],
                )
                if gate_verdict == "VALID"
                else ""
            ),
            "gate_admission_verdict": gate_verdict,
            "no_claim": V2_REVIEW_RECEIPT_ROW_NO_CLAIM,
        }
        receipts.append(v2_rooted(receipt))
    return v2_rooted(
        {
            "schema": V2_REVIEW_RECEIPTS_SCHEMA,
            "inventory_root": inventory["semantic_root"],
            "campaign_epoch_root": inventory["campaign_epoch_root"],
            "receipts": receipts,
            "source": "SYNTHETIC_FIXTURE",
            "no_claim": V2_REVIEW_RECEIPTS_NO_CLAIM,
        }
    )


def v2_synthetic_authority(
    inventory: Mapping[str, Any],
    *,
    compatible: bool = False,
    declared: bool = False,
    manual: bool = False,
    semantic_reviewed: bool = False,
    semantic_disposition: str | None = None,
    external_verdict: str = "NODATA",
    conditional_verdict: str = "NODATA",
    gate_verdict: str = "NODATA",
    version: str = "0.2.19",
    allow_mechanical_fixture: bool = False,
) -> dict[str, Any]:
    receipts = v2_synthetic_receipts(
        inventory,
        compatible=compatible,
        declared=declared,
        manual=manual,
        semantic_reviewed=semantic_reviewed,
        semantic_disposition=semantic_disposition,
        external_verdict=external_verdict,
        conditional_verdict=conditional_verdict,
        gate_verdict=gate_verdict,
    )
    return v2_derive_authority(
        inventory,
        receipts,
        current_br_version=version,
        allow_mechanical_fixture=allow_mechanical_fixture,
    )


