        }
    )


def v2_fixture_manifest_with_history(
    manifest: Mapping[str, Any],
    history_contract: Mapping[str, Any],
) -> dict[str, Any]:
    fixture = dict(manifest)
    fixture["history_contract"] = dict(history_contract)
    fixture["content_identity"] = semantic_root(
        {
            "base_manifest_root": manifest["semantic_root"],
            "history_contract": history_contract,
            "purpose": "artifact-only self-test trust anchor",
        }
    )
    fixture.pop("semantic_root", None)
    fixture["semantic_root"] = semantic_root(fixture)
    return fixture


def v2_fixture_br_envelopes(
    full_issue: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    status = str(full_issue["status"])
    tracker_status = v2_normalize_br_status(
        {
            "summary": {
                "average_lead_time_hours": 0.0,
                "blocked_issues": 0,
                "closed_issues": int(status == "closed"),
                "deferred_issues": int(status == "deferred"),
                "draft_issues": 0,
                "epics_eligible_for_closure": 0,
                "in_progress_issues": int(status == "in_progress"),
                "open_issues": int(status == "open"),
                "pinned_issues": 0,
                "ready_issues": 0,
                "tombstone_issues": 0,
                "total_issues": 1,
            }
        },
        error_type=EvidenceFailed,
    )
    sync_status = v2_normalize_br_sync_status(
        {
            "db_newer": False,
            "dirty_count": 0,
            "git_export": {"available": False},
            "jsonl_content_hash": "0" * 64,
            "jsonl_exists": True,
            "jsonl_newer": False,
            "last_export_time": None,
            "last_import_time": None,
            "reliability_audit": {
                "anomalies": [],
                "anomaly_count": 0,
                "health": "healthy",
                "source": "sync.status",
            },
            "workspace_health": "healthy",
        },
        error_type=EvidenceFailed,
    )
    chunk = {
        "byte_count": 1,
        "first_line_hash": "1" * 64,
        "hash": "2" * 64,
        "index": 0,
        "last_line_hash": "1" * 64,
        "line_count": 1,
        "start_line": 0,
    }
    action = {
        "action": "reuse_unchanged",
        "base_index": 0,
        "byte_count": 1,
        "candidate_index": 0,
        "line_count": 1,
        "start_line": 0,
    }
    comparison = {
        "added_byte_count": 0,
        "added_chunks": 0,
        "base_byte_count": 1,
        "base_chunk_count": 1,
        "base_line_count": 1,
        "candidate_byte_count": 1,
        "candidate_chunk_count": 1,
        "candidate_line_count": 1,
        "changed_base_byte_count": 0,
        "changed_candidate_byte_count": 0,
        "changed_chunks": 0,
        "chunk_size_lines_match": True,
        "comparable_chunk_count": 1,
        "drift_detected": False,
        "first_changed_chunk_index": None,
        "removed_byte_count": 0,
        "removed_chunks": 0,
        "root_hashes_match": True,
        "safe_reuse_prefix_chunks": 1,
        "schema_versions_match": True,
        "unchanged_byte_count": 1,
        "unchanged_chunks": 1,
    }
    export_witness = v2_normalize_br_export_witness(
        {
            "base_comparison": comparison,
            "base_jsonl_path": ".beads/beads.base.jsonl",
            "base_parallel_work_plan": {
                "batches": [
                    {
                        "action_count": 1,
                        "actions": [action],
                        "byte_count": 1,
                        "candidate_end_index": 1,
                        "candidate_start_index": 0,
                        "index": 0,
                        "kind": "candidate_output",
                        "line_count": 1,
                    }
                ],
                "candidate_output_batches": 1,
                "deterministic_batch_order": True,
                "max_parallelism": 1,
                "metadata_only_drop_batches": 0,
                "total_batches": 1,
            },
            "base_reuse_materialization": {
                "dropped_byte_count": 0,
                "dropped_chunks": 0,
                "output_byte_count": 1,
                "read_added_byte_count": 0,
                "read_added_chunks": 0,
                "rebuilt_byte_count": 0,
                "rebuilt_chunks": 0,
                "reused_byte_count": 1,
                "reused_chunks": 1,
            },
            "base_reuse_plan": {
                "actions": [action],
                "comparison": comparison,
                "schedule": {
                    "candidate_output_actions": 1,
                    "candidate_output_byte_count": 1,
                    "candidate_output_line_count": 1,
                    "deterministic_candidate_order": True,
                    "dropped_byte_count": 0,
                    "max_parallel_candidate_actions": 1,
                    "metadata_only_drop_actions": 0,
                    "read_added_actions": 0,
                    "read_added_byte_count": 0,
                    "rebuild_actions": 0,
                    "rebuild_byte_count": 0,
                    "reusable_actions": 1,
                    "reusable_byte_count": 1,
                    "total_actions": 1,
                },
            },
            "jsonl_path": ".beads/issues.jsonl",
            "witness": {
                "byte_count": 1,
                "chunk_size_lines": 1,
                "chunks": [chunk],
                "line_count": 1,
                "root_hash": "3" * 64,
                "schema_version": "br.jsonl-witness.v1",
            },
        },
        error_type=EvidenceFailed,
    )
    v2_validate_live_envelope_consistency(
        tracker_status=tracker_status,
        sync_status=sync_status,
        export_witness=export_witness,
        full_issues=[full_issue],
        error_type=EvidenceFailed,
    )
    return tracker_status, sync_status, export_witness


def v2_fixture_audit_capture(
    full_issue: Mapping[str, Any],
    *,
    history_mode: bool,
) -> dict[str, Any]:
    if not history_mode:
        return v2_not_requested_audit_capture()
    audit_events = [
        {
            "id": 2,
            "event_type": "closed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00.001000+00:00",
            "comment": full_issue["close_reason"],
        },
        {
            "id": 1,
            "event_type": "status_changed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00+00:00",
            "old_value": "open",
            "new_value": "closed",
        },
    ]
    normalized_audit = v2_normalize_audit_document(
        {"issue_id": full_issue["id"], "events": audit_events},
        issue_id=full_issue["id"],
    )
    audit_stdout = canonical_bytes(
        {"issue_id": full_issue["id"], "events": audit_events}
    )
    audit_argv = [
        "br",
        "audit",
        "log",
        full_issue["id"],
        "--json",
        *BR_READ_FLAGS,
    ]
    return v2_rooted(
        {
            "capture_count": 2,
            "worker_bound": V2_AUDIT_WORKERS,
            "issue_ids": [full_issue["id"]],
            "documents": [normalized_audit],
            "command_receipts": [
                {
                    "capture_ordinal": capture_ordinal,
                    "issue_id": full_issue["id"],
                    "argv": audit_argv,
                    "exit_code": 0,
                    "result_category": "SUCCESS",
                    "stdout_byte_length": len(audit_stdout),
                    "stdout_root": (
                        "sha256-v1:" + hashlib.sha256(audit_stdout).hexdigest()
                    ),
                    "stderr_byte_length": 0,
                    "stderr_root": (
                        "sha256-v1:" + hashlib.sha256(b"").hexdigest()
                    ),
                    "raw_stream_bodies_retained": False,
                }
                for capture_ordinal in (1, 2)
            ],
            "raw_stream_bodies_retained": False,
            "no_claim": V2_AUDIT_CAPTURE_NO_CLAIM,
        }
    )


def v2_replayable_fixture_bundle(
    manifest: Mapping[str, Any],
    *,
    subject_mode: str,
    issue: Mapping[str, Any] | None = None,
    oversize: bool = False,
    artifact_root: str = "target/v2-fixture",
    artifact_dir: str | None = None,
) -> tuple[
    dict[str, bytes],
    dict[str, Any],
    tuple[
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, bytes],
    ],
]:
    if subject_mode not in {"review-plan", "history-plan"}:
        raise EvidenceFailed("replayable fixture subject mode is unknown")
    resolved_artifact_dir = artifact_dir or f"{subject_mode}-run"
    history_mode = subject_mode == "history-plan"
    raw_issue = dict(
        issue
        or fixture_issue(
            issue_id=(
                "fixture-history-replay"
                if history_mode
                else "fixture-review-replay"
            ),
            status="closed" if history_mode else "open",
            priority=2,
            description=(
                "x" * (V2_CHILD_DESCRIPTION_CAP + 1)
                if oversize
                else "Exact released-tool fixture work with replay boundaries."
            ),
            acceptance="",
            labels=("reality-check", "authority:template-hygiene"),
        )
    )
    if history_mode:
        raw_issue.update(
            {
                "created_at": "2026-01-01T00:00:00+00:00",
                "created_by": "fixture-creator",
                "closed_at": "2026-01-02T00:00:00+00:00",
                "close_reason": "Fixture history replay completed.",
            }
        )
    full_issue = v2_full_issue_projection(raw_issue)
    fixture_audit = v2_fixture_audit_capture(
        full_issue,
        history_mode=history_mode,
    )
    missing = {
        full_issue["id"]: fixture_expected_missing(full_issue["type"])
    }
    lint = fixture_lint([full_issue], missing)
    accepted_manifest = dict(manifest)
    if history_mode:
        history_contract = dict(manifest["history_contract"])
        history_contract.update(
            {
                "legacy_coverage_anchor_issue": full_issue["id"],
                "legacy_coverage_anchor_closed_at": full_issue["closed_at"],
                "legacy_coverage_anchor_status_event_id": 1,
                "legacy_coverage_anchor_close_event_id": 2,
                "legacy_coverage_count": 0,
                "legacy_coverage_rows_root": semantic_root([]),
                "known_pair_max_skew_ms": 1_000,
            }
        )
        accepted_manifest = v2_fixture_manifest_with_history(
            manifest,
            history_contract,
        )
    synthetic_findings = independent_template_findings(full_issue)
    lint_ids = sorted(lint_result_map(lint))
    independent_ids = [full_issue["id"]] if synthetic_findings else []
    nonclosed_ids = (
        [] if full_issue["status"] == "closed" else [full_issue["id"]]
    )
    selected_ids = sorted(
        set(lint_ids) | set(independent_ids) | set(nonclosed_ids)
    )
    fixture_command_output = canonical_bytes({"fixture": "bounded-read"})
    fixture_command_receipts = [
        {
            "capture_sequence": index,
            "argv": argv,
            "exit_code": 0,
            "category": "SUCCESS",
            "stdout": {
                "bytes": len(fixture_command_output),
                "root": (
                    "sha256-v1:"
                    + hashlib.sha256(fixture_command_output).hexdigest()
                ),
                "body_retained": False,
            },
            "stderr": {
                "bytes": 0,
                "root": "sha256-v1:" + hashlib.sha256(b"").hexdigest(),
                "body_retained": False,
            },
            "cleanup_error_count": 0,
            "cleanup_error_kinds": [],
            "redaction_verdict": "RAW_STREAM_BODIES_NOT_RETAINED",
        }
        for index, argv in enumerate(
            v2_expected_observation_argv([full_issue["id"]])
        )
    ]
    fixture_br_version = {
        "version": "0.2.19",
        "build": "release",
        "commit": "fixture-released-br",
        "target": "fixture",
        "features": [],
    }
    fixture_br_capabilities = {
        "contract_version": "br.capabilities.v1",
        "commands": [
            {
                "name": "list",
                "summary": "List fixture issues",
                "operation": "read",
                "workspace": "required",
                "machine_output": ["json"],
                "examples": ["br list --json"],
            }
        ],
        "operation_count": 1,
    }
    (
        fixture_tracker_status,
        fixture_sync_status,
        fixture_export_witness,
    ) = v2_fixture_br_envelopes(full_issue)
    fixture_source_files = v2_source_file_identities()
    fixture_source_files[2] = {
        **fixture_source_files[2],
        "content_identity": accepted_manifest["content_identity"],
    }
    fixture_rule_contract = {
        "required_sections_by_type": REQUIRED_SECTIONS_BY_TYPE,
        "clause_terms": list(CLAUSE_TERMS),
        "classifier": "independent-template-findings-v2",
    }
    fixture_capture = v2_capture_state(
        issue_ids=[full_issue["id"]],
        full_issues=[full_issue],
        lint=lint,
        tracker_status=fixture_tracker_status,
        sync_status=fixture_sync_status,
        export_witness=fixture_export_witness,
        version=fixture_br_version,
        capabilities=fixture_br_capabilities,
        source_files=fixture_source_files,
        rule_contract=fixture_rule_contract,
    )
    observation = v2_rooted(
        {
            "schema": V2_SOURCE_SCHEMA,
            "capture_contract": {
                "count": 2,
                "coherent": True,
                "tracker_cli": "br",
                "direct_tracker_file_access": False,
                "network_access": False,
                "audit_bracket": v2_rooted(
                    {
                        "state": (
                            "CAPTURED" if history_mode else "NOT_REQUESTED"
                        ),
                        "position": "BETWEEN_SOURCE_CAPTURE_ROUNDS",
                        "source_before_ordinal": 1,
                        "source_after_ordinal": 2,
                        "audit_capture_ordinals": (
                            [1, 2] if history_mode else []
                        ),
                        "source_before_root": fixture_capture["semantic_root"],
                        "source_after_root": fixture_capture["semantic_root"],
                        "audit_capture_root": fixture_audit["semantic_root"],
                        "no_claim": V2_AUDIT_BRACKET_NO_CLAIM,
                    }
                ),
            },
            "br_version": fixture_br_version,
            "br_capabilities": fixture_br_capabilities,
            "tracker_status": fixture_tracker_status,
            "sync_status": fixture_sync_status,
            "export_witness": fixture_export_witness,
            "case_manifest_root": accepted_manifest["semantic_root"],
            "case_manifest_content_identity": accepted_manifest[
                "content_identity"
            ],
            "coherent_capture_root": fixture_capture["semantic_root"],
            "source_files": fixture_source_files,
            "rule_contract_root": semantic_root(fixture_rule_contract),
            "live_issue_count": 1,
            "live_issue_projection_root": semantic_root([full_issue]),
            "lint_issue_ids_root": semantic_root(lint_ids),
            "independent_finding_issue_ids_root": semantic_root(
                independent_ids
            ),
            "nonclosed_issue_ids_root": semantic_root(nonclosed_ids),
            "selected_review_issue_ids_root": semantic_root(selected_ids),
            "selected_review_issue_count": len(selected_ids),
            "nonclosed_issue_count": len(nonclosed_ids),
            "closed_finding_issue_count": len(
                (set(lint_ids) | set(independent_ids))
                - set(nonclosed_ids)
            ),
            "status_cut": list(STATUS_SCOPES),
            "command_receipts": fixture_command_receipts,
            "no_claim": V2_SOURCE_OBSERVATION_NO_CLAIM,
        }
    )
    v1_inventory = assemble_inventory(
        lint,
        [full_issue],
        observation,
        (
            {full_issue["id"]: synthetic_findings}
            if synthetic_findings
            else None
        ),
        include_issue_rows_without_findings=True,
    )
    snapshot = LiveSnapshot(
        lint,
        [full_issue],
        observation,
        v1_inventory,
        {},
        (full_issue,),
    )
    campaign_root, _ = v2_campaign_epoch(snapshot)
    inventory = v2_build_inventory(
        snapshot,
        campaign_epoch_root=campaign_root,
        priority_filter=None,
        status_filter=None,
    )
    receipts = v2_empty_review_receipts(
        inventory_root=inventory["semantic_root"],
        campaign_epoch_root=inventory["campaign_epoch_root"],
    )
    authority = v2_derive_authority(
        inventory,
        receipts,
        current_br_version="0.2.19",
    )
    prior = v2_empty_prior_campaign()
    audit = fixture_audit
    source = v2_build_source_document(
        snapshot=snapshot,
        manifest=accepted_manifest,
        inventory=inventory,
        review_receipts=receipts,
        prior_campaign=prior,
        audit_capture=audit,
        priority_filter=None,
        status_filter=None,
    )
    if history_mode:
        review = v2_not_requested(
            schema=V2_REVIEW_PLAN_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="review-plan",
        )
        optional: dict[str, bytes] = {}
        history = v2_build_history(
            source_root=source["semantic_root"],
            inventory=inventory,
            authority=authority,
            all_issues=snapshot.all_issues,
            audit_capture=audit,
            history_contract=accepted_manifest["history_contract"],
        )
    else:
        review, optional = v2_build_review_plan(
            inventory,
            authority,
            max_targets=V2_REVIEW_TARGET_DEFAULT,
        )
        history = v2_not_requested(
            schema=V2_HISTORY_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="history",
        )
    zero = v2_build_zero_sets(
        source_root=source["semantic_root"],
        inventory=inventory,
        prior_campaign=prior,
        current_universe=snapshot.all_issues,
        current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
    )
    reproduction = [
        str(SCRIPT_REL),
        f"--{subject_mode}",
        "--artifact-root",
        artifact_root,
        "--artifact-dir",
        resolved_artifact_dir,
    ]
    payloads = v2_bundle_payloads(
        mode=subject_mode,
        subject_mode=subject_mode,
        artifact_root=artifact_root,
        artifact_dir=resolved_artifact_dir,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review,
        history=history,
        zero_sets=zero,
        optional_payloads=optional,
        reproduction=reproduction,
    )
    components = (
        source,
        inventory,
        authority,
        review,
        history,
        zero,
        optional,
    )
    return payloads, accepted_manifest, components


def v2_plan_for_count(
    count: int,
    *,
    max_targets: int,
    review_minutes: int = 1,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, bytes]]:
    inventory = v2_synthetic_inventory(
        [
            v2_synthetic_target(index, review_minutes=review_minutes)
            for index in range(count)
        ]
    )
    authority = v2_synthetic_authority(
        inventory,
        compatible=count > 1,
    )
    plan, optional = v2_build_review_plan(
        inventory,
        authority,
        max_targets=max_targets,
    )
    return plan, authority, optional


def v2_authentic_projection_fixture(
    raw_issues: Sequence[Mapping[str, Any]],
    *,
    missing_by_id: Mapping[str, Sequence[str]] | None = None,
) -> tuple[
    list[dict[str, Any]],
    dict[str, Any],
    LiveSnapshot,
    dict[str, Any],
]:
    full_issues = sorted(
        (v2_full_issue_projection(issue) for issue in raw_issues),
        key=lambda row: row["id"],
    )
    v2_assert_unique(
        [row["id"] for row in full_issues],
        label="authentic fixture issue IDs",
    )
    normalized_missing = {
        row["id"]: tuple(
            sorted(
                (
                    missing_by_id.get(
                        row["id"],
                        fixture_expected_missing(row["type"]),
                    )
                    if missing_by_id is not None
                    else fixture_expected_missing(row["type"])
                )
            )
        )
        for row in full_issues
    }
    lint = fixture_lint(full_issues, normalized_missing)
    selected = [
        row
        for row in full_issues
        if row["status"] != "closed" or normalized_missing[row["id"]]
    ]
    source = fixture_source(full_issues)
    v1_inventory = assemble_inventory(
        lint,
        selected,
        source,
        include_issue_rows_without_findings=True,
    )
    snapshot = LiveSnapshot(
        lint,
        selected,
        source,
        v1_inventory,
        {},
        tuple(full_issues),
    )
    campaign_root, _ = v2_campaign_epoch(snapshot)
    inventory = v2_build_inventory(
        snapshot,
        campaign_epoch_root=campaign_root,
        priority_filter=None,
        status_filter=None,
    )
    return full_issues, lint, snapshot, inventory


def v2_execute_schema_cli_ux(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "schema-cli-ux", "slug": slug}
    if slug == "schema-closed-manifest":
        checks.check(
            "top-level-closed",
            set(manifest) - {"content_identity", "semantic_root"}
            == V2_MANIFEST_TOP_LEVEL_KEYS,
            expected=sorted(V2_MANIFEST_TOP_LEVEL_KEYS),
            observed=sorted(set(manifest) - {"content_identity", "semantic_root"}),
        )
        duplicate_rejected = False
        try:
            tomllib.loads("value = 1\nvalue = 2\n")
        except tomllib.TOMLDecodeError:
            duplicate_rejected = True
        checks.check(
            "duplicate-toml-key-refused",
            duplicate_rejected,
            expected=True,
            observed=duplicate_rejected,
        )
        checks.check(
            "schema-version",
            manifest["schema"] == V2_MANIFEST_SCHEMA
            and manifest["schema_version"] == 2,
            expected=(V2_MANIFEST_SCHEMA, 2),
            observed=(manifest["schema"], manifest["schema_version"]),
        )
        manifest_payload = bounded_read(REPO_ROOT / CASE_MANIFEST_V2_REL)
        accepted_identity = v2_validate_accepted_manifest_payload(
            manifest_payload
        )
        checks.check(
            "accepted-manifest-content-identity-exact",
            accepted_identity
            == manifest["content_identity"]
            == V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY,
            expected=V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY,
            observed={
                "loaded": manifest["content_identity"],
                "revalidated": accepted_identity,
            },
        )
        harness_payload = bounded_read(REPO_ROOT / SCRIPT_REL)
        harness_contract_identity = v2_validate_harness_contract_payload(
            harness_payload,
            manifest["harness_contract_identity"],
        )
        checks.check(
            "harness-contract-identity-exact",
            harness_contract_identity
            == manifest["harness_contract_identity"],
            expected=manifest["harness_contract_identity"],
            observed=harness_contract_identity,
        )
        current_pin = V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY.encode("ascii")
        alternate_pin = b"sha256-v1:" + (b"f" * 64)
        if current_pin == alternate_pin or harness_payload.count(current_pin) != 1:
            raise EvidenceFailed(
                "harness identity normalization fixture is not unique"
            )
        normalized_pin_payload = harness_payload.replace(
            current_pin,
            alternate_pin,
            1,
        )
        checks.check(
            "harness-manifest-pin-normalization-stable",
            v2_harness_contract_identity(normalized_pin_payload)
            == harness_contract_identity,
            expected=harness_contract_identity,
            observed=v2_harness_contract_identity(
                normalized_pin_payload
            ),
        )
        weakening_source = (
            b'            or check.get("passed") is not True\n'
        )
        weakening_replacement = (
            b'            or type(check.get("passed")) is not bool\n'
        )
        if harness_payload.count(weakening_source) != 1:
            raise EvidenceFailed(
                "harness semantic-weakening mutation site is not unique"
            )
        weakened_harness_payload = harness_payload.replace(
            weakening_source,
            weakening_replacement,
            1,
        )
        checks.refuses(
            "harness-semantic-weakening-with-stable-check-ids-refused",
            InputRefused,
            lambda: v2_validate_harness_contract_payload(
                weakened_harness_payload,
                manifest["harness_contract_identity"],
            ),
            contains="harness contract identity drifted",
            projection=lambda: {
                "accepted_harness_contract_identity": manifest[
                    "harness_contract_identity"
                ],
                "mutated_harness_contract_identity": (
                    v2_harness_contract_identity(weakened_harness_payload)
                ),
            },
            projection_label="HARNESS_CONTRACT_IDENTITIES",
        )
        drift_payload = manifest_payload + b"\n"
        original_document = tomllib.loads(manifest_payload.decode("utf-8"))
        drift_document = tomllib.loads(drift_payload.decode("utf-8"))
        checks.check(
            "trailing-newline-drift-preserves-toml-semantics",
            drift_document == original_document,
            expected=semantic_root(original_document),
            observed=semantic_root(drift_document),
        )
        identity_projection = lambda: {
            "accepted_identity": V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY,
            "loaded_identity": manifest["content_identity"],
        }
        checks.refuses(
            "semantically-equivalent-manifest-byte-drift-refused",
            InputRefused,
            lambda: v2_validate_accepted_manifest_payload(drift_payload),
            contains="content identity drifted",
            projection=identity_projection,
            projection_label="ACCEPTED_MANIFEST_IDENTITIES",
        )
        checks.check(
            "ordered-manifest-list-refuses-scalars-and-duplicates",
            not v2_manifest_ordered_string_list(
                "PURE_PROJECTION",
                V2_FIXTURE_ENGINES,
            )
            and not v2_manifest_ordered_string_list(
                [
                    V2_FIXTURE_ENGINES[0],
                    V2_FIXTURE_ENGINES[0],
                    *V2_FIXTURE_ENGINES[1:],
                ],
                V2_FIXTURE_ENGINES,
            ),
            expected={"scalar": False, "duplicate": False},
            observed={
                "scalar": v2_manifest_ordered_string_list(
                    "PURE_PROJECTION",
                    V2_FIXTURE_ENGINES,
                ),
                "duplicate": v2_manifest_ordered_string_list(
                    [
                        V2_FIXTURE_ENGINES[0],
                        V2_FIXTURE_ENGINES[0],
                        *V2_FIXTURE_ENGINES[1:],
                    ],
                    V2_FIXTURE_ENGINES,
                ),
            },
        )
        checks.refuses(
            "manifest-pattern-wrong-type-refused",
            InputRefused,
            lambda: v2_compile_manifest_pattern(
                7,
                label="fixture pattern",
            ),
            contains="nonempty string",
        )
        checks.refuses(
            "manifest-pattern-invalid-regex-refused",
            InputRefused,
            lambda: v2_compile_manifest_pattern(
                "[",
                label="fixture pattern",
            ),
            contains="valid regular expression",
        )
        v2_validate_cap_terminal_contract(manifest["caps"])
        checks.refuses(
            "cap-terminal-contract-drift-refused",
            InputRefused,
            lambda: v2_validate_cap_terminal_contract(
                {
                    **manifest["caps"],
                    "cap_exceeded_terminal": "ARBITRARY_TERMINAL",
                }
            ),
            contains="cap terminal contract",
        )
    elif slug == "schema-executable-assertions":
        case_ids = [row["id"] for row in manifest["case"]]
        assertion_ids = [row["assertion_id"] for row in manifest["case"]]
        criterion_links = {
            assertion_id
            for row in manifest["criterion"]
            for assertion_id in row["assertion_ids"]
        }
        checks.check(
            "case-assertion-bijection",
            len(case_ids) == len(set(case_ids)) == len(assertion_ids)
            == len(set(assertion_ids))
            == 96,
            expected=96,
            observed={
                "cases": len(set(case_ids)),
                "assertions": len(set(assertion_ids)),
            },
        )
        checks.check(
            "criterion-links-executable",
            criterion_links == set(assertion_ids),
            expected=semantic_root(sorted(assertion_ids)),
            observed=semantic_root(sorted(criterion_links)),
        )
        registry = v2_build_executor_registry(manifest)
        checks.check(
            "compiled-executor-bijection",
            set(registry) == set(assertion_ids)
            and all(callable(executor) for executor in registry.values()),
            expected=semantic_root(sorted(assertion_ids)),
            observed=semantic_root(sorted(registry)),
        )
        obligations = v2_validate_check_obligation_registry(
            manifest["case"],
            manifest["check_obligations"],
        )
        checks.check(
            "check-obligation-order-membership-bijection",
            list(obligations) == assertion_ids,
            expected=assertion_ids,
            observed=list(obligations),
        )
        runner_snapshot = v2_clone_runner_manifest(manifest)
        checks.check(
            "runner-snapshot-reconstructs-obligation-order",
            runner_snapshot == manifest
            and list(runner_snapshot["check_obligations"])
            == assertion_ids
            and runner_snapshot is not manifest
            and runner_snapshot["check_obligations"]
            is not manifest["check_obligations"],
            expected={
                "value_equal": True,
                "ordered_assertion_ids": assertion_ids,
                "distinct_snapshot": True,
                "distinct_obligation_registry": True,
            },
            observed={
                "value_equal": runner_snapshot == manifest,
                "ordered_assertion_ids": list(
                    runner_snapshot["check_obligations"]
                ),
                "distinct_snapshot": runner_snapshot is not manifest,
                "distinct_obligation_registry": (
                    runner_snapshot["check_obligations"]
                    is not manifest["check_obligations"]
                ),
            },
        )
        obligation_roots = [
            v2_check_obligation_root(
                row,
                obligations[str(row["assertion_id"])],
            )
