    elif slug in {"ux-empty-synopsis", "ux-large-synopsis"}:
        def fixture_synopsis(count: int) -> dict[str, Any]:
            inventory = v2_synthetic_inventory(
                [v2_synthetic_target(index) for index in range(count)]
            )
            authority = v2_synthetic_authority(inventory)
            review = v2_rooted(
                {
                    "schema": V2_REVIEW_PLAN_SCHEMA,
                    "children": [
                        {"priority": 2, "target_ids": [row["id"]]}
                        for row in inventory["rows"]
                    ],
                    "oversize_content": [],
                    "work": {
                        "total_review_minutes": count,
                        "minimum_child_review_minutes": (
                            0 if not count else 1
                        ),
                        "maximum_child_review_minutes": (
                            0 if not count else 1
                        ),
                    },
                }
            )
            history = v2_rooted(
                {"schema": V2_HISTORY_SCHEMA, "rows": []}
            )
            zero = v2_rooted(
                {
                    "schema": V2_ZERO_SETS_SCHEMA,
                    "counts": {
                        "zero_receipts": 25 if not count else 24
                    },
                }
            )
            return v2_synopsis(
                subject_mode="review-plan",
                review_plan=review,
                history=history,
                authority=authority,
                zero_sets=zero,
                artifact_dir="target/v2/fixture",
                reproduction=["script", "--review-plan"],
                explain_target=None,
            )

        if slug == "ux-empty-synopsis":
            synopsis = fixture_synopsis(0)
            required_top_level = {
                "schema",
                "mode",
                "counts",
                "work",
                "capacity_wave_forecast",
                "active_conflicts",
                "top_blockers",
                "selected_ids",
                "why_grouped",
                "explanation",
                "safe_next_action",
                "artifacts",
                "reproduction",
                "no_claim",
            }
            checks.check(
                "empty-synopsis-exact-sections",
                set(synopsis) == required_top_level
                and set(synopsis["counts"])
                == set(manifest["synopsis_contract"]["required_counts"])
                and set(synopsis["work"])
                == set(manifest["synopsis_contract"]["required_work"]),
                expected={
                    "top_level": sorted(required_top_level),
                    "counts": sorted(
                        manifest["synopsis_contract"]["required_counts"]
                    ),
                    "work": sorted(
                        manifest["synopsis_contract"]["required_work"]
                    ),
                },
                observed={
                    "top_level": sorted(synopsis),
                    "counts": sorted(synopsis["counts"]),
                    "work": sorted(synopsis["work"]),
                },
            )
            checks.check(
                "empty-synopsis-exact-zero-values",
                synopsis["counts"]
                == {
                    "targets": 0,
                    "children": 0,
                    "readiness": {},
                    "routes": {},
                    "owners": 0,
                    "oversize": 0,
                    "zero_receipts": 25,
                }
                and synopsis["work"]
                == {
                    "total_review_minutes": 0,
                    "minimum_review_minutes": 0,
                    "maximum_review_minutes": 0,
                }
                and synopsis["capacity_wave_forecast"]
                == {f"P{priority}": 0 for priority in range(5)}
                and synopsis["active_conflicts"] == []
                and synopsis["top_blockers"] == []
                and synopsis["selected_ids"]
                == {
                    "total": 0,
                    "shown": 0,
                    "ids": [],
                    "truncated": False,
                    "notice": None,
                }
                and synopsis["explanation"] is None,
                expected="all empty-campaign numeric and membership values exact",
                observed=synopsis,
            )
            checks.check(
                "empty-synopsis-operator-fields-exact",
                synopsis["artifacts"] == "target/v2/fixture"
                and synopsis["reproduction"]
                == ["script", "--review-plan"]
                and "do not mutate" in synopsis["safe_next_action"]
                and "no authority is minted" in synopsis["no_claim"],
                expected={
                    "artifacts": "target/v2/fixture",
                    "reproduction": ["script", "--review-plan"],
                    "safe": "do not mutate",
                    "no_claim": "no authority is minted",
                },
                observed={
                    "artifacts": synopsis["artifacts"],
                    "reproduction": synopsis["reproduction"],
                    "safe_next_action": synopsis["safe_next_action"],
                    "no_claim": synopsis["no_claim"],
                },
            )
            checks.check(
                "empty-synopsis-bounded-utf8",
                len(canonical_bytes(synopsis)) <= V2_SYNOPSIS_BYTES_CAP,
                expected=f"<= {V2_SYNOPSIS_BYTES_CAP}",
                observed=len(canonical_bytes(synopsis)),
            )
        else:
            boundary_synopses = {
                count: fixture_synopsis(count)
                for count in (
                    V2_SYNOPSIS_ID_PREVIEW_CAP - 1,
                    V2_SYNOPSIS_ID_PREVIEW_CAP,
                    V2_SYNOPSIS_ID_PREVIEW_CAP + 1,
                )
            }
            for count, synopsis in boundary_synopses.items():
                expected_ids = [
                    f"synthetic-{index:04d}"
                    for index in range(
                        min(count, V2_SYNOPSIS_ID_PREVIEW_CAP)
                    )
                ]
                checks.check(
                    f"selected-id-preview-boundary-{count}",
                    synopsis["selected_ids"]["total"] == count
                    and synopsis["selected_ids"]["shown"]
                    == min(count, V2_SYNOPSIS_ID_PREVIEW_CAP)
                    and synopsis["selected_ids"]["ids"] == expected_ids
                    and synopsis["selected_ids"]["truncated"]
                    == (count > V2_SYNOPSIS_ID_PREVIEW_CAP)
                    and (
                        synopsis["selected_ids"]["notice"] is not None
                    )
                    == (count > V2_SYNOPSIS_ID_PREVIEW_CAP),
                    expected={
                        "total": count,
                        "shown": min(
                            count,
                            V2_SYNOPSIS_ID_PREVIEW_CAP,
                        ),
                        "ids": expected_ids,
                        "truncated": (
                            count > V2_SYNOPSIS_ID_PREVIEW_CAP
                        ),
                    },
                    observed=synopsis["selected_ids"],
                )
            synopsis = boundary_synopses[
                V2_SYNOPSIS_ID_PREVIEW_CAP + 1
            ]
            exact_bytes = len(canonical_bytes(synopsis))
            original_synopsis_cap = V2_SYNOPSIS_BYTES_CAP
            injected_results: dict[str, Any] = {}
            try:
                globals()["V2_SYNOPSIS_BYTES_CAP"] = exact_bytes + 1
                injected_results["n_plus_one"] = fixture_synopsis(
                    V2_SYNOPSIS_ID_PREVIEW_CAP + 1
                )
                globals()["V2_SYNOPSIS_BYTES_CAP"] = exact_bytes
                injected_results["n"] = fixture_synopsis(
                    V2_SYNOPSIS_ID_PREVIEW_CAP + 1
                )
                globals()["V2_SYNOPSIS_BYTES_CAP"] = exact_bytes - 1
                try:
                    fixture_synopsis(V2_SYNOPSIS_ID_PREVIEW_CAP + 1)
                except EvidenceFailed as error:
                    injected_results["n_minus_one"] = error
            finally:
                globals()["V2_SYNOPSIS_BYTES_CAP"] = original_synopsis_cap
            checks.check(
                "synopsis-byte-cap-injected-n-minus-one-n-n-plus-one",
                len(
                    canonical_bytes(injected_results["n_plus_one"])
                )
                == exact_bytes
                and len(canonical_bytes(injected_results["n"]))
                == exact_bytes
                and isinstance(
                    injected_results.get("n_minus_one"),
                    EvidenceFailed,
                )
                and "UTF-8 byte cap"
                in str(injected_results["n_minus_one"]),
                expected={
                    "n_minus_one": "EvidenceFailed",
                    "n": exact_bytes,
                    "n_plus_one": exact_bytes,
                },
                observed={
                    "n_minus_one": type(
                        injected_results.get("n_minus_one")
                    ).__name__,
                    "n": len(canonical_bytes(injected_results["n"])),
                    "n_plus_one": len(
                        canonical_bytes(
                            injected_results["n_plus_one"]
                        )
                    ),
                },
            )
            checks.check(
                "large-synopsis-retains-complete-artifact-no-claim",
                synopsis["selected_ids"]["total"]
                == V2_SYNOPSIS_ID_PREVIEW_CAP + 1
                and synopsis["selected_ids"]["shown"]
                == V2_SYNOPSIS_ID_PREVIEW_CAP
                and "machine artifacts are complete"
                in str(synopsis["selected_ids"]["notice"])
                and "complete machine artifacts remain untruncated"
                in synopsis["no_claim"],
                expected={
                    "total": V2_SYNOPSIS_ID_PREVIEW_CAP + 1,
                    "shown": V2_SYNOPSIS_ID_PREVIEW_CAP,
                    "artifacts": "untruncated",
                },
                observed={
                    "selected_ids": synopsis["selected_ids"],
                    "no_claim": synopsis["no_claim"],
                },
            )
    elif slug == "ux-streams-color-tty":
        help_result = run_command(
            [str(REPO_ROOT / SCRIPT_REL), "--help"],
            environment_overrides={
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        invalid_result = run_command(
            [
                str(REPO_ROOT / SCRIPT_REL),
                "--self-test-v2",
                "--unknown-v2-mode",
            ],
            expected=(TERMINAL_EXIT["UsageRefused"],),
            environment_overrides={
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        invalid_document = strict_json_loads(
            invalid_result.stdout,
            label="v2 invalid CLI terminal",
            require_canonical=True,
        )
        v2_validate_preflight_terminal_document(invalid_document)
        checks.check(
            "actual-help-stdout-stderr-no-color",
            help_result.returncode == 0
            and "--review-plan" in help_result.stdout
            and help_result.stderr == ""
            and "\x1b[" not in help_result.stdout
            and "\x1b[" not in help_result.stderr,
            expected={
                "exit": 0,
                "stdout": "help",
                "stderr": "",
                "ansi": False,
            },
            observed={
                "exit": help_result.returncode,
                "stdout_root": text_root(help_result.stdout),
                "stderr_root": text_root(help_result.stderr),
                "ansi": "\x1b["
                in (help_result.stdout + help_result.stderr),
            },
        )
        checks.check(
            "actual-invalid-cli-typed-exit-and-streams",
            invalid_result.returncode == TERMINAL_EXIT["UsageRefused"]
            and invalid_result.stderr == ""
            and invalid_document["schema"] == V2_PREFLIGHT_TERMINAL_SCHEMA
            and set(invalid_document) == V2_PREFLIGHT_TERMINAL_FIELDS
            and invalid_document["terminal"] == "UsageRefused"
            and invalid_document["exit_code"]
            == TERMINAL_EXIT["UsageRefused"]
            and "\x1b[" not in invalid_result.stdout
            and "\x1b[" not in invalid_result.stderr,
            expected={
                "exit": TERMINAL_EXIT["UsageRefused"],
                "schema": V2_PREFLIGHT_TERMINAL_SCHEMA,
                "terminal": "UsageRefused",
                "stderr": "",
                "ansi": False,
            },
            observed={
                "exit": invalid_result.returncode,
                "schema": invalid_document.get("schema"),
                "terminal": invalid_document.get("terminal"),
                "typed_exit": invalid_document.get("exit_code"),
                "stderr_root": text_root(invalid_result.stderr),
                "ansi": "\x1b["
                in (invalid_result.stdout + invalid_result.stderr),
            },
        )
        accepted_failure_result = run_command(
            [
                str(REPO_ROOT / SCRIPT_REL),
                "--case-v2",
                "template-lint-v2.unknown-accepted-case",
            ],
            expected=(TERMINAL_EXIT["UsageRefused"],),
            environment_overrides={
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        accepted_failure_document = strict_json_loads(
            accepted_failure_result.stdout,
            label="v2 accepted-execution terminal",
            require_canonical=True,
        )
        v2_validate_execution_terminal_document(
            accepted_failure_document
        )
        checks.check(
            "actual-accepted-v2-failure-uses-execution-terminal",
            accepted_failure_result.returncode
            == TERMINAL_EXIT["UsageRefused"]
            and accepted_failure_result.stderr == ""
            and accepted_failure_document["schema"]
            == V2_EXECUTION_TERMINAL_SCHEMA
            and accepted_failure_document["terminal"]
            == "UsageRefused"
            and accepted_failure_document["mode"] == "case-v2"
            and accepted_failure_document["phase"] == "TEST_RUNNER"
            and accepted_failure_document["artifact_state"]
            == "NOT_APPLICABLE"
            and accepted_failure_document["manifest_root"]
            == manifest["semantic_root"],
            expected={
                "exit": TERMINAL_EXIT["UsageRefused"],
                "schema": V2_EXECUTION_TERMINAL_SCHEMA,
                "terminal": "UsageRefused",
                "mode": "case-v2",
                "phase": "TEST_RUNNER",
                "artifact_state": "NOT_APPLICABLE",
                "manifest_root": manifest["semantic_root"],
                "stderr": "",
            },
            observed={
                "exit": accepted_failure_result.returncode,
                "document": accepted_failure_document,
                "stderr_root": text_root(
                    accepted_failure_result.stderr
                ),
            },
        )
        repeated_invalid = run_command(
            [
                str(REPO_ROOT / SCRIPT_REL),
                "--self-test-v2",
                "--unknown-v2-mode",
            ],
            expected=(TERMINAL_EXIT["UsageRefused"],),
            environment_overrides={"TERM": "dumb"},
            record_global_receipt=False,
        )
        checks.check(
            "pipe-execution-no-tty-dependency-and-no-color-determinism",
            invalid_result.stdout == repeated_invalid.stdout
            and invalid_result.stderr == repeated_invalid.stderr
            and invalid_result.returncode == repeated_invalid.returncode,
            expected={
                "stdout_root": text_root(invalid_result.stdout),
                "stderr_root": text_root(invalid_result.stderr),
                "exit": invalid_result.returncode,
            },
            observed={
                "stdout_root": text_root(repeated_invalid.stdout),
                "stderr_root": text_root(repeated_invalid.stderr),
                "exit": repeated_invalid.returncode,
            },
        )
        forbidden_manifest_result = run_command(
            [str(REPO_ROOT / SCRIPT_REL), "--self-test-v2"],
            expected=(TERMINAL_EXIT["EvidenceFailed"],),
            environment_overrides={
                "FS_TEMPLATE_HYGIENE_FORBID_V2_LOAD": "1",
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        forbidden_manifest_document = strict_json_loads(
            forbidden_manifest_result.stdout,
            label="v2 forbidden-manifest preflight terminal",
            require_canonical=True,
        )
        v2_validate_preflight_terminal_document(
            forbidden_manifest_document
        )
        checks.check(
            "actual-v2-manifest-preflight-closed",
            forbidden_manifest_result.returncode
            == TERMINAL_EXIT["EvidenceFailed"]
            and forbidden_manifest_result.stderr == ""
            and forbidden_manifest_document["schema"]
            == V2_PREFLIGHT_TERMINAL_SCHEMA
            and set(forbidden_manifest_document)
            == V2_PREFLIGHT_TERMINAL_FIELDS
            and forbidden_manifest_document["terminal"]
            == "EvidenceFailed"
            and forbidden_manifest_document["mode"] == "self-test-v2"
            and forbidden_manifest_document["recovery"]
            == "FIX_HARNESS_OR_CONTRACT_AND_RETRY",
            expected={
                "exit": TERMINAL_EXIT["EvidenceFailed"],
                "schema": V2_PREFLIGHT_TERMINAL_SCHEMA,
                "terminal": "EvidenceFailed",
                "mode": "self-test-v2",
                "recovery": "FIX_HARNESS_OR_CONTRACT_AND_RETRY",
            },
            observed={
                "exit": forbidden_manifest_result.returncode,
                "document": forbidden_manifest_document,
                "stderr_root": text_root(forbidden_manifest_result.stderr),
            },
        )
    elif slug == "compat-v1-immutable":
        v1 = load_case_manifest()
        compatibility = manifest["compatibility_contract"]
        payload = bounded_read(REPO_ROOT / CASE_MANIFEST_REL)
        retained_manifest_blob = run_command(
            [
                "git",
                "rev-parse",
                (
                    compatibility["v1_manifest_adopted_git_commit"]
                    + ":"
                    + compatibility["v1_manifest_path"]
                ),
            ],
            record_global_receipt=False,
        ).stdout.strip()
        checks.check(
            "v1-content-root",
            "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            == compatibility["v1_manifest_content_root"],
            expected=compatibility["v1_manifest_content_root"],
            observed="sha256-v1:" + hashlib.sha256(payload).hexdigest(),
        )
        checks.check(
            "v1-semantic-root",
            v1["semantic_root"]
            == compatibility["v1_case_manifest_semantic_root"],
            expected=compatibility["v1_case_manifest_semantic_root"],
            observed=v1["semantic_root"],
        )
        checks.check(
            "v1-registry-counts",
            len(v1["case"]) == 21
            and compatibility["v1_assertion_count"] == 148,
            expected={"cases": 21, "assertions": 148},
            observed={
                "cases": len(v1["case"]),
                "assertions": compatibility["v1_assertion_count"],
            },
        )
        checks.check(
            "v1-manifest-baseline-portably-retained",
            retained_manifest_blob
            == compatibility["v1_manifest_adopted_git_blob"]
            and compatibility["v1_manifest_blob_retention"]
            == "REACHABLE_COMMIT_PATH_IDENTITY",
            expected={
                "blob": compatibility["v1_manifest_adopted_git_blob"],
                "retention": "REACHABLE_COMMIT_PATH_IDENTITY",
            },
            observed={
                "blob": retained_manifest_blob,
                "retention": compatibility[
                    "v1_manifest_blob_retention"
                ],
            },
        )
        checks.check(
            "nonportable-adoption-evidence-is-explicit-nodata",
            compatibility["v1_harness_blob_retention"]
            == "UNREACHABLE_LOCAL_OBJECT_NODATA"
            and compatibility["adoption_artifact_retention"]
            == "IGNORED_LOCAL_ONLY_NODATA"
            and compatibility["portable_adoption_evidence"] is False
            and compatibility["compatibility_proof_authority"]
            == "CURRENT_V1_MANIFEST_AND_RUNTIME_REGRESSION_ONLY",
            expected={
                "harness": "UNREACHABLE_LOCAL_OBJECT_NODATA",
                "artifact": "IGNORED_LOCAL_ONLY_NODATA",
                "portable": False,
                "authority": (
                    "CURRENT_V1_MANIFEST_AND_RUNTIME_REGRESSION_ONLY"
                ),
            },
            observed={
                "harness": compatibility[
                    "v1_harness_blob_retention"
                ],
                "artifact": compatibility[
                    "adoption_artifact_retention"
                ],
                "portable": compatibility[
                    "portable_adoption_evidence"
                ],
                "authority": compatibility[
                    "compatibility_proof_authority"
                ],
            },
        )
    else:
        raise EvidenceFailed(f"no schema/CLI/UX executor for {slug}")
    return checks.finish(parameters)


def v2_execute_source_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "source", "slug": slug}

    def capture_state(
        rows: Sequence[Mapping[str, Any]],
        *,
        lint: Mapping[str, Any] | None = None,
        tracker_status: Mapping[str, Any] | None = None,
        capabilities: Mapping[str, Any] | None = None,
        source_files: Sequence[Mapping[str, Any]] | None = None,
        rule_contract: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        ordered = sorted((dict(row) for row in rows), key=lambda row: row["id"])
        normalized_lint = (
            dict(lint)
            if lint is not None
            else fixture_lint(
                ordered,
                {
                    str(row["id"]): tuple(row.get("missing_sections") or ())
                    for row in ordered
                },
            )
        )
        return v2_capture_state(
            issue_ids=[str(row["id"]) for row in ordered],
            full_issues=ordered,
            lint=normalized_lint,
            tracker_status=dict(tracker_status or {"state": "clean"}),
            sync_status={"state": "synchronized"},
            export_witness={"state": "current"},
            version={"version": "0.2.19"},
            capabilities=dict(
                capabilities or {"contract_version": "br.capabilities.v1"}
            ),
            source_files=list(
                source_files
                or [
                    {
                        "path": "synthetic-source",
                        "bytes": 1,
                        "content_identity": text_root("x"),
                    }
                ]
            ),
            rule_contract=dict(
                rule_contract
                or {
                    "classifier": (
                        "synthetic-independent-template-findings"
                    )
                }
            ),
        )

    def authentic_capture(
        raw_rows: Sequence[Mapping[str, Any]],
        *,
        missing_by_id: Mapping[str, Sequence[str]] | None = None,
        tracker_status: Mapping[str, Any] | None = None,
        capabilities: Mapping[str, Any] | None = None,
        source_files: Sequence[Mapping[str, Any]] | None = None,
        rule_contract: Mapping[str, Any] | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any], LiveSnapshot, dict[str, Any]]:
        full_issues, lint, snapshot, inventory = (
            v2_authentic_projection_fixture(
                raw_rows,
                missing_by_id=missing_by_id,
            )
        )
        return (
            capture_state(
                full_issues,
                lint=lint,
                tracker_status=tracker_status,
                capabilities=capabilities,
                source_files=source_files,
                rule_contract=rule_contract,
            ),
            lint,
            snapshot,
            inventory,
        )

    if slug == "source-zero-one":
        empty_capture = capture_state([])
        checks.check(
            "empty-source-capture-is-first-class",
            v2_list_issue_ids([], label="empty issue list") == []
            and empty_capture["issue_ids"] == []
            and empty_capture["issue_count"] == 0
            and empty_capture["full_issue_projection_root"]
            == semantic_root([]),
            expected={
                "issue_ids": [],
                "issue_count": 0,
                "full_issue_projection_root": semantic_root([]),
            },
            observed={
                "issue_ids": empty_capture["issue_ids"],
                "issue_count": empty_capture["issue_count"],
                "full_issue_projection_root": empty_capture[
                    "full_issue_projection_root"
                ],
            },
        )
        for count in (0, 1):
            inventory = v2_synthetic_inventory(
                [v2_synthetic_target(0)] if count else []
            )
            checks.check(
                f"cardinality-{count}",
                inventory["counts"]["targets"] == count
                and len(inventory["rows"]) == count,
                expected=count,
                observed=inventory["counts"]["targets"],
            )
        fidelity_target = v2_synthetic_target(
            7,
            issue_id="synthetic-production-root-fidelity",
            priority=1,
            status="in_progress",
            disposition="OWNER_REVIEW_REQUIRED",
            issue_type="bug",
            missing_sections=(
                "## Acceptance Criteria",
                "## Steps to Reproduce",
            ),
            assignee="fixture-owner",
        )
        fidelity_source_issue = v2_synthetic_source_issue(
            fidelity_target
        )
        fidelity_projection = v2_stable_issue_projection(
            fidelity_source_issue
        )
        fidelity_inventory = v2_synthetic_inventory(
            [fidelity_target]
        )
        checks.check(
            "synthetic-target-root-is-production-exact",
            fidelity_target["target_root"]
            == semantic_root(fidelity_projection)
            == v2_target_root(fidelity_source_issue)
            == fidelity_inventory["rows"][0]["target_root"]
            and fidelity_target["dependency_neighborhood_root"]
            == v2_dependency_neighborhood_root(
                fidelity_source_issue
            )
            and fidelity_projection["assignee"] == "fixture-owner"
            and fidelity_projection["owner"] == ""
            and fidelity_projection["type"] == "bug"
            and fidelity_projection["missing_sections"]
            == [
                "## Acceptance Criteria",
                "## Steps to Reproduce",
            ],
            expected={
                "target_root": v2_target_root(
                    fidelity_source_issue
                ),
                "dependency_root": v2_dependency_neighborhood_root(
                    fidelity_source_issue
                ),
                "source_projection": fidelity_projection,
            },
            observed={
                "target_root": fidelity_target["target_root"],
                "inventory_target_root": fidelity_inventory["rows"][0][
                    "target_root"
                ],
                "dependency_root": fidelity_target[
                    "dependency_neighborhood_root"
                ],
                "source_projection": fidelity_projection,
            },
        )
        drifted_fidelity_target = dict(fidelity_target)
        drifted_fidelity_target.pop("semantic_root", None)
        drifted_fidelity_target["title"] = (
            "Synthetic source title changed after root construction"
        )
        drifted_fidelity_target = v2_rooted(
            drifted_fidelity_target
        )
        checks.refuses(
            "synthetic-source-field-drift-refused",
            EvidenceFailed,
            lambda: v2_synthetic_inventory(
                [drifted_fidelity_target]
            ),
            contains=(
                "target root differs from the production stable issue "
                "projection"
            ),
        )
        no_warning_id = "fixture-no-template-warning"
        _, _, no_warning_snapshot, no_warning_inventory = authentic_capture(
            [
                fixture_issue(
                    issue_id=no_warning_id,
                    status="open",
                )
            ],
            missing_by_id={no_warning_id: ()},
        )
        no_warning_row = no_warning_snapshot.inventory["rows"][0]
        derived_no_warning = v2_derive_authority(
            no_warning_inventory,
            v2_empty_review_receipts(
                inventory_root=no_warning_inventory["semantic_root"],
                campaign_epoch_root=no_warning_inventory[
                    "campaign_epoch_root"
                ],
            ),
            current_br_version="0.2.19",
        )["decisions"][0]
        checks.check(
            "nonclosed-no-warning-still-inventoried-unreviewed",
            no_warning_snapshot.inventory["counts"][
                "complete_review_scope_issues"
            ]
            == 1
            and no_warning_snapshot.inventory["counts"][
                "no_template_warning_issues"
            ]
            == 1
            and no_warning_row["template_warning_state"] == "NONE"
            and no_warning_row["semantic_review_disposition"]
            == "BLOCKED_AUTHORITY"
            and no_warning_row["semantic_review_receipt_state"]
            == "UNREVIEWED"
            and no_warning_row["semantic_review_dimensions"]
            == v2_unreviewed_semantic_dimensions()
            and no_warning_row["semantic_review_receipt_root"] is None
            and derived_no_warning["semantic_review_action"]
            == "SEMANTIC_REVIEW_REQUIRED"
            and no_warning_inventory["rows"][0]["id"] == no_warning_id,
            expected={
                "complete_scope": 1,
                "warning_state": "NONE",
                "review_state": "UNREVIEWED",
                "disposition": "BLOCKED_AUTHORITY",
            },
            observed={
                "counts": no_warning_snapshot.inventory["counts"],
                "warning_state": no_warning_row["template_warning_state"],
                "review_state": no_warning_row[
                    "semantic_review_receipt_state"
                ],
                "disposition": no_warning_row[
                    "semantic_review_disposition"
                ],
                "semantic_action": derived_no_warning[
                    "semantic_review_action"
                ],
            },
        )
        malformed_unreviewed = dict(no_warning_inventory["rows"][0])
        malformed_unreviewed["semantic_review_dimensions"] = (
            v2_unreviewed_semantic_dimensions()[:-1]
        )
        checks.refuses(
            "partial-unreviewed-dimensions-refused",
            InputRefused,
            lambda: v2_validate_unreviewed_semantic_contract(
                malformed_unreviewed,
                label="malformed unreviewed fixture",
            ),
            contains="exact unreviewed semantic contract",
        )
        closed_id = "fixture-closed-without-finding"
        _, _, closed_snapshot, closed_inventory = authentic_capture(
            [
                fixture_issue(
                    issue_id=closed_id,
                    status="closed",
                )
            ],
            missing_by_id={closed_id: ()},
        )
        checks.check(
            "closed-no-finding-remains-outside-active-review-scope",
            closed_snapshot.inventory["rows"] == []
            and closed_inventory["rows"] == [],
            expected=0,
            observed=len(closed_inventory["rows"]),
        )
    elif slug in {
        "source-rows-9-10-11",
        "source-rows-12-13",
        "source-rows-24-25-26",
    }:
        configurations = {
            "source-rows-9-10-11": (10, (9, 10, 11)),
            "source-rows-12-13": (13, (12, 13)),
            "source-rows-24-25-26": (25, (24, 25, 26)),
        }
        cap, populations = configurations[slug]
        for population in populations:
            plan, _, _ = v2_plan_for_count(
                population,
                max_targets=cap,
            )
            expected_children = math.ceil(population / cap)
            mapped = [
                target_id
                for child in plan["children"]
                for target_id in child["target_ids"]
            ]
            checks.check(
                f"population-{population}",
                len(plan["children"]) == expected_children
                and len(mapped) == population
                and len(mapped) == len(set(mapped)),
                expected={"children": expected_children, "targets": population},
                observed={
                    "children": len(plan["children"]),
                    "targets": len(mapped),
                },
            )
    elif slug == "source-rows-4096":
        v2_validate_source_limits(
            row_count=4_096,
            warning_count=0,
            maximum_warnings_per_issue=0,
        )
        checks.check(
            "row-cap-admitted",
            True,
            expected=4_096,
            observed=4_096,
        )
        checks.refuses(
            "row-cap-plus-one",
            InputRefused,
            lambda: v2_validate_source_limits(
                row_count=4_097,
                warning_count=0,
                maximum_warnings_per_issue=0,
            ),
            contains="row count",
        )
    elif slug == "source-warnings-8192":
        v2_validate_source_limits(
            row_count=2_731,
            warning_count=8_192,
            maximum_warnings_per_issue=3,
        )
        checks.check(
            "warning-cap-admitted",
            True,
            expected=8_192,
            observed=8_192,
        )
        checks.refuses(
            "warning-cap-plus-one",
            InputRefused,
            lambda: v2_validate_source_limits(
                row_count=2_731,
                warning_count=8_193,
                maximum_warnings_per_issue=3,
            ),
            contains="warning count",
        )
    elif slug == "source-all-types-statuses-priorities":
        statuses = ["open", "in_progress", "blocked", "deferred", "closed"]
        types = ["bug", "task", "feature", "epic", "chore", "docs", "question", "custom:x"]
        rows = [
            v2_synthetic_target(
                index,
                priority=index % 5,
                status=statuses[index % len(statuses)],
                issue_type=types[index % len(types)],
            )
            for index in range(40)
        ]
        checks.check(
            "covering-array-priorities",
            {row["priority"] for row in rows} == set(range(5)),
            expected=list(range(5)),
            observed=sorted({row["priority"] for row in rows}),
        )
        checks.check(
            "covering-array-statuses-types",
            {row["status"] for row in rows} == set(statuses)
            and {row["type"] for row in rows} == set(types),
            expected={"statuses": statuses, "types": types},
            observed={
                "statuses": sorted({row["status"] for row in rows}),
                "types": sorted({row["type"] for row in rows}),
            },
        )
        raw_rows = [
            fixture_issue(
                issue_id=(
                    f"fixture-enum-{type_index:02d}-"
                    f"{status_index:02d}-{priority}"
                ),
                issue_type=issue_type,
                status=status,
                priority=priority,
            )
            for type_index, issue_type in enumerate(types)
            for status_index, status in enumerate(statuses)
            for priority in range(5)
        ]
        full_issues, _, _, authentic_inventory = (
            v2_authentic_projection_fixture(raw_rows)
        )
        expected_product = {
            (issue_type, status, priority)
            for issue_type in types
            for status in statuses
            for priority in range(5)
        }
        observed_product = {
