            },
            observed=nonfixture_decision,
        )
    elif slug == "route-manual-distinct":
        manual = v2_synthetic_authority(
            base_inventory,
            declared=True,
            manual=True,
        )["decisions"][0]
        automated = v2_synthetic_authority(
            base_inventory,
            declared=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=True,
        )["decisions"][0]
        analysis = v2_synthetic_authority(base_inventory)["decisions"][0]
        checks.check(
            "three-routes-distinct",
            {
                analysis["remediation_route"],
                manual["remediation_route"],
                automated["remediation_route"],
            }
            == set(V2_REMEDIATION_ROUTES),
            expected=sorted(V2_REMEDIATION_ROUTES),
            observed=sorted(
                {
                    analysis["remediation_route"],
                    manual["remediation_route"],
                    automated["remediation_route"],
                }
            ),
        )
        checks.check(
            "manual-no-cas-claims",
            manual["manual_authorization"]["mechanical_authority"] is False
            and manual["manual_authorization"][
                "no_cas_no_clobber_no_exactly_once"
            ]
            is True,
            expected=True,
            observed=manual["manual_authorization"],
        )
    elif slug == "route-deferred-reactivation":
        deferred_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0, status="deferred")]
        )
        deferred_receipts = v2_synthetic_receipts(
            deferred_inventory,
            declared=True,
            manual=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
        )
        authority = v2_derive_authority(
            deferred_inventory,
            deferred_receipts,
            current_br_version="0.3.0",
            allow_mechanical_fixture=True,
        )
        decision = authority["decisions"][0]
        deferred_plan, _ = v2_build_review_plan(
            deferred_inventory,
            authority,
            max_targets=10,
        )
        checks.check(
            "deferred-always-analysis",
            decision["remediation_route"] == "ANALYSIS_ONLY"
            and decision["deferred_apply_prohibition"] is True
            and deferred_plan["children"][0]["desired_status"] == "deferred",
            expected=("ANALYSIS_ONLY", True, "deferred"),
            observed=(
                decision["remediation_route"],
                decision["deferred_apply_prohibition"],
                deferred_plan["children"][0]["desired_status"],
            ),
        )
        reactivated_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0, status="open")]
        )
        checks.check(
            "reactivation-requires-fresh-capture-and-reinventory",
            reactivated_inventory["semantic_root"]
            != deferred_inventory["semantic_root"]
            and reactivated_inventory["campaign_epoch_root"]
            != deferred_inventory["campaign_epoch_root"]
            and reactivated_inventory["rows"][0]["target_root"]
            != deferred_inventory["rows"][0]["target_root"],
            expected="all deferred source bindings change on reactivation",
            observed={
                "deferred_inventory": deferred_inventory["semantic_root"],
                "reactivated_inventory": reactivated_inventory["semantic_root"],
                "deferred_campaign": deferred_inventory[
                    "campaign_epoch_root"
                ],
                "reactivated_campaign": reactivated_inventory[
                    "campaign_epoch_root"
                ],
            },
        )
        checks.refuses(
            "deferred-receipt-refused-after-reactivation",
            InputRefused,
            lambda: v2_derive_authority(
                reactivated_inventory,
                deferred_receipts,
                current_br_version="0.3.0",
                allow_mechanical_fixture=True,
            ),
            contains="different source or schema",
        )
        reactivated_receipts = v2_synthetic_receipts(
            reactivated_inventory,
            declared=True,
            manual=True,
        )
        reactivated_authority = v2_derive_authority(
            reactivated_inventory,
            reactivated_receipts,
            current_br_version="0.2.19",
        )
        reactivated_plan, _ = v2_build_review_plan(
            reactivated_inventory,
            reactivated_authority,
            max_targets=10,
        )
        reactivated_decision = reactivated_authority["decisions"][0]
        checks.check(
            "owner-reviewed-fresh-reactivation-replans-manual-open",
            reactivated_decision["remediation_route"] == "MANUAL_BR_REVIEW"
            and reactivated_decision["deferred_apply_prohibition"] is False
            and reactivated_decision["manual_authorization"]["declared"] is True
            and reactivated_plan["inventory_root"]
            == reactivated_inventory["semantic_root"]
            and reactivated_plan["authority_root"]
            == reactivated_authority["semantic_root"]
            and reactivated_plan["children"][0]["desired_status"] == "open",
            expected={
                "route": "MANUAL_BR_REVIEW",
                "prohibition": False,
                "desired_status": "open",
            },
            observed={
                "route": reactivated_decision["remediation_route"],
                "prohibition": reactivated_decision[
                    "deferred_apply_prohibition"
                ],
                "manual": reactivated_decision["manual_authorization"],
                "desired_status": reactivated_plan["children"][0][
                    "desired_status"
                ],
            },
        )
    elif slug == "route-active-owner-conflict":
        for status, assignee in (("in_progress", ""), ("open", "agent")):
            inventory = v2_synthetic_inventory(
                [v2_synthetic_target(0, status=status, assignee=assignee)]
            )
            authority = v2_synthetic_authority(
                inventory,
                declared=True,
                manual=True,
            )
            plan, _ = v2_build_review_plan(
                inventory,
                authority,
                max_targets=10,
            )
            checks.check(
                f"active-{status}-{str(bool(assignee)).lower()}",
                authority["decisions"][0]["remediation_route"] == "ANALYSIS_ONLY"
                and plan["children"][0]["desired_status"] == "deferred",
                expected=("ANALYSIS_ONLY", "deferred"),
                observed=(
                    authority["decisions"][0]["remediation_route"],
                    plan["children"][0]["desired_status"],
                ),
            )
    elif slug == "route-no-target-mutation":
        mutation_target = v2_synthetic_target(
            0,
            assignee="",
            priority=1,
            status="open",
        )
        mutation_target = {
            **mutation_target,
            "labels": ["e2e", "fresh-eyes"],
            "parent": "synthetic-parent",
            "dependencies": [
                {
                    "id": "external:upstream",
                    "type": "blocks",
                    "status": "open",
                    "priority": 0,
                }
            ],
            "dependents": [
                {
                    "id": "synthetic-consumer",
                    "type": "related",
                    "status": "open",
                    "priority": 2,
                }
            ],
        }
        mutation_target.pop("semantic_root", None)
        mutation_source_issue = v2_synthetic_source_issue(
            mutation_target
        )
        mutation_target["dependency_neighborhood_root"] = (
            v2_dependency_neighborhood_root(mutation_source_issue)
        )
        mutation_target["target_root"] = v2_target_root(
            mutation_source_issue
        )
        mutation_target = v2_rooted(mutation_target)
        mutation_inventory = v2_synthetic_inventory([mutation_target])
        target_projection = lambda: mutation_inventory["rows"]
        before = semantic_root(target_projection())
        receipts = v2_synthetic_receipts(
            mutation_inventory,
            declared=True,
            manual=True,
        )
        authority = v2_derive_authority(
            mutation_inventory,
            receipts,
            current_br_version="0.2.19",
        )
        plan, _ = v2_build_review_plan(
            mutation_inventory,
            authority,
            max_targets=10,
        )
        synopsis = v2_synopsis(
            subject_mode="review-plan",
            review_plan=plan,
            history={"rows": []},
            authority=authority,
            zero_sets={"counts": {"zero_receipts": 0}},
            artifact_dir="target/v2-fixture/no-target-mutation",
            reproduction=["script", "--review-plan"],
            explain_target=mutation_target["id"],
        )
        after = semantic_root(target_projection())
        checks.check(
            "success-receipt-route-plan-explanation-target-unchanged",
            before == after
            and authority["decisions"][0]["remediation_route"]
            == "MANUAL_BR_REVIEW"
            and synopsis["explanation"]["target_id"]
            == mutation_target["id"],
            expected=before,
            observed={
                "after": after,
                "route": authority["decisions"][0]["remediation_route"],
                "explanation": synopsis["explanation"],
            },
        )
        stale_receipts = strict_json_loads(
            canonical_bytes(receipts),
            label="no-target-mutation stale receipt seed",
            require_canonical=True,
        )
        stale_receipts["inventory_root"] = semantic_root(
            {"stale": "inventory"}
        )
        checks.refuses(
            "receipt-failure-target-unchanged",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                stale_receipts,
                mutation_inventory,
            ),
            contains="different source or schema",
            projection=target_projection,
            projection_label="EXACT_TARGET_ROWS_BYTES",
        )
        checks.refuses(
            "explanation-failure-target-unchanged",
            InputRefused,
            lambda: v2_synopsis(
                subject_mode="review-plan",
                review_plan=plan,
                history={"rows": []},
                authority=authority,
                zero_sets={"counts": {"zero_receipts": 0}},
                artifact_dir="target/v2-fixture/no-target-mutation",
                reproduction=["script", "--review-plan"],
                explain_target="absent-target",
            ),
            contains="not selected",
            projection=target_projection,
            projection_label="EXACT_TARGET_ROWS_BYTES",
        )
        incompatible_authority = v2_synthetic_authority(
            mutation_inventory,
            declared=False,
            manual=False,
        )
        v2_build_review_plan(
            mutation_inventory,
            incompatible_authority,
            max_targets=10,
        )
        checks.check(
            "analysis-route-target-unchanged",
            semantic_root(target_projection()) == before
            and incompatible_authority["decisions"][0][
                "remediation_route"
            ]
            == "ANALYSIS_ONLY",
            expected=(before, "ANALYSIS_ONLY"),
            observed=(
                semantic_root(target_projection()),
                incompatible_authority["decisions"][0][
                    "remediation_route"
                ],
            ),
        )
    else:
        raise EvidenceFailed(f"no authority executor for {slug}")
    return checks.finish(parameters)


def v2_execute_packing_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    del manifest
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "packing", "slug": slug}
    if slug == "packing-hard-keys":
        base = v2_synthetic_target(0)
        authority = v2_synthetic_authority(
            v2_synthetic_inventory([base])
        )["decisions"][0]
        base_vector = v2_hard_vector(base, authority)
        mutations = {
            "priority": {"priority": 3},
            "status": {"status": "blocked"},
            "disposition": {"disposition": "OWNER_REVIEW_REQUIRED"},
            "type": {"type": "bug"},
            "missing": {"missing_sections": ["## Success Criteria"]},
        }
        for name, changes in mutations.items():
            target = dict(base)
            target.update(changes)
            checks.check(
                f"hard-key-{name}",
                v2_hard_vector(target, authority) != base_vector,
                expected="different vector",
                observed=v2_hard_vector(target, authority),
            )
        changed_authority = dict(authority)
        changed_authority["semantic_review_disposition"] = (
            "BLOCKED_AUTHORITY"
        )
        checks.check(
            "hard-key-semantic-review-disposition",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["semantic_review_receipt_state"] = (
            "ROOT_BOUND_REVIEWED"
        )
        checks.check(
            "hard-key-semantic-review-receipt-state",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["semantic_review_action"] = (
            "AUTHORITY_RESOLUTION_REQUIRED"
        )
        checks.check(
            "hard-key-semantic-review-action",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["readiness"] = "DECLARED_READY"
        checks.check(
            "hard-key-readiness",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["remediation_route"] = "MANUAL_BR_REVIEW"
        checks.check(
            "hard-key-remediation-route",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
    elif slug == "packing-compatible-receipt":
        plan, _, _ = v2_plan_for_count(2, max_targets=10)
        checks.check(
            "compatible-merge",
            len(plan["children"]) == 1
            and len(plan["children"][0]["target_ids"]) == 2,
            expected={"children": 1, "targets": 2},
            observed={
                "children": len(plan["children"]),
                "targets": len(plan["children"][0]["target_ids"]),
            },
        )
        checks.check(
            "receipt-rationale-falsifier",
            bool(plan["children"][0]["compatibility"]["rationale"])
            and bool(plan["children"][0]["compatibility"]["falsifier"]),
            expected=True,
            observed=plan["children"][0]["compatibility"],
        )
    elif slug == "packing-generic-merge-refused":
        def check_hostile_twins(
            name: str,
            targets: Sequence[Mapping[str, Any]],
            *,
            declared: bool = False,
        ) -> None:
            inventory = v2_synthetic_inventory(targets)
            authority = v2_synthetic_authority(
                inventory,
                declared=declared,
            )
            plan, _ = v2_build_review_plan(
                inventory,
                authority,
                max_targets=10,
            )
            children = plan["children"]
            checks.check(
                f"{name}-cannot-merge",
                len(children) == len(targets) == 2
                and all(
                    len(child["target_ids"]) == 1
                    and child["compatibility"]["target_complete"] is False
                    and child["compatibility"]["key"] == ""
                    and child["compatibility"]["target_ids"] == []
                    for child in children
                )
                and sorted(
                    target_id
                    for child in children
                    for target_id in child["target_ids"]
                )
                == sorted(str(target["id"]) for target in targets),
                expected={
                    "children": 2,
                    "target_counts": [1, 1],
                    "compatibility": "absent",
                },
                observed={
                    "children": len(children),
                    "target_counts": [
                        len(child["target_ids"]) for child in children
                    ],
                    "compatibility": [
                        child["compatibility"] for child in children
                    ],
                },
            )

        check_hostile_twins(
            "bare-type-twins",
            [
                v2_synthetic_target(
                    0,
                    issue_id="generic-bare-type-a",
                    issue_type="task",
                ),
                v2_synthetic_target(
                    1,
                    issue_id="generic-bare-type-b",
                    issue_type="task",
                ),
            ],
        )
        lexical_a = v2_synthetic_target(
            0,
            issue_id="generic-lexical-a",
        )
        lexical_b = v2_synthetic_target(
            1,
            issue_id="generic-lexical-b",
        )
        lexical_a = v2_rooted(
            {
                **{
                    key: value
                    for key, value in lexical_a.items()
                    if key != "semantic_root"
                },
                "title": "Review mesh import boundary",
            }
        )
        lexical_a = dict(lexical_a)
        lexical_a.pop("semantic_root", None)
        lexical_a["target_root"] = v2_target_root(
            v2_synthetic_source_issue(lexical_a)
        )
        lexical_a = v2_rooted(lexical_a)
        lexical_b = v2_rooted(
            {
                **{
                    key: value
                    for key, value in lexical_b.items()
                    if key != "semantic_root"
                },
                "title": "Review mesh imports boundary",
            }
        )
        lexical_b = dict(lexical_b)
        lexical_b.pop("semantic_root", None)
        lexical_b["target_root"] = v2_target_root(
            v2_synthetic_source_issue(lexical_b)
        )
        lexical_b = v2_rooted(lexical_b)
        check_hostile_twins(
            "lexical-similarity-twins",
            [lexical_a, lexical_b],
        )
        copied_a = v2_synthetic_target(
            0,
            issue_id="generic-copied-prose-a",
        )
        copied_b = dict(
            v2_synthetic_target(
                1,
                issue_id="generic-copied-prose-b",
            )
        )
        copied_b.pop("semantic_root", None)
        copied_b["field_roots"] = dict(copied_a["field_roots"])
        copied_b["field_byte_lengths"] = dict(
            copied_a["field_byte_lengths"]
        )
        copied_b["clause_roots"] = strict_json_loads(
            canonical_bytes(copied_a["clause_roots"]),
            label="copied-prose clause roots",
            require_canonical=True,
        )
        copied_b["target_root"] = v2_target_root(
            v2_synthetic_source_issue(copied_b)
        )
        copied_b = v2_rooted(copied_b)
        check_hostile_twins(
            "copied-prose-twins",
            [copied_a, copied_b],
        )
        check_hostile_twins(
            "aggregate-warning-count-twins",
            [
                v2_synthetic_target(
                    0,
                    issue_id="generic-count-a",
                    missing_sections=("## Acceptance Criteria",),
                ),
                v2_synthetic_target(
                    1,
                    issue_id="generic-count-b",
                    missing_sections=("## Success Criteria",),
                ),
            ],
        )
        check_hostile_twins(
            "generic-domain-twins",
            [
                v2_synthetic_target(
                    0,
                    issue_id="generic-domain-a",
                ),
                v2_synthetic_target(
                    1,
                    issue_id="generic-domain-b",
                ),
            ],
            declared=True,
        )
    elif slug == "packing-rationale-falsifier":
        singleton, _, _ = v2_plan_for_count(1, max_targets=10)
        merged, _, _ = v2_plan_for_count(2, max_targets=10)
        checks.check(
            "singleton-rationale",
            bool(singleton["children"][0]["compatibility"]["rationale"])
            and bool(singleton["children"][0]["compatibility"]["falsifier"]),
            expected=True,
            observed=singleton["children"][0]["compatibility"],
        )
        checks.check(
            "merge-witness-rationale",
            all(
                witness.get("rationale") and witness.get("falsifier")
                for witness in merged["packing_witnesses"]
            ),
            expected=True,
            observed=merged["packing_witnesses"],
        )
    elif slug == "packing-target-cap-10-25":
        for cap, population, expected_children in (
            (10, 10, 1),
            (10, 11, 2),
            (25, 25, 1),
            (25, 26, 2),
        ):
            plan, _, _ = v2_plan_for_count(population, max_targets=cap)
            checks.check(
                f"cap-{cap}-population-{population}",
                len(plan["children"]) == expected_children,
                expected=expected_children,
                observed=len(plan["children"]),
            )
        inventory = v2_synthetic_inventory([v2_synthetic_target(0)])
        authority = v2_synthetic_authority(inventory)
        checks.refuses(
            "configured-cap-26",
            UsageRefused,
            lambda: v2_build_review_plan(
                inventory,
                authority,
                max_targets=26,
            ),
            contains="1..25",
        )
    elif slug == "packing-minutes-479-480-481":
        for minutes in (479, 480):
            inventory = v2_synthetic_inventory(
                [v2_synthetic_target(0, review_minutes=minutes)]
            )
            authority = v2_synthetic_authority(inventory)
            plan, optional = v2_build_review_plan(
                inventory,
                authority,
                max_targets=10,
            )
            checks.check(
                f"minutes-{minutes}-bounded",
                not optional
                and plan["children"][0]["review_minutes"] == minutes,
                expected=minutes,
                observed=plan["children"][0]["review_minutes"],
            )
        inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0, review_minutes=481)]
        )
        authority = v2_synthetic_authority(inventory)
        plan, optional = v2_build_review_plan(
            inventory,
            authority,
            max_targets=10,
        )
        checks.check(
            "minutes-481-oversize",
            plan["children"][0]["review_minutes"] == 480
            and plan["work"]["total_review_minutes"] == 481
            and len(optional) == 1,
            expected={"bounded": 480, "underlying": 481, "optional": 1},
            observed={
                "bounded": plan["children"][0]["review_minutes"],
                "underlying": plan["work"]["total_review_minutes"],
                "optional": len(optional),
            },
        )
    elif slug == "packing-transport-cap-boundaries":
        inventory = v2_synthetic_inventory([v2_synthetic_target(0)])
        authority = v2_synthetic_authority(inventory)
        plan, _ = v2_build_review_plan(inventory, authority, max_targets=10)
        child = plan["children"][0]
        v2_validate_child_payload(child)
        checks.check(
            "baseline-transport-valid",
            True,
            expected="valid",
            observed=child["semantic_root"],
        )
        baseline_row = (
            inventory["rows"][0],
            authority["decisions"][0],
        )
        preflight_child = v2_make_child(
            [baseline_row],
            packing_witness={
                "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
            },
            _validate_payload=False,
        )
        preflight_observations = v2_child_transport_observations(
            [baseline_row]
        )
        checks.check(
            "generated-child-preflight-size-equals-final-canonical-size",
            preflight_observations["generated_child_payload_bytes"]
            == len(canonical_bytes(preflight_child))
            == len(canonical_bytes(child)),
            expected={
                "preflight": len(canonical_bytes(preflight_child)),
                "final": len(canonical_bytes(child)),
            },
            observed={
                "observation": preflight_observations[
                    "generated_child_payload_bytes"
                ],
                "preflight": len(canonical_bytes(preflight_child)),
                "final": len(canonical_bytes(child)),
            },
        )

        compatible_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    index,
                    issue_id=f"generated-cap-{index}",
                )
                for index in range(2)
            ]
        )
        compatible_authority = v2_synthetic_authority(
            compatible_inventory,
            compatible=True,
        )
        compatible_decisions = {
            row["target_id"]: row
            for row in compatible_authority["decisions"]
        }
        compatible_rows = [
            (target, compatible_decisions[target["id"]])
            for target in compatible_inventory["rows"]
        ]
        prior_generated_cap = V2_GENERATED_CHILD_PAYLOAD_CAP
        prior_transport_cache = dict(_v2_child_transport_cache)
        try:
            _v2_child_transport_cache.clear()
            single_generated_sizes = [
                v2_child_transport_observations([row])[
                    "generated_child_payload_bytes"
                ]
                for row in compatible_rows
            ]
            merged_generated_size = v2_child_transport_observations(
                compatible_rows
            )["generated_child_payload_bytes"]
            globals()["V2_GENERATED_CHILD_PAYLOAD_CAP"] = (
                merged_generated_size
            )
            generated_at_cap = [
                violation
                for violation in v2_child_transport_violations(
                    compatible_rows
                )
                if violation["cap"]
                == "max_generated_child_payload_bytes"
            ]
            globals()["V2_GENERATED_CHILD_PAYLOAD_CAP"] = (
                merged_generated_size - 1
            )
            generated_at_cap_plus_one = [
                violation
                for violation in v2_child_transport_violations(
                    compatible_rows
                )
                if violation["cap"]
                == "max_generated_child_payload_bytes"
            ]
            split_cap = max(single_generated_sizes)
            globals()["V2_GENERATED_CHILD_PAYLOAD_CAP"] = split_cap
            split_bins, split_witness = v2_pack_group(
                compatible_rows,
                max_targets=10,
            )
        finally:
            globals()["V2_GENERATED_CHILD_PAYLOAD_CAP"] = (
                prior_generated_cap
            )
            _v2_child_transport_cache.clear()
            _v2_child_transport_cache.update(prior_transport_cache)
        checks.check(
            "generated-child-payload-cap-exact-and-plus-one",
            merged_generated_size > max(single_generated_sizes)
            and generated_at_cap == []
            and len(generated_at_cap_plus_one) == 1
            and generated_at_cap_plus_one[0]["observed"]
            == merged_generated_size
            and generated_at_cap_plus_one[0]["limit"]
            == merged_generated_size - 1,
            expected={
                "exact": "admitted",
                "plus_one": "one generated-payload violation",
            },
            observed={
                "single_sizes": single_generated_sizes,
                "merged_size": merged_generated_size,
                "exact_violations": generated_at_cap,
                "plus_one_violations": generated_at_cap_plus_one,
            },
        )
        checks.check(
            "generated-child-payload-cap-forces-compatible-split",
            len(split_bins) == 2
            and all(len(batch) == 1 for batch in split_bins)
            and split_witness["algorithm"] == "EXACT_SUBSET_PARTITION",
            expected={
                "children": 2,
                "members_per_child": [1, 1],
                "algorithm": "EXACT_SUBSET_PARTITION",
            },
            observed={
                "children": len(split_bins),
                "members_per_child": [
                    len(batch) for batch in split_bins
                ],
                "algorithm": split_witness["algorithm"],
            },
        )
        cardinality_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    index,
                    issue_id=f"child-cardinality-{index:02d}",
                )
                for index in range(
                    V2_REVIEW_TARGET_HARD_MAX + 1
                )
            ]
        )
        cardinality_authority = v2_synthetic_authority(
            cardinality_inventory,
            compatible=True,
        )
        cardinality_decisions = {
            row["target_id"]: row
            for row in cardinality_authority["decisions"]
        }
        cardinality_rows = [
            (target, cardinality_decisions[target["id"]])
            for target in cardinality_inventory["rows"]
        ]
        admitted_cardinalities: list[int] = []
        for target_count in (
            V2_REVIEW_TARGET_HARD_MAX - 1,
            V2_REVIEW_TARGET_HARD_MAX,
        ):
            cardinality_child = v2_make_child(
                cardinality_rows[:target_count],
                packing_witness={
                    "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
                },
                _validate_payload=False,
            )
            v2_validate_child_payload(cardinality_child)
            admitted_cardinalities.append(target_count)
        checks.check(
            "planned-child-hard-cap-n-minus-one-and-n",
            admitted_cardinalities
            == [
                V2_REVIEW_TARGET_HARD_MAX - 1,
                V2_REVIEW_TARGET_HARD_MAX,
            ],
            expected=[
                V2_REVIEW_TARGET_HARD_MAX - 1,
                V2_REVIEW_TARGET_HARD_MAX,
            ],
            observed=admitted_cardinalities,
        )
        over_cardinality_child = v2_make_child(
            cardinality_rows,
            packing_witness={
                "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
            },
            _validate_payload=False,
        )
        checks.refuses(
            "planned-child-hard-cap-plus-one",
            EvidenceFailed,
            lambda: v2_validate_child_payload(over_cardinality_child),
            contains="hard cap",
        )

        def child_with_text(
            **values: str,
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(child),
                label="planned child transport mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            if "description" in values:
                description = dict(
                    candidate["description_file_artifact"]
                )
                description["content"] = values["description"]
                description["bytes"] = len(
                    values["description"].encode("utf-8")
                )
                description["root"] = text_root(
                    values["description"]
                )
                candidate["description_file_artifact"] = description
                candidate["description_root"] = description["root"]
            if "acceptance" in values:
                candidate["acceptance_criteria"] = values["acceptance"]
                candidate["acceptance"] = values["acceptance"]
            if "design" in values:
                candidate["design"] = values["design"]
            if "notes" in values:
                candidate["notes"] = values["notes"]
            return v2_rooted(candidate)

        transport_caps = {
            "description": V2_CHILD_DESCRIPTION_CAP,
            "acceptance": V2_CHILD_ACCEPTANCE_CAP,
            "design": V2_CHILD_DESIGN_CAP,
            "notes": V2_CHILD_NOTES_CAP,
        }
        for field, cap in transport_caps.items():
            admitted: list[int] = []
            for length in (cap - 1, cap):
                candidate = child_with_text(
                    **{field: "x" * length}
                )
                v2_validate_child_payload(candidate)
                admitted.append(length)
            checks.check(
                f"{field}-transport-n-minus-one-and-n",
                admitted == [cap - 1, cap],
                expected=[cap - 1, cap],
                observed=admitted,
            )
            oversized = child_with_text(
                **{field: "x" * (cap + 1)}
            )
            checks.refuses(
                f"{field}-transport-cap-plus-one",
                EvidenceFailed,
                lambda oversized=oversized: (
                    v2_validate_child_payload(oversized)
                ),
                contains=field,
            )

        aggregate_exact = child_with_text(
            acceptance="a" * V2_CHILD_ACCEPTANCE_CAP,
            design="d" * V2_CHILD_DESIGN_CAP,
            notes="n"
            * (
                V2_CHILD_ARGV_AGGREGATE_CAP
                - V2_CHILD_ACCEPTANCE_CAP
                - V2_CHILD_DESIGN_CAP
            ),
        )
        v2_validate_child_payload(aggregate_exact)
        checks.check(
            "aggregate-nondescription-argv-cap-exact",
            sum(
                len(aggregate_exact[field].encode("utf-8"))
                for field in (
                    "acceptance_criteria",
                    "design",
                    "notes",
                )
            )
            == V2_CHILD_ARGV_AGGREGATE_CAP,
            expected=V2_CHILD_ARGV_AGGREGATE_CAP,
            observed=sum(
                len(aggregate_exact[field].encode("utf-8"))
                for field in (
                    "acceptance_criteria",
                    "design",
                    "notes",
                )
            ),
        )
        aggregate_plus_one = child_with_text(
            acceptance="a" * V2_CHILD_ACCEPTANCE_CAP,
            design="d" * V2_CHILD_DESIGN_CAP,
            notes="n"
            * (
                V2_CHILD_ARGV_AGGREGATE_CAP
                - V2_CHILD_ACCEPTANCE_CAP
                - V2_CHILD_DESIGN_CAP
                + 1
            ),
        )
        checks.refuses(
            "aggregate-nondescription-cap-plus-one-refused",
            EvidenceFailed,
            lambda: v2_validate_child_payload(aggregate_plus_one),
            contains="aggregate non-description argv",
        )
        retained_boundary_states: list[tuple[int, int]] = []
        for retained_bytes in (
            V2_CHILD_PAYLOAD_CAP - 1,
            V2_CHILD_PAYLOAD_CAP,
        ):
            boundary_inventory = v2_synthetic_inventory(
                [
                    v2_synthetic_target(
                        retained_bytes,
                        issue_id=f"retained-{retained_bytes}",
                        retained_payload_bytes=retained_bytes,
                    )
                ]
            )
            boundary_authority = v2_synthetic_authority(
                boundary_inventory
            )
            boundary_plan, boundary_optional = v2_build_review_plan(
                boundary_inventory,
                boundary_authority,
                max_targets=10,
            )
            retained_boundary_states.append(
                (
                    len(boundary_plan["oversize_content"]),
                    len(boundary_optional),
                )
            )
        checks.check(
            "retained-payload-n-minus-one-and-n-standard",
            retained_boundary_states == [(0, 0), (0, 0)],
            expected=[(0, 0), (0, 0)],
            observed=retained_boundary_states,
        )
        oversize_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    V2_CHILD_PAYLOAD_CAP + 1,
                    issue_id="retained-cap-plus-one",
                    retained_payload_bytes=V2_CHILD_PAYLOAD_CAP + 1,
                )
            ]
        )
        oversize_authority = v2_synthetic_authority(
            oversize_inventory
        )
        oversize_plan, oversize_optional = v2_build_review_plan(
            oversize_inventory,
            oversize_authority,
            max_targets=10,
        )
        checks.check(
            "retained-payload-cap-plus-one-routes-oversize",
            len(oversize_plan["oversize_content"]) == 1
            and len(oversize_optional) == 1,
            expected={"registry": 1, "optional": 1},
            observed={
                "registry": len(oversize_plan["oversize_content"]),
                "optional": len(oversize_optional),
            },
        )
        bounded_review_fields = (
            "children",
            "packing_witnesses",
            "semantic_adjudications",
            "retained_without_direct_child",
            "remediation_candidates",
            "oversize_content",
        )
        prior_inventory_rows_cap = V2_INVENTORY_ROWS_CAP
        try:
            globals()["V2_INVENTORY_ROWS_CAP"] = 0
            for field in bounded_review_fields:
                stale_plan = strict_json_loads(
                    canonical_bytes(plan),
                    label="review-plan collection cap mutation seed",
                    require_canonical=True,
                )
                for bounded_field in bounded_review_fields:
                    stale_plan[bounded_field] = []
                stale_plan[field] = [{}]
                checks.refuses(
                    f"review-plan-{field}-cap-precedes-stale-root",
                    EvidenceFailed,
                    lambda stale_plan=stale_plan: v2_validate_review_plan(
                        stale_plan,
                        inventory,
                        authority,
                    ),
                    contains="row cap",
                )
            checks.refuses(
                "review-plan-builder-cap-precedes-rooting",
