                ),
            ),
            (
                "start-argv",
                lambda rows: rows[0].__setitem__(
                    "argv",
                    [str(SCRIPT_REL), "--history-plan"],
                ),
            ),
            (
                "later-argv",
                lambda rows: rows[1].__setitem__(
                    "argv",
                    ["forged"],
                ),
            ),
            (
                "prior-event-roots",
                lambda rows: rows[-1]["semantic_projection"].__setitem__(
                    "prior_event_roots",
                    [semantic_root({"forged": "prior"})],
                ),
            ),
        ]
        for falsifier_name, mutation in event_falsifiers:
            (
                candidate_payloads,
                candidate_terminal,
                candidate_events,
            ) = reroot_refusal_events(mutation)
            checks.refuses(
                f"rerooted-refusal-{falsifier_name}-refused",
                EvidenceFailed,
                lambda candidate_payloads=candidate_payloads,
                candidate_terminal=candidate_terminal,
                candidate_events=candidate_events: validate_refusal(
                    candidate_payloads=candidate_payloads,
                    candidate_terminal=candidate_terminal,
                    candidate_events=candidate_events,
                ),
                contains="exact reconstruction",
            )

        for field, forged_value in (
            ("artifact_root", "/absolute/forged"),
            ("artifact_root", "target/other-root"),
            ("artifact_dir", "../escape"),
            ("artifact_dir", "other-run"),
            ("replay_equivalence", {"forged": "equivalence"}),
            ("recovery", "MANUAL_RECOVERY_REQUIRED"),
        ):
            candidate_terminal = dict(refusal_terminal)
            candidate_terminal[field] = forged_value
            candidate_terminal = v2_rooted(candidate_terminal)
            candidate_payloads = bind_refusal_terminal(
                refusal_payloads,
                candidate_terminal,
            )
            checks.refuses(
                f"rerooted-refusal-terminal-{field}-{text_root(str(forged_value))[-8:]}",
                EvidenceFailed,
                lambda candidate_payloads=candidate_payloads,
                candidate_terminal=candidate_terminal: validate_refusal(
                    candidate_payloads=candidate_payloads,
                    candidate_terminal=candidate_terminal,
                ),
                contains="terminal contract differs",
            )
        changed = payloads["inventory-v2.json"] + b" "
        observed_identity = v2_artifact_identity(
            relative_path="inventory-v2.json",
            schema_kind=V2_INVENTORY_SCHEMA,
            payload=changed,
        )
        checks.check(
            "changed-artifact-identity-detected",
            observed_identity
            != terminal["artifact_identities"]["inventory-v2.json"],
            expected=terminal["artifact_identities"]["inventory-v2.json"],
            observed=observed_identity,
        )
        checks.check(
            "mixed-v1-schema-refused",
            RUN_TERMINAL_SCHEMA != V2_TERMINAL_SCHEMA,
            expected=V2_TERMINAL_SCHEMA,
            observed=RUN_TERMINAL_SCHEMA,
        )
    else:
        raise EvidenceFailed(f"no artifact executor for {slug}")
    return checks.finish(parameters)


def v2_failure_evidence(
    *,
    stage: str,
    detail: str,
    expected: Any = None,
    observed: Any = None,
    terminal: str = "EvidenceFailed",
    manifest_root: str | None = None,
    available_roots: Mapping[str, str | None] | None = None,
) -> dict[str, Any]:
    if terminal not in V2_SEMANTIC_REFUSAL_TERMINALS:
        raise EvidenceFailed("v2 failure evidence terminal is not semantic")
    divergence = (
        first_projection_divergence(expected, observed)
        if expected is not None or observed is not None
        else None
    )
    recovery = {
        "InputRefused": "CORRECT_INPUT_AND_RETRY_IN_FRESH_RUN_DIR",
        "NoData": "PROVIDE_REQUIRED_DATA_AND_RETRY_IN_FRESH_RUN_DIR",
        "EvidenceFailed": "MANUAL_RECOVERY_REQUIRED",
    }[terminal]
    normalized_roots = {
        key: (available_roots or {}).get(key)
        for key in (
            "source",
            "inventory",
            "authority",
            "review_plan",
            "history",
            "zero_sets",
        )
    }
    return v2_rooted(
        {
            "schema": V2_FAILURE_EVIDENCE_SCHEMA,
            "result_category": "SEMANTIC_REFUSAL",
            "stage": stage,
            "terminal": terminal,
            "exit_code": TERMINAL_EXIT[terminal],
            "diagnostic_code": f"{terminal}:{stage}",
            "detail_root": text_root(detail),
            "first_divergence": divergence or f"$.pipeline.{stage}",
            "recovery": recovery,
            "manifest_root": manifest_root,
            "available_roots": normalized_roots,
            "output_reserved": True,
            "complete_evidence_bundle": True,
            "complete_green_prefix": False,
            "retry_requires_fresh_run_dir": True,
            "no_claim": (
                "failure evidence identifies recovery work and never seals a "
                "partial or ambiguous publication as green"
            ),
        }
    )


def v2_execute_fault_resource_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "fault-resource-mutation", "slug": slug}
    inventory = v2_synthetic_inventory([v2_synthetic_target(0)])

    if slug == "mutation-forged-approval":
        forged = v2_synthetic_receipts(inventory, declared=True)
        forged_row = dict(forged["receipts"][0])
        forged_row["target_root"] = semantic_root({"forged": "stale-target"})
        forged_row = v2_rooted(forged_row)
        forged_document = dict(forged)
        forged_document["receipts"] = [forged_row]
        forged_document = v2_rooted(forged_document)
        checks.refuses(
            "stale-root-forged-approval",
            InputRefused,
            lambda: v2_derive_authority(
                inventory,
                forged_document,
                current_br_version="0.3.0",
                allow_mechanical_fixture=True,
            ),
            contains="target root drifted",
        )
        untrusted = v2_synthetic_authority(
            inventory,
            declared=True,
            manual=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=False,
        )["decisions"][0]
        checks.check(
            "self-issued-receipts-never-mechanical",
            untrusted["readiness"] == "DECLARED_READY"
            and untrusted["remediation_route"] == "MANUAL_BR_REVIEW"
            and untrusted["external_authority"]["verified"] is False
            and untrusted["conditional_write_capability"]["verified"] is False,
            expected=("DECLARED_READY", "MANUAL_BR_REVIEW", False, False),
            observed=(
                untrusted["readiness"],
                untrusted["remediation_route"],
                untrusted["external_authority"]["verified"],
                untrusted["conditional_write_capability"]["verified"],
            ),
        )
        undeclared_receipts = v2_synthetic_receipts(
            inventory,
            manual=True,
        )
        checks.refuses(
            "undeclared-manual-authorization-refused",
            InputRefused,
            lambda: v2_derive_authority(
                inventory,
                undeclared_receipts,
                current_br_version="0.2.19",
            ),
            contains="manual authorization lacks",
        )

    elif slug == "mutation-forged-capability-deferred":
        for verdict in ("LYING", "NON_ATOMIC", "VERSION_MISMATCHED"):
            decision = v2_synthetic_authority(
                inventory,
                declared=True,
                external_verdict="VALID",
                conditional_verdict=verdict,
                gate_verdict="VALID",
                version="0.3.0",
                allow_mechanical_fixture=True,
            )["decisions"][0]
            checks.check(
                f"{verdict.lower()}-cannot-upgrade",
                decision["readiness"] != "MECHANICALLY_APPLY_ELIGIBLE"
                and decision["remediation_route"] != "AUTOMATED_CONDITIONAL",
                expected="non-mechanical",
                observed=(decision["readiness"], decision["remediation_route"]),
            )
        deferred_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0, status="deferred")]
        )
        deferred = v2_synthetic_authority(
            deferred_inventory,
            declared=True,
            manual=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
            version="0.3.0",
            allow_mechanical_fixture=True,
        )["decisions"][0]
        checks.check(
            "deferred-never-upgrades",
            deferred["remediation_route"] == "ANALYSIS_ONLY"
            and deferred["deferred_apply_prohibition"] is True,
            expected=("ANALYSIS_ONLY", True),
            observed=(
                deferred["remediation_route"],
                deferred["deferred_apply_prohibition"],
            ),
        )

    elif slug == "mutation-missing-payload-edge":
        authority = v2_synthetic_authority(inventory)
        plan, _ = v2_build_review_plan(inventory, authority, max_targets=10)
        child = plan["children"][0]
        missing = dict(child)
        missing.pop("notes")
        missing = v2_rooted(missing)
        checks.refuses(
            "missing-required-payload-field",
            InputRefused,
            lambda: v2_validate_child_payload(missing),
            contains="non-closed schema",
        )
        membership = dict(child)
        membership["target_ids"] = [child["target_ids"][0], child["target_ids"][0]]
        membership["target_roots"] = [
            child["target_roots"][0],
            child["target_roots"][0],
        ]
        membership = v2_rooted(membership)
        checks.refuses(
            "duplicate-target-membership",
            EvidenceFailed,
            lambda: v2_validate_child_payload(membership),
            contains="target membership",
        )
        for label, edges in (
            (
                "missing-edge",
                child["intended_generated_edges"][:1],
            ),
            (
                "reversed-edge",
                [
                    {
                        **child["intended_generated_edges"][0],
                        "from": child["intended_generated_edges"][0]["to"],
                        "to": child["intended_generated_edges"][0]["from"],
                    },
                    child["intended_generated_edges"][1],
                ],
            ),
            (
                "duplicate-edge",
                [
                    child["intended_generated_edges"][0],
                    child["intended_generated_edges"][0],
                ],
            ),
            (
                "undeclared-edge",
                [
                    *child["intended_generated_edges"],
                    {
                        "from": "generated:extra",
                        "to": child["lane_parent"],
                        "type": "blocks",
                    },
                ],
            ),
        ):
            mutated = dict(child)
            mutated["intended_generated_edges"] = edges
            mutated = v2_rooted(mutated)
            checks.refuses(
                label,
                EvidenceFailed,
                lambda mutated=mutated: v2_validate_child_payload(mutated),
                contains="generated-edge",
            )

    elif slug == "mutation-relation-neighbor-drift":
        targets = [v2_synthetic_target(0), v2_synthetic_target(1)]
        before_inventory = v2_synthetic_inventory(targets)
        before_authority = v2_synthetic_authority(before_inventory)
        before_plan, _ = v2_build_review_plan(
            before_inventory,
            before_authority,
            max_targets=10,
        )
        changed_target = dict(targets[0])
        changed_target["dependencies"] = [
            {
                "id": "synthetic-neighbor",
                "type": "blocks",
                "status": "open",
                "priority": 1,
            }
        ]
        changed_source_issue = v2_synthetic_source_issue(
            changed_target
        )
        changed_target["dependency_neighborhood_root"] = (
            v2_dependency_neighborhood_root(changed_source_issue)
        )
        changed_target["target_root"] = v2_target_root(
            changed_source_issue
        )
        changed_target = v2_rooted(changed_target)
        after_inventory = v2_synthetic_inventory([changed_target, targets[1]])
        after_authority = v2_synthetic_authority(after_inventory)
        after_plan, _ = v2_build_review_plan(
            after_inventory,
            after_authority,
            max_targets=10,
        )
        before_keys = {
            child["target_ids"][0]: child["child_key"]
            for child in before_plan["children"]
        }
        after_keys = {
            child["target_ids"][0]: child["child_key"]
            for child in after_plan["children"]
        }
        checks.check(
            "only-affected-logical-key-moves",
            before_keys[targets[0]["id"]] != after_keys[targets[0]["id"]]
            and before_keys[targets[1]["id"]] == after_keys[targets[1]["id"]],
            expected={"affected": "changed", "unrelated": "stable"},
            observed={"before": before_keys, "after": after_keys},
        )
        raw_left = fixture_issue(
            issue_id="graph-left",
            status="open",
            priority=1,
            dependencies=(
                {
                    "id": "graph-right",
                    "dependency_type": "blocks",
                    "status": "blocked",
                    "priority": 2,
                },
            ),
        )
        raw_right = fixture_issue(
            issue_id="graph-right",
            status="blocked",
            priority=2,
        )
        raw_right["dependents"] = [
            {
                "id": "graph-left",
                "dependency_type": "blocks",
                "status": "open",
                "priority": 1,
            }
        ]
        valid_graph = [
            v2_full_issue_projection(raw_left),
            v2_full_issue_projection(raw_right),
        ]
        v2_validate_source_graph(valid_graph)
        raw_parent = fixture_issue(
            issue_id="graph-parent",
            status="open",
            priority=1,
            children=("graph-child",),
        )
        raw_child = fixture_issue(
            issue_id="graph-child",
            status="open",
            priority=1,
            parent="graph-parent",
            dependencies=(
                {
                    "id": "graph-parent",
                    "dependency_type": "parent-child",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        valid_parent_graph = [
            v2_full_issue_projection(raw_child),
            v2_full_issue_projection(raw_parent),
        ]
        v2_validate_source_graph(valid_parent_graph)
        raw_external = fixture_issue(
            issue_id="graph-external-source",
            dependencies=(
                {
                    "id": "external:vendor-ticket-42",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        external_graph = [v2_full_issue_projection(raw_external)]
        v2_validate_source_graph(external_graph)
        rollup_root = fixture_issue(
            issue_id="graph-rollup-root",
            status="open",
            priority=1,
            dependencies=(
                {
                    "id": "graph-rollup-terminal",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 1,
                },
            ),
            children=(
                "graph-rollup-terminal",
                "graph-rollup-leaf",
            ),
        )
        rollup_terminal = fixture_issue(
            issue_id="graph-rollup-terminal",
            status="open",
            priority=1,
            parent="graph-rollup-root",
            dependencies=(
                {
                    "id": "graph-rollup-root",
                    "dependency_type": "parent-child",
                    "status": "open",
                    "priority": 1,
                },
                {
                    "id": "graph-rollup-leaf",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        rollup_terminal["dependents"] = [
            {
                "id": "graph-rollup-root",
                "dependency_type": "blocks",
                "status": "open",
                "priority": 1,
            }
        ]
        rollup_leaf = fixture_issue(
            issue_id="graph-rollup-leaf",
            status="open",
            priority=1,
            parent="graph-rollup-root",
            dependencies=(
                {
                    "id": "graph-rollup-root",
                    "dependency_type": "parent-child",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        rollup_leaf["dependents"] = [
            {
                "id": "graph-rollup-terminal",
                "dependency_type": "blocks",
                "status": "open",
                "priority": 1,
            }
        ]
        valid_rollup_graph = [
            v2_full_issue_projection(issue)
            for issue in (
                rollup_root,
                rollup_terminal,
                rollup_leaf,
            )
        ]
        v2_validate_source_graph(valid_rollup_graph)
        checks.check(
            "source-graph-valid-reciprocal-and-parent-pairs",
            True,
            expected="internal, parent, and external graph forms admitted",
            observed={
                "relation_rows": 2,
                "parent_rows": 2,
                "external_rows": 1,
            },
        )
        checks.check(
            "source-graph-rollup-hierarchy-and-blocking-composition-admitted",
            True,
            expected=(
                "parent hierarchy is distinct from execution-blocking edges"
            ),
            observed={
                "issue_count": len(valid_rollup_graph),
                "execution_chain": [
                    "graph-rollup-root",
                    "graph-rollup-terminal",
                    "graph-rollup-leaf",
                ],
                "shared_parent": "graph-rollup-root",
            },
        )

        def graph_mutation(
            source: Sequence[Mapping[str, Any]],
            mutation: Callable[[list[dict[str, Any]]], None],
        ) -> list[dict[str, Any]]:
            candidate = strict_json_loads(
                canonical_bytes(source),
                label="source graph mutation seed",
                require_canonical=True,
            )
            mutation(candidate)
            return candidate

        graph_failures = (
            (
                "absent-neighbor",
                valid_graph,
                lambda rows: rows[0]["dependencies"][0].__setitem__(
                    "id",
                    "graph-absent",
                ),
                "absent neighbor",
            ),
            (
                "neighbor-status",
                valid_graph,
                lambda rows: rows[0]["dependencies"][0].__setitem__(
                    "status",
                    "open",
                ),
                "status or priority",
            ),
            (
                "neighbor-priority",
                valid_graph,
                lambda rows: rows[0]["dependencies"][0].__setitem__(
                    "priority",
                    3,
                ),
                "status or priority",
            ),
            (
                "missing-reciprocal",
                valid_graph,
                lambda rows: rows[1].__setitem__("dependents", []),
                "lacks exact reciprocal edge",
            ),
            (
                "parent-scalar",
                valid_parent_graph,
                lambda rows: rows[0].__setitem__("parent", ""),
                "parent scalar and parent-child dependency",
            ),
            (
                "self-edge",
                valid_graph,
                lambda rows: rows[0]["dependencies"][0].__setitem__(
                    "id",
                    "graph-left",
                ),
                "self edge or duplicate neighbor",
            ),
            (
                "duplicate-neighbor",
                valid_graph,
                lambda rows: rows[0]["dependencies"].append(
                    {
                        **rows[0]["dependencies"][0],
                        "type": "waits-for",
                    }
                ),
                "self edge or duplicate neighbor",
            ),
        )
        for label, source, mutation, diagnostic in graph_failures:
            candidate = graph_mutation(source, mutation)
            checks.refuses(
                f"source-graph-{label}-refused",
                EvidenceFailed,
                lambda candidate=candidate: v2_validate_source_graph(
                    candidate
                ),
                contains=diagnostic,
            )
        external_parent_graph = graph_mutation(
            external_graph,
            lambda rows: (
                rows[0].__setitem__(
                    "parent",
                    "external:vendor-ticket-42",
                ),
                rows[0]["dependencies"][0].__setitem__(
                    "type",
                    "parent-child",
                ),
            ),
        )
        checks.refuses(
            "source-graph-external-parent-child-refused",
            EvidenceFailed,
            lambda: v2_validate_source_graph(external_parent_graph),
            contains="invalid direction, type, or empty identity",
        )
        cycle_left = fixture_issue(
            issue_id="cycle-left",
            dependencies=(
                {
                    "id": "cycle-right",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        cycle_left["dependents"] = [
            {
                "id": "cycle-right",
                "dependency_type": "blocks",
                "status": "open",
                "priority": 1,
            }
        ]
        cycle_right = fixture_issue(
            issue_id="cycle-right",
            dependencies=(
                {
                    "id": "cycle-left",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        cycle_right["dependents"] = [
            {
                "id": "cycle-left",
                "dependency_type": "blocks",
                "status": "open",
                "priority": 1,
            }
        ]
        cycle_graph = [
            v2_full_issue_projection(cycle_left),
            v2_full_issue_projection(cycle_right),
        ]
        checks.refuses(
            "source-graph-blocking-cycle-refused",
            EvidenceFailed,
            lambda: v2_validate_source_graph(cycle_graph),
            contains="blocking dependency cycle",
        )
        parent_cycle_left = fixture_issue(
            issue_id="parent-cycle-left",
            parent="parent-cycle-right",
            dependencies=(
                {
                    "id": "parent-cycle-right",
                    "dependency_type": "parent-child",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        parent_cycle_left["dependents"] = [
            {
                "id": "parent-cycle-right",
                "dependency_type": "parent-child",
                "status": "open",
                "priority": 1,
            }
        ]
        parent_cycle_right = fixture_issue(
            issue_id="parent-cycle-right",
            parent="parent-cycle-left",
            dependencies=(
                {
                    "id": "parent-cycle-left",
                    "dependency_type": "parent-child",
                    "status": "open",
                    "priority": 1,
                },
            ),
        )
        parent_cycle_right["dependents"] = [
            {
                "id": "parent-cycle-left",
                "dependency_type": "parent-child",
                "status": "open",
                "priority": 1,
            }
        ]
        parent_cycle_graph = [
            v2_full_issue_projection(parent_cycle_left),
            v2_full_issue_projection(parent_cycle_right),
        ]
        checks.refuses(
            "source-graph-parent-hierarchy-cycle-refused",
            EvidenceFailed,
            lambda: v2_validate_source_graph(parent_cycle_graph),
            contains="parent hierarchy cycle",
        )

    elif slug == "mutation-dropped-duplicate-target":
        targets = [v2_synthetic_target(0), v2_synthetic_target(1)]
        exact_inventory = v2_synthetic_inventory(targets)
        exact_authority = v2_synthetic_authority(exact_inventory)
        plan, _ = v2_build_review_plan(
            exact_inventory,
            exact_authority,
            max_targets=10,
        )
        mutations: list[tuple[str, list[dict[str, Any]]]] = [
            ("dropped", plan["children"][:1]),
            ("duplicated", [*plan["children"], plan["children"][0]]),
        ]
        for label, children in mutations:
            mutated = dict(plan)
            mutated["children"] = children
            mutated = v2_rooted(mutated)
            checks.refuses(
                f"{label}-target",
                EvidenceFailed,
                lambda mutated=mutated: v2_validate_review_plan(
                    mutated,
                    exact_inventory,
                    exact_authority,
                ),
                contains="target mapping",
            )
        cross_lane_child = dict(plan["children"][0])
        cross_lane_child["priority"] = 4
        cross_lane_child = v2_rooted(cross_lane_child)
        cross_lane_plan = dict(plan)
        cross_lane_plan["children"] = [
            cross_lane_child,
            *plan["children"][1:],
        ]
        cross_lane_plan = v2_rooted(cross_lane_plan)
        checks.refuses(
            "cross-lane-substitution",
            EvidenceFailed,
            lambda: v2_validate_review_plan(
                cross_lane_plan,
                exact_inventory,
                exact_authority,
            ),
            contains="scalar or enum contract",
        )
        cross_lane_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    0,
                    issue_id="synthetic-cross-lane-0",
                    priority=2,
                ),
                v2_synthetic_target(
                    1,
                    issue_id="synthetic-cross-lane-1",
                    priority=4,
                ),
            ]
        )
        cross_lane_authority = v2_synthetic_authority(
            cross_lane_inventory
        )
        cross_lane_decisions = {
            row["target_id"]: row
            for row in cross_lane_authority["decisions"]
        }
        checks.refuses(
