            observed={
                **preflight_calls,
                "terminal_started": (
                    preflight_reservation.terminal_assignment_started
                ),
            },
        )

        def exercise_directory_chain(
            *,
            fail_operation: str | None = None,
        ) -> tuple[list[tuple[Any, ...]], BaseException | None]:
            original_open = os.open
            original_mkdir = os.mkdir
            original_fstat = os.fstat
            original_fsync = os.fsync
            original_close = os.close
            operations: list[tuple[Any, ...]] = []
            next_descriptor = 100

            class DirectoryStat:
                st_mode = stat.S_IFDIR | 0o755

            def fake_open(
                path: Any,
                flags: int,
                mode: int = 0o777,
                *,
                dir_fd: int | None = None,
            ) -> int:
                del flags, mode
                nonlocal next_descriptor
                descriptor = next_descriptor
                next_descriptor += 1
                operations.append(
                    ("open", str(path), dir_fd, descriptor)
                )
                return descriptor

            def fake_mkdir(
                path: Any,
                mode: int = 0o777,
                *,
                dir_fd: int | None = None,
            ) -> None:
                del mode
                operations.append(("mkdir", str(path), dir_fd))

            def fake_fstat(descriptor: int) -> DirectoryStat:
                operations.append(("fstat", descriptor))
                if fail_operation == "fstat":
                    raise OSError("synthetic fstat failure")
                return DirectoryStat()

            def fake_fsync(descriptor: int) -> None:
                operations.append(("fsync", descriptor))
                if fail_operation == "fsync":
                    raise OSError("synthetic fsync failure")

            def fake_close(descriptor: int) -> None:
                operations.append(("close", descriptor))

            os.open = fake_open
            os.mkdir = fake_mkdir
            os.fstat = fake_fstat
            os.fsync = fake_fsync
            os.close = fake_close
            error: BaseException | None = None
            try:
                result_descriptor = v2_open_or_create_directory_chain(
                    PurePosixPath("alpha/beta"),
                    label="synthetic directory chain",
                )
                fake_close(result_descriptor)
            except BaseException as caught:
                error = caught
            finally:
                os.open = original_open
                os.mkdir = original_mkdir
                os.fstat = original_fstat
                os.fsync = original_fsync
                os.close = original_close
            return operations, error

        directory_operations, directory_error = (
            exercise_directory_chain()
        )
        checks.check(
            "directory-entry-open-fstat-fsync-close-order",
            directory_error is None
            and directory_operations
            == [
                ("open", str(REPO_ROOT), None, 100),
                ("mkdir", "alpha", 100),
                ("open", "alpha", 100, 101),
                ("fstat", 101),
                ("fsync", 100),
                ("close", 100),
                ("mkdir", "beta", 101),
                ("open", "beta", 101, 102),
                ("fstat", 102),
                ("fsync", 101),
                ("close", 101),
                ("close", 102),
            ],
            expected="open child, fstat child, fsync parent, then close parent",
            observed=directory_operations,
        )
        for failure_operation in ("fstat", "fsync"):
            failure_operations, directory_failure = (
                exercise_directory_chain(
                    fail_operation=failure_operation,
                )
            )
            checks.check(
                f"directory-{failure_operation}-failure-closes-both-descriptors",
                isinstance(directory_failure, OSError)
                and ("close", 101) in failure_operations
                and ("close", 100) in failure_operations,
                expected={
                    "error": "OSError",
                    "child_closed": 101,
                    "parent_closed": 100,
                },
                observed={
                    "error": (
                        type(directory_failure).__name__
                        if directory_failure is not None
                        else None
                    ),
                    "operations": failure_operations,
                },
            )

        output_descriptor = os.open(
            REPO_ROOT,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        assignment_reservation = V2BundleReservation(
            output=REPO_ROOT,
            artifact_root="target",
            artifact_dir="fixture",
            terminal_descriptor=-1,
            output_descriptor=output_descriptor,
            parent_descriptor=os.dup(output_descriptor),
            path_anchors=(),
        )
        original_assert = v2_assert_reservation_anchors
        globals()["v2_verify_reserved_publication"] = (
            lambda *_args, **_kwargs: None
        )
        globals()["v2_assert_reservation_anchors"] = (
            lambda _reservation: None
        )
        try:
            assignment_error = expect_error(
                InfrastructureFailed,
                lambda: _v2_publish_reserved_bundle(
                    assignment_reservation,
                    payloads={"terminal.json": b"{}\n"},
                ),
                contains="could not be finalized",
            )
        finally:
            globals()["v2_verify_reserved_publication"] = original_verify
            globals()["v2_assert_reservation_anchors"] = original_assert
            v2_close_reservation(assignment_reservation)
        checks.check(
            "terminal-assignment-failure-state-is-exact",
            assignment_error.terminal == "InfrastructureFailed"
            and assignment_reservation.terminal_assignment_started is True
            and assignment_reservation.terminal_assignment_committed is False
            and assignment_reservation.sealed is False,
            expected={
                "started": True,
                "committed": False,
                "sealed": False,
            },
            observed={
                "started": assignment_reservation.terminal_assignment_started,
                "committed": (
                    assignment_reservation.terminal_assignment_committed
                ),
                "sealed": assignment_reservation.sealed,
            },
        )

    elif slug == "cancel-signals-drained":
        global _cancel_requested
        prior_cancel = _cancel_requested
        prior_timeout = CAPS["subprocess_timeout_seconds"]
        try:
            for signum in (signal.SIGINT, signal.SIGTERM):
                request_cancel(signum, None)
                for boundary in (
                    "source",
                    "audit",
                    "packing",
                    "publication",
                    "replay",
                ):
                    checks.refuses(
                        f"{signal.Signals(signum).name.lower()}-{boundary}",
                        CancelledDrained,
                        check_cancel,
                        contains="cancellation requested",
                    )
                _cancel_requested = False
            receipt_start = len(_command_receipts)
            timer = threading.Timer(
                0.05,
                request_cancel,
                args=(signal.SIGINT, None),
            )
            timer.start()
            started = time.monotonic()
            try:
                live_cancel_error = expect_error(
                    CancelledDrained,
                    lambda: run_command(
                        (
                            sys.executable,
                            "-c",
                            "import time; time.sleep(10)",
                        )
                    ),
                    contains="subprocess group was drained",
                )
            finally:
                timer.cancel()
                timer.join(timeout=1)
            live_cancel_elapsed = time.monotonic() - started
            live_cancel_receipt = _command_receipts[-1]
            _cancel_requested = False
            checks.check(
                "live-subprocess-cancellation-drains-and-receipts",
                live_cancel_error.terminal == "CancelledDrained"
                and live_cancel_elapsed < 2.0
                and len(_command_receipts) == receipt_start + 1
                and live_cancel_receipt["category"] == "CANCELLED"
                and live_cancel_receipt["cleanup_error_count"] == 0,
                expected={
                    "terminal": "CancelledDrained",
                    "elapsed_lt_seconds": 2,
                    "receipt": "CANCELLED",
                    "cleanup_errors": 0,
                },
                observed={
                    "terminal": live_cancel_error.terminal,
                    "elapsed_seconds": round(live_cancel_elapsed, 3),
                    "receipt": live_cancel_receipt["category"],
                    "cleanup_errors": live_cancel_receipt[
                        "cleanup_error_count"
                    ],
                },
            )

            CAPS["subprocess_timeout_seconds"] = 0.2
            timeout_started = time.monotonic()
            timeout_error = expect_error(
                InfrastructureFailed,
                lambda: run_command(
                    (
                        sys.executable,
                        "-c",
                        (
                            "import subprocess,sys; "
                            "subprocess.Popen([sys.executable,'-c',"
                            "'import time; time.sleep(10)'])"
                        ),
                    )
                ),
                contains="exceeded",
            )
            timeout_elapsed = time.monotonic() - timeout_started
            timeout_receipt = _command_receipts[-1]
            checks.check(
                "descendant-drain-cleanup-diagnostics",
                timeout_receipt["cleanup_error_kinds"] == [],
                expected=[],
                observed=timeout_receipt["cleanup_error_kinds"],
            )
            checks.check(
                "exited-leader-descendant-pipes-time-out-and-drain",
                timeout_error.terminal == "InfrastructureFailed"
                and timeout_elapsed < 2.0
                and timeout_receipt["category"] == "TIMEOUT"
                and timeout_receipt["cleanup_error_count"] == 0,
                expected={
                    "terminal": "InfrastructureFailed",
                    "elapsed_lt_seconds": 2,
                    "receipt": "TIMEOUT",
                    "cleanup_errors": 0,
                },
                observed={
                    "terminal": timeout_error.terminal,
                    "elapsed_seconds": round(timeout_elapsed, 3),
                    "receipt": timeout_receipt["category"],
                    "cleanup_errors": timeout_receipt[
                        "cleanup_error_count"
                    ],
                    "cleanup_error_kinds": timeout_receipt[
                        "cleanup_error_kinds"
                    ],
                },
            )

            original_killpg = os.killpg

            def synthetic_sigkill_permission_error(
                process_group: int,
                signum: int,
            ) -> None:
                if signum != signal.SIGKILL:
                    original_killpg(process_group, signum)
                    return
                try:
                    original_killpg(process_group, signum)
                except ProcessLookupError:
                    pass
                raise PermissionError(
                    errno.EPERM,
                    "synthetic SIGKILL process-group refusal",
                )

            os.killpg = synthetic_sigkill_permission_error
            try:
                sigkill_permission_error = expect_error(
                    InfrastructureFailed,
                    lambda: run_command(
                        (
                            sys.executable,
                            "-c",
                            (
                                "import signal,time; "
                                "signal.signal(signal.SIGTERM, signal.SIG_IGN); "
                                "time.sleep(10)"
                            ),
                        )
                    ),
                    contains="could not prove process-group retirement",
                )
            finally:
                os.killpg = original_killpg
            sigkill_permission_receipt = _command_receipts[-1]
            checks.check(
                "sigkill-permission-error-refuses-drained-claim",
                sigkill_permission_error.terminal
                == "InfrastructureFailed"
                and sigkill_permission_receipt["category"] == "TIMEOUT"
                and sigkill_permission_receipt["cleanup_error_count"] == 1
                and sigkill_permission_receipt["cleanup_error_kinds"]
                == ["SIGKILL_PROCESS_GROUP_ERRNO_1"],
                expected={
                    "terminal": "InfrastructureFailed",
                    "category": "TIMEOUT",
                    "cleanup_error_kinds": [
                        "SIGKILL_PROCESS_GROUP_ERRNO_1"
                    ],
                },
                observed={
                    "terminal": sigkill_permission_error.terminal,
                    "category": sigkill_permission_receipt["category"],
                    "cleanup_error_count": sigkill_permission_receipt[
                        "cleanup_error_count"
                    ],
                    "cleanup_error_kinds": sigkill_permission_receipt[
                        "cleanup_error_kinds"
                    ],
                },
            )

            def cancellation_reservation(
                *,
                nonterminal_members: Sequence[str] = (),
                assignment_started: bool = False,
                assignment_committed: bool = False,
                sealed: bool = False,
            ) -> V2BundleReservation:
                identities = {"terminal.json": {}}
                identities.update(
                    {name: {} for name in nonterminal_members}
                )
                return V2BundleReservation(
                    output=REPO_ROOT,
                    artifact_root="target",
                    artifact_dir="fixture",
                    terminal_descriptor=-1,
                    output_descriptor=-1,
                    parent_descriptor=-1,
                    path_anchors=(),
                    written_identities=identities,
                    terminal_assignment_started=assignment_started,
                    terminal_assignment_committed=assignment_committed,
                    sealed=sealed,
                )

            original_assert_anchors = v2_assert_reservation_anchors
            globals()["v2_assert_reservation_anchors"] = (
                lambda _reservation: None
            )
            try:
                cancellation_states = (
                    (
                        "before-publication-terminal-only",
                        cancellation_reservation(),
                        False,
                        "CancelledDrained",
                        "before publication",
                    ),
                    (
                        "publication-start-terminal-only",
                        cancellation_reservation(),
                        True,
                        "CancelledDrained",
                        "publication start",
                    ),
                    (
                        "partial-prefix",
                        cancellation_reservation(
                            nonterminal_members=("source-v2.json",),
                        ),
                        True,
                        "CancelledDrained",
                        "retained incomplete nonterminal",
                    ),
                    (
                        "assignment-started",
                        cancellation_reservation(
                            assignment_started=True,
                        ),
                        True,
                        "InfrastructureFailed",
                        "terminal assignment began",
                    ),
                    (
                        "assignment-committed",
                        cancellation_reservation(
                            assignment_started=True,
                            assignment_committed=True,
                        ),
                        True,
                        "InfrastructureFailed",
                        "durable terminal commit",
                    ),
                    (
                        "post-seal",
                        cancellation_reservation(
                            assignment_started=True,
                            assignment_committed=True,
                            sealed=True,
                        ),
                        True,
                        "InfrastructureFailed",
                        "durable terminal commit",
                    ),
                )
                for (
                    state_name,
                    state_reservation,
                    publication_started,
                    expected_terminal,
                    expected_detail,
                ) in cancellation_states:
                    classified = v2_contextual_cancellation_error(
                        state_reservation,
