        attempt_states["fixture-attempt-0002"] = "COMPLETE"
        reused_attempt = v2_select_persistent_attempt(
            "fixture",
            probe=lambda candidate: attempt_states.get(
                candidate,
                "INCOMPLETE",
            ),
        )
        checks.check(
            "incomplete-prefix-selects-and-reuses-fresh-attempt",
            selected_attempt == "fixture-attempt-0002"
            and reused_attempt == selected_attempt,
            expected="fixture-attempt-0002",
            observed={
                "selected": selected_attempt,
                "reused": reused_attempt,
            },
        )
        checks.refuses(
            "bounded-incomplete-attempt-exhaustion",
            EvidenceFailed,
            lambda: v2_select_persistent_attempt(
                "fixture",
                probe=lambda _candidate: "INCOMPLETE",
            ),
            contains="bounded fresh-attempt budget",
        )
        first_signature = (1, 2, 3, 4, 5)
        growing_signature = (1, 2, 4, 6, 7)
        observed_signature, observed_count, stable = (
            v2_observe_stable_invalid_terminal(
                None,
                0,
                first_signature,
            )
        )
        observed_signature, observed_count, stable_after_growth = (
            v2_observe_stable_invalid_terminal(
                observed_signature,
                observed_count,
                growing_signature,
            )
        )
        _, repeated_count, stable_after_repeat = (
            v2_observe_stable_invalid_terminal(
                observed_signature,
                observed_count,
                growing_signature,
            )
        )
        checks.check(
            "nonempty-invalid-terminal-must-be-stable-before-recovery",
            stable is False
            and stable_after_growth is False
            and observed_count == 1
            and stable_after_repeat is True
            and repeated_count == 2,
            expected={
                "first": False,
                "changing": False,
                "stable_repeat": True,
            },
            observed={
                "first": stable,
                "changing": stable_after_growth,
                "changing_count": observed_count,
                "stable_repeat": stable_after_repeat,
                "stable_count": repeated_count,
