                    audit_aggregate_error.terminal
                ),
            },
        )
        checks.check(
            "audit-capture-wires-distinct-stream-cap",
            observed_audit_stream_overrides
            == [
                (
                    V2_AUDIT_STREAM_BYTES_CAP,
                    V2_AUDIT_STREAM_BYTES_CAP,
                ),
                (
                    V2_AUDIT_STREAM_BYTES_CAP,
                    V2_AUDIT_STREAM_BYTES_CAP,
                ),
            ],
            expected=[
                (
                    V2_AUDIT_STREAM_BYTES_CAP,
                    V2_AUDIT_STREAM_BYTES_CAP,
                ),
                (
                    V2_AUDIT_STREAM_BYTES_CAP,
                    V2_AUDIT_STREAM_BYTES_CAP,
                ),
            ],
            observed=observed_audit_stream_overrides,
        )
        over_audit_stream_receipt = strict_json_loads(
            canonical_bytes(bounded_audit_capture),
            label="audit stream cap mutation seed",
            require_canonical=True,
        )
        over_audit_stream_receipt.pop("semantic_root", None)
        over_audit_stream_receipt["command_receipts"][0][
            "stdout_byte_length"
        ] = V2_AUDIT_STREAM_BYTES_CAP + 1
        over_audit_stream_receipt = v2_rooted(
            over_audit_stream_receipt
        )
        checks.refuses(
            "retained-audit-stream-cap-plus-one",
            InputRefused,
            lambda: v2_validate_audit_capture(
                over_audit_stream_receipt,
                allowed_issue_ids={"audit-stream-cap"},
            ),
            contains="identity or terminal contract differs",
        )
        v2_validate_log_event_count(
            V2_LOG_EVENTS_CAP,
            error_type=EvidenceFailed,
        )
        checks.refuses(
            "event-count-cap-plus-one-production-validator",
            EvidenceFailed,
            lambda: v2_validate_log_event_count(
                V2_LOG_EVENTS_CAP + 1,
                error_type=EvidenceFailed,
            ),
            contains="event count exceeds",
        )
        v2_validate_artifact_size(
            RUN_ARTIFACT_CAP,
            label="fixture artifact",
        )
        checks.refuses(
            "artifact-cap-plus-one-production-validator",
            EvidenceFailed,
            lambda: v2_validate_artifact_size(
                RUN_ARTIFACT_CAP + 1,
                label="fixture artifact",
            ),
            contains="artifact cap",
        )
        for length in (
            V2_LOG_LINE_BYTES_CAP - 1,
            V2_LOG_LINE_BYTES_CAP,
        ):
            v2_validate_log_line_payload(
                b"x" * length,
                label="fixture log line",
            )
        checks.refuses(
            "log-line-cap-plus-one-production-validator",
            EvidenceFailed,
            lambda: v2_validate_log_line_payload(
                b"x" * (V2_LOG_LINE_BYTES_CAP + 1),
                label="fixture log line",
            ),
            contains="log-line cap",
        )
        v2_sanitized_argv(["x"] * V2_COMMAND_ARGUMENTS_CAP)
        checks.refuses(
            "argv-count-cap-plus-one",
            EvidenceFailed,
            lambda: v2_sanitized_argv(
                ["x"] * (V2_COMMAND_ARGUMENTS_CAP + 1)
            ),
            contains="argument-count",
        )
        v2_sanitized_argv(["x" * V2_COMMAND_ARGUMENT_BYTES_CAP])
        checks.refuses(
            "argv-byte-cap-plus-one",
            EvidenceFailed,
            lambda: v2_sanitized_argv(
                ["x" * (V2_COMMAND_ARGUMENT_BYTES_CAP + 1)]
            ),
            contains="argument-byte",
        )
        safe_relative(
            "x" * CAPS["path_component_bytes"],
            label="fixture component",
        )
        checks.refuses(
            "path-component-cap-plus-one",
            UsageRefused,
            lambda: safe_relative(
                "x" * (CAPS["path_component_bytes"] + 1),
                label="fixture component",
            ),
            contains="unsafe or over-cap",
        )
        prior_stream_cap = CAPS["subprocess_stdout_bytes"]
        try:
            CAPS["subprocess_stdout_bytes"] = 16
            for stream_fd, stream_name, category in (
                (1, "stdout", "STDOUT_LIMIT"),
                (2, "stderr", "STDERR_LIMIT"),
            ):
                receipt_start = len(_command_receipts)
                error = expect_error(
                    InfrastructureFailed,
                    lambda stream_fd=stream_fd: run_command(
                        (
                            sys.executable,
                            "-c",
                            (
                                "import os; "
                                f"os.write({stream_fd}, b'x' * 17)"
                            ),
                        )
                    ),
                    contains="exceeded the bounded cap",
                )
                receipt = _command_receipts[-1]
                checks.check(
                    f"{stream_name}-capture-cap-is-exact",
                    error.terminal == "InfrastructureFailed"
                    and len(_command_receipts) == receipt_start + 1
                    and receipt["category"] == category
                    and receipt[stream_name]["bytes"] == 16
                    and receipt["cleanup_error_count"] == 0,
                    expected={
                        "category": category,
                        "retained_bytes": 16,
                        "cleanup_errors": 0,
                    },
                    observed={
                        "category": receipt["category"],
                        "retained_bytes": receipt[stream_name]["bytes"],
                        "cleanup_errors": receipt["cleanup_error_count"],
                    },
                )
            non_utf_error = expect_error(
                InfrastructureFailed,
                lambda: run_command(
                    (
                        sys.executable,
                        "-c",
                        "import os; os.write(1, bytes([255]))",
                    )
                ),
                contains="non-UTF-8",
            )
            non_utf_receipt = _command_receipts[-1]
            checks.check(
                "non-utf8-capture-retains-root-only-receipt",
                non_utf_error.terminal == "InfrastructureFailed"
                and non_utf_receipt["category"] == "NON_UTF8"
                and non_utf_receipt["stdout"]["bytes"] == 1
                and non_utf_receipt["stdout"]["body_retained"] is False,
                expected={
                    "category": "NON_UTF8",
                    "bytes": 1,
                    "body_retained": False,
                },
                observed={
                    "category": non_utf_receipt["category"],
                    **non_utf_receipt["stdout"],
                },
            )
            missing_error = expect_error(
                InfrastructureFailed,
                lambda: run_command(("missing-password=topsecret",)),
                contains="required tool not found",
            )
            missing_receipt = _command_receipts[-1]
            checks.check(
                "start-failure-receipt-redacts-sensitive-argv",
                missing_error.terminal == "InfrastructureFailed"
                and "topsecret" not in str(missing_error)
                and missing_receipt["category"] == "START_FAILED"
                and "topsecret"
                not in canonical_bytes(missing_receipt["argv"]).decode(
                    "utf-8"
                ),
                expected={
                    "category": "START_FAILED",
                    "raw_secret_retained": False,
                },
                observed={
                    "category": missing_receipt["category"],
                    "diagnostic": str(missing_error),
                    "argv": missing_receipt["argv"],
                },
            )
            checks.refuses(
                "stdin-cap-plus-one-refused-before-start",
                EvidenceFailed,
                lambda: run_command(
                    (sys.executable, "-c", "pass"),
                    input_text="x" * 17,
                ),
                contains="stdin exceeds",
                projection=lambda: len(_command_receipts),
                projection_label="COMMAND_RECEIPT_COUNT",
            )
        finally:
            CAPS["subprocess_stdout_bytes"] = prior_stream_cap

    elif slug == "mutation-truncation-oversize-root":
        _, _, components = v2_replayable_fixture_bundle(
