            all(
                resolve_run_dir(
                    artifact_root,
                    f"{fixture_base}/{name}",
                    label=f"retained mutation fixture {name}",
                    must_exist=True,
                ).exists()
                for name in (
                    "truncated-source",
                    "oversize-root-mutation",
                    "forged-semantic-root",
                )
            )
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
