            is not None,
            expected={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": 2,
                "tree_root": fixture_tree_root,
            },
            observed={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": 2,
                "tree_root": fixture_tree_root,
            },
        )

    elif slug == "fault-replay-manual-recovery":
        artifact_root, fixture_base, fixture_created = (
            v2_fresh_fault_fixture_base(
                manifest,
                label="fault-replay-manual-recovery",
            )
        )
        scenarios: list[
            tuple[
                str,
                str,
                dict[str, bytes],
                dict[str, bytes],
                type[HarnessError],
                str,
                str,
            ]
        ] = []

        mismatch_dir = f"{fixture_base}/replay-mismatch"
        mismatch_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=mismatch_dir,
        )
        mismatch_source = strict_json_loads(
            mismatch_expected["source-v2.json"],
            label="replay-mismatch source seed",
            require_canonical=True,
        )
        mismatch_source["semantic_root"] = semantic_root(
            {"forged": "replay-source-root"}
        )
        mismatch_observed = dict(mismatch_expected)
        mismatch_observed["source-v2.json"] = canonical_bytes(
            mismatch_source
        )
        scenarios.append(
            (
                "replay-mismatch",
                mismatch_dir,
                mismatch_expected,
                mismatch_observed,
                EvidenceFailed,
                "source-v2.json.semantic_root",
                "$.source-v2.json.content_root",
            )
        )

        ambiguous_source_dir = f"{fixture_base}/ambiguous-source"
        ambiguous_source_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=ambiguous_source_dir,
        )
        ambiguous_source_observed = dict(ambiguous_source_expected)
        ambiguous_source_observed["source-copy.json"] = (
            ambiguous_source_expected["source-v2.json"]
        )
        scenarios.append(
            (
                "ambiguous-source",
                ambiguous_source_dir,
                ambiguous_source_expected,
                ambiguous_source_observed,
                InputRefused,
                "source-copy.json",
                "$.source-copy.json",
            )
        )

        audit_conflict_dir = f"{fixture_base}/audit-conflict"
        audit_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=audit_conflict_dir,
        )
        audit_events = v2_read_event_stream(
            audit_expected["events.jsonl"]
        )
        audit_event_index = next(
            (
                index
                for index, event in enumerate(audit_events)
                if event["stage"].startswith("source-command-")
            ),
            None,
        )
        if audit_event_index is None:
            raise EvidenceFailed(
                "audit-conflict fixture lacks a source-command event"
            )
        conflicted_audit_event = strict_json_loads(
            canonical_bytes(audit_events[audit_event_index]),
            label="audit-conflict event seed",
            require_canonical=True,
        )
        conflicted_audit_event["semantic_projection"][
            "command_receipt_root"
        ] = semantic_root({"forged": "audit-command-receipt"})
        conflicted_audit_events = list(audit_events)
        conflicted_audit_events[audit_event_index] = (
            conflicted_audit_event
        )
        audit_observed = dict(audit_expected)
        audit_observed["events.jsonl"] = b"".join(
            canonical_bytes(event) for event in conflicted_audit_events
        )
        scenarios.append(
            (
                "audit-conflict",
                audit_conflict_dir,
                audit_expected,
                audit_observed,
                EvidenceFailed,
                "terminal event/reproduction seal differs",
                "$.events.jsonl.content_root",
            )
        )

        publication_dir = f"{fixture_base}/publication-ambiguity"
        publication_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=publication_dir,
        )
        publication_observed = dict(publication_expected)
        publication_observed["terminal-copy.json"] = (
            publication_expected["terminal.json"]
        )
        scenarios.append(
            (
                "publication-ambiguity",
                publication_dir,
                publication_expected,
                publication_observed,
                InputRefused,
                "terminal-copy.json",
                "$.terminal-copy.json",
            )
        )

        for (
            label,
            input_dir,
            expected_payloads,
            observed_payloads,
            error_type,
            diagnostic,
            expected_divergence,
        ) in scenarios:
            if fixture_created:
                v2_publish_bundle(
                    artifact_root=artifact_root,
                    artifact_dir=input_dir,
                    payloads=observed_payloads,
                )
            output_dir = f"{fixture_base}/{label}-replay-output"
            replay_error = expect_error(
                error_type,
                lambda input_dir=input_dir, output_dir=output_dir: (
                    v2_replay_bundle(
                        artifact_root=artifact_root,
                        input_dir=input_dir,
                        output_dir=output_dir,
                    )
                ),
                contains=diagnostic,
            )
            expected_projection = v2_payload_identity_projection(
                expected_payloads
            )
            observed_projection = v2_payload_identity_projection(
                observed_payloads
            )
            evidence = v2_failure_evidence(
                stage=label,
                detail=str(replay_error),
                expected=expected_projection,
                observed=observed_projection,
                manifest_root=manifest["semantic_root"],
                available_roots={
                    "source": strict_json_loads(
                        expected_payloads["source-v2.json"],
                        label=f"{label} expected source",
                        require_canonical=True,
                    )["semantic_root"],
                    "inventory": strict_json_loads(
                        expected_payloads["inventory-v2.json"],
                        label=f"{label} expected inventory",
                        require_canonical=True,
                    )["semantic_root"],
                    "authority": strict_json_loads(
                        expected_payloads["authority-v2.json"],
                        label=f"{label} expected authority",
                        require_canonical=True,
                    )["semantic_root"],
                    "review_plan": strict_json_loads(
                        expected_payloads["review-plan-v2.json"],
                        label=f"{label} expected review plan",
                        require_canonical=True,
                    )["semantic_root"],
                    "history": strict_json_loads(
                        expected_payloads["history-v2.json"],
                        label=f"{label} expected history",
                        require_canonical=True,
                    )["semantic_root"],
                    "zero_sets": strict_json_loads(
                        expected_payloads["zero-sets-v2.json"],
                        label=f"{label} expected zero sets",
                        require_canonical=True,
                    )["semantic_root"],
                },
            )
            checks.check(
                label,
                replay_error.terminal == error_type.terminal
                and evidence["first_divergence"] == expected_divergence
                and evidence["recovery"] == "MANUAL_RECOVERY_REQUIRED"
                and evidence["terminal"] == "EvidenceFailed"
                and evidence["complete_green_prefix"] is False
                and evidence["retry_requires_fresh_run_dir"] is True
                and evidence["detail_root"] == text_root(str(replay_error))
                and evidence["manifest_root"] == manifest["semantic_root"]
                and all(
                    isinstance(root, str)
                    and root.startswith("sha256-v1:")
                    for root in evidence["available_roots"].values()
                )
                and not resolve_run_dir(
                    artifact_root,
                    output_dir,
                    label=f"{label} replay output",
                ).exists(),
                expected={
                    "validator_terminal": error_type.terminal,
                    "first_divergence": expected_divergence,
                    "recovery": "MANUAL_RECOVERY_REQUIRED",
                    "failure_terminal": "EvidenceFailed",
                    "output_exists": False,
                },
                observed={
                    "validator_terminal": replay_error.terminal,
                    "validator_diagnostic": str(replay_error),
                    "failure_evidence": evidence,
                    "output_exists": resolve_run_dir(
                        artifact_root,
                        output_dir,
                        label=f"{label} replay output",
                    ).exists(),
                },
            )
        fixture_tree_root = v2_finish_fault_fixture(
            manifest,
            artifact_root=artifact_root,
            fixture_base=fixture_base,
            label="fault-replay-manual-recovery",
        )
        checks.check(
            "retained-replay-recovery-fixture-root",
            all(
                resolve_run_dir(
                    artifact_root,
                    input_dir,
                    label=f"retained recovery fixture {label}",
                    must_exist=True,
                ).exists()
                for label, input_dir, *_ in scenarios
            )
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                fixture_tree_root,
            )
            is not None,
            expected={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": len(scenarios),
                "tree_root": fixture_tree_root,
            },
            observed={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": len(scenarios),
                "tree_root": fixture_tree_root,
            },
        )

    else:
        raise EvidenceFailed(f"no fault/resource executor for {slug}")
    return checks.finish(parameters)


def v2_nomock_bv_projection() -> dict[str, Any]:
    completed = run_command(("bv", "--robot-triage"))
    document = strict_json_loads(
        completed.stdout,
        label="bv robot triage",
    )
    if not isinstance(document, dict):
        raise InfrastructureFailed("bv robot triage is not an object")
    triage = document.get("triage")
    if not isinstance(triage, dict):
        raise InfrastructureFailed("bv robot triage lacks triage data")
    meta = triage.get("meta")
    health = triage.get("project_health")
    quick = triage.get("quick_ref")
    if not all(isinstance(value, dict) for value in (meta, health, quick)):
        raise InfrastructureFailed("bv robot triage stable sections are malformed")
    projection = {
        "data_hash": str(document.get("data_hash") or ""),
        "version": str(meta.get("version") or ""),
        "issue_count": meta.get("issue_count"),
        "phase2_ready": meta.get("phase2_ready"),
        "counts": health.get("counts"),
        "graph": health.get("graph"),
        "quick_ref": {
            "open_count": quick.get("open_count"),
            "actionable_count": quick.get("actionable_count"),
            "blocked_count": quick.get("blocked_count"),
            "in_progress_count": quick.get("in_progress_count"),
        },
        "robot_mode": "--robot-triage",
        "raw_generated_at_retained": False,
    }
    return v2_rooted(projection)


def v2_nomock_history_evidence(
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    global _v2_nomock_history_cache
    if _v2_nomock_history_cache is not None:
        return dict(_v2_nomock_history_cache)
    contract = manifest["history_contract"]
    anchor_id = str(contract["legacy_coverage_anchor_issue"])
    legacy_id = "frankensim-0aeh"
    first = normalize_document(
        br_read_json(
            "list",
            "--status",
            "closed",
            "--json",
            "--limit",
            "0",
        ),
        label="no-mock closed list first",
    )
    second = normalize_document(
        br_read_json(
            "list",
            "--status",
            "closed",
            "--json",
            "--limit",
            "0",
        ),
        label="no-mock closed list second",
    )
    first_projection = [
        {
            "id": str(row.get("id") or ""),
            "closed_at": str(row.get("closed_at") or ""),
            "close_reason": str(row.get("close_reason") or ""),
        }
        for row in first
    ]
    second_projection = [
        {
            "id": str(row.get("id") or ""),
            "closed_at": str(row.get("closed_at") or ""),
            "close_reason": str(row.get("close_reason") or ""),
        }
        for row in second
    ]
    first_projection.sort(key=lambda row: row["id"])
    second_projection.sort(key=lambda row: row["id"])
    if first_projection != second_projection:
        raise InputRefused("ConcurrentDrift: closed membership changed during audit")
    show_document = br_read_json("show", anchor_id, legacy_id, "--json")
    if not isinstance(show_document, list) or len(show_document) != 2:
        raise InfrastructureFailed("no-mock history show did not return two rows")
    show_by_id = {
        str(row.get("id") or ""): v2_full_issue_projection(row)
        for row in show_document
        if isinstance(row, dict)
    }
    if set(show_by_id) != {anchor_id, legacy_id}:
        raise InfrastructureFailed("no-mock history show membership differs")
    anchor_first = v2_capture_one_audit(anchor_id, capture_ordinal=1)[1]
    anchor_second = v2_capture_one_audit(anchor_id, capture_ordinal=2)[1]
    legacy_first = v2_capture_one_audit(legacy_id, capture_ordinal=1)[1]
    legacy_second = v2_capture_one_audit(legacy_id, capture_ordinal=2)[1]
    if anchor_first != anchor_second or legacy_first != legacy_second:
        raise InputRefused("ConcurrentDrift: selected audit evidence changed")
    anchor_timestamp = v2_parse_timestamp(
        contract["legacy_coverage_anchor_closed_at"],
        label="no-mock history anchor",
    )
    legacy_rows = sorted(
        [
            {
                "id": row["id"],
                "closed_at": row["closed_at"],
                "close_reason_root": text_root(row["close_reason"]),
            }
            for row in first_projection
            if row["closed_at"]
            and v2_parse_timestamp(
                row["closed_at"],
                label=f"no-mock closed {row['id']}",
            )
            < anchor_timestamp
        ],
        key=lambda row: row["id"],
    )
    status_id = int(contract["legacy_coverage_anchor_status_event_id"])
    close_id = int(contract["legacy_coverage_anchor_close_event_id"])
    anchor_events = {
        event["id"]: event for event in anchor_first["events"]
    }
    status_event = anchor_events.get(status_id)
    close_event = anchor_events.get(close_id)
    if (
        status_event is None
        or close_event is None
        or status_event.get("new_value") != "closed"
        or close_event.get("comment") != show_by_id[anchor_id]["close_reason"]
        or status_event.get("actor") != close_event.get("actor")
    ):
        raise EvidenceFailed("no-mock known closer pair differs")
    if legacy_first["events"]:
        raise EvidenceFailed("no-mock legacy issue unexpectedly has audit events")
    evidence = v2_rooted(
        {
            "anchor_id": anchor_id,
            "anchor_target_root": v2_target_root(show_by_id[anchor_id]),
            "anchor_audit_root": anchor_first["semantic_root"],
            "anchor_actor": close_event.get("actor"),
            "known_pair": [status_id, close_id],
            "legacy_id": legacy_id,
            "legacy_target_root": v2_target_root(show_by_id[legacy_id]),
            "legacy_audit_root": legacy_first["semantic_root"],
            "legacy_count": len(legacy_rows),
            "legacy_rows_root": semantic_root(legacy_rows),
            "closed_membership_count": len(first_projection),
            "closed_projection_root": semantic_root(first_projection),
            "capture_count": 2,
            "raw_stream_bodies_retained": False,
            "no_claim": (
                "released-br audit evidence proves only exact known and "
                "legacy-unavailable closure provenance"
            ),
        }
    )
    if (
        evidence["legacy_count"] != contract["legacy_coverage_count"]
        or evidence["legacy_rows_root"] != contract["legacy_coverage_rows_root"]
    ):
        raise EvidenceFailed("no-mock legacy coverage receipt differs")
    _v2_nomock_history_cache = evidence
    return dict(evidence)


def v2_reconstruct_payload_map(
    payloads: Mapping[str, bytes],
    accepted_manifest: Mapping[str, Any],
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, bytes],
]:
    terminal = strict_json_loads(
        payloads["terminal.json"],
        label="no-mock retained terminal",
        require_canonical=True,
    )
    events = v2_read_event_stream(payloads["events.jsonl"])
    return v2_reconstruct_retained(
        artifact_root=str(terminal["artifact_root"]),
        input_dir=str(terminal["artifact_dir"]),
        payloads=payloads,
        terminal=terminal,
        events=events,
        accepted_manifest=accepted_manifest,
    )


def v2_select_persistent_attempt(
    base: str,
    *,
    probe: Callable[[str], str],
) -> str:
    for attempt in range(1, V2_PERSISTENT_ATTEMPTS_CAP + 1):
        check_cancel()
        candidate = (
            base
            if attempt == 1
            else f"{base}-attempt-{attempt:04d}"
        )
        state = probe(candidate)
        if state not in {"AVAILABLE", "COMPLETE", "INCOMPLETE"}:
            raise EvidenceFailed(
                "persistent fixture attempt probe returned an unknown state"
            )
        if state in {"AVAILABLE", "COMPLETE"}:
            return candidate
    raise EvidenceFailed(
        "persistent fixture exhausted its bounded fresh-attempt budget"
    )


def v2_persistent_terminal_prefix_state(output: Path) -> str:
    try:
        output_stat = os.lstat(output)
    except FileNotFoundError:
        return "AVAILABLE"
    except OSError as error:
        raise EvidenceFailed(
            "persistent fixture directory cannot be inspected safely"
        ) from error
    if not stat.S_ISDIR(output_stat.st_mode):
        raise EvidenceFailed(
            "persistent fixture path is not a directory"
        )
    terminal = output / "terminal.json"
    try:
        terminal_stat = os.lstat(terminal)
    except FileNotFoundError:
        return "EMPTY_PREFIX"
    except OSError as error:
        raise EvidenceFailed(
            "persistent fixture terminal cannot be inspected safely"
        ) from error
    if not stat.S_ISREG(terminal_stat.st_mode):
        raise EvidenceFailed(
            "persistent fixture terminal is not a regular file"
        )
    return (
        "EMPTY_PREFIX"
        if terminal_stat.st_size == 0
        else "NONEMPTY_TERMINAL"
    )


def v2_observe_stable_invalid_terminal(
    previous: tuple[int, int, int, int, int] | None,
    previous_count: int,
    current: tuple[int, int, int, int, int],
) -> tuple[tuple[int, int, int, int, int], int, bool]:
    if (
        previous is not None
        and (
            len(previous) != 5
            or any(type(value) is not int or value < 0 for value in previous)
        )
    ):
        raise EvidenceFailed(
            "persistent invalid-terminal prior signature is malformed"
        )
    if (
        type(previous_count) is not int
        or previous_count < 0
        or len(current) != 5
        or any(type(value) is not int or value < 0 for value in current)
    ):
        raise EvidenceFailed(
            "persistent invalid-terminal observation is malformed"
        )
    count = previous_count + 1 if current == previous else 1
    return current, count, count >= 2


def v2_persistent_e2e_location(
    manifest: Mapping[str, Any],
    *,
    label: str,
    identity_binding: Any = None,
) -> tuple[str, str]:
    script_payload = bounded_read(REPO_ROOT / SCRIPT_REL)
    identity = hashlib.sha256(
        canonical_bytes(
            {
                "manifest_content_identity": manifest["content_identity"],
                "script_content_identity": (
                    "sha256-v1:"
                    + hashlib.sha256(script_payload).hexdigest()
                ),
                "label": label,
                "identity_binding": identity_binding,
            }
        )
    ).hexdigest()[:24]
    artifact_root = "target/beads-template-hygiene/v2-e2e"
    base = f"{label}-{identity}"

    def probe(candidate: str) -> str:
        output = resolve_run_dir(
            artifact_root,
            candidate,
            label="persistent v2 fixture candidate",
        )
        prefix_state = v2_persistent_terminal_prefix_state(output)
        if prefix_state == "AVAILABLE":
            return "AVAILABLE"
        if prefix_state == "EMPTY_PREFIX":
            return "INCOMPLETE"
        deadline = (
            time.monotonic()
            + V2_PERSISTENT_TERMINAL_STABILITY_SECONDS
        )
        prior_signature: tuple[int, int, int, int, int] | None = None
        stable_observations = 0
        last_error: HarnessError | None = None
        while True:
            check_cancel()
            try:
                v2_read_retained_bundle(
                    artifact_root=artifact_root,
                    input_dir=candidate,
                )
                return "COMPLETE"
            except (InputRefused, EvidenceFailed) as error:
                last_error = error
            current_state = v2_persistent_terminal_prefix_state(output)
            if current_state != "NONEMPTY_TERMINAL":
                return "INCOMPLETE"
            try:
                terminal_stat = os.lstat(output / "terminal.json")
            except OSError as error:
                raise EvidenceFailed(
                    "persistent fixture terminal changed during bounded "
                    "stability observation"
                ) from error
            signature = (
                int(terminal_stat.st_dev),
                int(terminal_stat.st_ino),
                int(terminal_stat.st_size),
                int(terminal_stat.st_mtime_ns),
                int(terminal_stat.st_ctime_ns),
            )
            (
                prior_signature,
                stable_observations,
                stable_invalid,
            ) = v2_observe_stable_invalid_terminal(
                prior_signature,
                stable_observations,
                signature,
            )
            remaining = deadline - time.monotonic()
            if remaining <= 0 and stable_invalid:
                raise EvidenceFailed(
                    "persistent fixture has a stable nonempty invalid "
                    "terminal; manual recovery is required"
                ) from last_error
            if remaining <= 0:
                return "INCOMPLETE"
            time.sleep(min(0.05, max(0.0, remaining)))

    return (
        artifact_root,
        v2_select_persistent_attempt(base, probe=probe),
    )


def v2_publish_and_read_persistent_fixture(
    *,
    artifact_root: str,
    artifact_dir: str,
    payloads: Mapping[str, bytes],
) -> tuple[
    Path,
    dict[str, bytes],
    dict[str, Any],
    list[dict[str, Any]],
]:
    check_cancel()
    output = resolve_run_dir(
        artifact_root,
        artifact_dir,
        label="persistent v2 fixture",
    )
    publication_error: EvidenceFailed | None = None
    if not output.exists():
        try:
            publication = v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=artifact_dir,
                payloads=payloads,
            )
        except EvidenceFailed as error:
            if not output.exists():
                raise
            publication_error = error
        else:
            if (
                publication["publication_order"][-1] != "terminal.json"
                or publication["terminal_content_sealed_last"] is not True
            ):
                raise EvidenceFailed(
                    "persistent v2 fixture did not seal terminal content last"
                )
    deadline = time.monotonic() + 5.0
    nonempty_invalid_signature: tuple[int, int, int, int, int] | None = None
    stable_nonempty_invalid_observations = 0
    while True:
        check_cancel()
        try:
            directory, retained, terminal, events = (
                v2_read_retained_bundle(
                    artifact_root=artifact_root,
                    input_dir=artifact_dir,
                )
            )
            check_cancel()
            break
        except (InputRefused, EvidenceFailed) as error:
            check_cancel()
            prefix_state = v2_persistent_terminal_prefix_state(output)
            if prefix_state == "NONEMPTY_TERMINAL":
                try:
                    terminal_stat = os.lstat(output / "terminal.json")
                except OSError as stat_error:
                    raise EvidenceFailed(
                        "persistent fixture terminal changed during invalid-"
                        "seal classification"
                    ) from stat_error
                signature = (
                    int(terminal_stat.st_dev),
                    int(terminal_stat.st_ino),
                    int(terminal_stat.st_size),
                    int(terminal_stat.st_mtime_ns),
                    int(terminal_stat.st_ctime_ns),
                )
                (
                    nonempty_invalid_signature,
                    stable_nonempty_invalid_observations,
                    stable_invalid,
                ) = v2_observe_stable_invalid_terminal(
                    nonempty_invalid_signature,
                    stable_nonempty_invalid_observations,
                    signature,
                )
                if stable_invalid:
                    raise EvidenceFailed(
                        "persistent fixture has a stable nonempty invalid "
                        "terminal; manual recovery is required"
                    ) from error
            else:
                nonempty_invalid_signature = None
                stable_nonempty_invalid_observations = 0
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise EvidenceFailed(
                    "persistent fixture remained incomplete after the bounded "
                    "concurrent-publication wait; rerun to select a fresh "
                    "attempt directory"
                ) from (publication_error or error)
            check_cancel()
            time.sleep(min(0.05, remaining))
    if dict(retained) != dict(payloads):
        divergence = first_projection_divergence(
            {
                name: (
                    len(payload),
                    "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
                )
                for name, payload in payloads.items()
            },
            {
                name: (
                    len(payload),
                    "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
                )
                for name, payload in retained.items()
            },
        )
        raise EvidenceFailed(
            "persistent v2 fixture differs from expected payloads at "
            f"{divergence or '$'}"
        )
    check_cancel()
    return directory, retained, terminal, events


def v2_fresh_nomock_artifact_location(
    manifest: Mapping[str, Any],
    *,
    label: str,
    identity_binding: Any,
) -> tuple[str, str]:
    if re.fullmatch(r"[a-z0-9][a-z0-9-]{0,63}", label) is None:
        raise EvidenceFailed("no-mock live artifact label is noncanonical")
    try:
        nonce = os.urandom(32).hex()
    except OSError as error:
        raise InfrastructureFailed(
            "no-mock live artifact nonce could not be generated"
        ) from error
    identity = hashlib.sha256(
        canonical_bytes(
            {
                "manifest_content_identity": manifest["content_identity"],
                "label": label,
                "identity_binding": identity_binding,
                "nonce": nonce,
            }
        )
    ).hexdigest()[:24]
    artifact_root = "target/beads-template-hygiene/v2-live-e2e"
    base = f"{label}-{identity}"
    for attempt in range(1, V2_PERSISTENT_ATTEMPTS_CAP + 1):
        check_cancel()
        artifact_dir = (
            base
            if attempt == 1
            else f"{base}-attempt-{attempt:04d}"
        )
        output = resolve_run_dir(
            artifact_root,
            artifact_dir,
            label="no-mock live artifact candidate",
        )
        try:
            value = os.lstat(output)
        except FileNotFoundError:
            return artifact_root, artifact_dir
        except OSError as error:
            raise InfrastructureFailed(
                "no-mock live artifact candidate cannot be inspected safely"
            ) from error
        if not stat.S_ISDIR(value.st_mode):
            raise EvidenceFailed(
                "no-mock live artifact candidate collides with a non-directory"
            )
    raise EvidenceFailed(
        "no-mock live artifact allocator exhausted its bounded fresh attempts"
    )


def v2_fixture_fingerprint(
    context: Mapping[str, str],
) -> dict[str, Any]:
    with fixture_br_lease():
        return _v2_fixture_fingerprint_locked(context)


def _v2_fixture_fingerprint_locked(
    context: Mapping[str, str],
) -> dict[str, Any]:
    expected_context_fields = {"db", "stable_id", "regression_id"}
    if set(context) != expected_context_fields or any(
        not isinstance(context[field], str) or not context[field]
        for field in expected_context_fields
    ):
        raise EvidenceFailed("no-mock fixture fingerprint context is malformed")
    issue_ids = sorted(
        str(row["id"]) for row in fixture_br_list()
    )
    shows = [
        fixture_br_semantic_projection(fixture_br_show(issue_id))
        for issue_id in issue_ids
    ]
    audits = [
        {
            "issue_id": issue_id,
            "root": semantic_root(
                fixture_br_json("audit", "log", issue_id)
            ),
        }
        for issue_id in issue_ids
    ]
    status = fixture_br_json("status", "--no-activity")
    sync_status = fixture_br_json("sync", "--status")
    witness = fixture_br_json("sync", "--witness")
    return v2_rooted(
        {
            "fixture_db": context["db"],
            "issue_ids": issue_ids,
            "shows": shows,
            "audits": audits,
            "status": status,
            "sync_status": sync_status,
            "export_witness": witness,
            "no_claim": (
                "fingerprint covers the isolated released-br fixture and "
                "does not claim wall-clock or append-only audit reversibility"
            ),
        }
    )


V2_FIXTURE_BR_CASE_SLUGS = frozenset(
    {
        "nomock-current-br-two-gate-nodata",
        "nomock-review-plan",
        "nomock-history-plan",
        "nomock-unrelated-drift-stability",
        "nomock-selected-drift-refusal",
        "nomock-active-conflict-deferred",
        "nomock-oversize",
        "nomock-offline-replay",
        "nomock-live-target-unchanged",
    }
)


def v2_execute_nomock_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    if slug not in V2_FIXTURE_BR_CASE_SLUGS:
        return _v2_execute_nomock_cases_impl(case, manifest)
    with fixture_br_lease() as lease:
        if slug == "nomock-live-target-unchanged":
            fixture_br_external_lock_probe(
                lease,
                expected="CONTENDED",
            )
        result = _v2_execute_nomock_cases_impl(case, manifest)
    if slug == "nomock-live-target-unchanged":
        with fixture_br_lease() as reacquired:
            if (
                reacquired.device != lease.device
                or reacquired.inode != lease.inode
            ):
                raise InfrastructureFailed(
                    "fixture lock identity changed across release and reacquisition"
                )
            fixture_br_external_lock_probe(
                reacquired,
                expected="CONTENDED",
            )
    return result


def _v2_execute_nomock_cases_impl(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "released-br-no-mock-e2e", "slug": slug}

    if slug == "nomock-br-robot-cells":
        issues = normalize_document(
            br_read_json(
                "list",
                "--all",
                "--deferred",
                "--json",
                "--limit",
                "0",
            ),
            label="no-mock all-status list",
        )
        bv_projection = v2_nomock_bv_projection()
        snapshot = collect_live_v2(manifest)
        campaign_root, _ = v2_campaign_epoch(snapshot)
        production_inventory = v2_build_inventory(
            snapshot,
            campaign_epoch_root=campaign_root,
            priority_filter=None,
            status_filter=None,
        )
        production_zero = v2_build_zero_sets(
            source_root=snapshot.source["semantic_root"],
            inventory=production_inventory,
            prior_campaign=v2_empty_prior_campaign(),
            current_universe=snapshot.all_issues,
            current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
        )
        v2_validate_zero_sets(
            production_zero,
            source_root=snapshot.source["semantic_root"],
            inventory=production_inventory,
            prior_campaign=v2_empty_prior_campaign(),
            current_universe=snapshot.all_issues,
            current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
        )
        statuses = Counter(str(row.get("status") or "") for row in issues)
        priorities = Counter(int(row.get("priority")) for row in issues)
        cells = {
            f"P{priority}/{status}": sum(
                row.get("priority") == priority
                and row.get("status") == status
                for row in issues
            )
            for priority in range(5)
            for status in STATUS_SCOPES
        }
        zero_receipts = [
            v2_rooted(
                {
                    "cell": cell,
                    "count": count,
                    "issue_ids_root": semantic_root(
                        sorted(
                            str(row.get("id") or "")
                            for row in issues
                            if f"P{row.get('priority')}/{row.get('status')}" == cell
                        )
                    ),
                }
            )
            for cell, count in sorted(cells.items())
            if count == 0
        ]
        checks.check(
            "released-br-all-state-coverage",
            set(statuses) == set(STATUS_SCOPES)
            and set(priorities) == set(range(5))
            and any(str(row.get("assignee") or "") for row in issues)
            and any(not str(row.get("assignee") or "") for row in issues),
            expected={
                "statuses": list(STATUS_SCOPES),
                "priorities": list(range(5)),
                "assigned_and_ownerless": True,
            },
            observed={
                "statuses": dict(statuses),
                "priorities": dict(priorities),
                "assigned": sum(bool(row.get("assignee")) for row in issues),
            },
        )
        checks.check(
            "robot-deferred-accounting",
            bv_projection["issue_count"]
            == len(issues) - statuses["deferred"]
            and bv_projection["robot_mode"] == "--robot-triage",
            expected=len(issues) - statuses["deferred"],
            observed=bv_projection["issue_count"],
        )
        checks.check(
            "exact-25-cells-and-zero-receipts",
            len(cells) == 25
            and all(
                receipt["count"] == 0
                and receipt["issue_ids_root"] == semantic_root([])
                for receipt in zero_receipts
            ),
            expected={"cells": 25, "zero_receipts_root_bound": True},
            observed={
                "cells": len(cells),
                "zero_receipts": len(zero_receipts),
            },
        )
        live_nonclosed_ids = sorted(
            str(row.get("id") or "")
            for row in issues
            if row.get("status") != "closed"
        )
        inventoried_nonclosed_ids = sorted(
            row["id"]
            for row in production_inventory["rows"]
            if row["status"] != "closed"
        )
        checks.check(
            "production-v2-exact-covers-complete-nonclosed-universe",
            live_nonclosed_ids == inventoried_nonclosed_ids
            and snapshot.inventory["review_scope"]["nonclosed_complete"]
            is True
            and snapshot.inventory["counts"][
                "complete_review_scope_issues"
            ]
            == len(snapshot.inventory["rows"])
            and all(
                row["semantic_review_disposition"]
                in V2_SEMANTIC_REVIEW_DISPOSITIONS
                for row in production_inventory["rows"]
            ),
            expected={
                "nonclosed_ids_root": semantic_root(live_nonclosed_ids),
                "complete": True,
            },
            observed={
                "nonclosed_ids_root": semantic_root(
                    inventoried_nonclosed_ids
                ),
                "live_count": len(live_nonclosed_ids),
                "inventory_count": len(inventoried_nonclosed_ids),
                "selected_review_count": len(production_inventory["rows"]),
            },
        )
        checks.check(
            "production-zero-validator-and-command-evidence",
            len(production_zero["cells"]) == 25
            and production_zero["counts"]["issues"]
            == len(production_inventory["rows"])
            and bool(_command_receipts)
            and all(
                isinstance(receipt.get("argv"), list)
                and receipt.get("exit_code") == 0
                for receipt in _command_receipts
            ),
            expected={
                "cells": 25,
                "targets": len(production_inventory["rows"]),
                "commands": "nonempty successful receipts",
            },
            observed={
                "cells": len(production_zero["cells"]),
                "targets": production_zero["counts"]["issues"],
                "command_count": len(_command_receipts),
                "command_receipts_root": semantic_root(_command_receipts),
            },
        )

    elif slug == "nomock-audit-known-legacy-conflict":
        evidence = v2_nomock_history_evidence(manifest)
        checks.check(
            "released-known-and-legacy",
            evidence["known_pair"]
            == [
                manifest["history_contract"][
                    "legacy_coverage_anchor_status_event_id"
                ],
                manifest["history_contract"][
                    "legacy_coverage_anchor_close_event_id"
                ],
            ]
            and evidence["legacy_count"]
            == manifest["history_contract"]["legacy_coverage_count"],
            expected="pinned known pair and legacy receipt",
            observed=evidence,
        )
        conflicting = {
            "issue_id": "fixture-conflict",
            "events": [
                {
                    "id": 3,
                    "event_type": "closed",
                    "actor": "other",
                    "timestamp": "2026-01-02T00:00:00.002000+00:00",
                },
                {
                    "id": 2,
                    "event_type": "closed",
                    "actor": "first",
                    "timestamp": "2026-01-02T00:00:00.001000+00:00",
                },
                {
                    "id": 1,
                    "event_type": "status_changed",
                    "actor": "first",
                    "timestamp": "2026-01-02T00:00:00+00:00",
                    "new_value": "closed",
                },
            ],
        }
        normalized = v2_normalize_audit_document(
            conflicting,
            issue_id="fixture-conflict",
        )
        checks.check(
            "conflicting-close-state-retained",
            sum(
                event["event_type"] == "closed"
                for event in normalized["events"]
            )
            == 2,
            expected=2,
            observed=normalized["events"],
        )

    elif slug == "nomock-current-br-two-gate-nodata":
        context = fixture_br_context()
        before = fixture_br_semantic_projection(
            fixture_br_show(context["stable_id"])
        )
        payloads, accepted, components = v2_replayable_fixture_bundle(
            manifest,
            subject_mode="review-plan",
            issue=fixture_br_show(context["stable_id"]),
        )
        inventory = components[1]
        receipts = v2_synthetic_receipts(
            inventory,
            declared=True,
            external_verdict="VALID",
            conditional_verdict="NODATA",
        )
        version = br_version()["version"]
        authority = v2_derive_authority(
            inventory,
            receipts,
            current_br_version=version,
        )
        after = fixture_br_semantic_projection(
            fixture_br_show(context["stable_id"])
        )
        decision = authority["decisions"][0]
        checks.check(
            "current-released-two-gate-nodata",
            version == "0.2.19"
            and decision["readiness"] == "DECLARED_READY"
            and authority["current_br_conditional_write_capability"]
            == "AUTOMATION_NODATA"
            and decision["remediation_route"] == "ANALYSIS_ONLY",
            expected=(
                "0.2.19",
                "DECLARED_READY",
                "AUTOMATION_NODATA",
                "ANALYSIS_ONLY",
            ),
            observed=(
                version,
                decision["readiness"],
                authority["current_br_conditional_write_capability"],
                decision["remediation_route"],
            ),
        )
        checks.check(
            "released-target-unchanged",
            before == after and bool(payloads) and bool(accepted),
            expected=semantic_root(before),
            observed=semantic_root(after),
        )

    elif slug == "nomock-review-plan":
        context = fixture_br_context()
        stable_id = context["stable_id"]
        fixture_root = resolve_safe(
            str(FIXTURE_BR_ROOT_REL),
            label="no-mock live review fixture root",
            must_exist=True,
        )
        fixture_before = v2_fixture_fingerprint(context)
        artifact_root, artifact_dir = v2_fresh_nomock_artifact_location(
            manifest,
            label="released-review-plan",
            identity_binding={
                "fixture_root": fixture_before["semantic_root"],
                "target_id": stable_id,
            },
        )
        planner_arguments = parse_arguments(
            [
                "--review-plan",
                "--artifact-root",
                artifact_root,
                "--artifact-dir",
                artifact_dir,
                "--targets",
                stable_id,
            ]
        )
        synopsis = v2_execute_live_plan(
            mode="review-plan",
            parsed=planner_arguments,
            manifest=manifest,
            br_cwd=fixture_root,
        )
        (
            retained_directory,
            payloads,
            terminal,
            events,
        ) = v2_read_retained_bundle(
            artifact_root=artifact_root,
            input_dir=artifact_dir,
        )
        reconstructed = v2_reconstruct_retained(
            artifact_root=artifact_root,
            input_dir=artifact_dir,
            payloads=payloads,
            terminal=terminal,
            events=events,
            accepted_manifest=manifest,
        )
        source, inventory, authority, review, history, zero_sets, _ = (
            reconstructed
        )
        observation = source["captured"]["observation"]
        source_issue_ids = sorted(
            str(row["id"])
            for row in source["captured"]["all_issues"]
        )
        source_receipts = v2_validate_source_command_receipts(
            observation,
            issue_ids=source_issue_ids,
        )
        expected_source_receipts = [
            {"capture_sequence": index, **receipt}
            for index, receipt in enumerate(_command_receipts)
        ]
        expected_artifact_path = str(
            safe_relative(artifact_root, label="no-mock artifact root")
            / safe_relative(artifact_dir, label="no-mock artifact dir")
        )
        checks.check(
            "exact-nine-file-released-bundle",
            len(V2_RUN_ARTIFACTS) == 9
            and len(payloads) == 9
            and set(payloads) == set(V2_RUN_ARTIFACTS)
            and terminal["base_artifacts"] == list(V2_RUN_ARTIFACTS)
            and terminal["safe_relative_artifacts"]
            == sorted(V2_RUN_ARTIFACTS)
            and terminal["terminal"] == "Pass"
            and terminal["bundle_state"] == "COMPLETE_GREEN"
            and terminal["complete_evidence_bundle"] is True
            and terminal["complete_green_prefix"] is True
            and events[-1]["terminal"] == "Pass"
            and synopsis["schema"]
            == "frankensim.beads-template-hygiene.synopsis.v2"
            and synopsis["mode"] == "review-plan"
            and synopsis["artifacts"] == expected_artifact_path
            and synopsis["reproduction"] == terminal["reproduction"]
            and synopsis["selected_ids"] == {
                "total": 1,
                "shown": 1,
                "ids": [stable_id],
                "truncated": False,
                "notice": None,
            }
            and source_issue_ids == fixture_before["issue_ids"]
            and observation["live_issue_count"] == len(source_issue_ids)
            and observation["command_receipts"]
            == expected_source_receipts
            and [row["argv"] for row in source_receipts]
            == v2_expected_observation_argv(source_issue_ids)
            and all(
                row["exit_code"] == 0
                and row["category"] == "SUCCESS"
                and row["redaction_verdict"]
                == "RAW_STREAM_BODIES_NOT_RETAINED"
                for row in observation["command_receipts"]
            )
            and retained_directory
            == resolve_run_dir(
                artifact_root,
                artifact_dir,
                label="no-mock retained review plan",
                must_exist=True,
            ),
            expected={
                "base_artifacts": sorted(V2_RUN_ARTIFACTS),
                "terminal": "Pass",
                "bundle_state": "COMPLETE_GREEN",
                "synopsis_mode": "review-plan",
                "selected_ids": [stable_id],
                "source_issue_ids": fixture_before["issue_ids"],
                "source_command_count": len(
                    v2_expected_observation_argv(source_issue_ids)
                ),
            },
            observed={
                "base_artifacts": sorted(payloads),
                "terminal": terminal["terminal"],
                "bundle_state": terminal["bundle_state"],
                "synopsis_mode": synopsis["mode"],
                "selected_ids": synopsis["selected_ids"]["ids"],
                "source_issue_ids": source_issue_ids,
                "source_command_count": len(source_receipts),
                "source_command_root": semantic_root(source_receipts),
            },
        )

        replay_root, replay_dir = v2_fresh_nomock_artifact_location(
            manifest,
            label="released-review-replay",
            identity_binding={
                "retained_terminal_root": terminal["semantic_root"],
                "target_id": stable_id,
            },
        )
        if replay_root != artifact_root:
            raise EvidenceFailed(
                "no-mock live review replay escaped its artifact root"
            )
        receipt_count_before_replay = len(_command_receipts)
        replay_result = v2_replay_bundle(
            artifact_root=artifact_root,
            input_dir=artifact_dir,
            output_dir=replay_dir,
            accepted_manifest=manifest,
        )
        receipt_count_after_replay = len(_command_receipts)
        (
            replay_directory,
            replay_payloads,
            replay_terminal,
            replay_events,
        ) = v2_read_retained_bundle(
            artifact_root=artifact_root,
            input_dir=replay_dir,
        )
        replay_reconstructed = v2_reconstruct_retained(
            artifact_root=artifact_root,
            input_dir=replay_dir,
            payloads=replay_payloads,
            terminal=replay_terminal,
            events=replay_events,
            accepted_manifest=manifest,
        )
        checks.check(
            "released-plan-offline-replay",
            replay_result["terminal"] == "Pass"
            and replay_result["subject_mode"] == "review-plan"
            and replay_result["retained_terminal_root"]
            == terminal["semantic_root"]
            and replay_result["live_tracker_reads"] is False
            and replay_result["live_tracker_writes"] is False
            and replay_result["network_access"] is False
            and replay_terminal["mode"] == "replay"
            and replay_terminal["subject_mode"] == "review-plan"
            and replay_terminal["bundle_state"] == "COMPLETE_GREEN"
            and replay_terminal["terminal"] == "Pass"
            and replay_terminal["replay_equivalence"][
                "retained_terminal_root"
            ]
            == terminal["semantic_root"]
            and replay_terminal["replay_equivalence"]["live_tracker_reads"]
            is False
            and replay_terminal["replay_equivalence"]["live_tracker_writes"]
            is False
            and replay_terminal["replay_equivalence"]["network_access"]
            is False
            and [row["semantic_root"] for row in replay_reconstructed[:6]]
            == [row["semantic_root"] for row in reconstructed[:6]]
            and receipt_count_after_replay == receipt_count_before_replay
            and replay_directory != retained_directory,
            expected={
                "projection_roots": [
                    row["semantic_root"] for row in reconstructed[:6]
                ],
                "live_tracker_reads": False,
                "live_tracker_writes": False,
                "network_access": False,
                "new_source_commands": 0,
                "disjoint_output": True,
            },
            observed={
                "projection_roots": [
                    row["semantic_root"]
                    for row in replay_reconstructed[:6]
                ],
                "live_tracker_reads": replay_result[
                    "live_tracker_reads"
                ],
                "live_tracker_writes": replay_result[
                    "live_tracker_writes"
                ],
                "network_access": replay_result["network_access"],
                "new_source_commands": (
                    receipt_count_after_replay
                    - receipt_count_before_replay
                ),
                "disjoint_output": replay_directory != retained_directory,
            },
        )

        fixture_after = v2_fixture_fingerprint(context)
        checks.check(
            "mode-specific-projection-and-audit",
            [row["id"] for row in inventory["rows"]] == [stable_id]
            and review["state"] == "POPULATED"
            and review["counts"]["targets"] == 1
            and history["state"] == "NOT_REQUESTED"
            and source["captured"]["audit_capture"]["state"]
            == "NOT_REQUESTED"
            and terminal["subject_mode"] == "review-plan"
            and source["tracker_authority"] == "READ_ONLY"
            and source["direct_tracker_file_access"] is False
            and source["network_access"] is False
            and fixture_after["semantic_root"]
            == fixture_before["semantic_root"]
            and authority["inventory_root"] == inventory["semantic_root"]
            and zero_sets["inventory_root"] == inventory["semantic_root"],
            expected={
                "inventory_ids": [stable_id],
                "review_state": "POPULATED",
                "history_state": "NOT_REQUESTED",
                "audit_state": "NOT_REQUESTED",
                "tracker_authority": "READ_ONLY",
                "fixture_root": fixture_before["semantic_root"],
            },
            observed={
                "inventory_ids": [row["id"] for row in inventory["rows"]],
                "review_state": review["state"],
                "history_state": history["state"],
                "audit_state": source["captured"]["audit_capture"]["state"],
                "tracker_authority": source["tracker_authority"],
                "fixture_root": fixture_after["semantic_root"],
            },
        )

    elif slug == "nomock-history-plan":
        live_history = v2_nomock_history_evidence(manifest)
        context = fixture_br_context()
        payloads, accepted, retained = v2_replayable_fixture_bundle(
            manifest,
            subject_mode="history-plan",
            issue=None,
        )
        reconstructed = v2_reconstruct_payload_map(payloads, accepted)
