                    label="explicit replay-v2 stdout",
                )
                v2_validate_replay_result_document(explicit_result)
                (
                    _,
                    explicit_payloads,
                    explicit_terminal,
                    explicit_events,
                ) = v2_read_retained_bundle(
                    artifact_root=artifact_root,
                    input_dir=explicit_dir,
                )
                explicit_reconstructed = v2_reconstruct_retained(
                    artifact_root=artifact_root,
